TURATH_CHUNK(40,[{"num":8000,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَمَّا كَانَ يَوْمَ بَدْرٍ أُتِيَ بِأُسَارَى، وَأُتِيَ بِالْعَبَّاسِ، وَلَمْ يَكُنْ عَلَيْهِ ثَوْبٌ، فَنَظَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَهُ قَمِيصًا، فَوَجَدُوا قَمِيصَ عَبْدِ اللَّهِ بْنِ أُبَىٍّ يَقْدُرُ عَلَيْهِ، فَكَسَاهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِيَّاهُ، فَلِذَلِكَ نَزَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَمِيصَهُ الَّذِي أَلْبَسَهُ.","قَالَ ابْنُ عُيَيْنَةَ: كَانَتْ لَهُ عِنْدَ النَّبِيِّ صلى الله عليه وسلم يَدٌ، فَأَحَبَّ أَنْ يُكَافِئَهُ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (3008) عن عبد الله بن محمد، حدثنا ابن عيينة، عن عمرو، سمع جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب الإحسان إلى الأسرى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3008).","chapter_en":"Treating Prisoners Well","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الأسرى","group_en":"Collection of What Has Been Narrated Concerning Prisoners","part_no":43,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: On the day of Badr, prisoners were brought, and al-ʿAbbas was brought without a garment on him. The Prophet ﷺ looked for a shirt for him, and they found that the shirt of ʿAbdullah ibn Ubayy fit him, so the Prophet ﷺ clothed him with it. For that reason, the Prophet ﷺ later took off his own shirt and gave it to ʿAbdullah ibn Ubayy. Ibn ʿUyaynah said: He had done a favor for the Prophet ﷺ, so he wished to repay him."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3008)."},{"num":8001,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ مَكَّةَ عَامَ الْفَتْحِ وَعَلَى رَأْسِهِ المغفر، فَلَمَّا نَزَعَهُ جَاءَهُ رجلٌ، فَقَالَ لَهُ: يَا رَسُولَ اللَّهِ، ابنُ خَطَلٍ مُتَعَلِّقٌ بِأَسْتَارِ الْكَعْبَةِ، فَقَالَ: اقْتُلُوهُ."],"takhrij":"متفق عليه: رواه مالك في الحج (247) عن ابن شهاب، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب في قتل الأسير الخطير الذي له جنايات","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (247), al-Bukhari (3044), and Muslim (1357).","chapter_en":"Killing a Dangerous Prisoner Who Has Committed Crimes","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الأسرى","group_en":"Collection of What Has Been Narrated Concerning Prisoners","part_no":43,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Malik narrated that the Messenger of Allah ﷺ entered Makkah in the year of the Conquest while wearing a helmet on his head. When he removed it, a man came to him and said: “O Messenger of Allah, Ibn Khatal is clinging to the curtains of the Kaʿbah.” He said: “Kill him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7940],"tks":"متفق عليه: رواه مالك (247)، والبخاري (3044)، ومسلم (1357)."},{"num":8002,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ: رَضِيَ اللَّهُ عَنْهُ أَنَّ رِجَالاً، مِنَ الأَنْصَارِ اسْتَأْذَنُوا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: يَا رَسُولَ اللَّهِ، ائْذَنْ فَلْنَتْرُكْ لاِبْنِ أُخْتِنَا عَبَّاسٍ فِدَاءَهُ. فَقَالَ: لاَ تَدَعُونَ مِنْهَا دِرْهَمًا."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (3048) عن إسماعيل بن أبي إدريس، حدثنا إسماعيل بن إبراهيم بن عقبة، عن موسى بن عقبة، عن ابن شهاب قال: حدثني أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في فداء الأسرى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3048).","chapter_en":"What Has Been Reported Concerning Ransoming Prisoners","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الأسرى","group_en":"Collection of What Has Been Narrated Concerning Prisoners","part_no":43,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Malik narrated that some men from the Ansar asked permission from the Messenger of Allah ﷺ and said: “O Messenger of Allah, permit us to leave the ransom of our sister’s son, al-ʿAbbas.” He said: “Do not leave from it even a single dirham.”"]},"intro":{"ar":["قال تعالى:","(فَإِذَا لَقِيتُمُ الَّذِينَ كَفَرُوا فَضَرْبَ الرِّقَابِ حَتَّىٰ إِذَا أَثْخَنتُمُوهُمْ فَشُدُّوا الْوَثَاقَ فَإِمَّا مَنًّا بَعْدُ وَإِمَّا فِدَاءً حَتَّىٰ تَضَعَ الْحَرْبُ أَوْزَارَهَا) [محمد: ٤]."],"en":["Allah Most High said:","“So when you meet those who disbelieve, strike the necks until, when you have subdued them, bind them firmly; then afterward either release them graciously or ransom them until the war lays down its burdens.” [Muhammad: 4]"]}},"tuhfa":{},"full":1,"rep":[12422],"tks":"صحيح: رواه البخاري (3048)."},{"num":8003,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: بَعَثَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْلاً قِبَلَ نَجْدٍ، فَجَاءَتْ بِرَجُلٍ مِنْ بَنِي حَنِيفَةَ يُقَالُ لَهُ: ثُمَامَةُ بْنُ أُثَالٍ، فَرَبَطُوهُ بِسَارِيَةٍ مِنْ سَوَارِي الْمَسْجِدِ، فَخَرَجَ إِلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَقَالَ: مَا عِنْدَكَ يَا ثُمَامَةُ؟ فَقَالَ: عِنْدِي خَيْرٌ يَا مُحَمَّدُ إِنْ تَقْتُلْنِي تَقْتُلْ ذَا دَمٍ، وَإِنْ تُنْعِمْ تُنْعِمْ عَلَى شَاكِرٍ، وَإِنْ كُنْتَ تُرِيدُ الْمَالَ فَسَلْ مِنْهُ مَا شِئْتَ، فَتَرَكَ حَتَّى كَانَ الْغَدُ، ثُمَّ قَالَ لَهُ: مَا عِنْدَكَ يَا ثُمَامَةُ؟ قَالَ: مَا قُلْتُ لَكَ: إِنْ تُنْعِمْ تُنْعِمْ عَلَى شَاكِرٍ، فَتَرَكَهُ حَتَّى كَانَ بَعْدَ الْغَدِ، فَقَالَ: مَا عِنْدَكَ يَا ثُمَامَةُ؟ فَقَالَ: عِنْدِي مَا قُلْتُ لَكَ. فَقَالَ: أَطْلِقُوا ثُمَامَةَ، فَانْطَلَقَ إِلَى نَخْلٍ قَرِيبٍ مِنَ الْمَسْجِدِ، فَاغْتَسَلَ، ثُمَّ دَخَلَ الْمَسْجِدَ، فَقَالَ: أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ يَا مُحَمَّدُ، وَاللَّهِ مَا كَانَ عَلَى الأَرْضِ وَجْهٌ أَبْغَضَ إِلَى مِنْ وَجْهِكَ، فَقَدْ أَصْبَحَ وَجْهُكَ أَحَبَّ الْوُجُوهِ إِلَى، وَاللَّهِ مَا كَانَ مِنْ دِينٍ أَبْغَضَ إِلَى مِنْ دِينِكَ فَأَصْبَحَ دِينُكَ أَحَبَّ الدِّينِ إِلَى، وَاللَّهِ مَا كَانَ مِنْ بَلَدٍ أَبْغَضُ إِلَى مِنْ بَلَدِكَ فَأَصْبَحَ بَلَدُكَ أَحَبَّ الْبِلاَدِ إِلَى، وَإِنَّ خَيْلَكَ أَخَذَتْنِي، وَأَنَا أُرِيدُ الْعُمْرَةَ، فَمَاذَا تَرَى؟ فَبَشَّرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، وَأَمَرَهُ أَنْ يَعْتَمِرَ، فَلَمَّا قَدِمَ مَكَّةَ، قَالَ لَهُ قَائِلٌ: صَبَوْتَ؟ قَالَ: لاَ، وَلَكِنْ أَسْلَمْتُ مَعَ مُحَمَّدٍ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، وَلاَ وَاللَّهِ لاَ يَأْتِيكُمْ مِنَ الْيَمَامَةِ حَبَّةُ حِنْطَةٍ حَتَّى يَأْذَنَ فِيهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4372)، ومسلم في الجهاد والسير (1764) كلاهما من طريق الليث، حدثني سعيد بن أبي سعيد، أنه سمع ابا هريرة يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في المنّ على الأسرى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4372) and Muslim (1764).","chapter_en":"What Has Been Reported Concerning Graciously Releasing Prisoners","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الأسرى","group_en":"Collection of What Has Been Narrated Concerning Prisoners","part_no":43,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ sent horsemen toward Najd, and they brought back a man from Banu Hanifah called Thumamah ibn Uthal. They tied him to one of the pillars of the mosque. The Prophet ﷺ came out to him and said: “What do you have, O Thumamah?” He said: “I have good, O Muhammad. If you kill me, you kill one whose blood will be avenged; if you show favor, you show favor to one who is grateful; and if you want wealth, ask of it whatever you wish.” He left him until the next day, then said to him: “What do you have, O Thumamah?” He said: “What I told you: if you show favor, you show favor to one who is grateful.” He left him until the day after, then said: “What do you have, O Thumamah?” He said: “I have what I already told you.” He said: “Release Thumamah.” So he went to some palm trees near the mosque, washed himself, then entered the mosque and said: “I testify that there is no god but Allah, and I testify that Muhammad is the Messenger of Allah. O Muhammad, by Allah, there was no face on earth more hateful to me than your face, but now your face has become the most beloved of faces to me. By Allah, there was no religion more hateful to me than your religion, but now your religion has become the most beloved religion to me. By Allah, there was no land more hateful to me than your land, but now your land has become the most beloved of lands to me. Your horsemen captured me while I intended to perform ʿumrah, so what do you think?” The Messenger of Allah ﷺ gave him glad tidings and ordered him to perform ʿumrah. When he reached Makkah, someone said to him: “Have you abandoned your religion?” He said: “No, but I have accepted Islam with Muhammad, the Messenger of Allah ﷺ. And by Allah, not a single grain of wheat will come to you from al-Yamamah until the Prophet ﷺ gives permission for it.”"]}},"tuhfa":{},"full":1,"rep":[8950],"tks":"متفق عليه: رواه البخاري (4372)، ومسلم (1764)."},{"num":8004,"demo":false,"sanad":"","matn":["عَنْ جُبَيْرِ بْنِ مُطْعِمٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي أُسَارَى بَدْرٍ: لَوْ كَانَ الْمُطْعِمُ بْنُ عَدِيٍّ حيّا، ثُمَّ كَلَّمَنِي فِي هولاء النَّتْنَى لَتَرَكْتُهُمْ لَهُ."],"takhrij":"صحيح: رواه البخاري في فرض الخمس (3139) عن إسحاق بن منصور، أخبرنا عبد الرزاق، أخبرنا معمر، عن الزهري، عن محمد بن جبير، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في المنّ على الأسرى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3139).","chapter_en":"What Has Been Reported Concerning Graciously Releasing Prisoners","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الأسرى","group_en":"Collection of What Has Been Narrated Concerning Prisoners","part_no":43,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["Jubayr ibn Mutʿim narrated that the Prophet ﷺ said regarding the prisoners of Badr: “If al-Mutʿim ibn ʿAdi were alive and spoke to me about these foul ones, I would have released them for him.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3139)."},{"num":8005,"demo":false,"sanad":"","matn":["عن مَرْوَانَ بن الْحَكَمِ ومسور بن مَخْرَمَةَ أخبراه: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ حِينَ جَاءَهُ وَفْدُ هَوَازِنَ مُسْلِمِينَ، فَسَأَلُوهُ أَنْ يَرُدَّ إِلَيْهِمْ أَمْوَالَهُمْ وَسَبْيَهُمْ، فَقَالَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَحَبُّ الْحَدِيثِ إِلَىَّ أَصْدَقُهُ، فَاخْتَارُوا إِحْدَى الطَّائِفَتَيْنِ: إِمَّا السَّبْىَ، وَإِمَّا الْمَالَ، وَقَدْ كُنْتُ اسْتَأْنَيْتُ بِهِمْ. وَقَدْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ انْتَظَرَ آخِرَهُمْ بِضْعَ عَشْرَةَ لَيْلَةً، حِينَ قَفَلَ مِنَ الطَّائِفِ، فَلَمَّا تَبَيَّنَ لَهُمْ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَيْرُ رَادٍّ إِلَيْهِمْ إِلاَّ إِحْدَى الطَّائِفَتَيْنِ. قَالُوا: فَإِنَّا نَخْتَارُ سَبْيَنَا، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمُسْلِمِينَ، فَأَثْنَى عَلَى اللَّهِ بِمَا هُوَ أَهْلُهُ، ثُمَّ قَالَ: أَمَّا بَعْدُ، فَإِنَّ إِخْوَانَكُمْ هَؤُلاَءِ قَدْ جَاءُونَا تَائِبِينَ، وَإِنِّي قَدْ رَأَيْتُ أَنْ أَرُدَّ إِلَيْهِمْ سَبْيَهُمْ، مَنْ أَحَبَّ أَنْ يُطَيِّبَ فَلْيَفْعَلْ، وَمَنْ أَحَبَّ مِنْكُمْ أَنْ يَكُونَ عَلَى حَظِّهِ حَتَّى نُعْطِيَهُ إِيَّاهُ مِنْ أَوَّلِ مَا يُفِيءُ اللَّهُ عَلَيْنَا فَلْيَفْعَلْ. فَقَالَ النَّاسُ: قَدْ طَيَّبْنَا ذَلِكَ يَا رَسُولَ اللَّهِ لَهُمْ. فَقَالَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّا لاَ نَدْرِي مَنْ أَذِنَ مِنْكُمْ فِي ذَلِكَ مِمَّنْ لَمْ يَأْذَنْ، فَارْجِعُوا حَتَّى يَرْفَعَ إِلَيْنَا عُرَفَاؤُكُمْ أَمْرَكُمْ، فَرَجَعَ النَّاسُ، فَكَلَّمَهُمْ عُرَفَاؤُهُمْ، ثُمَّ رَجَعُوا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرُوهُ أَنَّهُمْ قَدْ طَيَّبُوا فَأَذِنُوا. فَهَذَا الَّذِي بَلَغَنَا عَنْ سَبْىِ هَوَازِنَ."],"takhrij":"صحيح: رواه البخاري في فرض الخمس (3131، 3132) عن سعيد بن عُفير، حدثني الليث، حدثني عُقيل، عن ابن شهاب قال: وزعم ان مروان بن الحكم ومسور بن مخرمة أخبراه فذكراه.","grade":"صحيح","chapter_ar":"باب ما جاء في المنّ على الأسرى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3131, 3132).","chapter_en":"What Has Been Reported Concerning Graciously Releasing Prisoners","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الأسرى","group_en":"Collection of What Has Been Narrated Concerning Prisoners","part_no":43,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["Marwan ibn al-Hakam and al-Miswar ibn Makhramah informed him that when the delegation of Hawazin came to the Messenger of Allah ﷺ as Muslims and asked him to return to them their property and captives, the Messenger of Allah ﷺ said to them: “The speech I love most is the truest. Choose one of the two groups: either the captives or the wealth; and I had waited for them.” The Messenger of Allah ﷺ had waited for their last arrivals for more than ten nights when he returned from al-Ta’if. When it became clear to them that the Messenger of Allah ﷺ would return to them only one of the two groups, they said: “We choose our captives.” So the Messenger of Allah ﷺ stood among the Muslims, praised Allah as He deserves, then said: “As for what follows: these brothers of yours have come to us repentant, and I have seen fit to return their captives to them. Whoever wishes to give willingly may do so, and whoever among you wishes to keep his share until we give it to him from the first spoils Allah grants us may do so.” The people said: “We have willingly given that to them, O Messenger of Allah.” The Messenger of Allah ﷺ said to them: “We do not know who among you has permitted that and who has not. So return until your chiefs bring your matter back to us.” The people returned, their chiefs spoke with them, then they returned to the Messenger of Allah ﷺ and informed him that they had willingly given and permitted it. This is what reached us concerning the captives of Hawazin."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3131، 3132)."},{"num":8006,"demo":false,"sanad":"","matn":["بْنُ سَلَمَةَ، حَدَّثَنِي أَبِي قَالَ:  غَزَوْنَا فَزَارَةَ، وَعَلَيْنَا أَبُو بَكْرٍ أَمَّرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيْنَا، فَلَمَّا كَانَ بَيْنَنَا وَبَيْنَ الْمَاءِ سَاعَةٌ، أَمَرَنَا أَبُو بَكْرٍ، فَعَرَّسْنَا، ثُمَّ شَنَّ الْغَارَةَ، فَوَرَدَ الْمَاءَ، فَقَتَلَ مَنْ قَتَلَ عَلَيْهِ، وَسَبَى، وَأَنْظُرُ إِلَى عُنُقٍ مِنَ النَّاسِ، فِيهِمُ الذَّرَارِيُّ، فَخَشِيتُ أَنْ يَسْبِقُونِي إِلَى الْجَبَلِ، فَرَمَيْتُ بِسَهْمٍ بَيْنَهُمْ وَبَيْنَ الْجَبَلِ، فَلَمَّا رَأَوُا السَّهْمَ وَقَفُوا، فَجِئْتُ بِهِمْ أَسُوقُهُمْ، وَفِيهِمُ امْرَأَةٌ مِنْ بَنِي فَزَارَةَ، عَلَيْهَا قَِشْعٌ مِنْ أَدَمٍ، (قَالَ: الْقَِشْعُ النِّطَعُ)، مَعَهَا ابْنَةٌ لَهَا مِنْ أَحْسَنِ الْعَرَبِ، فَسُقْتُهُمْ حَتَّى أَتَيْتُ بِهِمْ أَبَا بَكْرٍ، فَنَفَّلَنِي أَبُو بَكْرٍ ابْنَتَهَا، فَقَدِمْنَا الْمَدِينَةَ، وَمَا كَشَفْتُ لَهَا ثَوْبًا، فَلَقِيَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي السُّوقِ، فَقَالَ: يَا سَلَمَةُ، هَبْ لِي الْمَرْأَةَ. فَقُلْتُ: يَا رَسُولَ اللَّهِ، وَاللهِ لَقَدْ أَعْجَبَتْنِي، وَمَا كَشَفْتُ لَهَا ثَوْبًا، ثُمَّ لَقِيَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْغَدِ فِي السُّوقِ، فَقَالَ لِي: يَا سَلَمَةُ، هَبْ لِي الْمَرْأَةَ، لِلهِ أَبُوكَ. فَقُلْتُ: هِيَ لَكَ يَا رَسُولَ اللَّهِ، فَوَاللهِ مَا كَشَفْتُ لَهَا ثَوْبًا، فَبَعَثَ بِهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى أَهْلِ مَكَّةَ، فَفَدَى بِهَا نَاسًا مِنَ الْمُسْلِمِينَ، كَانُوا أُسِرُوا بِمَكَّةَ."],"takhrij":"صحيح: رواه مسلم في الجهاد والسير (1755) عن زهير بن حرب، عن عمر بن يونس، عن عكرمة بن عمار، عن إياس بن سلمة بن الأكوع، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب فداء أسرى المسلمين بأسرى الكفار","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1755).","chapter_en":"Ransoming Muslim Prisoners with Disbelieving Prisoners","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الأسرى","group_en":"Collection of What Has Been Narrated Concerning Prisoners","part_no":43,"group_no":5,"chapter_no":7,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ said: We campaigned against Fazarah, and Abu Bakr was over us; the Messenger of Allah ﷺ had appointed him over us. When there remained about an hour between us and the water, Abu Bakr ordered us to rest at night, then he launched the raid and reached the water. Some were killed at the water, and captives were taken. I saw a group of people among whom were women and children, and I feared that they would reach the mountain before me. So I shot an arrow between them and the mountain. When they saw the arrow, they stopped, and I came driving them. Among them was a woman from Banu Fazarah wearing a leather covering — he said: “al-qashʿ” means a leather mat — and with her was a daughter of hers who was among the most beautiful of the Arabs. I drove them until I brought them to Abu Bakr. Abu Bakr awarded me her daughter as an extra share. We came to Medina, and I had not uncovered her garment. Then the Messenger of Allah ﷺ met me in the market and said: “O Salamah, give me the woman.” I said: “O Messenger of Allah, by Allah, she has pleased me, and I have not uncovered her garment.” Then the Messenger of Allah ﷺ met me the next day in the market and said to me: “O Salamah, give me the woman, may Allah bless your father.” I said: “She is yours, O Messenger of Allah; by Allah, I have not uncovered her garment.” The Messenger of Allah ﷺ sent her to the people of Makkah and ransomed with her some Muslims who had been captured in Makkah."]}},"tuhfa":{},"full":1,"rep":[5906,9086],"tks":"صحيح: رواه مسلم (1755)."},{"num":8007,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ قَالَ:  كَانَتْ ثَقِيفُ حُلَفَاءَ لِبَنِي عُقَيْلٍ، فَأَسَرَتْ ثَقِيفُ رَجُلَيْنِ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَسَرَ أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا مِنْ بَنِي عُقَيْلٍ، وَأَصَابُوا مَعَهُ الْعَضْبَاءَ، فَأَتَى عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُْوَ فِي الْوَثَاقِ، قَالَ: يَا مُحَمَّدُ، فَأَتَاهُ، فَقَالَ: مَا شَأْنُكَ؟ فَقَالَ: بِمَ أَخَذْتَنِي، وَبِمَ أَخَذْتَ سَابِقَةَ الْحَاجِّ؟ فَقَالَ: (إِعْظَامًا لِذَلِكَ)، أَخَذْتُكَ، بِجَرِيرَةِ حُلَفَائِكَ ثَقِيفَ. ثُمَّ انْصَرَفَ عَنْهُ، فَنَادَاهُ، فَقَالَ: يَا مُحَمَّدُ، يَا مُحَمَّدُ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَحِيمًا رَقِيقًا، فَرَجَعَ إِلَيْهِ، فَقَالَ: مَا شَأْنُكَ؟ قَالَ: إِنِّي مُسْلِمٌ، قَالَ: لَوْ قُلْتَهَا، وَأَنْتَ تَمْلِكُ أَمْرَكَ، أَفْلَحْتَ كُلَّ الْفَلَاحِ. ثُمَّ انْصَرَفَ، فَنَادَاهُ فَقَالَ: يَا مُحَمَّدُ، يَا مُحَمَّدُ، فَأَتَاهُ، فَقَالَ: مَا شَأْنُكَ؟ قَالَ: إِنِّي جَائِعٌ فَأَطْعِمْنِي، وَظَمْآنُ فَأَسْقِنِي، قَالَ: هَذِهِ حَاجَتُكَ. فَفُدِيَ بِالرَّجُلَيْنِ. قَالَ:"],"takhrij":"صحيح: رواه مسلم في النذر (1641) من طريقين عن إسماعيل بن إبراهيم، حدثنا أيوب، عن أبي قلابة، عن أبي المهلب، عن عمران بن حصين فذكره.","grade":"صحيح","chapter_ar":"باب فداء أسرى المسلمين بأسرى الكفار","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1641).","chapter_en":"Ransoming Muslim Prisoners with Disbelieving Prisoners","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الأسرى","group_en":"Collection of What Has Been Narrated Concerning Prisoners","part_no":43,"group_no":5,"chapter_no":7,"content":{"translation":{"en":["ʿImran ibn Husayn said: Thaqif were allies of Banu ʿUqayl. Thaqif captured two of the companions of the Messenger of Allah ﷺ, and the companions of the Messenger of Allah ﷺ captured a man from Banu ʿUqayl, and they also captured al-ʿAdba’ with him. The Messenger of Allah ﷺ passed by him while he was bound, and he said: “O Muhammad.” He came to him and said: “What is the matter with you?” He said: “Why have you taken me, and why have you taken the she-camel that used to precede the pilgrims?” He said, magnifying the matter: “I took you because of the crime of your allies, Thaqif.” Then he turned away from him, but he called out: “O Muhammad, O Muhammad.” The Messenger of Allah ﷺ was merciful and tender, so he returned to him and said: “What is the matter with you?” He said: “I am a Muslim.” He said: “Had you said that while you still had control over your affair, you would have attained complete success.” Then he turned away, and he called him again: “O Muhammad, O Muhammad.” He came to him and said: “What is the matter with you?” He said: “I am hungry, so feed me; and thirsty, so give me drink.” He said: “This is your need.” Then he was ransomed for the two men. The hadith continues."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1641)."},{"num":8008,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ الْأَنْصَارِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  أُعْطِيتُ خَمْسًا لَمْ يُعْطَهُنَّ أَحَدٌ قَبْلِي: كَانَ كُلُّ نَبِيٍّ يُبْعَثُ إِلَى قَوْمِهِ خَاصَّةً وَبُعِثْتُ إِلَى كُلِّ أَحْمَرَ وَأَسْوَدَ، وَأُحِلَّتْ لِيَ الْغَنَائِمُ وَلَمْ تُحَلَّ لِأَحَدٍ قَبْلِي، وَجُعِلَتْ لِيَ الْأَرْضُ طَيِّبَةً طَهُورًا وَمَسْجِدًا، فَأَيُّمَا رَجُلٍ أَدْرَكَتْهُ الصَّلَاةُ صَلَّى حَيْثُ كَانَ، وَنُصِرْتُ بِالرُّعْبِ بَيْنَ يَدَيْ مَسِيرَةِ شَهْرٍ، وَأُعْطِيتُ الشَّفَاعَةَ."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3122)، ومسلم في المساجد (521) كلاهما من طريق هشيم، أخبرنا سيّار، حدثنا يزيد الفقير، عن جابر بن عبد الله فذكره. والسياق لمسلم، واقتصر البخاري على الغنائم.","grade":"متفق عليه","chapter_ar":"باب تحليل الغنائم لهذه الأمة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3122) and Muslim (521).","chapter_en":"The Permissibility of Spoils for This Ummah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: The Messenger of Allah ﷺ said: “I have been given five things that no one before me was given: every prophet used to be sent to his own people specifically, but I was sent to every red and black person; spoils were made lawful for me, though they were not lawful for anyone before me; the earth was made good, purifying, and a place of prayer for me, so any man whom prayer reaches may pray wherever he is; I was supported by awe before me for a month’s journey; and I was given intercession.”"]},"intro":{"ar":["قال تعالى:","(وَعَدَكُمُ اللهُ مَغَانِمَ كَثِيرَةً تَأْخُذُونَهَا) [الفتح: ٢٠]."],"en":["Allah Most High said:","“Allah has promised you many spoils that you will take.” [al-Fath: 20]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12347,12905,13117,13231],"tks":"متفق عليه: رواه البخاري (3122)، ومسلم (521)."},{"num":8009,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَالَ: فُضِّلْتُ عَلَى الأَنْبِيَاءِ بِسِتٍّ: أُعْطِيتُ جَوَامِعَ الْكَلِمِ، وَنُصِرْتُ بِالرُّعْبِ، وَأُحِلَّتْ لِيَ الْغَنَائِمُ، وَجُعِلَتْ لِيَ الأَرْضُ طَهُورًا وَمَسْجِدًا، وَأُرْسِلْتُ إِلَى الْخَلْقِ كَافَّةً، وَخُتِمَ بِيَ النَّبِيُّونَ."],"takhrij":"صحيح: رواه مسلم في المساجد (523: 5) من طريق إسماعيل بن جعفر، عن العلاء، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب تحليل الغنائم لهذه الأمة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Book of Mosques (523:5), through Ismaʿil ibn Jaʿfar, from al-ʿAla’, from his father, from Abu Hurayrah, who mentioned it.","chapter_en":"The Permissibility of Spoils for This Ummah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “I have been favored over the prophets with six things: I have been given concise comprehensive speech; I have been supported by awe; spoils have been made lawful for me; the earth has been made for me a purifier and a place of prayer; I have been sent to all creation; and the prophets have been sealed with me.”"]}},"tuhfa":{},"full":1,"rep":[731,796,12026,12348,12906,13078],"tks":"صحيح: رواه مسلم (523: 5)."},{"num":8010,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أُعْطِيتُ خَمْسًا لَمْ يُعْطَهُنَّ أحدٌ قَبْلِي: بُعِثْتُ إِلَى الأَحْمَرِ وَالأَسْوَدِ، وَجُعِلَتْ لِي الأَرْضُ طَهُورًا وَمَسْجِدًا، وَأُحِلَّتْ لِيَ الْغَنَائِمُ وَلَمْ تَحِلَّ لأَحَدٍ قَبْلِي، وَنُصِرْتُ بِالرُّعْبِ فَيَرْعَبُ الْعَدُوُّ وهو مِنِّي مَسِيرَةِ شَهْرٍ، وَقِيلَ لِي: سَلْ تُعْطَهْ، وَاخْتَبَأْتُ دَعْوَتِي شَفَاعَةً لأُمَّتِي، فَهِيَ نَائِلَةٌ مِنْكُمْ إِنْ شَاءَ اللَّهُ تَعَالَى مِنْ لَمْ يُشْرِكْ بِاللهِ شَيْئًا."],"takhrij":"صحيح: رواه أبو داود (489)، وأحمد (21314، 21299) واللفظ له-، وصحّحه ابن حبان (6462)، والحاكم (3587) من طرق عن سليمان الأعمش، عن مجاهد، عن عبيد بن عمير الليثي، عن أبي ذر فذكره.","grade":"صحيح","chapter_ar":"باب تحليل الغنائم لهذه الأمة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (489), Ahmad (21299, 21314) — this is his wording — and authenticated by Ibn Hibban (6462), and narrated by al-Hakim (3587).","chapter_en":"The Permissibility of Spoils for This Ummah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Abu Dharr said: The Messenger of Allah ﷺ said: “I have been given five things that no one before me was given: I was sent to the red and the black; the earth was made for me a purifier and a place of prayer; spoils were made lawful for me, though they were not lawful for anyone before me; I was supported by awe, so the enemy is frightened while he is a month’s journey away from me; and it was said to me: Ask, and you will be given. So I saved my supplication as intercession for my ummah, and it will reach, if Allah Most High wills, those among you who did not associate anything with Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (489)، وأحمد (21299، 21314) — واللفظ له — وصححه ابن حبان (6462)، والحاكم (3587)."},{"num":8011,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فَضَّلَنِي رَبِّي عَلَى الْأَنْبِيَاءِ، أَوْ قَالَ: عَلَى الْأُمَمِ، بِأَرْبَعٍ. قَالَ: أُرْسِلْتُ إِلَى النَّاسِ كَافَّةً، وَجُعِلَتِ الْأَرْضُ كُلُّهَا لِي وَلِأُمَّتِي مَسْجِدًا وَطَهُورًا، فَأَيْنَمَا أَدْرَكَتْ رَجُلًا مِنْ أُمَّتِي الصَّلَاةُ فَعِنْدَهُ مَسْجِدُهُ، وَعِنْدَهُ طَهُورُهُ، وَنُصِرْتُ بِالرُّعْبِ مَسِيرَةَ شَهْرٍ، يَقْذِفُهُ فِي قُلُوبِ أَعْدَائِي، وَأَحَلَّ لَنَا الْغَنَائِمَ."],"takhrij":"حسن: رواه أحمد (22137، 22209)، والترمذي (1553) والبيهقي (1/212، 2/433-434) من طرق عن سليمان التيمي، عن سيّار، عن أبي أمامة فذكره.","grade":"حسن","chapter_ar":"باب تحليل الغنائم لهذه الأمة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (22137, 22209), al-Tirmidhi (1553), and al-Bayhaqi (1/212, 2/433–434).","chapter_en":"The Permissibility of Spoils for This Ummah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Abu Umamah narrated that the Messenger of Allah ﷺ said: “My Lord favored me over the prophets” — or he said, “over the nations” — “with four things.” He said: “I was sent to all people; the whole earth was made for me and my ummah a place of prayer and a purifier, so wherever prayer reaches a man from my ummah, there is his place of prayer and there is his purification; I was supported by awe for a month’s journey, which He casts into the hearts of my enemies; and spoils were made lawful for us.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9635],"tks":"حسن: رواه أحمد (22137، 22209)، والترمذي (1553)، والبيهقي (1/212، 2/433-434)."},{"num":8012,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ غَزْوَةِ تَبُوكَ قَامَ مِنَ اللَّيْلِ يُصَلِّي، فَاجْتَمَعَ وَرَاءَهُ رِجَالٌ مِنْ أَصْحَابِهِ يَحْرُسُونَهُ، حَتَّى إِذَا صَلَّى وَانْصَرَفَ إِلَيْهِمْ، فَقَالَ لَهُمْ: لَقَدْ أُعْطِيتُ اللَّيْلَةَ خَمْسًا، مَا أُعْطِيَهُنَّ أَحَدٌ قَبْلِي: أَمَّا أَنَا فَأُرْسِلْتُ إِلَى النَّاسِ كُلِّهِمْ عَامَّةً، وَكَانَ مَنْ قَبْلِي إِنَّمَا يُرْسَلُ إِلَى قَوْمِهِ، وَنُصِرْتُ عَلَى الْعَدُوِّ بِالرُّعْبِ، وَلَوْ كَانَ بَيْنِي وَبَيْنَهُمْ مَسِيرَةُ شَهْرٍ لَمُلِئَ مِنْهُ رُعْبًا، وَأُحِلَّتْ لِي الْغَنَائِمُ آكُلُهَا، وَكَانَ مَنْ قَبْلِي يُعَظِّمُونَ أَكْلَهَا، كَانُوا يُحْرِقُونَهَا، وَجُعِلَتْ لِي الْأَرْضُ مَسَاجِدَ وَطَهُورًا، أَيْنَمَا أَدْرَكَتْنِي الصَّلَاةُ تَمَسَّحْتُ وَصَلَّيْتُ، وَكَانَ مَنْ قَبْلِي يُعَظِّمُونَ ذَلِكَ، إِنَّمَا كَانُوا يُصَلُّونَ فِي كَنَائِسِهِمْ وَبِيَعِهِمْ، وَالْخَامِسَةُ هِيَ مَا هِيَ، قِيلَ لِي: سَلْ فَإِنَّ كُلَّ نَبِيٍّ قَدْ سَأَلَ، فَأَخَّرْتُ مَسْأَلَتِي إِلَى يَوْمِ الْقِيَامَةِ، فَهِيَ لَكُمْ وَلِمَنْ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ."],"takhrij":"حسن: رواه أحمد (7068) عن قتيبة بن سعيد، حدثنا بكر بن مضر، عن ابن الهاد، عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب تحليل الغنائم لهذه الأمة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (7068).","chapter_en":"The Permissibility of Spoils for This Ummah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather, that during the year of the expedition of Tabuk, the Messenger of Allah ﷺ stood at night praying. Some men from his companions gathered behind him to guard him. When he finished praying and turned to them, he said: “Tonight I have been given five things that no one before me was given: as for me, I was sent to all people generally, while those before me were only sent to their own people; I was supported against the enemy by awe, so even if there were a month’s journey between me and them, he would be filled with fear; spoils were made lawful for me to eat, while those before me regarded eating them as a grave matter and used to burn them; the earth was made for me places of prayer and purification, so wherever prayer reaches me, I wipe for purification and pray, while those before me regarded that as a grave matter and used to pray only in their churches and synagogues; and the fifth — what is it? It was said to me: Ask, for every prophet has asked. So I delayed my request until the Day of Resurrection, and it is for you and for whoever testifies that there is no god but Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[799,925,9634],"tks":"حسن: رواه أحمد (7068)."},{"num":8013,"demo":false,"sanad":"","matn":["حَدَّثَنَا أَبُو هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَ أَحَادِيثَ مِنْهَا: وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  غَزَا نَبِيٌّ مِنَ الْأَنْبِيَاءِ فَقَالَ لِقَوْمِهِ: لَا يَتْبَعْنِي رَجُلٌ قَدْ مَلَكَ بُضْعَ امْرَأَةٍ، وَهُوَ يُرِيدُ أَنْ يَبْنِيَ بِهَا، وَلَمَّا يَبْنِ، وَلَا آخَرُ قَدْ بَنَى بُنْيَانًا، وَلَمَّا يَرْفَعْ سُقُفَهَا، وَلَا آخَرُ قَدِ اشْتَرَى غَنَمًا، أَوْ خَلِفَاتٍ، وَهُوَ مُنْتَظِرٌ وِلَادَهَا. قَالَ: فَغَزَا، فَأَدْنَى لِلْقَرْيَةِ حِينَ صَلَاةِ الْعَصْرِ، أَوْ قَرِيبًا مِنْ ذَلِكَ، فَقَالَ لِلشَّمْسِ: أَنْتِ مَأْمُورَةٌ، وَأَنَا مَأْمُورٌ، اللَّهُمَّ احْبِسْهَا عَلَيَّ شَيْئًا، فَحُبِسَتْ عَلَيْهِ حَتَّى فَتَحَ اللَّهُ عَلَيْهِ. قَالَ: فَجَمَعُوا مَا غَنِمُوا، فَأَقْبَلَتِ النَّارُ لِتَأْكُلَهُ، فَأَبَتْ أَنْ تَطْعَمَهُ، فَقَالَ: فِيكُمْ غُلُولٌ، فَلْيُبَايِعْنِي مِنْ كُلِّ قَبِيلَةٍ رَجُلٌ، فَبَايَعُوهُ، فَلَصِقَتْ يَدُ رَجُلٍ بِيَدِهِ، فَقَالَ: فِيكُمُ الْغُلُولُ، فَلْتُبَايِعْنِي قَبِيلَتُكَ، فَبَايَعَتْهُ، قَالَ: فَلَصِقَتْ بِيَدِ رَجُلَيْنِ أَوْ ثَلَاثَةٍ، فَقَالَ: فِيكُمُ الْغُلُولُ، أَنْتُمْ غَلَلْتُمْ، قَالَ: فَأَخْرَجُوا لَهُ مِثْلَ رَأْسِ بَقَرَةٍ مِنْ ذَهَبٍ، قَالَ: فَوَضَعُوهُ فِي الْمَالِ، وَهُوَ بِالصَّعِيدِ، فَأَقْبَلَتِ النَّارُ فَأَكَلَتْهُ، فَلَمْ تَحِلَّ الْغَنَائِمُ لِأَحَدٍ مِنْ قَبْلِنَا، ذَلِكَ بِأَنَّ اللهَ تَبَارَكَ وَتَعَالَى رَأَى ضَعْفَنَا وَعَجْزَنَا، فَطَيَّبَهَا لَنَا."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3124)، ومسلم في الجهاد والسير (1747) كلاهما من طريق ابن المبارك- وزاد مسلم : وعبد الرزاق- عن معمر، عن همام بن منبه، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب الغنائم في الأمم السابقة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3124) and Muslim (1747).","chapter_en":"Spoils Among Previous Nations","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah narrated from the Messenger of Allah ﷺ, and he mentioned several hadiths, among them that the Messenger of Allah ﷺ said: “A prophet from among the prophets went on campaign and said to his people: ‘No man should follow me who has contracted marriage with a woman and wishes to consummate with her but has not yet done so; nor another who has built a building but has not yet raised its roof; nor another who has bought sheep or pregnant she-camels and is waiting for their offspring.’ He said: So he went on campaign and approached the town around the time of ʿAsr prayer, or close to that. He said to the sun: ‘You are commanded, and I am commanded. O Allah, hold it back for me for a little while.’ So it was held back for him until Allah granted him victory. He said: Then they gathered what they had taken as spoils, and the fire came to consume it, but it refused to eat it. He said: ‘Among you is stolen spoil, so let one man from every tribe pledge allegiance to me.’ They pledged allegiance to him, and the hand of one man stuck to his hand. He said: ‘Among you is the stolen spoil; let your tribe pledge allegiance to me.’ So his tribe pledged allegiance to him. He said: The hands of two or three men stuck to his hand. He said: ‘Among you is the stolen spoil; you are the ones who stole from the spoils.’ He said: So they brought out for him something like the head of a cow made of gold. He said: They placed it among the wealth on the open ground, and the fire came and consumed it. Spoils were not lawful for anyone before us. That is because Allah, Blessed and Most High, saw our weakness and incapacity, so He made them lawful for us.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12419],"tks":"متفق عليه: رواه البخاري (3124)، ومسلم (1747)."},{"num":8014,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ بن رِبْعِيٍّ أنه قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ حُنَيْنٍ فَلَمَّا الْتَقَيْنَا كَانَتْ لِلْمُسْلِمِينَ جَوْلَةٌ قَالَ: فَرَأَيْتُ رَجُلًا مِنَ الْمُشْرِكِينَ قَدْ عَلَا رَجُلًا مِنَ الْمُسْلِمِينَ، قَالَ: فَاسْتَدَرْتُ لَهُ حَتَّى أَتَيْتُهُ مِنْ وَرَائِهِ فَضَرَبْتُهُ بِالسَّيْفِ عَلَى حَبْلِ عَاتِقِهِ، فأقبل عَلَيَّ فَضَمَّنِي ضَمَّةً، وَجَدْتُ مِنْهَا رِيحَ الْمَوْتِ، ثُمَّ أَدْرَكَهُ الْمَوْتُ، فَأَرْسَلَنِي، قَالَ: فَلَقِيتُ عُمَرَ بْنَ الْخَطَّابِ فَقُلْتُ: مَا بَالُ النَّاسَ؟ فَقَالَ: أَمْرُ اللهِ ثُمَّ ان النَّاسَ رَجَعُوا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَنْ قَتَلَ قَتِيلًا لَهُ عَلَيْهِ بَيِّنَةٌ فَلَهُ سَلَبُهُ، قَالَ: فَقُمْتُ ثُمَّ قُلْتُ: مَنْ يَشْهَدُ لِي؟ ثُمَّ جَلَسْتُ، ثُمَّ قَالَ: من قَتَلَ قَتِيلًا لَهُ عَلَيْهِ بَيِّنَةٌ فَلَهُ سَلَبُهُ، قَالَ: فَقُمْتُ ثُمَّ قُلْتُ مَنْ يَشْهَدُ لِي؟ ثُمَّ جَلَسْتُ. ثُمَّ قَالَ ذَلِكَ الثَّالِثَةَ، فَقُمْتُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَالِكَ يَا أَبَا قَتَادَةَ؟ قَالَ: فاقتصصت عَلَيْهِ الْقِصَّةَ فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: صَدَقَ يَا رَسُولَ اللَّهِ! وسلب ذَلِكَ الْقَتِيلِ عِنْدِي، فَأَرْضِهِ عَنْهُ يَا رَسُولَ اللَّهِ. فَقَالَ أَبُو بَكْرٍ: لَا هاء اللهِ إِذًا لَا يَعْمِدُ إِلَى أَسَدٍ مِنْ أُسُْدِ اللهِ يُقَاتِلُ عَنِ اللَّهِ ورسوله فَيُعْطِيكَ سَلَبَهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : صَدَقَ فَأَعْطِهِ إِيَّاهُ فأعطانيه، فَبِعْتُ الدِّرْعَ، فاشتريت بِهِ مَخْرَفًا فِي بَنِي سَلِمَةَ، فَإِنَّهُ لَأَوَّلُ مالٍ تَأَثَّلْتُهُ فِي الْإِسْلَامِ."],"takhrij":"متفق عليه: رواه مالك في الجهاد (18) عن يحيى بن سعيد، عن عمر بن كثير بن أفلح، عن أبي محمد مولى أبي قتادة، عن أبي قتادة بن ربعي أنه قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في حكم السلب","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (18), al-Bukhari (3142), and Muslim (1751).","chapter_en":"What Has Been Reported Concerning the Ruling on the Slain Enemy’s Personal Effects","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Abu Qatadah ibn Ribʿi said: We went out with the Messenger of Allah ﷺ in the year of Hunayn. When we met the enemy, the Muslims had a moment of retreat. He said: I saw a man from the polytheists overpowering a man from the Muslims, so I went around until I came behind him and struck him with the sword on the vein of his shoulder. He turned toward me and embraced me with a grip from which I felt the scent of death. Then death overtook him and he released me. He said: I met ʿUmar ibn al-Khattab and said: “What is the matter with the people?” He said: “The command of Allah.” Then the people returned, and the Messenger of Allah ﷺ said: “Whoever kills an enemy combatant and has proof of it, then his personal effects belong to him.” He said: I stood and said: “Who will testify for me?” Then I sat down. Then he said: “Whoever kills an enemy combatant and has proof of it, then his personal effects belong to him.” He said: I stood and said: “Who will testify for me?” Then I sat down. Then he said it a third time, so I stood. The Messenger of Allah ﷺ said: “What is the matter with you, O Abu Qatadah?” He said: I told him the story. A man from the people said: “He has spoken the truth, O Messenger of Allah. The slain man’s personal effects are with me, so satisfy him on my behalf, O Messenger of Allah.” Abu Bakr said: “No, by Allah, then he would not go to one of the lions of Allah who fights for Allah and His Messenger and give you his spoil.” The Messenger of Allah ﷺ said: “He has spoken the truth, so give it to him.” So he gave it to me. I sold the armor and bought with it a garden among Banu Salamah, and it was the first wealth I acquired in Islam."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (18)، والبخاري (3142)، ومسلم (1751)."},{"num":8015,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ أَنَّهُ قَالَ:  بَيْنَا أَنَا وَاقِفٌ فِي الصَّفِّ يَوْمَ بَدْرٍ نَظَرْتُ عَنْ يَمِينِي وَشِمَالِي، فَإِذَا أَنَا بَيْنَ غُلَامَيْنِ مِنَ الْأَنْصَارِ حَدِيثَةٍ أَسْنَانُهُمَا، تَمَنَّيْتُ لَوْ كُنْتُ بَيْنَ أَضْلَعَ مِنْهُمَا، فَغَمَزَنِي أَحَدُهُمَا، فَقَالَ: يَا عَمِّ، هَلْ تَعْرِفُ أَبَا جَهْلٍ؟ قَالَ: قُلْتُ: نَعَمْ، وَمَا حَاجَتُكَ إِلَيْهِ يَا ابْنَ أَخِي؟ قَالَ: أُخْبِرْتُ أَنَّهُ يَسُبُّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَالَّذِي نَفْسِي بِيَدِهِ لَئِنْ رَأَيْتُهُ لَا يُفَارِقُ سَوَادِي سَوَادَهُ حَتَّى يَمُوتَ الْأَعْجَلُ مِنَّا، قَالَ: فَتَعَجَّبْتُ لِذَلِكَ، فَغَمَزَنِي الْآخَرُ، فَقَالَ: مِثْلَهَا، قَالَ: فَلَمْ أَنْشَبْ أَنْ نَظَرْتُ إِلَى أَبِي جَهْلٍ يَزُولُ فِي النَّاسِ، فَقُلْتُ: أَلَا تَرَيَانِ؟ هَذَا صَاحِبُكُمَا الَّذِي تَسْأَلَانِ عَنْهُ، قَالَ: فَابْتَدَرَاهُ، فَضَرَبَاهُ بِسَيْفَيْهِمَا حَتَّى قَتَلَاهُ، ثُمَّ انْصَرَفَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَاهُ فَقَالَ: أَيُّكُمَا قَتَلَهُ؟ فَقَالَ كُلُّ وَاحِدٍ مِنْهُمَا: أَنَا قَتَلْتُ، فَقَالَ: هَلْ مَسَحْتُمَا سَيْفَيْكُمَا؟ قَالَا: لَا، فَنَظَرَ فِي السَّيْفَيْنِ فَقَالَ: كِلَاكُمَا قَتَلَهُ. وَقَضَى بِسَلَبِهِ لِمُعَاذِ بْنِ عَمْرِو بْنِ الْجَمُوحِ، (وَالرَّجُلَانِ: مُعَاذُ بْنُ عَمْرِو بْنِ الْجَمُوحِ، وَمُعَاذُ بْنُ عَفْرَاءَ."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3141)، ومسلم في الجهاد والسير (1752) كلاهما من طريق يوسف بن الماجشون، عن صالح بن إبراهيم بن عبد الرحمن بن عوف، عن أبيه، عن عبد الرحمن بن عوف فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في حكم السلب","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3141) and Muslim (1752).","chapter_en":"What Has Been Reported Concerning the Ruling on the Slain Enemy’s Personal Effects","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["ʿAbd al-Rahman ibn ʿAwf said: While I was standing in the row on the day of Badr, I looked to my right and left and found myself between two young boys from the Ansar, both very young. I wished that I were between two men stronger than them. One of them nudged me and said: “Uncle, do you know Abu Jahl?” I said: “Yes. What need do you have of him, my nephew?” He said: “I have been told that he insults the Messenger of Allah ﷺ. By the One in whose hand is my soul, if I see him, my body will not leave his body until the one of us whose term is sooner dies.” He said: I was amazed at that. Then the other nudged me and said the same. He said: Soon after, I saw Abu Jahl moving about among the people, so I said: “Do you not see? This is the man you were asking about.” They rushed toward him and struck him with their swords until they killed him. Then they returned to the Messenger of Allah ﷺ and informed him. He said: “Which of you killed him?” Each one said: “I killed him.” He said: “Have you wiped your swords?” They said: “No.” He looked at the two swords and said: “Both of you killed him.” He awarded his personal effects to Muʿadh ibn ʿAmr ibn al-Jamuh. The two men were Muʿadh ibn ʿAmr ibn al-Jamuh and Muʿadh ibn ‘Afra’."]},"buhuth":{"en":["His saying, “my blackness will not leave his blackness,” means: my person will not leave his person. His saying, “the sooner of us,” means the one whose death is nearer."]}},"tuhfa":{},"full":1,"dr":1,"rep":[8763],"tks":"متفق عليه: رواه البخاري (3141)، ومسلم (1752)."},{"num":8016,"demo":false,"sanad":"","matn":["عَنْ عَوْفِ بْنِ مَالِكٍ قَالَ:  قَتَلَ رَجُلٌ مِنْ حِمْيَرَ رَجُلًا مِنَ الْعَدُوِّ، فَأَرَادَ سَلَبَهُ، فَمَنَعَهُ خَالِدُ بْنُ الْوَلِيدِ، وَكَانَ وَالِيًا عَلَيْهِمْ، فَأَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَوْفُ بْنُ مَالِكٍ فَأَخْبَرَهُ، فَقَالَ لِخَالِدٍ: مَا مَنَعَكَ أَنْ تُعْطِيَهُ سَلَبَهُ؟ قَالَ: اسْتَكْثَرْتُهُ يَا رَسُولَ اللَّهِ، قَالَ: ادْفَعْهُ إِلَيْهِ. فَمَرَّ خَالِدٌ، بِعَوْفٍ، فَجَرَّ بِرِدَائِهِ، ثُمَّ قَالَ: هَلْ أَنْجَزْتُ لَكَ مَا ذَكَرْتُ لَكَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَسَمِعَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَاسْتُغْضِبَ فَقَالَ: لَا تُعْطِهِ يَا خَالِدُ، لَا تُعْطِهِ يَا خَالِدُ، هَلْ أَنْتُمْ تَارِكُونَ لِي أُمَرَائِي؟ إِنَّمَا مَثَلُكُمْ وَمَثَلُهُمْ كَمَثَلِ رَجُلٍ اسْتُرْعِيَ إِبِلًا أَوْ غَنَمًا فَرَعَاهَا، ثُمَّ تَحَيَّنَ سَقْيَهَا، فَأَوْرَدَهَا حَوْضًا، فَشَرَعَتْ فِيهِ، فَشَرِبَتْ صَفْوَهُ، وَتَرَكَتْ كَدِْرَهُ، فَصَفْوُهُ لَكُمْ، وَكَدِْرُهُ عَلَيْهِمْ."],"takhrij":"صحيح: رواه مسلم في الجهاد والسير (1753: 43) عن أبي الطاهر أحمد بن عمرو بن سرح، أخبرنا عبد الله بن وهب، أخبرني معاوية بن صالح، عن عبدالرحمن بن جبير، عن أبيه، عن عوف بن مالك قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في حكم السلب","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1753:43).","chapter_en":"What Has Been Reported Concerning the Ruling on the Slain Enemy’s Personal Effects","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["ʿAwf ibn Malik said: A man from Himyar killed a man from the enemy and wanted his personal effects, but Khalid ibn al-Walid, who was the commander over them, prevented him. ʿAwf ibn Malik came to the Messenger of Allah ﷺ and informed him. He said to Khalid: “What prevented you from giving him his personal effects?” He said: “I considered it too much, O Messenger of Allah.” He said: “Give it to him.” Then Khalid passed by ʿAwf, pulled his cloak, and said: “Did I not fulfill for you what I mentioned to you from the Messenger of Allah ﷺ?” The Messenger of Allah ﷺ heard him and became angry, saying: “Do not give it to him, O Khalid. Do not give it to him, O Khalid. Will you not leave my commanders to me? Your example and theirs is only like that of a man who is appointed to tend camels or sheep. He tends them, then chooses the time to water them and brings them to a basin. They enter it and drink its clear water, leaving its muddy water. Its clear water is for you, and its muddy water is upon them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1753: 43)."},{"num":8017,"demo":false,"sanad":"","matn":["عن سَلَمَةَ بن الأكوع عَنْ أَبِيهِ، قَالَ: أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَيْنٌ مِنَ الْمُشْرِكِينَ، وَهْوَ فِي سَفَرٍ، فَجَلَسَ عِنْدَ أَصْحَابِهِ يَتَحَدَّثُ، ثُمَّ انْفَتَلَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اطْلُبُوهُ وَاقْتُلُوهُ. فَقَتَلَهُ فَنَفَّلَهُ سَلَبَهُ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (3051)، ومسلم في الجهاد والسير (1754: 45) كلاهما من حديث إياس بن سلمة بن الأكوع، عن أبيه فذكره. واللفظ للبخاري، وهو عند مسلم بطوله. وفيه قال رسول الله صلى الله عليه وسلم: من قتل الرجل؟ قالوا: ابن الأكوع. قال: له سلبه أجمع.","grade":"متفق عليه","chapter_ar":"باب ما جاء في حكم السلب","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3051) and Muslim (1754:45). The wording is al-Bukhari’s, and it appears at length in Muslim.","chapter_en":"What Has Been Reported Concerning the Ruling on the Slain Enemy’s Personal Effects","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ said: A spy from the polytheists came to the Prophet ﷺ while he was on a journey. He sat with his companions and spoke, then turned away and left. The Prophet ﷺ said: “Pursue him and kill him.” So he killed him, and the Prophet ﷺ awarded him his personal effects as extra spoil."]},"buhuth":{"ar":["وفيه قال رسول الله ﷺ: من قتل الرجل؟ قالوا: ابن الأكوع. قال: له سلبه أجمع."],"en":["In it, the Messenger of Allah ﷺ said: “Who killed the man?” They said: “Ibn al-Akwaʿ.” He said: “All of his personal effects belong to him.”"]}},"tuhfa":{},"full":1,"rep":[7888],"tks":"متفق عليه: رواه البخاري (3051)، ومسلم (1754: 45). واللفظ للبخاري، وهو عند مسلم بطوله."},{"num":8018,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ هَوَازِنَ جَاءَتْ يَوْمَ حُنَيْنٍ بِالصِّبْيَانِ وَالنِّسَاءِ وَالْإِبِلِ وَالنَّعَمِ، فَجَعَلُوهُمْ صُفُوفًا يُكَثِّرُونَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا الْتَقَوْا وَلَّى الْمُسْلِمُونَ مُدْبِرِينَ، كَمَا قَالَ اللَّهُ عَزَّ وَجَلَّ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا عِبَادَ اللَّهِ، أَنَا عَبْدُ اللَّهِ وَرَسُولُهُ، يَا مَعْشَرَ الْأَنْصَارِ، أَنَا عَبْدُ اللَّهِ وَرَسُولُهُ، فَهَزَمَ اللهُ الْمُشْرِكِينَ.","قَالَ عَفَّانُ: وَلَمْ يَضْرِبُوا بِسَيْفٍ، وَلَمْ يَطْعَنُوا بِرُمْحٍ، وَقَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَئِذٍ: مَنْ قَتَلَ كَافِرًا فَلَهُ سَلَبُهُ فَقَتَلَ أَبُو طَلْحَةَ يَوْمَئِذٍ عِشْرِينَ رَجُلًا وَأَخَذَ أَسْلَابَهُمْ.","قَالَ: وَقَالَ أَبُو قَتَادَةَ: يَا رَسُولَ اللَّهِ! ضَرَبْتُ رَجُلًا عَلَى حَبْلِ الْعَاتِقِ وَعَلَيْهِ دِرْعٌ، فَأُجْهِضْتُ عَنْهُ، فَانْظُرْ مَنْ أَخَذَهَا، فَقَامَ رَجُلٌ، فَقَالَ: أَنَا أَخَذْتُهَا، فَأَرْضِهِ مِنْهَا، وَأَعْطِنِيهَا، قَالَ: وَكَانَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَا يُسْأَلُ شَيْئًا إِلَّا أَعْطَاهُ، أَوْ سَكَتَ، فَسَكَتَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ عُمَرُ: لَا وَاللَّهِ لَا يُفِيئُهَا اللَّهُ عَلَى أَسَدٍ مِنْ أُسْدِهِ، وَيُعْطِيكَهَا، فَضَحِكَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: صَدَقَ عُمَرُ."],"takhrij":"صحيح: رواه أحمد (12977، 13975)، وابن حبان (4838) من طرق عن حماد بن سلمة، أخبرنا إسحاق بن عبد الله بن أبي طلحة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في حكم السلب","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (12977, 13975) and Ibn Hibban (4838).","chapter_en":"What Has Been Reported Concerning the Ruling on the Slain Enemy’s Personal Effects","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Malik narrated that Hawazin came on the day of Hunayn with children, women, camels, and livestock, and placed them in rows in order to make their numbers appear great against the Messenger of Allah ﷺ. When the two sides met, the Muslims turned away in retreat, as Allah, Mighty and Majestic, said. The Messenger of Allah ﷺ said: “O servants of Allah, I am the servant of Allah and His Messenger. O Ansar, I am the servant of Allah and His Messenger.” Then Allah defeated the polytheists. ʿAffan said: They did not strike with a sword nor thrust with a spear. The Messenger of Allah ﷺ said that day: “Whoever kills a disbeliever, his personal effects belong to him.” Abu Talhah killed twenty men that day and took their personal effects. He said: Abu Qatadah said: “O Messenger of Allah, I struck a man on the vein of the shoulder while he was wearing armor, and I knocked him away from it, so look to see who took it.” A man stood and said: “I took it, so satisfy him from it and give it to me.” He said: The Messenger of Allah ﷺ was not asked for anything except that he gave it or remained silent. ʿUmar said: “No, by Allah. Allah would not grant it as fay’ to one of His lions and then give it to you.” The Messenger of Allah ﷺ laughed and said: “Umar has spoken the truth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (12977، 13975)، وابن حبان (4838)."},{"num":8019,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ بَدْرٍ: مَنْ فَعَلَ كَذَا وَكَذَا فَلَهُ مِنَ النَّفَلِ كَذَا وَكَذَا قَالَ: فَتَقَدَّمَ الْفِتْيَانُ وَلَزِمَ الْمَشْيَخَةُ الرَّايَاتِ، فَلَمْ يَبْرَحُوهَا فَلَمَّا فَتَحَ اللَّهُ عَلَيْهِمْ قَالَ الْمَشْيَخَةُ: كُنَّا ردءا لَكُمْ لَوِ انْهَزَمْتُمْ لفئتم إِلَيْنَا فَلَا تذهبوا بِالْمَغْنَمِ وَنَبْقَى، فَأَبَى الْفِتْيَانِ وَقَالُوا: جَعَلَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَنَا فَأَنْزَلَ ﴿يَسْأَلُونَكَ عَنِ الْأَنْفَالِ قُلِ الْأَنْفَالُ لِلَّهِ وَالرَّسُولِ فَاتَّقُوا اللَّهَ وَأَصْلِحُوا ذَاتَ بَيْنِكُمْ وَأَطِيعُوا اللَّهَ وَرَسُولَهُ إِنْ كُنْتُمْ مُؤْمِنِينَ﴾ [سورة الأنفال: 1] يَقُولُ: فَكَانَ ذَلِكَ خَيْرًا لَهُمْ، فَكَذَلِكَ أَيْضًا فَأَطِيعُونِي؛ فَإِنِّي أَعْلَمُ بِعَاقِبَةِ هَذَا مِنْكُمْ.","وفي لفظ: من قتل قتيلا فله كذا وكذا، ومن أسر أسيرا فله كذا وكذا. وزاد في رواية: فقسمها رسول الله صلى الله عليه وسلم بالسواء."],"takhrij":"صحيح: رواه أبو داود (2737)، والحاكم (2594) -وعنه البيهقي (12712)- كلاهما من طريق خالد بن عبد الله الواسطي، عن داود بن أبي هند، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في حكم السلب","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2737), al-Hakim (2594), and from him al-Bayhaqi (6/291).","chapter_en":"What Has Been Reported Concerning the Ruling on the Slain Enemy’s Personal Effects","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ said on the day of Badr: “Whoever does such-and-such will have such-and-such from the extra share.” He said: The young men advanced, while the elders stayed with the banners and did not leave them. When Allah granted them victory, the elders said: “We were a support for you; if you had been defeated, you would have returned to us. So do not take the spoils while we remain behind.” The young men refused and said: “The Messenger of Allah ﷺ assigned it to us.” So Allah revealed: “They ask you about the spoils. Say: The spoils belong to Allah and the Messenger, so fear Allah, reconcile between yourselves, and obey Allah and His Messenger if you are believers.” [al-Anfal: 1] He said: This was better for them; so likewise, obey me, for I know the outcome of this better than you do. In another wording: “Whoever kills an enemy combatant will have such-and-such, and whoever captures a prisoner will have such-and-such.” Another narration adds: The Messenger of Allah ﷺ divided it equally."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2737)، والحاكم (2594)، وعنه البيهقي (12712)."},{"num":8020,"demo":false,"sanad":"","matn":["عَنْ عَوْفِ بْنِ مَالِكٍ الأَشْجَعِيِّ، وَخَالِدِ بْنِ الْوَلِيدِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى بِالسَّلَبِ لِلْقَاتِلِ، وَلَمْ يُخَمِّسِ السَّلَبَ."],"takhrij":"صحيح: رواه أبو داود (2721)- ومن طريقه البيهقي (12782)- عن سعيد بن منصور (2698)، حدثنا إسماعيل بن عياش، عن صفوان بن عمرو، عن عبدالرحمن بن جبير بن نفير، عن أبيه، عن عوف بن مالك الأشجعي وخالد بن الوليد فذكراه.","grade":"صحيح","chapter_ar":"باب أن السلب لا يخمس","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2721) and Saʿid ibn Mansur (2698), and through Abu Dawud by al-Bayhaqi (6/310).","chapter_en":"The Slain Enemy’s Personal Effects Are Not Subject to Khums","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":4,"content":{"translation":{"en":["ʿAwf ibn Malik and Khalid ibn al-Walid narrated that the Messenger of Allah ﷺ judged that the slain enemy’s personal effects belong to the killer, and he did not take a fifth from the personal effects."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2721)، وسعيد بن منصور (2698)، ومن طريق أبي داود رواه البيهقي (12782)."},{"num":8021,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: ذَهَبَ فَرَسٌ لَهُ، فَأَخَذَهُ الْعَدُوُّ، فَظَهَرَ عَلَيْهِ الْمُسْلِمُونَ فَرُدَّ عَلَيْهِ فِي زَمَنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَبَقَ عَبْدٌ لَهُ، فَلَحِقَ بِالرُّومِ، فَظَهَرَ عَلَيْهِمُ الْمُسْلِمُونَ، فَرَدَّهُ عَلَيْهِ خَالِدُ بْنُ الْوَلِيدِ بَعْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (3067) قال: قال ابن نمير: حدثنا عبيد الله، عن نافع، عن ابن عمر، فذكره.","grade":"صحيح","chapter_ar":"باب مال المسلم إذا أصابه العدو ثم غنمه المسلمون فصاحبه أحق به","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3067).","chapter_en":"If the Enemy Seizes a Muslim’s Property and Then the Muslims Take It as Spoils, Its Owner Has the Greatest Right to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿUmar said: A horse of his went away, and the enemy took it. Then the Muslims gained victory over them, and it was returned to him during the time of the Messenger of Allah ﷺ. A slave of his also ran away and joined the Romans. Then the Muslims gained victory over them, and Khalid ibn al-Walid returned him to him after the Messenger of Allah ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (3067)."},{"num":8022,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ: أَنَّهُ كَانَ عَلَى فَرَسٍ يَوْمَ لَقِيَ الْمُسْلِمُونَ- وَأَمِيرُ الْمُسْلِمِينَ يَوْمَئِذٍ خَالِدُ بْنُ الْوَلِيدِ بَعَثَهُ أَبُو بَكْرٍ- فَأَخَذَهُ الْعَدُوُّ، فَلَمَّا هُزم الْعَدُوُّ رَدَّ خَالِدٌ فَرَسَهُ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (3069) عن أحمد بن يونس، حدثنا زهير، عن موسى بن عقبة، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب مال المسلم إذا أصابه العدو ثم غنمه المسلمون فصاحبه أحق به","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3069).","chapter_en":"If the Enemy Seizes a Muslim’s Property and Then the Muslims Take It as Spoils, Its Owner Has the Greatest Right to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar narrated that he was riding a horse on the day the Muslims met the enemy — and the commander of the Muslims that day was Khalid ibn al-Walid, whom Abu Bakr had sent — and the enemy took it. When the enemy was defeated, Khalid returned his horse."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3069)."},{"num":8023,"demo":false,"sanad":"","matn":["عن نَافِعٍ أَنَّ عَبْدًا، لاِبْنِ عُمَرَ أَبَقَ، فَلَحِقَ بِالرُّومِ، فَظَهَرَ عَلَيْهِ خَالِدُ بْنُ الْوَلِيدِ، فَرَدَّهُ عَلَى عَبْدِ اللَّهِ، وَأَنَّ فَرَسًا لاِبْنِ عُمَرَ عَارَ، فَلَحِقَ بِالرُّومِ، فَظَهَرَ عَلَيْهِ، فَرَدُّوهُ عَلَى عَبْدِ اللَّهِ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (3068) عن محمد بن بشار، حدثنا يحيى، عن عبيد الله قال: أخبرني نافع فذكره.","grade":"صحيح","chapter_ar":"باب مال المسلم إذا أصابه العدو ثم غنمه المسلمون فصاحبه أحق به","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3068).","chapter_en":"If the Enemy Seizes a Muslim’s Property and Then the Muslims Take It as Spoils, Its Owner Has the Greatest Right to It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Nafiʿ narrated that a slave of Ibn ʿUmar ran away and joined the Romans. Khalid ibn al-Walid gained victory over them and returned him to ʿAbdullah. A horse of Ibn ʿUmar also ran loose and joined the Romans. They gained victory over it and returned it to ʿAbdullah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (3068)."},{"num":8024,"demo":false,"sanad":"","matn":["عَنْ علي قَالَ: كَانَتْ لِي شَارِفٌ مِنْ نَصِيبِي مِنَ الْمَغْنَمِ يَوْمَ بَدْرٍ، وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْطَانِي شَارِفًا مِنَ الْخُمُسِ، فَلَمَّا أَرَدْتُ أَنْ أَبْتَنِيَ بِفَاطِمَةَ بِنْتِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، وَاعَدْتُ رَجُلاً صَوَّاغًا مِنْ بَنِي قَيْنُقَاعَ أَنْ يَرْتَحِلَ مَعِيَ، فَنَأْتِيَ بِإِذْخِرٍ أَرَدْتُ أَنْ أَبِيعَهُ الصَّوَّاغِينَ، وَأَسْتَعِينَ بِهِ فِي وَلِيمَةِ عُرْسِي فَبَيْنَا أَنَا أَجْمَعُ لشارفي مَتَاعًا مِنَ الأَقْتَابِ وَالْغَرَائِرِ وَالْحِبَالِ وشارفاي مناختان إِلَى جَنْبِ حُجْرَةِ رَجُلٍ مِنَ الأَنْصَارِ، رَجَعْتُ حِينَ جَمَعْتُ مَا جَمَعْتُ، فَإِذَا شارفاي قَدِ اجْتُبَّ أَسْنِمَتُهُمَا، وَبُقِرَتْ خَوَاصِرُهُمَا، وَأُخِذَ مِنْ أَكْبَادِهِمَا، فَلَمْ أَمْلِكْ عيني حِينَ رَأَيْتُ ذَلِكَ الْمَنْظَرَ مِنْهُمَا، فَقُلْتُ: مَنْ فَعَلَ هَذَا؟ فَقَالُوا: فَعَلَ حَمْزَةُ بْنُ عَبْدِ الْمُطَّلِبِ، وَهْوَ فِي هَذَا الْبَيْتِ فِي شربٍ مِنَ الأَنْصَارِ، فَانْطَلَقْتُ حَتَّى أَدْخُلَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، وَعِنْدَهُ زَيْدُ بْنُ حَارِثَةَ فَعَرَفَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي وَجْهِي الَّذِي لَقِيتُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَا لَكَ؟ فَقُلْتُ: يَا رَسُولَ اللَّهَ، مَا رَأَيْتُ كَالْيَوْمِ قَطُّ عدَا حَمْزَةُ عَلَى ناقتي فَأَجَبَّ أَسْنِمَتَهُمَا وَبَقَرَ خَوَاصِرَهُمَا، وَهَا هُوَ ذَا فِي بَيْتٍ مَعَهُ شَرْبٌ، فَدَعَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِرِدَائِهِ فَارْتَدَى، ثُمَّ انْطَلَقَ يَمْشِي، وَاتَّبَعْتُهُ أَنَا وَزَيْدُ بْنُ حَارِثَةَ حَتَّى جَاءَ الْبَيْتَ الَّذِي فِيهِ حَمْزَةُ، فَاسْتَأْذَنَ فَأَذِنُوا لَهُمْ، فَإِذَا هُمْ شَرْبٌ، فَطَفِقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَلُومُ حَمْزَةَ فِيمَا فَعَلَ، فَإِذَا حَمْزَةُ قَدْ ثَمِلَ مُحْمَرَّةً عَيْنَاهُ، فَنَظَرَ حَمْزَةُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ صَعَّدَ النَّظَرَ، فَنَظَرَ إِلَى رُكْبَتِهِ، ثُمَّ صَعَّدَ النَّظَرَ فَنَظَرَ إِلَى سُرَّتِهِ، ثُمَّ صَعَّدَ النَّظَرَ فَنَظَرَ إِلَى وَجْهِهِ، ثُمَّ قَالَ حَمْزَةُ: هَلْ أَنْتُمْ إِلاَّ عَبِيدٌ لأَبِي، فَعَرَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَدْ ثَمِلَ، فَنَكَصَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى عَقِبَيْهِ الْقَهْقَرَى وَخَرَجْنَا مَعَهُ."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3091)، ومسلم في الأشربة (1979: 2) كلاهما من طريق عبد الله بن وهب، أخبرنا يونس بن يزيد، عن الزهري، أخبرني علي بن الحسين بن علي، ان حسين بن علي أخبره أن عليا قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب قسمة الغنائم","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3091) and Muslim (1979:2).","chapter_en":"Dividing the Spoils","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["ʿAli said: I had an old she-camel from my share of the spoils on the day of Badr, and the Prophet ﷺ had given me another old she-camel from the khums. When I wanted to consummate my marriage with Fatimah, the daughter of the Messenger of Allah ﷺ, I made an appointment with a goldsmith from Banu Qaynuqaʿ to go with me so that we could bring idhkhir grass, which I intended to sell to the goldsmiths and use to help with the wedding feast. While I was gathering equipment for my two she-camels — saddles, sacks, and ropes — and my two she-camels were kneeling beside the room of a man from the Ansar, I returned after gathering what I had gathered, and behold, their humps had been cut off, their flanks had been slit open, and some of their livers had been taken. I could not hold back my tears when I saw that sight. I said: “Who did this?” They said: “Hamzah ibn ʿAbd al-Muttalib did it, and he is in this house among a drinking party of the Ansar.” I went until I entered upon the Prophet ﷺ, and Zayd ibn Harithah was with him. The Prophet ﷺ recognized from my face what had happened to me and said: “What is wrong with you?” I said: “O Messenger of Allah, I have never seen anything like today. Hamzah attacked my two she-camels, cut off their humps, slit open their flanks, and he is there in a house with a drinking party.” The Prophet ﷺ called for his cloak and put it on, then set out walking, and I and Zayd ibn Harithah followed him until he came to the house where Hamzah was. He asked permission, and they gave permission to them, and they were a drinking party. The Messenger of Allah ﷺ began blaming Hamzah for what he had done, but Hamzah was intoxicated, his eyes red. Hamzah looked at the Messenger of Allah ﷺ, then raised his gaze and looked at his knees, then raised his gaze and looked at his navel, then raised his gaze and looked at his face, then Hamzah said: “Are you anything but slaves of my father?” The Messenger of Allah ﷺ realized that he was intoxicated, so he withdrew backward on his heels, and we left with him."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3091)، ومسلم (1979: 2)."},{"num":8025,"demo":false,"sanad":"","matn":["8025 - عَنْ عُمَرَ قَالَ: لَوْ لا آخِرُ الْمُسْلِمِينَ مَا فَتَحْتُ قَرْيَةً إِلاَّ قَسَمْتُهَا بَيْنَ أَهْلِهَا كَمَا قَسَمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ."],"takhrij":"صحيح: رواه البخاري في فرض الخمس (3125) عن صدقة، أخبرنا عبدالرحمن، عن مالك، عن زيد بن أسلم، عن أبيه قال: قال عمر: فذكره.","grade":"صحيح","chapter_ar":"باب قسمة الغنائم","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3125).","chapter_en":"Dividing the Spoils","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["ʿUmar said: “Were it not for the later Muslims, I would not conquer any town except that I would divide it among its people, just as the Prophet ﷺ divided Khaybar.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3125)."},{"num":8026,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا أُعْطِيكُمْ وَلاَ أَمْنَعُكُمْ، أَنَا قَاسِمٌ أَضَعُ حَيْثُ أُمِرْتُ."],"takhrij":"صحيح: رواه البخاري في فرض الخمس (3117) عن محمد بن سنان، حدثنا فليح، حدثنا هلال، عن عبد الرحمن بن أبي عمرة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب قسمة الغنائم","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3117).","chapter_en":"Dividing the Spoils","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “I do not give you nor withhold from you; I am only a distributor, placing where I have been commanded.”"]}},"tuhfa":{},"full":1,"rep":[7603],"tks":"صحيح: رواه البخاري (3117)."},{"num":8027,"demo":false,"sanad":"","matn":["عَنْ عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا جَاءَ فَيْءٌ قَسَمَهُ مِنْ يَوْمِهِ، فَأَعْطَى الْآهِلَ حَظَّيْنِ، وَأَعْطَى الْعَزَبَ حَظًّا وَاحِدًا. فَدُعِينَا، وَكُنْتُ أُدْعَى قَبْلَ عَمَّارِ بْنِ يَاسِرٍ، فَدُعِيتُ، فَأَعْطَانِي حَظَّيْنِ، وَكَانَ لِي أَهْلٌ، ثُمَّ دَعَا بَعْدُ عَمَّارَ بْنَ يَاسِرٍ فَأُعْطِيَ حَظًّا وَاحِدًا، فَبَقِيَتْ قِطْعَةُ سِلْسِلَةٍ مِنْ ذَهَبٍ، فَجَعَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَرْفَعُهَا بِطَرَفِ عَصَاهُ، ثُمَّ رَفَعَهَا وَهُوَ يَقُولُ: كَيْفَ أَنْتُمْ يَوْمَ يَكْثُرُ لَكُمْ مِنْ هَذَا؟"],"takhrij":"صحيح: رواه أحمد (23986) –والسياق له-وأبو داود (2953)، وصحّحه ابن حبان (4816)، والحاكم (2/140-141) من طرق عن صفوان بن عمرو، عن عبد الرحمن بن جبير بن نفير، عن أبيه، عن عوف بن مالك فذكره. ومنهم من اختصره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب قسمة الغنائم","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (23986), Abu Dawud (2953), and authenticated by Ibn Hibban (4816) and al-Hakim (2/140–141).","chapter_en":"Dividing the Spoils","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["ʿAwf ibn Malik al-Ashjaʿi said: When fay’ came to the Messenger of Allah ﷺ, he would divide it on that same day. He gave the married man two portions and the unmarried man one portion. We were called, and I used to be called before ʿAmmar ibn Yasir. I was called and he gave me two portions, as I had a family. Then he called ʿAmmar ibn Yasir and gave him one portion. A piece of a gold chain remained, so the Prophet ﷺ began lifting it with the tip of his staff, then raised it and said: “How will you be when much of this comes to you?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (23986)، وأبو داود (2953)، وصححه ابن حبان (4816)، والحاكم (2/140-141)."},{"num":8028,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِظَبْيَةٍ فِيهَا خَرَزٌ، فَقَسَمَهَا لِلْحُرَّةِ وَالأَمَةِ. قَالَتْ عَائِشَةُ: كَانَ أَبِي رَضِيَ اللَّهُ عَنْهُ يَقْسِمُ لِلْحُرِّ وَالْعَبْدِ."],"takhrij":"صحيح: رواه أبو داود (2952)، وأحمد (25229) والحاكم (2/137)، والبيهقي (6/347) كلهم من طريق ابن أبي ذئب، عن القاسم بن عباس، عن عبدالله بن نيار الأسلمي، عن عروة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب قسمة الغنائم","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2952), Ahmad (25229), al-Hakim (2/137), and al-Bayhaqi (6/347).","chapter_en":"Dividing the Spoils","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["ʿA’ishah narrated that the Prophet ﷺ was brought a small leather pouch containing beads, and he divided them among free women and slave women. ʿA’ishah said: My father used to divide among the free person and the slave."]},"buhuth":{"en":["Her word “al-ẓabyah” means a small leather pouch with hair on it. It was also said to be something like a small bag or purse. Ibn al-Athir said this. This was from the spoils, as explicitly stated in the narration of al-Hakim."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2952)، وأحمد (25229)، والحاكم (2/137)، والبيهقي (6/347)."},{"num":8029,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ: ـ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَعَلَ لِلْفَرَسِ سَهْمَيْنِ، وَلِصَاحِبِهِ سَهْمًا.","وفي لفظ: قسم رسول الله صلى الله عليه وسلم يوم خيبر للفرس سهمين، وللراجل سهما. قال –أي عبيد الله بن عمر العمري-: فسّره نافع، فقال: إذا كان مع الرجل فرس فله ثلاثة أسهم، فإن لم يكن له فرس فله سهم."],"takhrij":"متفق عليه: رواه البخاري في الجهاد (2863) عن عبيد بن إسماعيل، عن أبي أسامة، عن عبيد الله، عن نافع، عن ابن عمر فذكره باللفظ الأول.","grade":"متفق عليه","chapter_ar":"باب للفارس ثلاثة أسهم: سهمان لفرسه وسهم له، وللراجل سهم واحد","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2863) and (4228). Muslim (1762:57) narrated it through another route from Ibn ʿUmar: The Messenger of Allah ﷺ divided in the extra spoils two shares for the horse and one share for the man.","chapter_en":"The Horseman Receives Three Shares: Two for His Horse and One for Himself, and the Foot-Soldier Receives One Share","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ assigned two shares for the horse and one share for its rider. In another wording: The Messenger of Allah ﷺ divided on the day of Khaybar two shares for the horse and one share for the foot-soldier. He — meaning ʿUbayd Allah ibn ʿUmar al-ʿUmari — said: Nafiʿ explained it, saying: If a man has a horse with him, he receives three shares; and if he does not have a horse, he receives one share."]},"buhuth":{"en":["Abu Dawud (2733) narrated it with the wording: “The Messenger of Allah ﷺ assigned three shares for a man and his horse: one share for him and two shares for his horse.”","The summary of these narrations is that the horseman receives three shares: one for himself and two for his horse; and the foot-soldier receives one share."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2863، 4228)، ورواه مسلم (1762: 57)."},{"num":8030,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ: رَضِيَ اللَّهُ عَنْهُمَا، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَسَمَ لِمِائَتَيْ فَرَسٍ يَوْمَ خَيْبَرَ سَهْمَيْنِ سَهْمَيْنِ."],"takhrij":"حسن: رواه البخاري في التاريخ الكبير (7/215)، والدارقطني (4/103)، والحاكم (2615)، والبيهقي(12872) كلهم من طريق إبراهيم بن سعد بن إبراهيم، عن كثير مولى بني مخزوم، عن عطاء، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب للفارس ثلاثة أسهم: سهمان لفرسه وسهم له، وللراجل سهم واحد","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bukhari in al-Tarikh al-Kabir (7/215), al-Daraqutni (4/103), and al-Hakim (2615), and al-Bayhaqi (6/326).","chapter_en":"The Horseman Receives Three Shares: Two for His Horse and One for Himself, and the Foot-Soldier Receives One Share","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbas narrated that the Prophet ﷺ assigned two shares each for two hundred horses on the day of Khaybar."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البخاري في التاريخ الكبير (7/215)، والدارقطني (4/103)، والحاكم (2615)، والبيهقي (12872)."},{"num":8031,"demo":false,"sanad":"","matn":["عَنْ يَزِيدَ بْنِ هُرْمُزَ قَالَ:  كَتَبَ نَجْدَةُ بْنُ عَامِرٍ الْحَرُورِيُّ إِلَى ابْنِ عَبَّاسٍ يَسْأَلُهُ عَنِ الْعَبْدِ وَالْمَرْأَةِ يَحْضُرَانِ الْمَغْنَمَ، هَلْ يُقْسَمُ لَهُمَا؟ وَعَنْ قَتْلِ الْوِلْدَانِ، وَعَنِ الْيَتِيمِ، مَتَى يَنْقَطِعُ عَنْهُ الْيُتْمُ؟ وَعَنْ ذَوِي الْقُرْبَى، مَنْ هُمْ؟ فَقَالَ لِيَزِيدَ: اكْتُبْ إِلَيْهِ، فَلَوْلَا أَنْ يَقَعَ فِي أُحْمُوقَةٍ مَا كَتَبْتُ إِلَيْهِ، اكْتُبْ: إِنَّكَ كَتَبْتَ تَسْأَلُنِي عَنِ الْمَرْأَةِ وَالْعَبْدِ يَحْضُرَانِ الْمَغْنَمَ، هَلْ يُقْسَمُ لَهُمَا شَيْءٌ؟ وَإِنَّهُ لَيْسَ لَهُمَا شَيْءٌ، إِلَّا أَنْ يُحْذَيَا، وَكَتَبْتَ تَسْأَلُنِي عَنْ قَتْلِ الْوِلْدَانِ، وَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَقْتُلْهُمْ، وَأَنْتَ فَلَا تَقْتُلْهُمْ، إِلَّا أَنْ تَعْلَمَ مِنْهُمْ مَا عَلِمَ صَاحِبُ مُوسَى مِنَ الْغُلَامِ الَّذِي قَتَلَهُ، وَكَتَبْتَ تَسْأَلُنِي عَنِ الْيَتِيمِ مَتَى يَنْقَطِعُ عَنْهُ اسْمُ الْيُتْمِ؟ وَإِنَّهُ لَا يَنْقَطِعُ عَنْهُ اسْمُ الْيُتْمِ، حَتَّى يَبْلُغَ وَيُؤْنَسَ مِنْهُ رُشْدٌ، وَكَتَبْتَ تَسْأَلُنِي عَنْ ذَوِي الْقُرْبَى مَنْ هُمْ؟ وَإِنَّا زَعَمْنَا أَنَّا هُمْ، فَأَبَى ذَلِكَ عَلَيْنَا قَوْمُنَا."],"takhrij":"صحيح: رواه مسلم في الجهاد والسير (1812: 139) عن ابن أبي عمر، حدثنا سفيان، عن إسماعيل بن أمية، عن سعيد المقبري، عن يزيد بن هرمز فذكره.","grade":"صحيح","chapter_ar":"باب يُرضخ للعبد والمرأة من الغنيمة إذا شاركا في الغزو، ولا يسهم لهما","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1812:139).","chapter_en":"The Slave and the Woman Are Given a Gift from the Spoils if They Participate in the Campaign, but No Fixed Share Is Assigned to Them","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":8,"content":{"translation":{"en":["Yazid ibn Hurmuz said: Najdah ibn ʿAmir al-Haruri wrote to Ibn ʿAbbas asking him about a slave and a woman who are present at the spoils: should a share be assigned to them? He also asked about killing children, about when the status of orphanhood ends for an orphan, and about who the relatives are. Ibn ʿAbbas said to Yazid: “Write to him. Were it not that he might fall into foolishness, I would not write to him. Write: You wrote asking me about a woman and a slave being present at the spoils and whether anything should be assigned to them. They have no fixed share, except that they may be given a gift. You wrote asking me about killing children. The Messenger of Allah ﷺ did not kill them, so you should not kill them, unless you know about them what the companion of Musa knew about the boy whom he killed. You wrote asking me when the name of orphanhood ends for an orphan. The name of orphanhood does not end for him until he reaches maturity and sound judgment is perceived from him. You wrote asking me who the relatives are. We claimed that we are they, but our people refused that for us.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1812: 139)."},{"num":8032,"demo":false,"sanad":"","matn":["عَنْ عُمَيْرٍ، مَوْلَى آبِي اللَّحْمِ قَالَ: شَهِدْتُ خَيْبَرَ مَعَ سَادَتِي فَكَلَّمُوا فِيَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَعْلَمُوهُ أَنِّي مَمْلُوكٌ. قَالَ: فَأَمَرَ بِي فَقُلِّدْتُ السَّيْفَ فَإِذَا أَنَا أَجُرُّهُ فَأَمَرَ لِي بِشَيْءٍ مِنْ خُرْثِيِّ الْمَتَاعِ، وَعَرَضْتُ عَلَيْهِ رُقْيَةً كُنْتُ أَرْقِي بِهَا الْمَجَانِينَ، فَأَمَرَنِي بِطَرْحِ بَعْضِهَا، وَحَبْسِ بَعْضِهَا.","وفي رواية: وأعطاني خرثي متاع، ولم يسهم لي."],"takhrij":"صحيح: رواه الترمذي (1557)، والنسائي في الكبرى (7493)، والحاكم (1224) من طريق قتيبة، حدثنا بشر بن المفضل، عن محمد بن زيد (هو ابن المهاجر بن قنفذ)، عن عمير مولى أبي اللحم فذكره.","grade":"صحيح","chapter_ar":"باب يُرضخ للعبد والمرأة من الغنيمة إذا شاركا في الغزو، ولا يسهم لهما","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1557), who authenticated it, al-Nasa’i in al-Kubra (7493), and al-Hakim (1224).","chapter_en":"The Slave and the Woman Are Given a Gift from the Spoils if They Participate in the Campaign, but No Fixed Share Is Assigned to Them","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":8,"content":{"translation":{"en":["ʿUmayr, the freedman of Abi al-Lahm, said: I was present at Khaybar with my masters. They spoke to the Messenger of Allah ﷺ about me and told him that I was owned as a slave. He said: He ordered me, so I was given a sword to wear, but I was dragging it. He ordered that I be given something from the lesser goods. I also presented to him an incantation by which I used to treat the insane, and he ordered me to discard some of it and keep some of it. In another narration: He gave me some lesser goods and did not assign me a fixed share."]},"buhuth":{"en":["His saying, “I was given the sword to wear,” is in the passive form from “taqlid,” meaning he ordered me to carry a weapon and be with the fighters.","His saying, “I was dragging it,” means I was dragging the sword on the ground because of my short stature.","The phrase “kharathi al-mataʿ,” with a dotted kha’ carrying dammah and a silent ra’, means the lowest-quality goods.","Al-Baghawi said in Sharh al-Sunnah (11/104): “The practice according to most of the people of knowledge is that slaves, children, and women, when they are present in battle, are given a gift, but no fixed share is assigned to them.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9061],"tks":"صحيح: رواه الترمذي (1557) وصححه، والنسائي في الكبرى (7493)، والحاكم (1224)."},{"num":8033,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: إِنَّمَا تَغَيَّبَ عُثْمَانُ عَنْ بَدْرٍ، فَإِنَّهُ كَانَتْ تَحْتَهُ بِنْتُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَانَتْ مَرِيضَةً. فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ لَكَ أَجْرَ رَجُلٍ مِمَّنْ شَهِدَ بَدْرًا وَسَهْمَهُ."],"takhrij":"صحيح: رواه البخاري في فرض الخمس (3130)، عن موسى، حدثنا أبو عوانة، حدثنا عثمان بن موهب، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب سهم عثمان في غنيمة غزوة بدر ولم يشهدها","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3130).","chapter_en":"ʿUthman’s Share from the Spoils of the Battle of Badr Although He Did Not Attend It","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿUmar said: ʿUthman was absent from Badr only because the daughter of the Messenger of Allah ﷺ was his wife, and she was ill. The Prophet ﷺ said to him: “You will have the reward and share of a man who attended Badr.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9898],"tks":"صحيح: رواه البخاري (3130)."},{"num":8034,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ: بَلَغَنَا مَخْرَجُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ بِالْيَمَنِ، فَخَرَجْنَا مُهَاجِرِينَ إِلَيْهِ، أَنَا وَأَخَوَانِ لِي، أَنَا أَصْغَرُهُمْ، أَحَدُهُمَا أَبُو بُرْدَةَ وَالآخَرُ أَبُو رُهْمٍ، إِمَّا قَالَ: فِي بِضْعٍ، وَإِمَّا قَالَ: فِي ثَلاَثَةٍ وَخَمْسِينَ أَوِ اثْنَيْنِ وَخَمْسِينَ رَجُلاً مِنْ قَوْمِي، فَرَكِبْنَا سَفِينَةً، فَأَلْقَتْنَا سَفِينَتُنَا إِلَى النَّجَاشِيِّ بِالْحَبَشَةِ، وَوَافَقْنَا جَعْفَرَ بْنَ أَبِي طَالِبٍ وَأَصْحَابَهُ عِنْدَهُ فَقَالَ جَعْفَرٌ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَنَا هَا هُنَا، وَأَمَرَنَا بِالإِقَامَةِ فَأَقِيمُوا مَعَنَا. فَأَقَمْنَا مَعَهُ، حَتَّى قَدِمْنَا جَمِيعًا، فَوَافَقْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ افْتَتَحَ خَيْبَرَ، فَأَسْهَمَ لَنَا. أَوْ قَالَ: فَأَعْطَانَا مِنْهَا. وَمَا قَسَمَ لأَحَدٍ غَابَ عَنْ فَتْحِ خَيْبَرَ مِنْهَا شَيْئًا، إِلاَّ لِمَنْ شَهِدَ مَعَهُ، إِلاَّ أَصْحَابَ سَفِينَتِنَا مَعَ جَعْفَرٍ وَأَصْحَابِهِ، قَسَمَ لَهُمْ مَعَهُمْ."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3136)، ومسلم في فضائل الصحابة (2502) كلاهما عن محمد بن العلاء الهمداني- وزاد مسلم عبد الله بن براد الأشعري- عن أبي أسامة، حدثنا بُريد بن عبد الله، عن أبي بردة، عن أبي موسى فذكره.","grade":"متفق عليه","chapter_ar":"باب قسمة الغنائم على أصحاب السفينة وجعفر بن أبي طالب مع أصحابه في غزوة خيبر","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3136) and Muslim (2502).","chapter_en":"Dividing the Spoils Among the People of the Ship, and Jaʿfar ibn Abi Talib with His Companions, During the Expedition of Khaybar","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":10,"content":{"translation":{"en":["Abu Musa said: News of the Prophet’s ﷺ departure reached us while we were in Yemen, so we set out emigrating to him, I and two brothers of mine, and I was the youngest of them. One of them was Abu Burdah and the other was Abu Ruhm. He said either: among a few, or he said: among fifty-three or fifty-two men from my people. We boarded a ship, and our ship brought us to the Negus in Abyssinia. We found Jaʿfar ibn Abi Talib and his companions with him. Jaʿfar said: “The Messenger of Allah ﷺ sent us here and ordered us to remain, so stay with us.” We remained with him until we all arrived, and we reached the Prophet ﷺ when he had conquered Khaybar. He assigned us a share — or he said: he gave us from it. He did not divide anything from Khaybar for anyone who had been absent from its conquest, except for those who had witnessed it with him, apart from the people of our ship with Jaʿfar and his companions; he divided for them along with them."]}},"tuhfa":{},"full":1,"rep":[8598],"tks":"متفق عليه: رواه البخاري (3136)، ومسلم (2502)."},{"num":8035,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مُغَفَّلٍ قَالَ: كُنَّا مُحَاصِرِينَ قَصْرَ خَيْبَرَ فَرَمَى إِنْسَانٌ بِجِرَابٍ فِيهِ شحمٌ، فَنَزَوْتُ لآخُذَهُ فَالْتَفَتُّ فَإِذَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاسْتَحْيَيْتُ مِنْهُ.","وفي لفظ: أَصَبْتُ جِرَابًا مِنْ شَحْمٍ يَوْمَ خَيْبَرَ قَالَ: فَالْتَزَمْتُهُ فَقُلْتُ: لَا أُعْطِي الْيَوْمَ أَحَدًا مِنْ هَذَا شَيْئًا، قَالَ: فَالْتَفَتُّ فَإِذَا رَسُولُ اللهِ صلى الله عليه وسلم مُتَبَسِّمًا."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3153)، ومسلم في الجهاد والسير (1772: 73) كلاهما من طريق شعبة، حدثني حميد بن هلال، سمعت عبدالله بن مغفّل فذكره. واللفظ الآخر لمسلم (1772: 72) من طريق سليمان بن المغيرة، حدثنا حميد بن هلال به فذكره.","grade":"متفق عليه","chapter_ar":"باب الأكل من طعام الغنيمة قبل قسمتها","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3153) and Muslim (1772:73).","chapter_en":"Eating from the Food of the Spoils Before It Is Divided","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullah ibn Mughaffal said: We were besieging the fortress of Khaybar when someone threw a leather bag containing fat. I leapt to take it, then turned around and saw the Prophet ﷺ, so I felt shy before him. In another wording: I found a leather bag of fat on the day of Khaybar. He said: I clung to it and said: “Today I will not give anyone anything from this.” He said: Then I turned around and saw the Messenger of Allah ﷺ smiling."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3153)، ومسلم (1772: 73)."},{"num":8036,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا نُصِيبُ فِي مَغَازِينَا الْعَسَلَ وَالْعِنَبَ فَنَأْكُلُهُ وَلاَ نَرْفَعُهُ."],"takhrij":"صحيح: رواه البخاري في فرض الخمس (3154) عن مسدّد، حدثنا حماد بن زيد، عن أيوب، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب الأكل من طعام الغنيمة قبل قسمتها","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3154).","chapter_en":"Eating from the Food of the Spoils Before It Is Divided","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: We used to obtain honey and grapes during our expeditions, and we would eat them and not store them away."]}},"tuhfa":{},"full":1,"rep":[9065],"tks":"صحيح: رواه البخاري (3154)."},{"num":8037,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ جَيْشًا، غَنِمُوا فِي زَمَانِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَعَامًا وَعَسَلاً، فَلَمْ يُؤْخَذْ مِنْهُمُ الْخُمُسُ."],"takhrij":"صحيح: رواه أبو داود (2701)، وصحّحه ابن حبان (4825) والبيهقي (17995) كلهم من طرق عن عبيد الله، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب الأكل من طعام الغنيمة قبل قسمتها","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2701), and authenticated by Ibn Hibban (4825) and al-Bayhaqi (9/59).","chapter_en":"Eating from the Food of the Spoils Before It Is Divided","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿUmar narrated that an army acquired food and honey as spoils during the time of the Messenger of Allah ﷺ, and the fifth was not taken from them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2701)، وصححه ابن حبان (4825)، والبيهقي (17995)."},{"num":8038,"demo":false,"sanad":"","matn":["عَنْ رَافِعِ بن خَدِيجٍ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِذِي الْحُلَيْفَةِ، فَأَصَابَ النَّاسَ جُوعٌ، وَأَصَبْنَا إِبِلاً وَغَنَمًا وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي أُخْرَيَاتِ النَّاسِ فَعَجِلُوا فَنَصَبُوا الْقُدُورَ، فَأَمَرَ بِالْقُدُورِ فَأُكْفِئَتْ، ثُمَّ قَسَمَ فَعَدَلَ عَشَرَةً مِنَ الْغَنَمِ بِبَعِيرٍ، فندَّ مِنْهَا بَعِيرٌ، وَفِي الْقَوْمِ خَيْلٌ يسيرة فَطَلَبُوهُ فَأَعْيَاهُمْ فَأَهْوَى إِلَيْهِ رَجُلٌ بِسَهْمٍ، فَحَبَسَهُ اللَّهُ، فَقَالَ: هَذِهِ الْبَهَائِمُ لَهَا أَوَابِدُ كَأَوَابِدِ الْوَحْشِ فَمَا ندّ عَلَيْكُمْ فَاصْنَعُوا بِهِ هَكَذَا فَقَالَ جدّي: إِنَّا نَرْجُو أَوْ نَخَافُ أَنْ نَلْقَى الْعَدُوَّ غَدًا، وَلَيْسَ مَعَنَا مُدًى أَفَنَذْبَحُ بِالْقَصَبِ؟ فَقَالَ: مَا أَنْهَرَ الدَّمَ وَذُكِرَ اسْمُ اللَّهِ عَلَيْهِ فكلوه لَيْسَ السِّنَّ وَالظُّفُرَ، وَسَأُحَدِّثُكُمْ عَنْ ذَلِكَ، أَمَّا السِّنُّ فَعَظْمٌ، وَأَمَّا الظُّفُرُ فَمُدَى الْحَبَشَةِ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (3075)، ومسلم في الأضاحي (1968: 20) كلاهما من طريق سعيد بن مسروق، عن عباية بن رفاعة بن رافع بن خديج، عن جده رافع فذكره.","grade":"متفق عليه","chapter_ar":"باب الأكل من طعام الغنيمة قبل قسمتها","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3075) and Muslim (1968:20).","chapter_en":"Eating from the Food of the Spoils Before It Is Divided","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["Rafiʿ ibn Khadij said: We were with the Prophet ﷺ at Dhu al-Hulayfah, and the people were struck by hunger. We obtained camels and sheep, while the Prophet ﷺ was at the rear of the people. They hurried and set up the cooking pots, so he ordered that the pots be overturned. Then he divided the animals, equating ten sheep with one camel. One camel ran away, and there were only a few horses among the people. They pursued it, but it exhausted them, so a man aimed at it with an arrow and Allah stopped it. He said: “These animals have wild tendencies like wild animals, so whatever runs away from you, do with it like this.” My grandfather said: “We hope, or fear, that we may meet the enemy tomorrow, and we do not have knives. May we slaughter with reeds?” He said: “Whatever causes the blood to flow and Allah’s name is mentioned over it, eat it, except the tooth and the claw. I will tell you about that: as for the tooth, it is bone; and as for the claw, it is the knife of the Abyssinians.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3075)، ومسلم (1968: 20)."},{"num":8039,"demo":false,"sanad":"","matn":["عَنْ ثَعْلَبَةَ بْنِ الْحَكَمِ، قَالَ: أَصَبْنَا غَنَمًا لِلْعَدُوِّ، فَانْتَهَبْنَاهَا فَنَصَبْنَا قُدُورَنَا، فَمَرَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْقُدُورِ، فَأَمَرَ بِهَا فَأُكْفِئَتْ ثُمَّ قَالَ: إِنَّ النُّهْبَةَ لاَ تَحِلُّ."],"takhrij":"حسن: رواه ابن ماجه (3938) – واللفظ له- والطيالسي (1291)، وعبدالرزاق (18841)، وصحّحه الحاكم (2/134) كلهم من طرق عن سماك، عن ثعلبة بن الحكم فذكره. وجاء عند عبد الرزاق والحاكم أن ذلك كان يوم خيبر.","grade":"حسن","chapter_ar":"باب النهي عن النهبة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (3938) — this is his wording — al-Tayalisi (1291), and ʿAbd al-Razzaq (18841), and authenticated by al-Hakim (2/134).","chapter_en":"The Prohibition of Plundering","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Thaʿlabah ibn al-Hakam said: We obtained sheep belonging to the enemy and plundered them, then set up our cooking pots. The Prophet ﷺ passed by the pots and ordered that they be overturned. Then he said: “Plundering is not lawful.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (3938) — واللفظ له — والطيالسي (1291)، وعبد الرزاق (18841)، وصححه الحاكم (2/134)."},{"num":8040,"demo":false,"sanad":"","matn":["عَنْ أَبِي لُبَيْدٍ، قَالَ: كُنَّا مَعَ عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ بِكَابُلَ، فَأَصَابَ النَّاسُ غَنِيمَةً، فَانْتَهَبُوهَا، فَقَامَ خَطِيبًا فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنِ النُّهْبَى. فَرَدُّوا مَا أَخَذُوا فَقَسَمَهُ بَيْنَهُمْ."],"takhrij":"حسن: رواه أبو داود (2703)، وأحمد (20619، 20631) من طرق عن جرير بن حازم، عن يعلى بن حكيم، عن أبي لبيد فذكره.","grade":"حسن","chapter_ar":"باب النهي عن النهبة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2703) and Ahmad (20619, 20631).","chapter_en":"The Prohibition of Plundering","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Abu Labid said: We were with ʿAbd al-Rahman ibn Abi Samurah in Kabul, and the people obtained spoils and plundered them. He stood as a preacher and said: “I heard the Messenger of Allah ﷺ forbidding plunder.” So they returned what they had taken, and he divided it among them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2703)، وأحمد (20619، 20631)."},{"num":8041,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: غَزَوْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَصَابَتْنَا مَجَاعَةٌ، فَفَتَحَ اللَّهُ عَلَيْنَا، فَأَصَبْنَا غَنَمًا، فَانْتَهَبَ الْقَوْمُ، فَأَخَذْنَا مِنْهَا شَاةً، وَإِنَّهَا لَتَغْلِي فِي قُدُورِنَا، إِذْ أَتَأَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْشِي عَلَى قَوْسِهِ حَتَّى طَعَنَ فِي قُدُورَنَا بِالْقَوْسِ، فَجَفَنَهَا وَقَالَ: لَيْسَتِ النُّهْبَةُ بِأَحَلَّ مِنَ الْمَيْتَةِ، فَجَعَلَ يَنْظُرُ إِلَى الْعَظْمِ قَدِ ارْتَفَعَ عَنِ الْأَرْضِ فَيَدُوسُهُ بِقَوْسِهِ حَتَّى يُرَمِّلَهُ بِالتُّرَابِ."],"takhrij":"حسن: رواه سعيد بن منصور (2636) عن أبي عوانة، عن عاصم بن كليب، عن أبيه، عن رجل من أصحاب النبي صلى الله عليه وسلم فذكره.","grade":"حسن","chapter_ar":"باب النهي عن النهبة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Saʿid ibn Mansur (2636), and Abu Dawud (2705) narrated it with: “Plunder is no more lawful than carrion,” or, “Carrion is no more lawful than plunder.”","chapter_en":"The Prohibition of Plundering","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["A man from the companions of the Prophet ﷺ said: We went on an expedition with the Messenger of Allah ﷺ and were struck by hunger. Then Allah granted us victory, and we obtained sheep. The people plundered, and we took one sheep, while it was boiling in our pots. Then the Messenger of Allah ﷺ came to us walking while leaning on his bow, and he struck our pots with the bow, overturning them, and said: “Plunder is no more lawful than carrion.” He began looking at bones raised from the ground and pressing them down with his bow until he covered them with dust."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه سعيد بن منصور (2636)، ورواه أبو داود (2705) وفيه: ((إن النهبة ليست بأحل من الميتة)) أو ((إن الميتة ليست بأحل من النهبة))."},{"num":8042,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَامَ فِينَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ الْغُلُولَ فَعَظَّمَهُ وَعَظَّمَ أَمْرَهُ قَالَ: لاَ أُلْفِيَنَّ أَحَدَكُمْ يَوْمَ الْقِيَامَةِ عَلَى رَقَبَتِهِ شَاةٌ لَهَا ثُغَاءٌ، عَلَى رَقَبَتِهِ فَرَسٌ لَهُ حَمْحَمَةٌ، يَقُولُ: يَا رَسُولَ اللَّهِ أَغِثْنِي، فَأَقُولُ: لاَ أَمْلِكُ لَكَ شَيْئًا قَدْ أَبْلَغْتُكَ، وَعَلَى رَقَبَتِهِ بَعِيرٌ لَهُ رُغَاءٌ يَقُولُ: يَا رَسُولَ اللَّهِ أَغِثْنِي فَأَقُولُ: لاَ أَمْلِكُ لَكَ شَيْئًا، قَدْ أَبْلَغْتُكَ، وَعَلَى رَقَبَتِهِ صَامِتٌ فَيَقُولُ: يَا رَسُولَ اللَّهِ أَغِثْنِي، فَأَقُولُ: لاَ أَمْلِكُ لَكَ شَيْئًا قَدْ أَبْلَغْتُكَ، أَوْ عَلَى رَقَبَتِهِ رِقَاعٌ تَخْفِقُ فَيَقُولُ: يَا رَسُولَ اللَّهِ أَغِثْنِي فَأَقُولُ: لاَ أَمْلِكُ لَكَ شَيْئًا قَدْ أَبْلَغْتُكَ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد (3073)، ومسلم في الإمارة (1831: 24) كلاهما من طريق أبي حيان، عن أبي زرعة، حدثني أبو هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تحريم الغلول","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3073) and Muslim (1831:24).","chapter_en":"What Has Been Reported Concerning the Prohibition of Stealing from Spoils","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ stood among us and mentioned stealing from the spoils, magnifying it and emphasizing its seriousness. He said: “Let me not find any of you on the Day of Resurrection carrying on his neck a sheep bleating, or carrying on his neck a horse neighing, saying: ‘O Messenger of Allah, help me,’ and I will say: ‘I possess nothing for you; I conveyed the message to you.’ Or carrying on his neck a camel bellowing, saying: ‘O Messenger of Allah, help me,’ and I will say: ‘I possess nothing for you; I conveyed the message to you.’ Or carrying on his neck silent wealth, saying: ‘O Messenger of Allah, help me,’ and I will say: ‘I possess nothing for you; I conveyed the message to you.’ Or carrying on his neck pieces of cloth fluttering, saying: ‘O Messenger of Allah, help me,’ and I will say: ‘I possess nothing for you; I conveyed the message to you.’”"]},"intro":{"ar":["قال تعالى:","(وَمَن يَغْلُلْ يَأْتِ بِمَا غَلَّ يَوْمَ الْقِيَامَةِ) [سورة آل عمران: ١٦١]."],"en":["Allah Most High said:","“And whoever steals from the spoils will come with what he stole on the Day of Resurrection.” [Surat Al ʿImran: 161]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3073)، ومسلم (1831: 24)."},{"num":8043,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ خَيْبَرَ فَلَمْ نَغْنَمْ ذَهَبًا وَلاَ فِضَّةً إِلاَّ الأَمْوَالَ: الثياب وَالْمَتَاعَ. فَأَهْدَى رِفَاعَةُ بْنُ زَيْدٍ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غُلاَمًا أَسْوَدَ يُقَالُ لَهُ: مِدْعَمٌ فَوَجَّهَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى وَادِي الْقُرَى حَتَّى إِذَا كُنَّا بِوَادِي الْقُرَى بَيْنَمَا مِدْعَمٌ يَحُطُّ رحل رسول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا جَاءَهُ سَهْمٌ عَائِرٌ فأصابه فَقَتَلَهُ فَقَالَ النَّاسُ: هَنِيئًا لَهُ الْجَنَّةُ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : كَلاَّ وَالَّذِي نَفْسِي بِيَدِهِ إِنَّ الشَّمْلَةَ الَّتِي أَخَذَهَا يَوْمَ خَيْبَرَ مِنَ الْمَغَانِمِ لَمْ تُصِبْهَا الْمَقَاسِمُ لَتَشْتَعِلُ عَلَيْهِ نَارًا، فَلَمَّا سَمِعَ ذَلِكَ النَّاسُ جَاءَ رَجُلٌ بِشِرَاكٍ أَوْ شِرَاكَيْنِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: شِرَاكٌ مِنْ نَارٍ أَوْ شِرَاكَانِ مِنْ نَارٍ."],"takhrij":"متفق عليه: رواه مالك في الجهاد (25) عن ثور بن زيد الديلي، عن أبي الغيث سالم مولى ابن مطيع، عن أبي هريرة فذكره. ورواه البخاري في المغازي (4234)، ومسلم في الإيمان (115) كلاهما من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تحريم الغلول","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (25), al-Bukhari (4234), and Muslim (115).","chapter_en":"What Has Been Reported Concerning the Prohibition of Stealing from Spoils","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah said: We went out with the Messenger of Allah ﷺ on the day of Khaybar, and we did not gain gold or silver as spoils, only goods: clothing and belongings. Rifaʿah ibn Zayd gifted the Messenger of Allah ﷺ a black slave called Midʿam. The Messenger of Allah ﷺ set out toward Wadi al-Qura. When we were at Wadi al-Qura, while Midʿam was unloading the saddle of the Messenger of Allah ﷺ, a stray arrow came and struck him, killing him. The people said: “Congratulations to him for Paradise.” The Messenger of Allah ﷺ said: “No. By the One in whose hand is my soul, the cloak that he took from the spoils on the day of Khaybar before the shares were distributed is burning upon him as fire.” When the people heard this, a man came to the Prophet ﷺ with one or two sandal straps. He said: “A strap of fire, or two straps of fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (25)، والبخاري (4234)، ومسلم (115)."},{"num":8044,"demo":false,"sanad":"","matn":["عن عُمَرَ بن الْخَطَّابِ قَالَ:  لَمَّا كَانَ يَوْمُ خَيْبَرَ أَقْبَلَ نَفَرٌ مِنْ صَحَابَةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: فُلَانٌ شَهِيدٌ، فُلَانٌ شَهِيدٌ، حَتَّى مَرُّوا عَلَى رَجُلٍ، فَقَالُوا: فُلَانٌ شَهِيدٌ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَلَّا إِنِّي رَأَيْتُهُ فِي النَّارِ فِي بُرْدَةٍ غَلَّهَا أَوْ عَبَاءَةٍ، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا ابْنَ الْخَطَّابِ، اذْهَبْ فَنَادِ فِي النَّاسِ أَِنَّهُ: لَا يَدْخُلُ الْجَنَّةَ إِلَّا الْمُؤْمِنُونَ، قَالَ: فَخَرَجْتُ فَنَادَيْتُ: أَلَا إِنَّهُ لَا يَدْخُلُ الْجَنَّةَ إِلَّا الْمُؤْمِنُونَ."],"takhrij":"صحيح: رواه مسلم في الإيمان (114) عن زهير بن حرب، حدثنا هاشم بن القاسم، حدثنا عكرمة بن عمار، حدثني سماك الحنفي أبو زُميل، حدثني عبد الله بن عباس، حدثني عمر بن الخطاب فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تحريم الغلول","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (114).","chapter_en":"What Has Been Reported Concerning the Prohibition of Stealing from Spoils","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["ʿUmar ibn al-Khattab said: On the day of Khaybar, a group of the Prophet’s ﷺ companions came saying: “So-and-so is a martyr, so-and-so is a martyr,” until they passed by a man and said: “So-and-so is a martyr.” The Messenger of Allah ﷺ said: “No. I saw him in the Fire because of a cloak or mantle that he stole from the spoils.” Then the Messenger of Allah ﷺ said: “O son of al-Khattab, go and announce among the people that no one enters Paradise except the believers.” He said: So I went out and announced: “Indeed, no one enters Paradise except the believers.”"]}},"tuhfa":{},"full":1,"rep":[98,9085,16348],"tks":"صحيح: رواه مسلم (114)."},{"num":8045,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، قَالَ: كَانَ عَلَى ثَقَلِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ يُقَالُ لَهُ كِرْكِرَةُ فَمَاتَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هُوَ فِي النَّارِ. فَذَهَبُوا يَنْظُرُونَ إِلَيْهِ فَوَجَدُوا عَبَاءَةً قَدْ غَلَّهَا."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (3074) عن علي بن عبد الله، حدثنا سفيان، عن عمرو، عن سالم بن أبي الجعد، عن عبد الله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تحريم الغلول","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3074).","chapter_en":"What Has Been Reported Concerning the Prohibition of Stealing from Spoils","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs said: A man called Karkarah was in charge of the Prophet’s ﷺ baggage. He died, and the Messenger of Allah ﷺ said: “He is in the Fire.” They went to look at him and found a mantle that he had stolen from the spoils."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3074)."},{"num":8046,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ، قَالَ: قَالَ رَسُولُ اللَّهِ مَنْ مَاتَ وَهُوَ بَرِيءٌ مِنْ ثَلاَثٍ الْكِبْرِ، وَالْغُلُولِ، وَالدَّيْنِ دَخَلَ الْجَنَّةَ."],"takhrij":"صحيح: رواه الترمذي (1572)، وابن ماجه (2412)، وأحمد (22427)، وابن حبان (198)، والحاكم (2218)، والبيهقي (18208)، والدارمي (2634) كلهم من حديث سعيد بن أبي عروبة، عن قتادة، عن سالم بن أبي الجعد، عن معدان بن أبي طلحة، عن ثوبان مولى رسول الله صلى الله عليه وسلم فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في تحريم الغلول","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1572), Ibn Majah (2412), Ahmad (22427), Ibn Hibban (198), al-Hakim (2218), al-Bayhaqi (5/355), and al-Darimi (2634).","chapter_en":"What Has Been Reported Concerning the Prohibition of Stealing from Spoils","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["Thawban said: The Messenger of Allah ﷺ said: “Whoever dies while free of three things — arrogance, stealing from spoils, and debt — will enter Paradise.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه الترمذي (1572)، وابن ماجه (2412)، وأحمد (22427)، وابن حبان (198)، والحاكم (2218)، والبيهقي (18208)، والدارمي (2634)."},{"num":8047,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَصَابَ غَنِيمَةً أَمَرَ بِلاَلاً فَنَادَى فِي النَّاسِ فَيَجِيئُونَ بِغَنَائِمِهِمْ فَيُخَمِّسُهُ وَيُقَسِّمُهُ، فَجَاءَ رَجُلٌ بَعْدَ ذَلِكَ بِزِمَامٍ مِنْ شَعَرٍ، فَقَالَ: يَا رَسُولَ اللَّهِ هَذَا فِيمَا كُنَّا أَصَبْنَاهُ مِنَ الْغَنِيمَةِ. فَقَالَ: أَسَمِعْتَ بِلاَلاً يُنَادِي. ثَلاَثًا. قَالَ نَعَمْ. قَالَ: فَمَا مَنَعَكَ أَنْ تَجِيءَ بِهِ. فَاعْتَذَرَ إِلَيْهِ فَقَالَ: كُنْ أَنْتَ تَجِيءُ بِهِ يَوْمَ الْقِيَامَةِ فَلَنْ أَقْبَلَهُ عَنْكَ."],"takhrij":"حسن: رواه أبو داود (2712)، وأحمد (6996)، وصحّحه ابن حبان (4809)، والحاكم (2583) كلهم من طرق عن عبد الله بن شوذب، حدثني عامر بن عبد الواحد، عن عبد الله بن بريدة، عن عبد الله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تحريم الغلول","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2712), Ahmad (6996), and authenticated by Ibn Hibban (4809) and al-Hakim (2/127 and 129).","chapter_en":"What Has Been Reported Concerning the Prohibition of Stealing from Spoils","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr said: When the Messenger of Allah ﷺ obtained spoils, he would order Bilal to call out among the people. They would bring their spoils, and he would take the fifth and divide the rest. Then a man came afterward with a hair rein and said: “O Messenger of Allah, this is from what we obtained from the spoils.” He said: “Did you hear Bilal call out three times?” He said: “Yes.” He said: “Then what prevented you from bringing it?” He offered an excuse, but he said: “You will be the one to bring it on the Day of Resurrection; I will not accept it from you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2712)، وأحمد (6996)، وصححه ابن حبان (4809)، والحاكم (2583)."},{"num":8048,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَانَ يَأْخُذُ الْوَبَرَةَ مِنْ جَنْبِ الْبَعِيرِ مِنَ الْمَغْنَمِ فَيَقُولُ: مَا لِي فِيهِ إِلَّا مِثْلُ مَا لِأَحَدِكُمْ مِنْهُ، إِيَّاكُمْ وَالْغُلُولَ؛ فَإِنَّ الْغُلُولَ خِزْيٌ عَلَى صَاحِبِهِ يَوْمَ الْقِيَامَةِ، أَدُّوا الْخَيْطَ وَالْمَخِيطَ، وَمَا فَوْقَ ذَلِكَ، وَجَاهِدُوا فِي سَبِيلِ اللَّهِ الْقَرِيبَ وَالْبَعِيدَ فِي الْحَضَرِ وَالسَّفَرِ؛ فَإِنَّ الْجِهَادَ بَابٌ مِنْ أَبْوَابِ الْجَنَّةِ، إِنَّهُ لَيُنَجِّي اللهُ بِهِ مِنَ الْهَمِّ وَالْغَمِّ، وَأَقِيمُوا حُدُودَ اللَّهِ فِي الْقَرِيبِ وَالْبَعِيدِ، وَلَا تَأْخُذْكُمْ فِي اللَّهِ لَوْمَةُ لَائِمٍ."],"takhrij":"حسن: رواه عبد الله بن أحمد في زوائده على المسند (22795) عن عبد الله بن سالم الكوفي المفلوج، حدثنا عبيدة بن الأسود، عن القاسم بن الوليد، عن أبي صادق، عن ربيعة بن ناجد، عن عبادة بن الصامت فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تحريم الغلول","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by ʿAbdullah ibn Ahmad in his additions to al-Musnad (22795).","chapter_en":"What Has Been Reported Concerning the Prohibition of Stealing from Spoils","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["ʿUbadah ibn al-Samit narrated that the Prophet ﷺ would take a single hair from the side of a camel from the spoils and say: “I have no right in it except like the right of any one of you. Beware of stealing from the spoils, for stealing from the spoils will be disgrace upon its doer on the Day of Resurrection. Return the thread, the needle, and whatever is above that. Strive in the path of Allah Most High, near or far, while resident or traveling, for jihad is one of the gates of Paradise. Through it Allah, Blessed and Most High, saves from anxiety and grief. Establish the limits of Allah for the near and the far, and let not the blame of any blamer affect you regarding Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه عبد الله بن أحمد في زوائده على المسند (22795)."},{"num":8049,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن شَقِيقٍ أَنَّهُ أَخْبَرَهُ مَنْ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ بِوَادِي الْقُرَى، وَهُوَ عَلَى فَرَسِهِ، وَسَأَلَهُ رَجُلٌ مِنْ بُلْقِينَ، فَقَالَ: يَا رَسُولَ اللَّهِ، مَنْ هَؤُلَاءِ؟ قَالَ: هَؤُلَاءِ الْمَغْضُوبُ عَلَيْهِمْ، وَأَشَارَ إِلَى الْيَهُودِ. قَالَ: فَمَنْ هَؤُلَاءِ؟ قَالَ: هَؤُلَاءِ الضَّالُّونَ يَعْنِي النَّصَارَى، قَالَ: وَجَاءَهُ رَجُلٌ، فَقَالَ: اسْتُشْهِدَ مَوْلَاكَ، أَوْ قَالَ: غُلَامُكَ فُلَانٌ، قَالَ: بَلْ يُجَرُّ إِلَى النَّارِ فِي عَبَاءَةٍ غَلَّهَا."],"takhrij":"صحيح: رواه أحمد (20351) عن عبد الرزاق، حدثنا معمر، عن بديل العقيلي قال: أخبرني عبد الله بن شقيق فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تحريم الغلول","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (20351).","chapter_en":"What Has Been Reported Concerning the Prohibition of Stealing from Spoils","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullah ibn Shaqiq narrated from one who heard the Prophet ﷺ while he was in Wadi al-Qura, mounted on his horse. A man from Balqayn asked him: “O Messenger of Allah, who are these?” He said: “These are those who incurred wrath,” and he pointed to the Jews. He said: “Then who are these?” He said: “These are those who went astray,” meaning the Christians. He said: A man came to him and said: “Your freedman” — or he said, “your servant” — “so-and-so has been martyred.” He said: “Rather, he is being dragged to the Fire because of a mantle he stole from the spoils.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (20351)."},{"num":8050,"demo":false,"sanad":"","matn":["عَنْ ثابت بن رفيع – وَكَانَ يؤمر على السرايا – سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِيَّاكُمْ وَالْغُلُولَ، الرَّجُلُ يَنْكِحُ الْمَرْأَةَ قَبْلَ أَنْ يقسم، ثُمَّ يَرُدُّهَا إِلَى الْقَسْمِ، أَوْ يَلْبَسُ الثَّوْبَ حَتَّى يَخْلُقَ ثُمَّ يَرُدُّهَا إِلَى الْقَسْمِ."],"takhrij":"صحيح: رواه ابن أبي شيبة في مسنده (654)، -ومن طريقه ابن أبي عاصم في الآحاد والمثاني (2198)، والطبراني في الكبير (5/16)- كلاهما من طريق عبيد الله بن موسى، عن إسرائيل، عن زياد المصفر، عن الحسن، حدثني ثابت بن رفيع فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تحريم الغلول","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Abi Shaybah in his Musnad (654), Ibn Abi ʿAsim in al-Ahad wa al-Mathani (2198), and al-Tabarani in al-Kabir (5/16).","chapter_en":"What Has Been Reported Concerning the Prohibition of Stealing from Spoils","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["Thabit ibn Rafiʿ — who used to be appointed over detachments — said: I heard the Messenger of Allah ﷺ say: “Beware of stealing from the spoils: a man has relations with a woman before she is distributed, then returns her to the division; or he wears a garment until it becomes worn out, then returns it to the division.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن أبي شيبة في مسنده (654)، وابن أبي عاصم في الآحاد والمثاني (2198)، والطبراني في الكبير (5/16)."},{"num":8051,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ سَرِيَّةً فِيهَا عَبْدُ اللَّهِ بْنُ عُمَرَ قِبَلَ نَجْدٍ، فَغَنِمُوا إِبِلاً كَثِيرَةً فَكَانَ سُهْمَانُهُمُ اثْنَىْ عَشَرَ بَعِيرًا أَوْ أَحَدَ عَشَرَ بَعِيرًا، وَنُفِّلُوا بَعِيرًا بَعِيرًا."],"takhrij":"متفق عليه: رواه مالك في الجهاد (10) عن نافع، عن عبد الله بن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الأنفال","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (10), al-Bukhari (3134), and Muslim (1749:35).","chapter_en":"What Has Been Reported Concerning Extra Shares","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar narrated that the Messenger of Allah ﷺ sent a detachment toward Najd, and ʿAbdullah ibn ʿUmar was among it. They acquired many camels as spoils. Their shares were twelve camels, or eleven camels, each, and they were each given one camel as an extra share."]},"intro":{"ar":["قال تعالى:","(يَسْأَلُونَكَ عَنِ الْأَنْفَالِ قُلِ الْأَنْفَالُ لِلَّهِ وَالرَّسُولِ فَاتَّقُوا اللهَ وَأَصْلِحُوا ذَاتَ بَيْنِكُمْ وَأَطِيعُوا اللهَ وَرَسُولَهُ إِن كُنتُم مُّؤْمِنِينَ) [سورة الأنفال: ١]."],"en":["Allah Most High said:","“They ask you about the spoils. Say: The spoils belong to Allah and the Messenger. So fear Allah, reconcile between yourselves, and obey Allah and His Messenger, if you are believers.” [Surat al-Anfal: 1]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (10)، والبخاري (3134)، ومسلم (1749: 35)."},{"num":8052,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عُمَرَ قَالَ: نَفَّلَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَفَلًا سِوَى نَصِيبِنَا مِنَ الْخُمُْسِ، فَأَصَابَنِي شَارِفٌ، (وَالشَّارِفُ: الْمُسِنُّ الْكَبِيرُ."],"takhrij":"صحيح: رواه مسلم في الجهاد والسير (1750: 38) من طريق عبد الله بن رجاء، عن يونس، عن الزهري، عن سالم، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الأنفال","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1750:38).","chapter_en":"What Has Been Reported Concerning Extra Shares","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: The Messenger of Allah ﷺ gave us an extra share apart from our share of the fifth, and I received an old she-camel. “Al-sharif” means an old, aged camel."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1750: 38)."},{"num":8053,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ كَانَ يُنَفِّلُ بَعْضَ مَنْ يَبْعَثُ مِنَ السَّرَايَا لِأَنْفُسِهِمْ خَاصَّةً سِوَى قَسْمِ عَامَّةِ الْجَيْشِ، وَالْخُمُْسُ فِي ذَلِكَ وَاجِبٌ كُلِّهِ."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3135)، ومسلم في الجهاد والسير (1750: 40) كلاهما من طريق الليث، حدثني عقيل بن خالد، عن ابن شهاب، عن سالم، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الأنفال","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3135) and Muslim (1750:40).","chapter_en":"What Has Been Reported Concerning Extra Shares","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ would give extra shares to some of those he sent in detachments, specifically for themselves, apart from the general division of the army; and the fifth was obligatory in all of that."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3135)، ومسلم (1750: 40)."},{"num":8054,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بن أَبِي وَقَّاصٍ قَالَ: نَزَلَتْ فيّ أَرْبَعُ آيَاتٍ، أَصَبْتُ سَيْفًا فَأَتَى بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ نَفِّلْنِيهِ فَقَالَ: ضعْه، ثُمَّ قَامَ، فَقَالَ لَهُ النَّبِيُّ : صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَعْهُ مِنْ حَيْثُ أَخَذْتَهُ، ثُمَّ قَامَ، فَقَالَ: نَفِّلْنِيهِ يَا رَسُولَ اللَّهِ، فَقَالَ: ضَعْهُ فَقَامَ، فَقَالَ: يَا رَسُولَ اللَّهِ نَفِّلْنِيهِ أَأُجْعَلُ كَمَنْ لَا غَنَاءَ لَهُ؟ فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : ضَعْهُ مِنْ حَيْثُ أَخَذْتَهُ، قَالَ: فَنَزَلَتْ هَذِهِ الْآيَةُ ﴿يَسْأَلُونَكَ عَنِ الْأَنْفَالِ قُلِ الْأَنْفَالُ لِلَّهِ وَالرَّسُولِ﴾. [سورة الأنفال: 1] ."],"takhrij":"صحيح: رواه مسلم في الجهاد والسير (1748: 34) من طريق محمد بن جعفر، حدثنا شعبة، عن سماك بن حرب، عن مصعب بن سعد، عن أبيه، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الأنفال","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1748:34).","chapter_en":"What Has Been Reported Concerning Extra Shares","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["Saʿd ibn Abi Waqqas said: Four verses were revealed concerning me. I obtained a sword, and it was brought to the Prophet ﷺ. I said: “O Messenger of Allah, give it to me as an extra share.” He said: “Put it down.” Then he stood up, and the Prophet ﷺ said to him: “Put it where you took it from.” Then he stood and said: “Give it to me as an extra share, O Messenger of Allah.” He said: “Put it down.” Then he stood and said: “O Messenger of Allah, give it to me as an extra share. Am I to be made like one who has no benefit?” The Prophet ﷺ said to him: “Put it where you took it from.” He said: Then this verse was revealed: “They ask you about the spoils. Say: The spoils belong to Allah and the Messenger.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12351],"tks":"صحيح: رواه مسلم (1748: 34)."},{"num":8055,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَنَفَّلَ سَيْفَهُ ذَا الْفَقَارِ يَوْمَ بَدْرٍ، وَهُوَ الَّذِي رَأَى فِيهِ الرُّؤْيَا يَوْمَ أُحُدٍ."],"takhrij":"حسن: رواه الترمذي (1561) –واللفظ له- وابن ماجه (2808)، وأحمد (2445)، والحاكم (2588) وعنه البيهقي في السنن (13282) من طرق عن عبد الرحمن بن أبي الزناد، عن أبيه، عن عبيد الله بن عبد الله بن عتبة بن مسعود، عن ابن عباس فذكره. وسياق أحمد والحاكم طويل.","grade":"حسن","chapter_ar":"باب ما جاء في الأنفال","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1561) — this is his wording — Ibn Majah (2808), Ahmad (2445), al-Hakim (2588), and through him al-Bayhaqi in al-Sunan (7/41).","chapter_en":"What Has Been Reported Concerning Extra Shares","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["Ibn ʿAbbas narrated that the Prophet ﷺ took as an extra share his sword Dhu al-Fiqar on the day of Badr, and it was the one concerning which he saw the dream on the day of Uhud."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1561) — واللفظ له — وابن ماجه (2808)، وأحمد (2445)، والحاكم (2588)، وعنه البيهقي في السنن (13282)."},{"num":8056,"demo":false,"sanad":"","matn":["عن أَبِي الجويرية قَالَ: أَصَبْتُ جَرَّةً حَمْرَاءَ فِيهَا دَنَانِيرُ، فِي إِمَارَةِ مُعَاوِيَةَ فِي أَرْضِ الرُّومِ، قَالَ: وَعَلَيْنَا رَجُلٌ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، مِنْ بَنِي سُلَيْمٍ، يُقَالُ لَهُ: مَعْنُ بْنُ يَزِيدَ، قَالَ: فَأَتَيْتُ بِهَا يَقْسِمُهَا بَيْنَ الْمُسْلِمِينَ، فَأَعْطَانِي مِثْلَ مَا أَعْطَى رَجُلًا مِنْهُمْ، ثُمَّ قَالَ: لَوْلَا أَنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَرَأَيْتُهُ يَفْعَلُهُ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا نَفْلَ إِلَّا بَعْدَ الْخُمُسِ إِذًا لَأَعْطَيْتُكَ، قَالَ: ثُمَّ أَخَذَ فَعَرَضَ عَلَيَّ مِنْ نَصِيبِهِ فَأَبَيْتُ عَلَيْهِ، قُلْتُ: مَا أَنَا بِأَحَقَّ بِهِ مِنْكَ."],"takhrij":"حسن: رواه أبو داود (2754)، وأحمد (15862)، والبيهقي (12809) من طرق عن عاصم بن كليب قال: حدثني أبو الجويرية فذكره. واللفظ لأحمد.","grade":"حسن","chapter_ar":"باب ما جاء في الأنفال","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2754), Ahmad (15862), and al-Bayhaqi (6/314). The wording is Ahmad’s.","chapter_en":"What Has Been Reported Concerning Extra Shares","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["Abu al-Juwayriyah said: I found a red jar containing dinars during the governorship of Muʿawiyah in the land of the Romans. He said: Over us was a man from the companions of the Messenger of Allah ﷺ from Banu Sulaym called Maʿn ibn Yazid. He said: I brought it to him so that he could divide it among the Muslims, and he gave me the same as he gave one of them. Then he said: “Were it not that I heard the Messenger of Allah ﷺ and saw him do it — I heard the Messenger of Allah ﷺ say: ‘There is no extra share except after the fifth’ — I would have given you more.” He said: Then he began offering me from his own share, but I refused and said: “I do not have more right to it than you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2754)، وأحمد (15862)، والبيهقي (12809). واللفظ لأحمد."},{"num":8057,"demo":false,"sanad":"","matn":["عَنْ حَبِيبِ بْنِ مَسْلَمَةَ الْفِهْرِيِّ، أَنَّهُ قَالَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُنَفِّلُ الثُّلُثَ بَعْدَ الْخُمُسِ.","وفي لفظ: أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم نَفَلَ الرُّبُعَ بَعْدَ الْخُمُسِ فِي بَدْأَتِهِ، وَنَفَلَ الثُّلُثَ بَعْدَ الْخُمُسِ."],"takhrij":"صحيح: رواه أبو داود (2748-2750)، وابن ماجه (2851)، وأحمد (17462)، وابن حبان (4835)، والحاكم (2599)، والبيهقي (12807) كلهم من طرق عن مكحول، عن زياد بن جارية –أو زيد بن جارية- عن حبيب بن مسلمة، الفهري فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الأنفال","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2748–2750), Ibn Majah (2851), Ahmad (17462), Ibn Hibban (4835), al-Hakim (2/133), and al-Bayhaqi (6/314).","chapter_en":"What Has Been Reported Concerning Extra Shares","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["Habib ibn Maslamah al-Fihri narrated: The Messenger of Allah ﷺ used to give one-third as an extra share after taking the fifth. In another wording: The Messenger of Allah ﷺ gave one-fourth after taking the fifth at the beginning of the expedition, and one-third after taking the fifth."]},"buhuth":{"en":["His saying, “he gave an extra share after the fifth,” means that he first took the fifth from the entire spoils, then gave one-third or one-fourth from what remained of the four-fifths, then divided the rest among those who had acquired the spoils.","His saying, “at its beginning,” means at the beginning of the expedition. This refers to a detachment that rises from the army and rushes ahead toward the enemy at the beginning of the campaign; whatever they acquire, he would give them one-fourth of it, and the rest would be divided among the whole army. If a group did something similar when the army was returning, he would give them one-third of what they acquired, because doing that during the return of the army is harder due to the weakness of mounts, equipment, fatigue, and increased longing for home, so he increased it for that reason."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2748-2750)، وابن ماجه (2851)، وأحمد (17462)، وابن حبان (4835)، والحاكم (2599)، والبيهقي (12807)."},{"num":8058,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَتْ أَمْوَالُ بَنِي النَّضِيرِ مِمَّا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِمَّا لَمْ يُوجِفِ الْمُسْلِمُونَ عَلَيْهِ بِخَيْلٍ وَلاَ رِكَابٍ، فَكَانَتْ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاصَّةً، وَكَانَ يُنْفِقُ عَلَى أَهْلِهِ نَفَقَةَ سَنَتِهِ، ثُمَّ يَجْعَلُ مَا بَقِيَ فِي السِّلاَحِ وَالْكُرَاعِ، عُدَّةً فِي سَبِيلِ اللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2904)، ومسلم في الجهاد والسير (1757: 48) كلاهما من طريق سفيان (هو ابن عيينة)، عن عمرو (هو ابن دينار)، عن الزهري، عن مالك بن أوس، عن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الفيء","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2904) and Muslim (1757:48).","chapter_en":"What Has Been Reported Concerning Fay’","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":17,"content":{"translation":{"en":["ʿUmar ibn al-Khattab said: The wealth of Banu al-Nadir was from what Allah restored to His Messenger ﷺ, for which the Muslims did not spur any horses or camels. It belonged specifically to the Messenger of Allah ﷺ. He would spend from it on his family for the expenses of a year, then place what remained in weapons and horses as preparation in the path of Allah."]},"intro":{"ar":["قال الله تعالى:","(وَمَا أَفَاءَ اللهُ عَلَىٰ رَسُولِهِ مِنْهُمْ فَمَا أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ وَلَٰكِنَّ اللهَ يُسَلِّطُ رُسُلَهُ عَلَىٰ مَن يَشَاءُ ۚ وَاللهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ) [سورة الحشر: ٦]."],"en":["Allah Most High said:","“And what Allah restored to His Messenger from them — you did not spur for it any horses or camels, but Allah gives His messengers authority over whom He wills. And Allah is over all things powerful.” [Surat al-Hashr: 6]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2904)، ومسلم (1757: 48)."},{"num":8059,"demo":false,"sanad":"","matn":["عن مَالِكِ بن أَوْسٍ بْنِ الْحَدَثَانِ قَالَ: بَيْنَا أَنَا جَالِسٌ فِي أَهْلِي حِينَ مَتَعَ النَّهَارُ، إِذَا رَسُولُ عُمَرَ بْنِ الْخَطَّابِ يَأْتِينِي فَقَالَ: أَجِبْ أَمِيرَ الْمُؤْمِنِينَ. فَانْطَلَقْتُ مَعَهُ حَتَّى أَدْخُلَ عَلَى عُمَرَ، فَإِذَا هُوَ جَالِسٌ عَلَى رِمَالِ سَرِيرٍ، لَيْسَ بَيْنَهُ وَبَيْنَهُ فِرَاشٌ مُتَّكِئٌ عَلَى وِسَادَةٍ مِنْ أَدَمٍ، فَسَلَّمْتُ عَلَيْهِ، ثُمَّ جَلَسْتُ فَقَالَ: يَا مَالِ، إِنَّهُ قَدِمَ عَلَيْنَا مِنْ قَوْمِكَ أَهْلُ أَبْيَاتٍ، وَقَدْ أَمَرْتُ فِيهِمْ بِرَضْخٍ فَاقْبِضْهُ، فَاقْسِمْهُ بَيْنَهُمْ. فَقُلْتُ: يَا أَمِيرَ الْمُؤْمِنِينَ، لَوْ أَمَرْتَ بِهِ غَيْرِي. قَالَ: اقْبِضْهُ أَيُّهَا الْمَرْءُ. فَبَيْنَا أَنَا جَالِسٌ عِنْدَهُ أَتَاهُ حَاجِبُهُ يَرْفَا فَقَالَ: هَلْ لَكَ فِي عُثْمَانَ وَعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ وَالزُّبَيْرِ وَسَعْدِ بْنِ أَبِي وَقَّاصٍ يَسْتَأْذِنُونَ؟ قَالَ: نَعَمْ. فَأَذِنَ لَهُمْ فَدَخَلُوا فَسَلَّمُوا وَجَلَسُوا، ثُمَّ جَلَسَ يَرْفَا يَسِيرًا ثُمَّ قَالَ: هَلْ لَكَ فِي عَلِيٍّ وَعَبَّاسٍ قَالَ نَعَمْ. فَأَذِنَ لَهُمَا، فَدَخَلاَ فَسَلَّمَا فَجَلَسَا، فَقَالَ عَبَّاسٌ: يَا أَمِيرَ الْمُؤْمِنِينَ، اقْضِ بَيْنِي وَبَيْنَ هَذَا. وَهُمَا يَخْتَصِمَانِ فِيمَا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ بَنِي النَّضِيرِ. فَقَالَ الرَّهْطُ عُثْمَانُ وَأَصْحَابُهُ: يَا أَمِيرَ الْمُؤْمِنِينَ، اقْضِ بَيْنَهُمَا وَأَرِحْ أَحَدَهُمَا مِنَ الآخَرِ. قَالَ عُمَرُ: تَيْدَكُمْ، أَنْشُدُكُمْ بِاللَّهِ الَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالأَرْضُ، هَلْ تَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ نُورَثُ مَا تَرَكْنَا صَدَقَةٌ. يُرِيدُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَفْسَهُ. قَالَ الرَّهْطُ: قَدْ قَالَ ذَلِكَ. فَأَقْبَلَ عُمَرُ عَلَى عَلِيٍّ وَعَبَّاسٍ فَقَالَ: أَنْشُدُكُمَا اللَّهَ، أَتَعْلَمَانِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ قَالَ ذَلِكَ؟ قَالاَ: قَدْ قَالَ ذَلِكَ. قَالَ عُمَرُ: فَإِنِّي أُحَدِّثُكُمْ عَنْ هَذَا الأَمْرِ، إِنَّ اللَّهَ قَدْ خَصَّ رَسُولَهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي هَذَا الْفَىْءِ بِشَىْءٍ لَمْ يُعْطِهِ أَحَدًا غَيْرَهُ ـ ثُمَّ قَرَأَ ﴿وَمَا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ مِنْهُمْ﴾ [سورة الحشر: 6]} إِلَى قَوْلِهِ {قَدِيرٌ} ـ فَكَانَتْ هَذِهِ خَالِصَةً لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَاللَّهِ مَا احْتَازَهَا دُونَكُمْ، وَلاَ اسْتَأْثَرَ بِهَا عَلَيْكُمْ قَدْ أَعْطَاكُمُوهُ، وَبَثَّهَا فِيكُمْ حَتَّى بَقِيَ مِنْهَا هَذَا الْمَالُ، فَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُنْفِقُ عَلَى أَهْلِهِ نَفَقَةَ سَنَتِهِمْ مِنْ هَذَا الْمَالِ، ثُمَّ يَأْخُذُ مَا بَقِيَ، فَيَجْعَلُهُ مَجْعَلَ مَالِ اللَّهِ، فَعَمِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِذَلِكَ حَيَاتَهُ، أَنْشُدُكُمْ بِاللَّهِ هَلْ تَعْلَمُونَ ذَلِكَ؟ قَالُوا: نَعَمْ. ثُمَّ قَالَ لِعَلِيٍّ وَعَبَّاسٍ: أَنْشُدُكُمَا بِاللَّهِ هَلْ تَعْلَمَانِ ذَلِكَ؟ قَالَ عُمَرُ: ثُمَّ تَوَفَّى اللَّهُ نَبِيَّهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ أَبُو بَكْرٍ: أَنَا وَلِيُّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَبَضَهَا أَبُو بَكْرٍ، فَعَمِلَ فِيهَا بِمَا عَمِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَاللَّهُ يَعْلَمُ إِنَّهُ فِيهَا لَصَادِقٌ بَارٌّ رَاشِدٌ تَابِعٌ لِلْحَقِّ، ثُمَّ تَوَفَّى اللَّهُ أَبَا بَكْرٍ، فَكُنْتُ أَنَا وَلِيَّ أَبِي بَكْرٍ، فَقَبَضْتُهَا سَنَتَيْنِ مِنْ إِمَارَتِي، أَعْمَلُ فِيهَا بِمَا عَمِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَا عَمِلَ فِيهَا أَبُو بَكْرٍ، وَاللَّهُ يَعْلَمُ إِنِّي فِيهَا لَصَادِقٌ بَارٌّ رَاشِدٌ تَابِعٌ لِلْحَقِّ، ثُمَّ جِئْتُمَانِي تُكَلِّمَانِي وَكَلِمَتُكُمَا وَاحِدَةٌ، وَأَمْرُكُمَا وَاحِدٌ، جِئْتَنِي يَا عَبَّاسُ تَسْأَلُنِي نَصِيبَكَ مِنِ ابْنِ أَخِيكَ، وَجَاءَنِي هَذَا ـ يُرِيدُ عَلِيًّا ـ يُرِيدُ نَصِيبَ امْرَأَتِهِ مِنْ أَبِيهَا، فَقُلْتُ لَكُمَا إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لاَ نُورَثُ مَا تَرَكْنَا صَدَقَةٌ. فَلَمَّا بَدَا لِي أَنْ أَدْفَعَهُ إِلَيْكُمَا قُلْتُ: إِنْ شِئْتُمَا دَفَعْتُهَا إِلَيْكُمَا عَلَى أَنَّ عَلَيْكُمَا عَهْدَ اللَّهِ وَمِيثَاقَهُ لَتَعْمَلاَنِ فِيهَا بِمَا عَمِلَ فِيهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَبِمَا عَمِلَ فِيهَا أَبُو بَكْرٍ، وَبِمَا عَمِلْتُ فِيهَا مُنْذُ وَلِيتُهَا، فَقُلْتُمَا: ادْفَعْهَا إِلَيْنَا. فَبِذَلِكَ دَفَعْتُهَا إِلَيْكُمَا، فَأَنْشُدُكُمْ بِاللَّهِ، هَلْ دَفَعْتُهَا إِلَيْهِمَا بِذَلِكَ؟ قَالَ الرَّهْطُ: نَعَمْ. ثُمَّ أَقْبَلَ عَلَى عَلِيٍّ وَعَبَّاسٍ فَقَالَ: أَنْشُدُكُمَا بِاللَّهِ هَلْ دَفَعْتُهَا إِلَيْكُمَا بِذَلِكَ؟ قَالاَ: نَعَمْ. قَالَ: فَتَلْتَمِسَانِ مِنِّي قَضَاءً غَيْرَ ذَلِكَ، فَوَاللَّهِ الَّذِي بِإِذْنِهِ تَقُومُ السَّمَاءُ وَالأَرْضُ، لاَ أَقْضِي فِيهَا قَضَاءً غَيْرَ ذَلِكَ، فَإِنْ عَجَزْتُمَا عَنْهَا فَادْفَعَاهَا إِلَىَّ، فَإِنِّي أَكْفِيكُمَاهَا."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3094) عن إسحاق بن محمد الفروي، حدثنا مالك بن أنس، عن ابن شهاب، عن مالك بن أوس بن الحدثان فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الفيء","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3094) and Muslim (1756:49).","chapter_en":"What Has Been Reported Concerning Fay’","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":17,"content":{"translation":{"en":["Malik ibn Aws ibn al-Hadathan said: While I was sitting with my family in the late morning, a messenger of ʿUmar ibn al-Khattab came to me and said: “Answer the Commander of the Believers.” I went with him until I entered upon ʿUmar, and there he was sitting on the woven matting of a bed, with no mattress between him and it, leaning on a leather cushion. I greeted him, then sat down. He said: “O Malik, some households from your people have come to us, and I have ordered that a gift be given to them. Take it and divide it among them.” I said: “O Commander of the Believers, if only you would order someone else to do it.” He said: “Take it, O man.” While I was sitting with him, his doorkeeper Yarfa’ came and said: “Do you permit ʿUthman, ʿAbd al-Rahman ibn ʿAwf, al-Zubayr, and Saʿd ibn Abi Waqqas to enter?” He said: “Yes.” So he gave them permission, and they entered, greeted, and sat. Then Yarfa’ sat a little while and said: “Do you permit ʿAli and ʿAbbas to enter?” He said: “Yes.” He gave them permission, and they entered, greeted, and sat. Al-ʿAbbas said: “O Commander of the Believers, judge between me and this one” — while they were disputing — “concerning what Allah restored to His Messenger ﷺ from the wealth of Banu al-Nadir.” The group, ʿUthman and his companions, said: “O Commander of the Believers, judge between them and relieve one of them from the other.” ʿUmar said: “Wait. I ask you by Allah, by whose permission the heaven and earth stand: do you know that the Messenger of Allah ﷺ said: ‘We are not inherited from; what we leave is charity,’ meaning the Messenger of Allah ﷺ himself?” The group said: “He did say that.” Then ʿUmar turned to ʿAli and ʿAbbas and said: “I ask you both by Allah: do you know that the Messenger of Allah ﷺ said that?” They said: “He did say that.” ʿUmar said: “I will tell you about this matter. Allah singled out His Messenger ﷺ with this fay’ in a way He did not give to anyone else.” Then he recited: “And what Allah restored to His Messenger from them…” until His saying: “Powerful.” “So this belonged exclusively to the Messenger of Allah ﷺ. By Allah, he did not keep it away from you, nor did he prefer himself over you with it. He gave it to you and distributed it among you until this wealth remained from it. The Messenger of Allah ﷺ used to spend from this wealth on his family for their yearly expenses, then take what remained and place it where the wealth of Allah was placed. The Messenger of Allah ﷺ acted according to that during his life. I ask you by Allah: do you know that?” They said: “Yes.” Then he said to ʿAli and ʿAbbas: “I ask you both by Allah: do you know that?” They said: “Yes.” ʿUmar said: “Then Allah took His Prophet ﷺ, and Abu Bakr said: ‘I am the successor responsible for the Messenger of Allah ﷺ.’ Abu Bakr took charge of it and acted with it as the Messenger of Allah ﷺ had acted. Allah knows that he was truthful, dutiful, rightly guided, and following the truth concerning it. Then Allah took Abu Bakr, and I became the successor responsible after Abu Bakr. I took charge of it for two years of my rule, acting with it as the Messenger of Allah ﷺ acted and as Abu Bakr acted. Allah knows that I was truthful, dutiful, rightly guided, and following the truth concerning it. Then you both came to me speaking to me, and your word was one and your matter was one. You came to me, O ʿAbbas, asking for your share from your nephew, and this one” — meaning ʿAli — “came to me seeking the share of his wife from her father. I said to you both: The Messenger of Allah ﷺ said: ‘We are not inherited from; what we leave is charity.’ When I decided to hand it over to you both, I said: If you wish, I will hand it over to you on the covenant and pledge of Allah upon you that you will act concerning it as the Messenger of Allah ﷺ acted, as Abu Bakr acted, and as I have acted since I became responsible for it. You both said: ‘Hand it over to us.’ So on that basis I handed it over to you both. I ask you by Allah: did I hand it over to them on that basis?” The group said: “Yes.” Then he turned to ʿAli and ʿAbbas and said: “I ask you both by Allah: did I hand it over to you on that basis?” They said: “Yes.” He said: “So are you seeking from me a judgment other than that? By Allah, by whose permission the heaven and earth stand, I will not judge concerning it with any judgment other than that. If you are unable to manage it, then hand it back to me, and I will take care of it for you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3094)، ومسلم (1756: 49)."},{"num":8060,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ: أَنَّ فَاطِمَةَ ابْنَةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَأَلَتْ أَبَا بَكْرٍ الصِّدِّيقَ بَعْدَ وَفَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَقْسِمَ لَهَا مِيرَاثَهَا مِمَّا تَرَكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِمَّا أَفَاءَ اللَّهُ عَلَيْهِ فَقَالَ لَهَا أَبُو بَكْرٍ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ نُورَثُ مَا تَرَكْنَا صَدَقَةٌ. فَغَضِبَتْ فَاطِمَةُ بِنْتُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَهَجَرَتْ أَبَا بَكْرٍ فَلَمْ تَزَلْ مُهَاجِرَتَهُ حَتَّى تُوُفِّيَتْ وَعَاشَتْ بَعْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سِتَّةَ أَشْهُرٍ قَالَتْ: وَكَانَتْ فَاطِمَةُ تَسْأَلُ أَبَا بَكْرٍ نَصِيبَهَا مِمَّا تَرَكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ خَيْبَرَ وَفَدَكٍ وَصَدَقَتِهِ بِالْمَدِينَةِ فَأَبَى أَبُو بَكْرٍ عَلَيْهَا ذَلِكَ وَقَالَ: لَسْتُ تَارِكًا شَيْئًا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعْمَلُ بِهِ إِلاَّ عَمِلْتُ بِهِ فَإِنِّي أَخْشَى إِنْ تَرَكْتُ شَيْئًا مِنْ أَمْرِهِ أَنْ أَزِيغَ، فَأَمَّا صَدَقَتُهُ بِالْمَدِينَةِ فَدَفَعَهَا عُمَرُ إِلَى عَلِيٍّ وَعَبَّاسٍ، فغلبه عَلَيْهَا عليٌّ، وأما خَيْبَرُ وَفَدَكٌ فأمسكهما عُمَرُ وَقَالَ: هُمَا صَدَقَةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَتَا لِحُقُوقِهِ الَّتِي تَعْروه وَنَوَائِبِهِ، وَأَمْرُهُمَا إِلَى مَنْ وَلِيَ الأَمْرَ قَالَ: فَهُمَا عَلَى ذَلِكَ إِلَى الْيَوْمِ.","وفي لفظ: أَنَّ فَاطِمَةَ عَلَيْهَا السَّلاَمُ أَرْسَلَتْ إِلَى أَبِي بَكْرٍ تَسْأَلُهُ مِيرَاثَهَا مِنَ النَّبِيِّ صلى الله عليه وسلم فِيمَا أَفَاءَ اللَّهُ عَلَى رَسُولِهِ صلى الله عليه وسلم تَطْلُبُ صَدَقَةَ النَّبِيِّ صلى الله عليه وسلم الَّتِي بِالْمَدِينَةِ وَفَدَكٍ وَمَا بَقِيَ مِنْ خُمُسِ خَيْبَرَ فَقَالَ أَبُو بَكْرٍ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ: لاَ نُورَثُ مَا تَرَكْنَا فَهْوَ صَدَقَةٌ إِنَّمَا يَأْكُلُ آلُ مُحَمَّدٍ مِنْ هَذَا الْمَالِ يَعْنِي مَالَ اللَّهِ لَيْسَ لَهُمْ أَنْ يَزِيدُوا عَلَى الْمَأْكَلِ وَإِنِّي وَاللَّهِ لاَ أُغَيِّرُ شَيْئًا مِنْ صَدَقَاتِ النَّبِيِّ صلى الله عليه وسلم الَّتِي كَانَتْ عَلَيْهَا فِي عَهْدِ النَّبِيِّ صلى الله عليه وسلم وَلأَعْمَلَنَّ فِيهَا بِمَا عَمِلَ فِيهَا رَسُولُ اللَّهِ صلى الله عليه وسلم."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3092-3093)، ومسلم في الجهاد والسير (1759: 54) من طريق إبراهيم بن سعد، عن صالح، عن ابن شهاب، أخبرني عروة بن الزبير، ان عائشة أخبرته فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الفيء","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3092–3093) and Muslim (1759:54).","chapter_en":"What Has Been Reported Concerning Fay’","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":17,"content":{"translation":{"en":["ʿA’ishah narrated that Fatimah, the daughter of the Messenger of Allah ﷺ, asked Abu Bakr al-Siddiq after the death of the Messenger of Allah ﷺ to divide for her her inheritance from what the Messenger of Allah ﷺ had left from what Allah had restored to him. Abu Bakr said to her: The Messenger of Allah ﷺ said: “We are not inherited from; what we leave is charity.” Fatimah, the daughter of the Messenger of Allah ﷺ, became upset with Abu Bakr and stopped speaking to him, and she continued not speaking to him until she died. She lived six months after the Messenger of Allah ﷺ. She said: Fatimah used to ask Abu Bakr for her share of what the Messenger of Allah ﷺ had left from Khaybar, Fadak, and his charity in Medina. Abu Bakr refused that to her and said: “I will not leave anything that the Messenger of Allah ﷺ used to do except that I will do it, for I fear that if I leave anything from his command, I would deviate.” As for his charity in Medina, ʿUmar handed it over to ʿAli and ʿAbbas. As for Khaybar and Fadak, ʿUmar kept them and said: “They are the charity of the Messenger of Allah ﷺ. They were for his rights that would arise and his needs, and their matter belongs to whoever holds authority.” He said: They remain upon that until today. In another wording: Fatimah, peace be upon her, sent to Abu Bakr asking him for her inheritance from the Prophet ﷺ regarding what Allah had restored to His Messenger ﷺ. She sought the Prophet’s ﷺ charity in Medina, Fadak, and what remained of the fifth of Khaybar. Abu Bakr said: The Messenger of Allah ﷺ said: “We are not inherited from; what we leave is charity.” The family of Muhammad only eats from this wealth — meaning Allah’s wealth — and they have no right to increase beyond food. “By Allah, I will not change anything from the charities of the Prophet ﷺ as they were during the time of the Prophet ﷺ, and I will surely act concerning them as the Messenger of Allah ﷺ acted.”"]},"buhuth":{"en":["Al-Bukhari also narrated it (3711–3712) with the second wording."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3092-3093)، ومسلم (1759: 54)."},{"num":8061,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ أَسْلَمَ عَنْ أَبِيهِ: أَنَّ مُعَاوِيَةَ رَضِيَ اللَّهُ عَنْهُ لَمَّا قَدِمَ الْمَدِينَةَ حَاجًّا جَاءَهُ عَبْدُ اللَّهِ بْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا فَقَالَ لَهُ مُعَاوِيَةُ حَاجَتُكَ يَا أَبَا عبدالرحمن فَقَالَ لَهُ: حَاجَتِي عَطَاءُ الْمُحَرَّرِينَ فَإِنِّي رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوَّلُ مَا جَاءَهُ شَيْءٌ بدأ بالمحررين."],"takhrij":"حسن: رواه ابن الجارود (1114)، والطحاوي في شرح المشكل (4274)، والبيهقي (12991) من طريق محمد بن عبد الله بن عبد الحكم، حدثنا عبد الله بن نافع الصائغ، عن هشام بن سعد، عن زيد بن أسلم، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الفيء","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn al-Jarud (1114), al-Tahawi in Sharh al-Mushkil (4274), and al-Bayhaqi (6/349).","chapter_en":"What Has Been Reported Concerning Fay’","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":17,"content":{"translation":{"en":["Zayd ibn Aslam narrated from his father that when Muʿawiyah came to Medina for Hajj, ʿAbdullah ibn ʿUmar, may Allah be pleased with them both, came to him. Muʿawiyah said to him: “What do you need, O Abu ʿAbd al-Rahman?” He said: “My need is the stipend of the freedmen, for I saw that when something first came to the Messenger of Allah ﷺ, he began with the freedmen.”"]},"buhuth":{"en":["Al-Khattabi said in Maʿalim al-Sunan (4/204): “By ‘freedmen’ he means emancipated slaves. They were a people who had no register of their own; rather, they were included secondarily under their patrons. The register was arranged by giving precedence to Banu Hashim, then those next to them in kinship and precedence. These freedmen were delayed in mention, so ʿAbdullah ibn ʿUmar reminded him of them and interceded for their stipends to be given earlier because he knew their weakness and need.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن الجارود (1114)، والطحاوي في شرح المشكل (4274)، والبيهقي (12991)."},{"num":8062,"demo":false,"sanad":"","matn":["عَنْ أنس قَالَ فِي سياق قصة خيبر: فَجُمِعَ السبي فَجَاءَ دِحْيَةُ رَضِيَ اللَّهُ عَنْهُ فَقَالَ: يَا نَبِيَّ اللَّهِ أَعْطِنِي جَارِيَةً مِنَ السبي، قَالَ: اذْهَبْ فَخُذْ جَارِيَةً فَأَخَذَ صَفِيَّةَ بِنْتَ حيي فَجَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا نَبِيَّ اللَّهِ أَعْطَيْتَ دِحْيَةَ صَفِيَّةَ بِنْتَ حيي سَيِّدَةَ قُرَيْظَةَ وَالنَّضِيرِ لاَ تَصْلُحُ إِلاَّ لَكَ قَالَ: ادْعُوهُ بِهَا فَجَاءَ بِهَا فَلَمَّا نَظَرَ إِلَيْهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: خُذْ جَارِيَةً مِنَ السبي غَيْرَهَا."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (371)، ومسلم في النكاح (1365: 84) كلاهما من طريق إسماعيل بن علية، عن عبد العزيز بن صهيب، عن أنس بن مالك فذكره في أثناء قصة خيبر.","grade":"متفق عليه","chapter_ar":"باب صفي رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (371) and Muslim (1365:84).","chapter_en":"The Chosen Share of the Messenger of Allah ﷺ","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":18,"content":{"translation":{"en":["Anas said, within the story of Khaybar: The captives were gathered, and Dihyah came and said: “O Prophet of Allah, give me a slave-woman from the captives.” He said: “Go and take a slave-woman.” So he took Safiyyah bint Huyayy. A man came to the Prophet ﷺ and said: “O Prophet of Allah, you have given Dihyah Safiyyah bint Huyayy, the lady of Qurayzah and al-Nadir; she is suitable only for you.” He said: “Call him with her.” He brought her, and when the Prophet ﷺ looked at her, he said: “Take another slave-woman from the captives.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (371)، ومسلم (1365: 84)."},{"num":8063,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: كَانَتْ صَفِيَّةُ مِنَ الصَّفِيِّ."],"takhrij":"صحيح: رواه أبو داود (2994)، وصحّحه ابن حبان (4822)، والحاكم (2/128، و3/39) من طرق عن سفيان (هو الثوري)، عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب صفي رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2994), and authenticated by Ibn Hibban (4822) and al-Hakim (2/128, 3/39).","chapter_en":"The Chosen Share of the Messenger of Allah ﷺ","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":18,"content":{"translation":{"en":["ʿA’ishah said: Safiyyah was from the chosen share."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2994)، وصححه ابن حبان (4822)، والحاكم (2/128، 3/39)."},{"num":8064,"demo":false,"sanad":"","matn":["عَنْ مَالِكِ بْنِ أَوْسِ بْنِ الْحَدَثَانِ، قَالَ: كَانَ فِيمَا احْتَجَّ بِهِ عُمَرُ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ كَانَتْ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلاَثُ صَفَايَا: بَنُو النَّضِيرِ وَخَيْبَرُ وَفَدَكُ، فَأَمَّا بَنُو النَّضِيرِ فَكَانَتْ حُبْسًا لِنَوَائِبِهِ، وَأَمَّا فَدَكُ فَكَانَتْ حُبْسًا لأَبْنَاءِ السَّبِيلِ وَأَمَّا خَيْبَرُ فَجَزَّأَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلاَثَةَ أَجْزَاءٍ: جُزْءَيْنِ بَيْنَ الْمُسْلِمِينَ وَجُزْءًا نَفَقَةً لأَهْلِهِ، فَمَا فَضَلَ عَنْ نَفَقَةِ أَهْلِهِ جَعَلَهُ بَيْنَ فُقَرَاءِ الْمُهَاجِرِينَ."],"takhrij":"حسن: رواه أبو داود (2967)، والبزار (256)، والبيهقي (13370) من طرق عن أسامة بن زيد، عن الزهري، عن مالك بن أوس بن الحدثان فذكره.","grade":"حسن","chapter_ar":"باب صفي رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2967), al-Bazzar (256), and al-Bayhaqi (6/296).","chapter_en":"The Chosen Share of the Messenger of Allah ﷺ","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":18,"content":{"translation":{"en":["Malik ibn Aws ibn al-Hadathan said: Among the arguments presented by ʿUmar was that he said: The Messenger of Allah ﷺ had three chosen properties: Banu al-Nadir, Khaybar, and Fadak. As for Banu al-Nadir, it was reserved for his unexpected needs. As for Fadak, it was reserved for travelers. As for Khaybar, the Messenger of Allah ﷺ divided it into three parts: two parts among the Muslims, and one part for the expenses of his family. Whatever remained beyond the expenses of his family, he placed among the poor of the Muhajirun."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2967)، والبزار (256)، والبيهقي (13370)."},{"num":8065,"demo":false,"sanad":"","matn":["عَنْ علي قَالَ: كَانَتْ لِي شَارِفٌ مِنْ نَصِيبِي مِنَ الْمَغْنَمِ يوم بَدْرٍ، وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْطَانِي شَارِفًا مِنَ الْخُمْسِ. الحديث."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3091)، ومسلم في الأشربة (1979: 2) كلاهما من طريق عبد الله بن وهب، أخبرنا يونس بن يزيد، عن الزهري، أخبرني علي بن الحسين بن علي، أن حسين بن علي أخبره أن عليا قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الخمس","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3091) and Muslim (1979:2).","chapter_en":"What Has Been Reported Concerning the Fifth","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":19,"content":{"translation":{"en":["ʿAli said: I had an old she-camel from my share of the spoils on the day of Badr, and the Prophet ﷺ had given me another old she-camel from the fifth. The hadith."]},"intro":{"ar":["قال تعالى:","(وَاعْلَمُوا أَنَّمَا غَنِمْتُم مِّن شَيْءٍ فَأَنَّ لِلَّهِ خُمُسَهُ وَلِلرَّسُولِ وَلِذِي الْقُرْبَىٰ وَالْيَتَامَىٰ وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ إِن كُنتُمْ آمَنتُم بِاللهِ وَمَا أَنزَلْنَا عَلَىٰ عَبْدِنَا يَوْمَ الْفُرْقَانِ يَوْمَ الْتَقَى الْجَمْعَانِ ۗ وَاللهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ) [سورة الأنفال: ٤١]."],"en":["Allah Most High said:","“And know that whatever you gain as spoils, then one-fifth of it belongs to Allah, the Messenger, near relatives, orphans, the needy, and the traveler, if you believe in Allah and in what We sent down upon Our servant on the Day of Distinction, the day when the two armies met. And Allah is over all things powerful.” [Surat al-Anfal: 41]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12390],"tks":"متفق عليه: رواه البخاري (3091)، ومسلم (1979: 2)."},{"num":8066,"demo":false,"sanad":"","matn":["عن يَزِيدَ بْنِ عَبْدِ اللَّهِ قَالَ: كُنَّا بِالْمِرْبَدِ فَجَاءَ رَجُلٌ أَشْعَثُ الرَّأْسِ بِيَدِهِ قِطْعَةُ أَدِيمٍ أَحْمَرَ فَقُلْنَا كَأَنَّكَ مِنْ أَهْلِ الْبَادِيَةِ. فَقَالَ: أَجَلْ. قُلْنَا: نَاوِلْنَا هَذِهِ الْقِطْعَةَ الأَدِيمَ الَّتِي فِي يَدِكَ فَنَاوَلَنَاهَا، فَقَرَأْنَاهَا فَإِذَا فِيهَا: مِنْ مُحَمَّدٍ رَسُولِ اللَّهِ إِلَى بَنِي زُهَيْرِ بْنِ أُقَيْشٍ إِنَّكُمْ إِنْ شَهِدْتُمْ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ وَأَقَمْتُمُ الصَّلاَةَ وَآتَيْتُمُ الزَّكَاةَ وَأَدَّيْتُمُ الْخُمُسَ مِنَ الْمَغْنَمِ وَسَهْمَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَسَهْمَ الصَّفِيِّ أَنْتُمْ آمِنُونَ بِأَمَانِ اللَّهِ وَرَسُولِهِ. فَقُلْنَا مَنْ كَتَبَ لَكَ هَذَا الْكِتَابَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه أبو داود (2999)، وأحمد (20740)، وصحّحه ابن حبان (6557) من طرق عن قرة بن خالد، سمعت يزيد بن عبد الله فذكره. واللفظ لأبي داود.","grade":"صحيح","chapter_ar":"باب ما جاء في الخمس","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2999), Ahmad (20740), and authenticated by Ibn Hibban (6557).","chapter_en":"What Has Been Reported Concerning the Fifth","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":19,"content":{"translation":{"en":["Yazid ibn ʿAbdullah said: We were at al-Mirbad when a man with disheveled hair came, holding a piece of red leather in his hand. We said: “You seem to be from the desert people?” He said: “Yes.” We said: “Hand us this piece of leather that is in your hand.” He handed it to us, and we read it. It contained: “From Muhammad, the Messenger of Allah, to Banu Zuhayr ibn Uqaysh: If you testify that there is no god but Allah and that Muhammad is the Messenger of Allah, establish prayer, give zakah, and pay the fifth from the spoils, the share of the Prophet ﷺ, and the chosen share, then you are safe under the protection of Allah and His Messenger.” We said: “Who wrote this document for you?” He said: “The Messenger of Allah ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9799],"tks":"صحيح: رواه أبو داود (2999)، وأحمد (20740)، وصححه ابن حبان (6557)."},{"num":8067,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ قَدِمَ وَفْدُ عَبْدِ الْقَيْسِ فَقَالُوا: يَا رَسُولَ اللَّهِ، إِنَّا هَذَا الْحَىَّ مِنْ رَبِيعَةَ، بَيْنَنَا وَبَيْنَكَ كُفَّارُ مُضَرَ، فَلَسْنَا نَصِلُ إِلَيْكَ إِلاَّ فِي الشَّهْرِ الْحَرَامِ، فَمُرْنَا بِأَمْرٍ نَأْخُذُ مِنْهُ وَنَدْعُو إِلَيْهِ مَنْ وَرَاءَنَا. قَالَ: آمُرُكُمْ بِأَرْبَعٍ، وَأَنْهَاكُمْ عَنْ أَرْبَعٍ، الإِيمَانِ بِاللَّهِ شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ ـ وَعَقَدَ بِيَدِهِ ـ وَإِقَامِ الصَّلاَةِ، وَإِيتَاءِ الزَّكَاةِ، وَصِيَامِ رَمَضَانَ، وَأَنْ تُؤَدُّوا لِلَّهِ خُمُسَ مَا غَنِمْتُمْ، وَأَنْهَاكُمْ عَنِ الدُّبَّاءِ وَالنَّقِيرِ وَالْحَنْتَمِ وَالْمُزَفَّتِ."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3095)، ومسلم في الإيمان (17: 23) كلاهما من طريق حماد بن زيد، عن أبي جمرة الضبعي قال: سمعت ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الخمس","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3095) and Muslim (17:23).","chapter_en":"What Has Been Reported Concerning the Fifth","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":19,"content":{"translation":{"en":["Ibn ʿAbbas said: The delegation of ʿAbd al-Qays came and said: “O Messenger of Allah, we are this tribe from Rabiʿah, and between us and you are the disbelievers of Mudar, so we can only reach you during the sacred month. Command us with something we may hold to and call those behind us to.” He said: “I command you with four and forbid you from four: faith in Allah — testifying that there is no god but Allah” — and he counted it with his hand — “establishing prayer, giving zakah, fasting Ramadan, and giving the fifth of what you acquire as spoils. And I forbid you from al-dubba’, al-naqir, al-hantam, and al-muzaffat.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3095)، ومسلم (17: 23)."},{"num":8068,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أَيُّمَا قَرْيَةٍ أَتَيْتُمُوهَا وَأَقَمْتُمْ فِيهَا فَسَهْمُكُمْ فِيهَا وَأَيُّمَا قَرْيَةٍ عَصَتِ اللَّهَ وَرَسُولَهُ فَإِنَّ خُمُسَهَا لِلهِ وَلِرَسُولِهِ ثُمَّ هِيَ لَكُمْ."],"takhrij":"صحيح: رواه مسلم في الجهاد والسير (1756) من طريقين عن عبد الرزاق، أخبرنا معمر، عن همام بن منبه قال: هذا ما حدثنا أبو هريرة عن رسول الله صلى الله عليه وسلم فذكر أحاديث منها وقال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الخمس","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1756).","chapter_en":"What Has Been Reported Concerning the Fifth","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":19,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Any town you come to and settle in, your share is in it; and any town that disobeys Allah and His Messenger, its fifth belongs to Allah and His Messenger, then it is yours.”"]}},"tuhfa":{},"full":1,"rep":[12388],"tks":"صحيح: رواه مسلم (1756)."},{"num":8069,"demo":false,"sanad":"","matn":["عن عَمْرِو بْنِ عَبَسَةَ قَالَ: صَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى بَعِيرٍ مِنَ الْمَغْنَمِ فَلَمَّا سَلَّمَ أَخَذَ وَبَرَةً مِنْ جَنْبِ الْبَعِيرِ، ثُمَّ قَالَ: وَلاَ يَحِلُّ لِي مِنْ غَنَائِمِكُمْ مِثْلُ هَذَا إِلاَّ الْخُمُسَ وَالْخُمُسُ مَرْدُودٌ فِيكُمْ."],"takhrij":"صحيح: رواه أبو داود (2755) –ومن طريقه البيهقي (12943)- حدثنا الوليد بن عتبة، حدثنا الوليد (هو ابن مسلم)، حدثنا عبد الله بن العلاء أنه سمع أبا سلام الأسود قال: سمعت عمرو بن عبسة قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الخمس","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2755), and through him by al-Bayhaqi (6/339).","chapter_en":"What Has Been Reported Concerning the Fifth","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":19,"content":{"translation":{"en":["ʿAmr ibn ʿAbasah said: The Messenger of Allah ﷺ led us in prayer facing a camel from the spoils. When he gave salām, he took a single hair from the side of the camel, then said: “Not even the like of this from your spoils is lawful for me except the fifth, and the fifth is returned among you.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12389],"tks":"صحيح: رواه أبو داود (2755)، ومن طريقه البيهقي (12943)."},{"num":8070,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ قَالَ: أَخَذَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَبَرَةً مِنْ جَنْبِ بَعِيرٍ فَقَالَ: أَيُّهَا النَّاسُ إِنَّهُ، لَا يَحِلُّ لِي مِمَّا أَفَاءَ اللَّهُ عَلَيْكُمْ قَدْرَ هَذِهِ إِلَّا الْخُمُسُ، وَالْخُمُسُ مَرْدُودٌ عَلَيْكُمْ."],"takhrij":"حسن: رواه النسائي (4138)، وأحمد (22718)، والبيهقي (12747) كلهم من طريقين عن أبي إسحاق الفزاري، عن عبد الرحمن بن عياش عن سليمان بن موسى عن مكحول عن أبي سلام عن أبي أمامة الباهلي عن عبادة بن الصامت قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الخمس","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4138), Ahmad (22718), and al-Bayhaqi (6/303).","chapter_en":"What Has Been Reported Concerning the Fifth","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":19,"content":{"translation":{"en":["ʿUbadah ibn al-Samit said: On the day of Hunayn, the Messenger of Allah ﷺ took a single hair from the side of a camel and said: “O people, nothing from what Allah has granted you as spoils is lawful for me, not even the amount of this, except the fifth; and the fifth is returned to you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (4138)، وأحمد (22718)، والبيهقي (12747)."},{"num":8071,"demo":false,"sanad":"","matn":["عن جُبَيْرِ بْنِ مُطْعِمٍ أَخْبَرَهُ قَالَ: مَشَيْتُ أَنَا وَعُثْمَانُ بْنُ عَفَّانَ، إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْنَا: أَعْطَيْتَ بَنِي الْمُطَّلِبِ مِنْ خُمْسِ خَيْبَرَ، وَتَرَكْتَنَا، وَنَحْنُ بِمَنْزِلَةٍ وَاحِدَةٍ مِنْكَ. فَقَالَ: إِنَّمَا بَنُو هَاشِمٍ وَبَنُو الْمُطَّلِبِ شَىْءٌ وَاحِدٌ.","قَالَ جُبَيْرٌ: وَلَمْ يَقْسِمُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِبَنِي عَبْدِ شَمْسٍ وَبَنِي نَوْفَلٍ شَيْئًا."],"takhrij":"صحيح: رواه البخاري (4229) عن يحيى بن بكير حدثنا الليث عن يونس عن ابن شهاب عن سعيد بن المسيب أن جبير بن مطعم أخبره قال: فذكره.","grade":"صحيح","chapter_ar":"باب قسم الخمس، وسهم ذوي القربى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4229). Abu Dawud (2978) also narrated it and added: Abu Bakr used to divide the fifth in a manner similar to the division of the Messenger of Allah ﷺ, except that he did not give the relatives of the Messenger of Allah ﷺ what the Prophet ﷺ had given them. He said: ʿUmar ibn al-Khattab used to give them from it, and ʿUthman after him.","chapter_en":"Dividing the Fifth and the Share of Near Relatives","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":20,"content":{"translation":{"en":["Jubayr ibn Mutʿim reported: ʿUthman ibn ʿAffan and I walked to the Prophet ﷺ and said: “You gave Banu al-Muttalib from the fifth of Khaybar and left us, though we and they are in the same position in relation to you.” He said: “Banu Hashim and Banu al-Muttalib are only one thing.” Jubayr said: The Prophet ﷺ did not give anything to Banu ʿAbd Shams or Banu Nawfal."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9052,12391],"tks":"صحيح: رواه البخاري (4229). ورواه أبو داود (2978) وزاد: قال: وكان أبو بكر يقسم الخمس نحو قسم رسول الله ﷺ، غير أنه لم يكن يعطي قربى رسول الله ﷺ ما كان النبي ﷺ يعطيهم. قال: وكان عمر بن الخطاب يعطيهم منه، وعثمان بعده."},{"num":8072,"demo":false,"sanad":"","matn":["عن جُبَيْرِ بْنِ مُطْعِمٍ قَالَ: لَمَّا كَانَ يَوْمُ خَيْبَرَ وَضَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَهْمَ ذِي الْقُرْبَى فِي بَنِي هَاشِمٍ وَبَنِي الْمُطَّلِبِ وَتَرَكَ بَنِي نَوْفَلٍ وَبَنِي عَبْدِ شَمْسٍ فَانْطَلَقْتُ أَنَا وَعُثْمَانُ بْنُ عَفَّانَ حَتَّى أَتَيْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْنَا: يَا رَسُولَ اللَّهِ هَؤُلاَءِ بَنُو هَاشِمٍ لاَ نُنْكِرُ فَضْلَهُمْ لِلْمَوْضِعِ الَّذِي وَضَعَكَ اللَّهُ بِهِ مِنْهُمْ فَمَا بَالُ إِخْوَانِنَا بَنِي الْمُطَّلِبِ أَعْطَيْتَهُمْ وَتَرَكْتَنَا وَقَرَابَتُنَا وَاحِدَةٌ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَا وَبَنُو الْمُطَّلِبِ لاَ نَفْتَرِقُ فِي جَاهِلِيَّةٍ وَلاَ إِسْلاَمٍ، وَإِنَّمَا نَحْنُ وَهُمْ شَىْءٌ وَاحِدٌ. وَشَبَّكَ بَيْنَ أَصَابِعِهِ."],"takhrij":"حسن: رواه أبو داود (2980)، والنسائي (4137)، وأحمد (16741)، والبيهقي (6/341) كلهم من طرق عن محمد بن إسحاق، عن الزهري، عن سعيد بن المسيب، عن جبير بن مطعم فذكره.","grade":"حسن","chapter_ar":"باب قسم الخمس، وسهم ذوي القربى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2980), al-Nasa’i (4137), Ahmad (16741), and al-Bayhaqi (6/341).","chapter_en":"Dividing the Fifth and the Share of Near Relatives","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":20,"content":{"translation":{"en":["Jubayr ibn Mutʿim said: On the day of Khaybar, the Messenger of Allah ﷺ placed the share of near relatives among Banu Hashim and Banu al-Muttalib, and left Banu Nawfal and Banu ʿAbd Shams. So I and ʿUthman ibn ʿAffan went until we came to the Prophet ﷺ and said: “O Messenger of Allah, as for Banu Hashim, we do not deny their virtue due to the position in which Allah placed you among them. But what about our brothers Banu al-Muttalib? You gave them and left us, though our kinship is the same.” The Messenger of Allah ﷺ said: “We and Banu al-Muttalib did not separate in the pre-Islamic period or in Islam; rather, we and they are one thing,” and he interlaced his fingers."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2980)، والنسائي (4137)، وأحمد (16741)، والبيهقي (6/341)."},{"num":8073,"demo":false,"sanad":"","matn":["عَنْ يَزِيدَ بْنِ هُرْمُزَ: أَنَّ نَجْدَةَ الْحَرُورِيَّ حِينَ خَرَجَ مِنْ فِتْنَةِ ابْنِ الزُّبَيْرِ، أَرْسَلَ إِلَى ابْنِ عَبَّاسٍ، يَسْأَلُهُ عَنْ سَهْمِ ذِي الْقُرْبَى: لِمَنْ تَرَاهُ؟ قَالَ: هُوَ لَنَا، لِقُرْبَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَسَمَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَهُمْ، وَقَدْ كَانَ عُمَرُ عَرَضَ عَلَيْنَا مِنْهُ شَيْئًا، رَأَيْنَاهُ دُونَ حَقِّنَا، فَرَدَدْنَاهُ عَلَيْهِ، وَأَبَيْنَا أَنْ نَقْبَلَهُ، وَكَانَ الَّذِي عَرَضَ عَلَيْهِمْ: أَنْ يُعِينَ نَاكِحَهُمْ، وَأَنْ يَقْضِيَ عَنْ غَارِمِهِمْ، وَأَنْ يُعْطِيَ فَقِيرَهُمْ، وَأَبَى أَنْ يَزِيدَهُمْ عَلَى ذَلِكَ."],"takhrij":"صحيح: رواه أبو داود (2982)، والنسائي (4133)، وأحمد (2941) من طريقين عن يونس، عن الزهري، عن يزيد بن هرمز فذكره. والسياق للنسائي وأحمد.","grade":"صحيح","chapter_ar":"باب قسم الخمس، وسهم ذوي القربى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2982), al-Nasa’i (4133), and Ahmad (2941). The wording is that of al-Nasa’i and Ahmad.","chapter_en":"Dividing the Fifth and the Share of Near Relatives","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":20,"content":{"translation":{"en":["Yazid ibn Hurmuz narrated that when Najdah al-Haruri rebelled during the turmoil of Ibn al-Zubayr, he sent to Ibn ʿAbbas asking him about the share of near relatives: “For whom do you consider it?” He said: “It is for us, due to our kinship with the Messenger of Allah ﷺ. The Messenger of Allah ﷺ divided it for them. ʿUmar had offered us something that we considered less than our right, so we refused to accept it.” What he offered them was that he would help the one among them who wished to marry, pay the debt of their debtor, and give to their poor; but he refused to give them more than that."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2982)، والنسائي (4133)، وأحمد (2941). والسياق للنسائي وأحمد."},{"num":8074,"demo":false,"sanad":"","matn":["عَنْ نَاشِرَةَ بْنِ سُمَيٍّ الْيَزَنِيِّ، قَالَ: سَمِعْتُ عُمَرَ بْنَ الْخَطَّابِ،، يَقُولُ فِي يَوْمِ الْجَابِيَةِ، وَهُوَ يَخْطُبُ النَّاسَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ جَعَلَنِي خَازِنًا لِهَذَا الْمَالِ، وَقَاسِمَهُ لَهُ، ثُمَّ قَالَ: بَلِ اللَّهُ يَقْسِمُهُ، وَأَنَا بَادِئٌ بِأَهْلِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ أَشْرَفِهِمْ، فَفَرَضَ لِأَزْوَاجِ النَّبِيِّ عَشْرَةَ آلَافٍ إِلَّا جُوَيْرِيَةَ، وَصَفِيَّةَ، ومَيْمُونَةَ، فَقَالَتْ عَائِشَةُ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَعْدِلُ بَيْنَنَا، فَعَدَلَ بَيْنَهُنَّ عُمَرُ، ثُمَّ قَالَ: إِنِّي بَادِئٌ بِأَصْحَابِي الْمُهَاجِرِينَ الْأَوَّلِينَ، فَإِنَّا أُخْرِجْنَا مِنْ دِيَارِنَا ظُلْمًا، وَعُدْوَانًا، ثُمَّ أَشْرَفِهِمْ فَفَرَضَ لِأَصْحَابِ بَدْرٍ مِنْهُمْ خَمْسَةَ آلَافٍ، وَلِمَنْ كَانَ شَهِدَ بَدْرًا مِنَ الْأَنْصَارِ أَرْبَعَةَ آلَافٍ، وَلِمَنْ شَهِدَ أُحُدًا ثَلَاثَةَ آلَافٍ، قَالَ: وَمَنْ أَسْرَعَ فِي الْهِجْرَةِ أَسْرَعَ بِهِ الْعَطَاءُ، وَمَنْ أَبْطَأَ فِي الْهِجْرَةِ أَبْطَأَ بِهِ الْعَطَاءُ، فَلَا يَلُومَنَّ رَجُلٌ إِلَّا مُنَاخَ رَاحِلَتِهِ، وَإِنِّي أَعْتَذِرُ إِلَيْكُمْ مِنْ خَالِدِ بْنِ الْوَلِيدِ، إِنِّي أَمَرْتُهُ أَنْ يَحْبِسَ هَذَا الْمَالَ عَلَى ضَعَفَةِ الْمُهَاجِرِينَ، فَأَعْطَاهُ ذَا الْبَأْسِ، وَذَا الشَّرَفِ، وَذَا اللَّسَانَةِ، فَنَزَعْتُهُ، وَأَمَّرْتُ أَبَا عُبَيْدَةَ بْنَ الْجَرَّاحِ، فَقَالَ أَبُو عَمْرِو بْنُ حَفْصِ بْنِ الْمُغِيرَةِ: وَاللهِ مَا أَعْذَرْتَ يَا عُمَرُ بْنَ الْخَطَّابِ، لَقَدْ نَزَعْتَ عَامِلًا اسْتَعْمَلَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَغَمَدْتَ سَيْفًا سَلَّهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَوَضَعْتَ لِوَاءً نَصَبَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَقَدْ قَطَعْتَ الرَّحِمَ، وَحَسَدْتَ ابْنَ الْعَمِّ، فَقَالَ عُمَرُ بْنُ الْخَطَّابِ: إِنَّكَ قَرِيبُ الْقَرَابَةِ، حَدِيثُ السِّنِّ، مُغْضَبٌ مِنْ ابْنِ عَمِّكَ."],"takhrij":"صحيح: رواه أحمد (15905) عن علي بن إسحاق، حدثنا عبد الله –يعني ابن المبارك-، أخبرنا سعيد بن يزيد (هو أبو الشجاع) قال: سمعت الحارث بن يزيد الحضرمي، يحدث عن علي بن رباح عن ناشرة بن سمي فذكره.","grade":"صحيح","chapter_ar":"باب تدوين العطاء","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (15905).","chapter_en":"Recording the Stipends","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الغنائم، والأنفال، والفيء","group_en":"Collection of What Has Been Narrated Concerning Spoils, Extra Shares, and Fay’","part_no":43,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["Nashirah ibn Sumayy al-Yazani said: I heard ʿUmar ibn al-Khattab, may Allah be pleased with him, speaking on the day of al-Jabiyah while addressing the people: “Allah, Mighty and Majestic, has made me the treasurer of this wealth and its distributor.” Then he said: “Rather, Allah distributes it, and I will begin with the family of the Prophet ﷺ, then with the noblest among them.” He assigned ten thousand to the wives of the Prophet ﷺ, except Juwayriyah, Safiyyah, and Maymunah. ʿA’ishah said: “The Messenger of Allah ﷺ used to be just among us,” so ʿUmar made them equal. Then he said: “I will begin with my companions, the earliest Muhajirun, for we were expelled from our homes unjustly and aggressively, then the noblest among them.” He assigned five thousand to those among them who attended Badr, four thousand to those from the Ansar who attended Badr, and three thousand to those who attended Uhud. He said: “Whoever was early in migration will be given early in stipend, and whoever was late in migration will be delayed in stipend. So let no man blame anyone but the resting place of his mount. And I apologize to you regarding Khalid ibn al-Walid. I ordered him to reserve this wealth for the weak among the Muhajirun, but he gave it to people of strength, status, and eloquence, so I removed him and appointed Abu ʿUbaydah ibn al-Jarrah.” Abu ʿAmr ibn Hafs ibn al-Mughirah said: “By Allah, you have not excused yourself, O ʿUmar ibn al-Khattab. You removed a governor whom the Messenger of Allah ﷺ had appointed, sheathed a sword that the Messenger of Allah ﷺ had drawn, lowered a banner that the Messenger of Allah ﷺ had raised, severed kinship, and envied your cousin.” ʿUmar ibn al-Khattab said: “You are close in kinship, young in age, and angry on behalf of your cousin.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (15905)."},{"num":8075,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَالَّذِي نَفْسِي بِيَدِهِ، لاَ يُكْلم أحدٌ فِي سَبِيلِ اللَّهِ – وَاللَّهُ أَعْلَمُ بِمَنْ يُكْلَمُ فِي سَبِيلِهِ- إِلاَّ جَاءَ يَوْمَ الْقِيَامَةِ، وجُرحه يثعبُ دما، اللونُ لونُ الدَّمِ، وَالرِّيحُ ريحُ الْمِسْكِ."],"takhrij":"متفق عليه: رواه مالك في الجهاد (29) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. ورواه البخاري في الجهاد والسير (2803) من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب فضل الشهادة في سبيل الله تعالى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (29), al-Bukhari (2803), and Muslim (1876:105).","chapter_en":"The Virtue of Martyrdom in the Path of Allah Most High","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “By the One in whose hand is my soul, no one is wounded in the path of Allah — and Allah knows best who is wounded in His path — except that he will come on the Day of Resurrection with his wound flowing with blood: its color will be the color of blood, but its fragrance will be the fragrance of musk.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16148],"tks":"متفق عليه: رواه مالك (29)، والبخاري (2803)، ومسلم (1876: 105)."},{"num":8076,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: وَالَّذِي نَفْسِي بِيَدِهِ لَوْلاَ أَنَّ رِجَالاً مِنَ الْمُؤْمِنِينَ لاَ تَطِيبُ أَنْفُسُهُمْ أَنْ يَتَخَلَّفُوا عَنِّي وَلاَ أَجِدُ مَا أَحْمِلُهُمْ عَلَيْهِ مَا تَخَلَّفْتُ عَنْ سَرِيَّةٍ تَغْزُو فِي سَبِيلِ اللَّهِ وَالَّذِي نَفْسِي بِيَدِهِ لَوَدِدْتُ أَنِّي أُقْتَلُ فِي سَبِيلِ اللَّهِ ثُمَّ أُحْيَا ثُمَّ أُقْتَلُ ثُمَّ أُحْيَا ثُمَّ أُقْتَلُ ثُمَّ أُحْيَا ثُمَّ أُقْتَلُ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2797) من طريق الزهري، عن سعيد بن المسيب، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل الشهادة في سبيل الله تعالى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2797) and Muslim (1876).","chapter_en":"The Virtue of Martyrdom in the Path of Allah Most High","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: I heard the Prophet ﷺ say: “By the One in whose hand is my soul, were it not that some men among the believers would not feel content to remain behind from me, and I do not find mounts to carry them on, I would not remain behind from any detachment that goes forth in the path of Allah. By the One in whose hand is my soul, I wish that I could be killed in the path of Allah, then brought back to life, then killed, then brought back to life, then killed, then brought back to life, then killed.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2797)، ومسلم (1876)."},{"num":8077,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا أَحَدٌ يَدْخُلُ الْجَنَّةَ يُحِبُّ أَنْ يَرْجِعَ إِلَى الدُّنْيَا وَلَهُ مَا عَلَى الأَرْضِ مِنْ شَىْءٍ، إِلاَّ الشَّهِيدُ، يَتَمَنَّى أَنْ يَرْجِعَ إِلَى الدُّنْيَا فَيُقْتَلَ عَشْرَ مَرَّاتٍ، لِمَا يَرَى مِنَ الْكَرَامَةِ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2817)، ومسلم في الإمارة (1877: 109) كلاهما عن محمد بن بشار-وزاد مسلم: محمد بن المثنى- ثنا محمد بن جعفر غُندر، ثنا شعبة، قال: سمعت قتادة قال: سمعت أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل الشهادة في سبيل الله تعالى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2817) and Muslim (1877:109).","chapter_en":"The Virtue of Martyrdom in the Path of Allah Most High","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Malik narrated from the Prophet ﷺ that he said: “No one who enters Paradise would love to return to the world, even if he had everything on earth, except the martyr. He wishes to return to the world and be killed ten times because of the honor he sees.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2817)، ومسلم (1877: 109)."},{"num":8078,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : يُؤْتَى بِالرَّجُلِ مِنْ أَهْلِ الْجَنَّةِ فَيَقُولُ اللَّهُ عَزَّ وَ جَلَّ: يَا ابْنَ آدَمَ كَيْفَ وَجَدْتَ مَنْزِلَكَ؟ فَيَقُولُ: أَيْ رَبِّ خَيْرَ مَنْزِلٍ فَيَقُولُ: سَلْ وتمنَّ، فَيَقُولُ: أَسْأَلُكَ أَنْ تَرُدَّنِيَ إِلَى الدُّنْيَا فَأُقْتَلَ فِي سَبِيلِكِ عَشْرَ مَرَّاتٍ لِمَا يَرَى مِنْ فَضْلِ الشَّهَادَةِ."],"takhrij":"صحيح: رواه النسائي (3160)، وأحمد (12342)، والحاكم (2405) من طرق عن حماد بن سلمة، عن ثابت، عن أنس فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب فضل الشهادة في سبيل الله تعالى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3160), Ahmad (12342), and al-Hakim (2405).","chapter_en":"The Virtue of Martyrdom in the Path of Allah Most High","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said: “A man from the people of Paradise will be brought, and Allah, Mighty and Majestic, will say: ‘O son of Adam, how did you find your dwelling?’ He will say: ‘My Lord, the best dwelling.’ He will say: ‘Ask and wish.’ He will say: ‘I ask You to return me to the world so that I may be killed in Your path ten times,’ because of what he sees of the virtue of martyrdom.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (3160)، وأحمد (12342)، والحاكم (2405)."},{"num":8079,"demo":false,"sanad":"","matn":["عَنِ ابْنِ أَبِي عَمِيرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا مِنَ النَّاسِ نَفْسُ مُسْلِمٍ يَقْبِضُهَا اللهُ تُحِبُّ أَنْ تَعُودَ إِلَيْكُمْ، وَأَنَّ لَهَا الدُّنْيَا وَمَا فِيهَا، غَيْرُ الشَّهِيدِ.","قَالَ ابْنُ أَبِي عَمِيرَةَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: وَلأَنْ أُقْتَلَ فِي سَبِيلِ اللَّهِ أَحَبُّ إِلَىَّ مِنْ أَنْ يَكُونَ لِي أَهْلُ الْوَبَرِ وَالْمَدَرِ."],"takhrij":"حسن: رواه النسائي (3153)، وأحمد (17894) من طريقين عن بقية، حدثني بحير بن سعد، عن خالد بن معدان، عن جبير بن نفير، عن ابن أبي عميرة فذكره.","grade":"حسن","chapter_ar":"باب فضل الشهادة في سبيل الله تعالى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3153) and Ahmad (17894).","chapter_en":"The Virtue of Martyrdom in the Path of Allah Most High","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Ibn Abi ʿUmayrah narrated that the Messenger of Allah ﷺ said: “There is no Muslim soul among the people whose Lord takes it that would love to return to you, even if it had the world and everything in it, except the martyr.” Ibn Abi ʿUmayrah said: The Messenger of Allah ﷺ said: “To be killed in the path of Allah is more beloved to me than to possess the people of tents and towns.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (3153)، وأحمد (17894)."},{"num":8080,"demo":false,"sanad":"","matn":["عن عُبَادَةَ بْنِ الصَّامِتِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا فِي الْأَرْضِ مِنْ نَفْسٍ تَمُوتُ وَلَهَا عِنْدَ اللَّهِ خَيْرٌ، تُحِبُّ أَنْ تَرْجِعَ إِلَيْكُمْ، وَأَنَّ لَهَا الدُّنْيَا، إِلَّا الشَّهِيدُ، فَإِنَّهُ يُحِبُّ أَنْ يَرْجِعَ، فَيُقْتَلَ مُرَّةً أُخْرَى."],"takhrij":"حسن: رواه النسائي (3159) من طريق محمد بن عيسى بن القاسم بن سُميع، حدثنا زيد بن واقد، عن كثير بن مرة، عن عبادة بن الصامت فذكره.","grade":"حسن","chapter_ar":"باب فضل الشهادة في سبيل الله تعالى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3159) and al-Tabarani in al-Awsat (401).","chapter_en":"The Virtue of Martyrdom in the Path of Allah Most High","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["ʿUbadah ibn al-Samit narrated that the Messenger of Allah ﷺ said: “There is no soul on earth that dies and has good with Allah, which would love to return to you even if it had the world, except the one killed in Allah’s path. He loves to return and be killed again.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (3159)، والطبراني في الأوسط (401)."},{"num":8081,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ، قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: رَأَيْتُ اللَّيْلَةَ رَجُلَيْنِ أَتَيَانِي فَصَعِدَا بِي الشَّجَرَةَ، فَأَدْخَلاَنِي دَارًا هِيَ أَحْسَنُ وَأَفْضَلُ، لَمْ أَرَ قَطُّ أَحْسَنَ مِنْهَا قَالاَ: أَمَّا هَذِهِ الدَّارُ فَدَارُ الشُّهَدَاءِ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (2791)، عن موسى، حدثنا جرير، حدثنا أبو رجاء، عن سمرة فذكره.","grade":"صحيح","chapter_ar":"باب فضل الشهادة في سبيل الله تعالى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2791).","chapter_en":"The Virtue of Martyrdom in the Path of Allah Most High","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Samurah said: The Prophet ﷺ said: “Tonight I saw two men who came to me. They took me up a tree and entered me into a house that was the most beautiful and excellent; I had never seen anything more beautiful than it. They said: As for this house, it is the house of the martyrs.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2791)."},{"num":8082,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَضْحَكُ اللَّهُ إِلَى رَجُلَيْنِ يَقْتُلُ أَحَدُهُمَا الآخَرَ يَدْخُلاَنِ الْجَنَّةَ، يُقَاتِلُ هَذَا فِي سَبِيلِ اللَّهِ فَيُقْتَلُ، ثُمَّ يَتُوبُ اللَّهُ عَلَى الْقَاتِلِ فَيُسْتَشْهَدُ."],"takhrij":"متفق عليه: رواه مالك في الجهاد (28) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. ورواه البخاري في الجهاد والسير (2826) من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب فضل الشهادة في سبيل الله تعالى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (28), al-Bukhari (2826), and Muslim (1890:128).","chapter_en":"The Virtue of Martyrdom in the Path of Allah Most High","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Allah laughs at two men, one of whom kills the other, and both enter Paradise: this one fights in the path of Allah and is killed; then Allah accepts the repentance of the killer, so he fights and is martyred.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (28)، والبخاري (2826)، ومسلم (1890: 128)."},{"num":8083,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا يَجِدُ الشَّهِيدُ مِنْ مَسِّ الْقَتْلِ إِلاَّ كَمَا يَجِدُ أَحَدُكُمْ مِنْ مَسِّ الْقَرْصَةِ."],"takhrij":"حسن: رواه الترمذي (1668)، والنسائي (3161)، وابن ماجه (2802)، وأحمد (7953)، وصحّحه ابن حبان (4655) كلهم من طريق محمد بن عجلان، عن القعقاع بن حكيم، عن أبي صالح، (هو السمان)، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب فضل الشهادة في سبيل الله تعالى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1668), who authenticated it, al-Nasa’i (3161), Ibn Majah (2802), Ahmad (7953), and authenticated by Ibn Hibban (4655).","chapter_en":"The Virtue of Martyrdom in the Path of Allah Most High","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “The martyr does not feel the touch of being killed except as one of you feels the touch of a pinch.”"]},"buhuth":{"en":["“Al-qarṣah,” with an open qaf and a silent ra’, comes from “pinching.” It says in al-Qamus: “al-qarṣ” is when you take a person’s flesh between two fingers until you hurt him, and it also refers to flea bites."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1668) وصححه، والنسائي (3161)، وابن ماجه (2802)، وأحمد (7953)، وصححه ابن حبان (4655)."},{"num":8084,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَيْسَ شَيْءٌ أَحَبَّ إِلَى اللَّهِ مِنْ قَطْرَتَيْنِ وَأَثَرَيْنِ: قَطْرَةٌ مِنْ دُمُوعٍ فِي خَشْيَةِ اللَّهِ، وَقَطْرَةُ دَمٍ تُهَرَاقُ فِي سَبِيلِ اللَّهِ. وَأَمَّا الأَثَرَانِ: فَأَثَرٌ فِي سَبِيلِ اللَّهِ، وَأَثَرٌ فِي فَرِيضَةٍ مِنْ فَرَائِضِ اللَّهِ."],"takhrij":"حسن: رواه الترمذي (1669)، وابن أبي عاصم في الجهاد (108) من طريق يزيد بن هارون، حدثنا الوليد بن جميل، عن القاسم أبي عبد الرحمن، عن أبي أمامة فذكره.","grade":"حسن","chapter_ar":"باب فضل الشهادة في سبيل الله تعالى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1669), who graded it good, and Ibn Abi ʿAsim in al-Jihad (108).","chapter_en":"The Virtue of Martyrdom in the Path of Allah Most High","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Abu Umamah narrated from the Prophet ﷺ that he said: “There is nothing more beloved to Allah than two drops and two traces: a drop of tears out of fear of Allah, and a drop of blood shed in the path of Allah. As for the two traces: a trace in the path of Allah, and a trace in one of the obligations of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1669) وحسنه، وابن أبي عاصم في الجهاد (108)."},{"num":8085,"demo":false,"sanad":"","matn":["عن مُعَاذِ بن جَبَلٍ حَدَّثَهُمْ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ قَاتَلَ فِي سَبِيلِ اللَّهِ مِنْ رَجُلٍ مُسْلِمٍ فُوَاقَ نَاقَةٍ، وَجَبَتْ لَهُ الْجَنَّةُ، وَمَنْ سَأَلَ اللَّهَ الْقَتْلَ مِنْ عِنْدِ نَفْسِهِ صَادِقًا ثُمَّ مَاتَ أَوْ قُتِلَ فَلَهُ أَجْرُ شَهِيدٍ، وَمَنْ جُرِحَ جُرْحًا فِي سَبِيلِ اللَّهِ أَوْ نُكِبَ نَكْبَةً، فَإِنَّهَا تَجِيءُ يَوْمَ الْقِيَامَةِ كَأَغَرِّ مَا كَانَتْ، لَوْنُهَا كَالزَّعْفَرَانِ وَرِيحُهَا كَالْمِسْكِ، وَمَنْ جُرِحَ جُرْحًا فِي سَبِيلِ اللَّهِ، فَعَلَيْهِ طَابَعُ الشُّهَدَاءِ."],"takhrij":"حسن: رواه النسائي (3141)، والبيهقي (18556) من طريق حجاج بن محمد (وهو المصيصي)- والترمذي (1654، 1657) مفرقا، وأحمد (22116)، والحاكم (2410) مختصرا من طريق روح بن عبادة- وابن ماجه (2792) مختصرا من طريق الضحاك بن مخلد- وأحمد (22014، 22116) من طريق عبد الرزاق- (وهو في مصنفه 9534)، ومحمد بن بكر- خمستُهم عن ابن جريج قال: حدثنا سليمان بن موسى قال: حدثنا مالك بن يخاير أن معاذ بن جبل حدثهم أنه سمع رسول الله صلى الله عليه وسلم يقول: فذكره، والسياق للنسائي.","grade":"حسن","chapter_ar":"باب فضل الشهادة في سبيل الله تعالى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3141), al-Bayhaqi (9/170), al-Tirmidhi (1654, 1657) in separate portions, Ahmad (22116), al-Hakim (2410) in abridged form, Ibn Majah (2792) in abridged form, Ahmad (22014, 22116), and ʿAbd al-Razzaq in al-Musannaf (9534).","chapter_en":"The Virtue of Martyrdom in the Path of Allah Most High","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Muʿadh ibn Jabal heard the Messenger of Allah ﷺ say: “Any Muslim man who fights in the path of Allah, Mighty and Majestic, for the time between two milkings of a she-camel, Paradise becomes obligatory for him. Whoever sincerely asks Allah for being killed, then dies or is killed, will have the reward of a martyr. Whoever is wounded in the path of Allah or suffers an injury, it will come on the Day of Resurrection as abundant as it ever was, its color like saffron and its fragrance like musk. Whoever is wounded in the path of Allah will bear the mark of the martyrs.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (3141)، والبيهقي (18556)، والترمذي (1654، 1657) مفرقا، وأحمد (22116)، والحاكم (2410) مختصرا، وابن ماجه (2792) مختصرا، وأحمد (22014، 22116)، وعبد الرزاق في المصنف (9534)."},{"num":8086,"demo":false,"sanad":"","matn":["عَنِ الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لِلشَّهِيدِ عِنْدَ اللَّهِ سِتُّ خِصَالٍ يُغْفَرُ لَهُ فِي أَوَّلِ دَفْعَةٍ مِنْ دَمِهِ، وَيُرَى مَقْعَدَهُ مِنَ الْجَنَّةِ وَيُجَارُ مِنْ عَذَابِ الْقَبْرِ، وَيَأْمَنُ مِنَ الْفَزَعِ الأَكْبَرِ، وَيُحَلَّى حُلَّةَ الإِيمَانِ وَيُزَوَّجُ مِنَ الْحُورِ الْعِينِ، وَيُشَفَّعُ فِي سَبْعِينَ إِنْسَانًا مِنْ أَقَارِبِهِ."],"takhrij":"حسن: رواه ابن ماجه (2799) عن هشام بن عمار، ثنا إسماعيل بن عياش، حدثني بحير بن سعيد، عن خالد بن معدان، عن المقدام بن معد يكرب فذكره.","grade":"حسن","chapter_ar":"باب فضل الشهادة في سبيل الله تعالى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2799).","chapter_en":"The Virtue of Martyrdom in the Path of Allah Most High","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Al-Miqdam ibn Maʿdikarib narrated from the Messenger of Allah ﷺ that he said: “The martyr has six qualities with Allah: he is forgiven at the first flow of his blood; he sees his seat in Paradise; he is protected from the punishment of the grave; he is safe from the greatest terror; he is adorned with the garment of faith; he is married to the wide-eyed maidens; and he intercedes for seventy people from his relatives.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13276],"tks":"حسن: رواه ابن ماجه (2799)."},{"num":8087,"demo":false,"sanad":"","matn":["عَنْ قَيْسٍ الْجُذَامِيِّ، رَجُلٍ كَانَتْ لَهُ صُحْبَةٌ، قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يُعْطَى الشَّهِيدُ سِتَّ خِصَالٍ: عِنْدَ أَوَّلِ قَطْرَةٍ مِنْ دَمِهِ: يُكَفَّرُ عَنْهُ كُلُّ خَطِيئَةٍ، وَيُرَى مَقْعَدَهُ مِنَ الْجَنَّةِ، وَيُزَوَّجُ مِنَ الْحُورِ الْعِينِ، وَيُؤَمَّنُ مِنَ الْفَزَعِ الْأَكْبَرِ، وَمِنْ عَذَابِ الْقَبْرِ، وَيُحَلَّى حُلَّةَ الْإِيمَانِ."],"takhrij":"حسن: رواه أحمد (17883) عن زيد بن يحيى الدمشقي قال: حدثنا ابن ثوبان عن أبيه، عن مكحول، عن كثير بن مرة، عن قيس الجذامي فذكره.","grade":"حسن","chapter_ar":"باب فضل الشهادة في سبيل الله تعالى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (17883).","chapter_en":"The Virtue of Martyrdom in the Path of Allah Most High","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Qays al-Judhami — a man who had companionship — said: The Prophet ﷺ said: “The martyr is given six qualities: at the first drop of his blood, every sin is expiated from him; he sees his seat in Paradise; he is married to the wide-eyed maidens; he is protected from the greatest terror and from the punishment of the grave; and he is adorned with the garment of faith.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3877,13277],"tks":"حسن: رواه أحمد (17883)."},{"num":8088,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ، مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ رَجُلاً قَالَ: يَا رَسُولَ اللَّهِ، مَا بَالُ الْمُؤْمِنِينَ يُفْتَنُونَ فِي قُبُورِهِمْ إِلاَّ الشَّهِيدَ؟ قَالَ: كَفَى بِبَارِقَةِ السُّيُوفِ عَلَى رَأْسِهِ فِتْنَةً."],"takhrij":"صحيح: رواه النسائي (2053) عن إبراهيم بن الحسن قال حدثنا حجاج عن ليث بن سعد عن معاوية بن صالح أن صفوان بن عمرو حدثه عن راشد بن سعد عن رجل من أصحاب النبيصلى الله عليه وسلم فذكره. وإسناده صحيح وهو مخرج في الجنائز.","grade":"صحيح","chapter_ar":"باب فضل الشهادة في سبيل الله تعالى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (2053).","chapter_en":"The Virtue of Martyrdom in the Path of Allah Most High","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["A man from the companions of the Prophet ﷺ narrated that a man said: “O Messenger of Allah, why are the believers tested in their graves except the martyr?” He said: “The flashing of swords over his head is enough of a trial for him.”"]}},"tuhfa":{},"full":1,"rep":[3875],"tks":"صحيح: رواه النسائي (2053)."},{"num":8089,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الشُّهَدَاءُ عَلَى بَارِقٍ - نَهْرٍ بِبَابِ الْجَنَّةِ - فِي قُبَّةٍ خَضْرَاءَ، يَخْرُجُ عَلَيْهِمْ رِزْقُهُمْ مِنَ الجَنَّةِ بُكْرَةً وَعَشِيًّا."],"takhrij":"حسن: رواه أحمد (2390)، وابن أبي عاصم في الجهاد (199)، وصحّحه ابن حبان (4658)، والحاكم (2403) كلهم من طرق عن ابن إسحاق قال: حدثني الحارث بن فضيل الأنصاري، عن محمود بن لبيد الأنصاري، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب فضل الشهادة في سبيل الله تعالى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (2390), Ibn Abi ʿAsim in al-Jihad (199), and authenticated by Ibn Hibban (4658) and al-Hakim (2403).","chapter_en":"The Virtue of Martyrdom in the Path of Allah Most High","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ said: “The martyrs are on the bank of a river at the gate of Paradise, in a green dome. Their provision comes out to them from Paradise morning and evening.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (2390)، وابن أبي عاصم في الجهاد (199)، وصححه ابن حبان (4658)، والحاكم (2403)."},{"num":8090,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَفْضَلُ الْجِهَادِ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ الَّذِينَ يَلْتَقُونَ فِي الصَّفِّ فَلَا يَلْفِتُونَ وُجُوهَهُمْ حَتَّى يُقْتَلُوا، أُولَئِكَ يَتَلَبَّطُونَ فِي الْغُرَفِ الْعُلَى مِنَ الْجَنَّةِ، يَنْظُرُ إِلَيْهِمْ رَبُّكَ، إِنَّ رَبَّكَ إِذَا ضَحِكَ إِلَى قَوْمٍ فَلَا حِسَابَ عَلَيْهِمْ."],"takhrij":"حسن: رواه الطبراني في الأوسط (2684-مجمع البحرين) عن علي بن سعيد حدثنا سعيد بن يحيى بن سعيد الأموي، حدثنا عمي عنبسة بن سعيد، حدثنا عبدالله بن المبارك، عن الأوزاعي، عن عروة بن رويم، عن قزعة بن يحيى، عن أبي سعيد الخدري فذكره. وإسناده حسن من أجل علي بن سعيد وهو الرازي وعروة بن رويم فإنهما حسنا الحديث.","grade":"حسن","chapter_ar":"باب فضل الشهادة في سبيل الله تعالى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat (2684 — Majmaʿ al-Bahrayn).","chapter_en":"The Virtue of Martyrdom in the Path of Allah Most High","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ said: “The best fighters in Allah’s sight on the Day of Resurrection are those who meet in the battle-line and do not turn their faces until they are killed. They will move about in the highest chambers of Paradise. Your Lord looks at them, and when your Lord laughs toward a people, there is no reckoning upon them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (2684 — مجمع البحرين)."},{"num":8091,"demo":false,"sanad":"","matn":["عَنْ نُعَيْمِ بْنِ هَمَّارٍ، أَنَّ رَجُلًا سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّ الشُّهَدَاءِ أَفْضَلُ؟ قَالَ: الَّذِينَ إِنْ يُلْقَوْا فِي الصَّفِّ لَا يَلْفِتُونَ وُجُوهَهُمْ حَتَّى يُقْتَلُوا، أُولَئِكَ يَتَلَبَّطُونَ فِي الْغُرَفِ الْعُلَى مِنَ الْجَنَّةِ، وَيَضْحَكُ إِلَيْهِمْ رَبُّكَ، وَإِذَا ضَحِكَ رَبُّكَ إِلَى عَبْدٍ فِي الدُّنْيَا فَلَا حِسَابَ عَلَيْهِ."],"takhrij":"حسن: رواه الإمام أحمد (22476)، وأبو يعلى (6855)، وابن أبي عاصم في الجهاد (228)، والبيهقي في الأسماء والصفات (986)، والآجريّ في الشريعة (650) كلّهم من طرق عن إسماعيل بن عياش، عن بحير بن سعد، عن خالد بن معدان، عن كثير بن مرة، عن نعيم بن همّار، فذكره.","grade":"حسن","chapter_ar":"باب فضل الشهادة في سبيل الله تعالى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (22476), Abu Yaʿla (6855), Ibn Abi ʿAsim in al-Jihad (228), al-Bayhaqi in al-Asma’ wa al-Sifat (986), and al-Ajurri in al-Shariʿah (650).","chapter_en":"The Virtue of Martyrdom in the Path of Allah Most High","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Nuʿaym ibn Hammar narrated that a man asked the Prophet ﷺ: “Which martyrs are best?” He said: “Those who, when they are placed in the battle-line, do not turn their faces until they are killed. They will move about in the highest chambers of Paradise, and your Lord laughs toward them. When your Lord laughs toward a servant in this world, there is no reckoning upon him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (22476)، وأبو يعلى (6855)، وابن أبي عاصم في الجهاد (228)، والبيهقي في الأسماء والصفات (986)، والآجري في الشريعة (650)."},{"num":8092,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَشْفَعُ الشَّهِيدُ فِي سَبِيعِنَّ مِنْ أَهْلِ بَيْتِهِ."],"takhrij":"حسن: رواه أبو داود (2522) عن أحمد بن صالح المصري، حدثنا يحيى بن حسان، حدثنا الوليد بن رباح الذمارى، حدثنى عمي نمران بن عتبة الذمارى قال: دخلنا على أم الدرداء ونحن أيتام فقالت: أبشروا فإنى سمعت أبا الدرداء يقول: فذكره. ثم قال أبو داود: صوابه: \"رباح بن الوليد\".","grade":"حسن","chapter_ar":"باب فضل الشهادة في سبيل الله تعالى","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2522). Abu Dawud then said: “The correct form is Rabah ibn al-Walid.”","chapter_en":"The Virtue of Martyrdom in the Path of Allah Most High","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Abu al-Darda’ said: The Messenger of Allah ﷺ said: “The martyr will be allowed to intercede for seventy of his family.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2522). ثم قال أبو داود: صوابه: «رباح بن الوليد»."},{"num":8093,"demo":false,"sanad":"","matn":["عن جابر بْنِ عبدالله رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَجُلٌ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ أُحُدٍ: أَرَأَيْتَ إِنْ قُتِلْتُ فَأَيْنَ أَنَا؟ قَالَ: فِي الْجَنَّةِ فَأَلْقَى تَمَرَاتٍ فِي يَدِهِ، ثُمَّ قَاتَلَ حَتَّى قُتِلَ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4046)، ومسلم في الإمارة (1899: 143) من طريق سفيان (هو ابن عيينة)، عن عمرو (هو ابن دينار) سمع جابر بن عبد الله فذكره.","grade":"متفق عليه","chapter_ar":"باب الشهيد في الجنة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4046) and Muslim (1899:143).","chapter_en":"The Martyr Is in Paradise","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":2,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: On the day of Uhud, a man said to the Prophet ﷺ: “Tell me, if I am killed, where will I be?” He said: “In Paradise.” So he threw away some dates that were in his hand, then fought until he was killed."]}},"tuhfa":{},"full":1,"rep":[8835],"tks":"متفق عليه: رواه البخاري (4046)، ومسلم (1899: 143)."},{"num":8094,"demo":false,"sanad":"","matn":["عَنْ ثَابِتٍ قَالَ: قَالَ أَنَسٌ  عَمِّيَ الَّذِي سُمِّيتُ بِهِ لَمْ يَشْهَدْ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَدْرًا، قَالَ: فَشَقَّ عَلَيْهِ. قَالَ: أَوَّلُ مَشْهَدٍ شَهِدَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غُيِّبْتُ عَنْهُ، وَإِنْ أَرَانِيَ اللهُ مَشْهَدًا فِيمَا بَعْدُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، لَيَرَانِي اللهُ مَا أَصْنَعُ. قَالَ: فَهَابَ أَنْ يَقُولَ غَيْرَهَا، قَالَ: فَشَهِدَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ أُحُدٍ، قَالَ: فَاسْتَقْبَلَ سَعْدُ بْنُ مُعَاذٍ فَقَالَ لَهُ أَنَسٌ: يَا أَبَا عَمْرٍو، أَيْنَ؟ فَقَالَ: وَاهًا لِرِيحِ الْجَنَّةِ، أَجِدُهُ دُونَ أُحُدٍ، قَالَ: فَقَاتَلَهُمْ حَتَّى قُتِلَ، قَالَ: فَوُجِدَ فِي جَسَدِهِ بِضْعٌ وَثَمَانُونَ مِنْ بَيْنِ ضَرْبَةٍ وَطَعْنَةٍ وَرَمْيَةٍ، قَالَ: فَقَالَتْ أُخْتُهُ عَمَّتِيَ الرُّبَيِّعُ بِنْتُ النَّضْرِ: فَمَا عَرَفْتُ أَخِي إِلَّا بِبَنَانِهِ، وَنَزَلَتْ هَذِهِ الْآيَةُ: ﴿رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ فَمِنْهُمْ مَنْ قَضَى نَحْبَهُ وَمِنْهُمْ مَنْ يَنْتَظِرُ وَمَا بَدَّلُوا تَبْدِيلا﴾. قَالَ: فَكَانُوا يُرَوْنَ أَنَّهَا نَزَلَتْ فِيهِ وَفِي أَصْحَابِهِ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2805)، ومسلم في الإمارة (1903: 148) كلاهما من طرق عن أنس فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب الشهيد في الجنة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2805) and Muslim (1903:148). The wording is Muslim’s.","chapter_en":"The Martyr Is in Paradise","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":2,"content":{"translation":{"en":["Anas said: My uncle, after whom I was named, did not attend Badr with the Messenger of Allah ﷺ. He said: That was hard for him. He said: “The first battle witnessed by the Messenger of Allah ﷺ, I was absent from it. If Allah shows me a battle afterward with the Messenger of Allah ﷺ, Allah will surely see what I will do.” He said: He was hesitant to say more than that. He then witnessed Uhud with the Messenger of Allah ﷺ. He met Saʿd ibn Muʿadh, and Anas said to him: “O Abu ʿAmr, where are you going?” He said: “Ah, the fragrance of Paradise! I find it before Uhud.” He fought them until he was killed. More than eighty wounds were found on his body, between sword-strikes, spear-thrusts, and arrow-wounds. His sister, my aunt al-Rubayyiʿ bint al-Nadr, said: “I only recognized my brother by his fingertips.” Then this verse was revealed: “Among the believers are men who were true to what they pledged to Allah. Among them are those who have fulfilled their vow, and among them are those who are waiting, and they have not changed in the least.” [al-Ahzab: 23] He said: They used to think that it was revealed concerning him and his companions."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2805)، ومسلم (1903: 148). واللفظ لمسلم."},{"num":8095,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ:  جَاءَ نَاسٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: أَنِ ابْعَثْ مَعَنَا رِجَالًا يُعَلِّمُونَا الْقُرْآنَ وَالسُّنَّةَ. فَبَعَثَ إِلَيْهِمْ سَبْعِينَ رَجُلًا مِنَ الْأَنْصَارِ يُقَالُ لَهُمُ: الْقُرَّاءُ: فِيهِمْ خَالِي حَرَامٌ، يَقْرَءُونَ الْقُرْآنَ، وَيَتَدَارَسُونَ، بِاللَّيْلِ يَتَعَلَّمُونَ، وَكَانُوا بِالنَّهَارِ يَجِيئُونَ بِالْمَاءِ فَيَضَعُونَهُ فِي الْمَسْجِدِ، وَيَحْتَطِبُونَ فَيَبِيعُونَهُ وَيَشْتَرُونَ بِهِ الطَّعَامَ لِأَهْلِ الصُّفَّةِ وَلِلْفُقَرَاءِ، فَبَعَثَهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَيْهِمْ، فَعَرَضُوا لَهُمْ فَقَتَلُوهُمْ قَبْلَ أَنْ يَبْلُغُوا الْمَكَانَ، فَقَالُوا: اللَّهُمَّ بَلِّغْ عَنَّا نَبِيَّنَا أَنَّا قَدْ لَقِينَاكَ فَرَضِينَا عَنْكَ وَرَضِيتَ عَنَّا، قَالَ: وَأَتَى رَجُلٌ حَرَامًا خَالَ أَنَسٍ مِنْ خَلْفِهِ فَطَعَنَهُ بِرُمْحٍ حَتَّى أَنْفَذَهُ، فَقَالَ حَرَامٌ: فُزْتُ وَرَبِّ الْكَعْبَةِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَصْحَابِهِ: إِنَّ إِخْوَانَكُمْ قَدْ قُتِلُوا، وَإِنَّهُمْ قَالُوا: اللَّهُمَّ بَلِّغْ عَنَّا نَبِيَّنَا أَنَّا قَدْ لَقِينَاكَ فَرَضِينَا عَنْكَ، وَرَضِيتَ عَنَّا."],"takhrij":"متفق عليه: رواه مسلم في الإمارة (677: 147) عن محمد بن حاتم، حدثنا عفان، حدثنا حماد، أخبرنا ثابت، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب الشهيد في الجنة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (677:147) and al-Bukhari (2801).","chapter_en":"The Martyr Is in Paradise","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Malik said: Some people came to the Prophet ﷺ and said: “Send with us men who will teach us the Qur’an and the Sunnah.” So he sent to them seventy men from the Ansar who were called the Qurra’, among whom was my maternal uncle Haram. They used to recite the Qur’an and study together at night, learning, and during the day they would bring water and place it in the mosque, gather firewood and sell it, and buy food with it for the people of al-Suffah and the poor. The Prophet ﷺ sent them to those people, but they attacked them and killed them before they reached the place. They said: “O Allah, convey from us to our Prophet that we have met You, and we are pleased with You, and You are pleased with us.” He said: A man came to Haram, the maternal uncle of Anas, from behind and pierced him with a spear until it went through him. Haram said: “I have succeeded, by the Lord of the Kaʿbah.” The Messenger of Allah ﷺ said to his companions: “Your brothers have been killed, and they said: O Allah, convey from us to our Prophet that we have met You, and we are pleased with You, and You are pleased with us.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (677: 147)، والبخاري (2801)."},{"num":8096,"demo":false,"sanad":"","matn":["عن كَعْبِ بن مَالِكٍ، عَنْ أَبِيهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ أَرْوَاحَ الشُّهَدَاءِ فِي طَيْرٍ خُضْرٍ تَعْلُقُ مِنْ ثَمَرَةِ الْجَنَّةِ أَوْ شَجَرِ الْجَنَّةِ."],"takhrij":"صحيح: رواه الترمذي (1641)، عن ابن أبي عمر- وأحمد (27166)- كلاهما عن سفيان (هو ابن عيينة)، عن عمرو بن دينار، عن الزهري، عن ابن كعب بن مالك (واسمه عبد الرحمن) عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أرواح الشهداء","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1641) and Ahmad (27166). He said: “This is a good authentic hadith.”","chapter_en":"What Has Been Reported Concerning the Souls of the Martyrs","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Kaʿb ibn Malik narrated that the Messenger of Allah ﷺ said: “The souls of the martyrs are in green birds, eating from the fruit of Paradise or the trees of Paradise.”"]},"intro":{"ar":["قال تعالى:","(وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللهِ أَمْوَاتًا ۚ بَلْ أَحْيَاءٌ عِندَ رَبِّهِمْ يُرْزَقُونَ ۝ فَرِحِينَ بِمَا آتَاهُمُ اللهُ مِن فَضْلِهِ ۙ وَيَسْتَبْشِرُونَ بِالَّذِينَ لَمْ يَلْحَقُوا بِهِم مِّنْ خَلْفِهِمْ أَلَّا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ ۝ يَسْتَبْشِرُونَ بِنِعْمَةٍ مِّنَ اللهِ وَفَضْلٍ وَأَنَّ اللهَ لَا يُضِيعُ أَجْرَ الْمُؤْمِنِينَ) [آل عمران: ١٦٩-١٧١].","قال تعالى:","(وَلَا تَقُولُوا لِمَن يُقْتَلُ فِي سَبِيلِ اللهِ أَمْوَاتٌ ۚ بَلْ أَحْيَاءٌ وَلَٰكِن لَّا تَشْعُرُونَ) [البقرة: ١٥٤]."],"en":["Allah Most High said:","“Do not think of those who were killed in the path of Allah as dead. Rather, they are alive with their Lord, receiving provision, rejoicing in what Allah has given them of His bounty, and they rejoice for those who have not yet joined them from behind them, that there will be no fear upon them, nor will they grieve. They rejoice in blessing from Allah and bounty, and that Allah does not allow the reward of the believers to be lost.” [Al ʿImran: 169–171]","Allah Most High said:","“And do not say of those who are killed in the path of Allah, ‘They are dead.’ Rather, they are alive, but you do not perceive.” [al-Baqarah: 154]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (1641)، وأحمد (27166). وقال: “هذا حديث حسن صحيح”."},{"num":8097,"demo":false,"sanad":"","matn":["عَنْ مَسْرُوقٍ قَالَ:  سَأَلْنَا عَبْدَ اللَّهِ عَنْ هَذِهِ الْآيَةِ: ﴿وَلا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ أَمْوَاتًا بَلْ أَحْيَاءٌ عِنْدَ رَبِّهِمْ يُرْزَقُونَ﴾ قَالَ: أَمَا إِنَّا قَدْ سَأَلْنَا عَنْ ذَلِكَ فَقَالَ: أَرْوَاحُهُمْ فِي جَوْفِ طَيْرٍ خُضْرٍ، لَهَا قَنَادِيلُ مُعَلَّقَةٌ بِالْعَرْشِ، تَسْرَحُ مِنَ الْجَنَّةِ حَيْثُ شَاءَتْ، ثُمَّ تَأْوِي إِلَى تِلْكَ الْقَنَادِيلِ، فَاطَّلَعَ إِلَيْهِمْ رَبُّهُمُ اطِّلَاعَةً، فَقَالَ: هَلْ تَشْتَهُونَ شَيْئًا؟ قَالُوا: أَيَّ شَيْءٍ نَشْتَهِي وَنَحْنُ نَسْرَحُ مِنَ الْجَنَّةِ حَيْثُ شِئْنَا، فَفَعَلَ ذَلِكَ بِهِمْ ثَلَاثَ مَرَّاتٍ، فَلَمَّا رَأَوْا أَنَّهُمْ لَنْ يُتْرَكُوا مِنْ أَنْ يُسْأَلُوا قَالُوا: يَا رَبِّ نُرِيدُ أَنْ تَرُدَّ أَرْوَاحَنَا فِي أَجْسَادِنَا، حَتَّى نُقْتَلَ فِي سَبِيلِكَ مَرَّةً أُخْرَى، فَلَمَّا رَأَى أَنْ لَيْسَ لَهُمْ حَاجَةٌ تُرِكُوا."],"takhrij":"صحيح: رواه مسلم في الإمارة (1887: 121) من طريق الأعمش، عن عبدالله بن مرة، عن مسروق به فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أرواح الشهداء","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1887:121).","chapter_en":"What Has Been Reported Concerning the Souls of the Martyrs","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Masruq said: We asked ʿAbdullah ibn Masʿud about this verse: “Do not think of those who were killed in the path of Allah as dead. Rather, they are alive with their Lord, receiving provision.” He said: We did ask about that, and he said: “Their souls are inside green birds. They have lamps hanging from the Throne. They roam freely in Paradise wherever they wish, then return to those lamps. Their Lord looks upon them and says: ‘Do you desire anything?’ They say: ‘What could we desire while we roam freely in Paradise wherever we wish?’ He does that with them three times. When they see that they will not be left without being asked, they say: ‘Our Lord, we want You to return our souls to our bodies so that we may be killed in Your path once more.’ When He sees that they have no need, He leaves them.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1887: 121)."},{"num":8098,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَمَّا أُصِيبَ إِخْوَانُكُمْ بِأُحُدٍ جَعَلَ اللَّهُ أَرْوَاحَهُمْ فِي جَوْفِ طَيْرٍ خُضْرٍ تَرِدُ أَنْهَارَ الْجَنَّةِ، تَأْكُلُ مِنْ ثِمَارِهَا، وَتَأْوِي إِلَى قَنَادِيلَ مِنْ ذَهَبٍ مُعَلَّقَةٍ فِي ظِلِّ الْعَرْشِ، فَلَمَّا وَجَدُوا طِيبَ مَأْكَلِهِمْ وَمَشْرَبِهِمْ وَمَقِيلِهِمْ قَالُوا: مَنْ يُبَلِّغُ إِخْوَانَنَا عَنَّا أَنَّا أَحْيَاءٌ فِي الْجَنَّةِ نُرْزَقُ لِئَلاَّ يَزْهَدُوا فِي الْجِهَادِ وَلاَ يَنْكُلُوا عِنْدَ الْحَرْبِ فَقَالَ اللَّهُ سُبْحَانَهُ: أَنَا أُبَلِّغُهُمْ عَنْكُمْ. قَالَ: فَأَنْزَلَ اللَّهُ ﴿وَلاَ تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ أَمْوَاتًا﴾ [سورة آل عمران: 169] }. إِلَى آخِرِ الآيَةِ."],"takhrij":"حسن: رواه أبو داود (2520) عن عثمان بن أبي شيبة، حدثنا عبد الله بن إدريس، عن محمد بن إسحاق، عن إسماعيل بن أمية، عن أبى الزبير، عن سعيد بن جبير، عن ابن عباس قال: فذكره. وهو حديث حسن.","grade":"حسن","chapter_ar":"باب ما جاء في أرواح الشهداء","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2520).","chapter_en":"What Has Been Reported Concerning the Souls of the Martyrs","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ said: “When your brothers were struck down at Uhud, Allah placed their souls inside green birds that come to the rivers of Paradise, eat from its fruits, and return to lamps of gold hanging in the shade of the Throne. When they found the goodness of their food, drink, and resting place, they said: ‘Who will convey to our brothers from us that we are alive in Paradise, receiving provision, so that they will not turn away from jihad or shrink back during war?’ Allah, Glorified is He, said: ‘I will convey it from you.’ He said: Then Allah revealed: ‘Do not think of those who were killed in the path of Allah…’ to the end of the verse.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10070,12101],"tks":"حسن: رواه أبو داود (2520)."},{"num":8099,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ: أَنَّهُ سَمِعَهُ يُحَدِّثُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  أَنَّهُ قَامَ فِيهِمْ فَذَكَرَ لَهُمْ: أَنَّ الْجِهَادَ فِي سَبِيلِ اللَّهِ وَالْإِيمَانَ بِاللهِ أَفْضَلُ الْأَعْمَالِ. فَقَامَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ تُكَفَّرُ عَنِّي خَطَايَايَ؟ فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: نَعَمْ، إِنْ قُتِلْتَ فِي سَبِيلِ اللَّهِ وَأَنْتَ صَابِرٌ مُحْتَسِبٌ، مُقْبِلٌ غَيْرُ مُدْبِرٍ. ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَيْفَ قُلْتَ؟. قَالَ: أَرَأَيْتَ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ، أَتُكَفَّرُ عَنِّي خَطَايَايَ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: نَعَمْ، وَأَنْتَ صَابِرٌ مُحْتَسِبٌ، مُقْبِلٌ غَيْرُ مُدْبِرٍ، إِلَّا الدَّيْنَ، فَإِنَّ جِبْرِيلَ عَلَيْهِ السلام قَالَ لِي ذَلِكَ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1885: 117) عن قتيبة بن سعيد، حدثنا ليث، عن سعيد بن أبي سعيد، عن عبد الله بن أبي قتادة، عن أبي قتادة فذكره.","grade":"صحيح","chapter_ar":"باب الشهيد يُغفر له كل ذنب إلا الدين","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1885:117).","chapter_en":"The Martyr Is Forgiven Every Sin Except Debt","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Abu Qatadah narrated that he heard the Messenger of Allah ﷺ standing among them and mentioning to them that jihad in the path of Allah and faith in Allah are the best deeds. A man stood and said: “O Messenger of Allah, tell me, if I am killed in the path of Allah, will my sins be expiated from me?” The Messenger of Allah ﷺ said to him: “Yes, if you are killed in the path of Allah while patient, seeking reward, advancing and not retreating.” Then the Messenger of Allah ﷺ said: “How did you put it?” He said: “Tell me, if I am killed in the path of Allah, will my sins be expiated from me?” The Messenger of Allah ﷺ said: “Yes, while you are patient, seeking reward, advancing and not retreating — except debt, for Jibril, peace be upon him, said that to me.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1885: 117)."},{"num":8100,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ فَخَطَبَ النَّاسَ ثُمَّ ذَكَرَ: أن الْإِيمَانَ بِاللهِ وَالْجِهَادَ فِي سَبِيلِ اللَّهِ مِنْ أَفْضَلِ الْأَعْمَالِ عِنْدَ اللَّهِ، فَقَامَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ وَأَنَا صَابِرٌ مُحْتَسِبٌ مُقْبِلٌ غَيْرَ مُدْبِرٍ يكفر اللهُ عَنِّي خَطَايَايَ؟ قَالَ: نَعَمْ فَكَيْفَ قُلْتَ؟ قَالَ: إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ وَأَنَا صَابِرٌ مُحْتَسِبٌ مُقْبِلٌ غَيْرَ مُدْبِرٍ يكفر الله عَنِّي خَطَايَايَ؟ قَالَ: نَعَمْ كَيْفَ قُلْتَ؟ قَالَ: إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ وَأَنَا صَابِرٌ مُحْتَسِبٌ مُقْبِلٌ غَيْرَ مُدْبِرٍ يكفر الله عَنِّي خَطَايَايَ؟ قَالَ: نَعَمْ إِلَّا الدَّيْنَ، فَإِنَّ جِبْرِيلَ سَارَّنِي بِذَلِكَ."],"takhrij":"حسن: رواه أحمد (8075، 8371) من طريقين عن عبد الحميد بن جعفر الأنصاري، أخبرني عياض بن عبد الله بن أبي سرح، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب الشهيد يُغفر له كل ذنب إلا الدين","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (8075, 8371).","chapter_en":"The Martyr Is Forgiven Every Sin Except Debt","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ stood and addressed the people, then mentioned that faith in Allah and jihad in the path of Allah are among the best deeds with Allah. A man stood and said: “O Messenger of Allah, if I am killed in the path of Allah while patient, seeking reward, advancing and not retreating, will Allah expiate my sins from me?” He said: “Yes. How did you put it?” He said: “If I am killed in the path of Allah while patient, seeking reward, advancing and not retreating, will Allah expiate my sins from me?” He said: “Yes. How did you put it?” He said: “If I am killed in the path of Allah while patient, seeking reward, advancing and not retreating, will Allah expiate my sins from me?” He said: “Yes, except debt, for Jibril privately informed me of that.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (8075، 8371)."},{"num":8101,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  يُغْفَرُ لِلشَّهِيدِ كُلُّ ذَنْبٍ إِلَّا الدَّيْنَ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1886: 119) عن زكريا بن يحيى بن صالح المصري، حدثنا المفضل بن فضالة، عن عياش بن عباس القتباني، عن عبد الله بن يزيد أبي عبد الرحمن الحبلي، عن عبد الله بن عمرو بن العاص فذكره.","grade":"صحيح","chapter_ar":"باب الشهيد يُغفر له كل ذنب إلا الدين","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1886:119).","chapter_en":"The Martyr Is Forgiven Every Sin Except Debt","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr narrated that the Messenger of Allah ﷺ said: “The martyr is forgiven every sin except debt.”"]}},"tuhfa":{},"full":1,"rep":[5602,13278],"tks":"صحيح: رواه مسلم (1886: 119)."},{"num":8102,"demo":false,"sanad":"","matn":["عن سهل بْنِ حُنَيْفٍأَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَوَّلُ مَا يُهْرَاقُ دَمُ الشَّهِيدِ يُغْفَرُ لَهُ ذَنْبُهُ كُلُّهُ إِلَّا الدَّيْنَ."],"takhrij":"حسن: رواه أبو يعلى (1926- المطالب) عن هارون بن معروف- والطبراني في الكبير (5552) من طريق أحمد بن صالح- والحاكم (2/119) وعنه البيهقي (9/163-164) من طريق محمد بن عبد الله بن عبد الحكم- ثلاثتهم عن ابن وهب، أخبرني عبد الرحمن بن سعد، عن سهل بن أبي أمامة بن سهل بن حنيف، عن أبيه، عن جده فذكره. وليس عند الحاكم والبيهقي \"إلا الدين\".","grade":"حسن","chapter_ar":"باب الشهيد يُغفر له كل ذنب إلا الدين","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Yaʿla (1926 — al-Matalib), al-Tabarani in al-Kabir (6/88), al-Hakim (2555), and through him al-Bayhaqi (9/163–164). The words “except debt” are not present in the narrations of al-Hakim and al-Bayhaqi.","chapter_en":"The Martyr Is Forgiven Every Sin Except Debt","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Sahl ibn Hunayf said: The Messenger of Allah ﷺ said: “At the first blood that is shed from the martyr, all his sins are forgiven except debt.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى (1926 — المطالب)، والطبراني في الكبير (5552)، والحاكم (2555)، وعنه البيهقي (9/163-164). وليس عند الحاكم والبيهقي: «إلا الدين»."},{"num":8103,"demo":false,"sanad":"","matn":["عَنْ أنَسٍ، أَنَّ رَجُلا قَالَ: يَا رَسُولَ اللَّهِ، إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ صَابِرًا مُحْتَسِبًا أَدْخُلُ الْجَنَّةَ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: نَعَمْ، فَلَمَّا وَلَّى قَالَ: إِلا الدَّيْنَ."],"takhrij":"حسن: رواه البزار (7328) عن محمد بن يحيى بن عدي، حدثنا محمد بن عبد الله الأنصاري، عن أبيه (هو عبد الله بن المثنى)، عن ثمامة، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب الشهيد يُغفر له كل ذنب إلا الدين","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar (7328).","chapter_en":"The Martyr Is Forgiven Every Sin Except Debt","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Malik narrated that a man said: “O Messenger of Allah, if I am killed in the path of Allah while patient and seeking reward, will I enter Paradise?” The Prophet ﷺ said: “Yes.” When he turned away, he said: “Except debt.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (7328)."},{"num":8104,"demo":false,"sanad":"","matn":["عن محمد بن عَبْدِ اللَّهِ بن جَحْشٍ قَالَ: كُنَّا جُلُوسًا بِفِنَاءِ الْمَسْجِدِ حَيْثُ تُوضَعُ الْجَنَائِزُ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ بَيْنَ ظَهْرَيْنَا، فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَصَرَهُ قِبَلَ السَّمَاءِ فَنَظَرَ، ثُمَّ طَأْطَأَ بَصَرَهُ وَوَضَعَ يَدَهُ عَلَى جَبْهَتِهِ، ثُمَّ قَالَ: سُبْحَانَ اللَّهِ سُبْحَانَ اللَّهِ مَاذَا نَزَلَ مِنَ التَّشْدِيدِ؟ قَالَ: فَسَكَتْنَا يَوْمَنَا وَلَيْلَتَنَا، فَلَمْ نَرَهَا خَيْرًا حَتَّى أَصْبَحْنَا. قَالَ مُحَمَّدٌ: فَسَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا التَّشْدِيدُ الَّذِي نَزَلَ؟ قَالَ: فِي الدَّيْنِ، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَوْ أَنَّ رَجُلًا قُتِلَ فِي سَبِيلِ اللَّهِ، ثُمَّ عَاشَ، ثُمَّ قُتِلَ فِي سَبِيلِ اللَّهِ، ثُمَّ عَاشَ، ثُمَّ قُتِلَ فِي سَبِيلِ اللَّهِ، ثُمَّ عَاشَ وَعَلَيْهِ دَيْنٌ مَا دَخَلَ الْجَنَّةَ حَتَّى يَقْضِيَ دَيْنَهُ."],"takhrij":"حسن: رواه النسائي (4684)، وأحمد (22493)، والحاكم (2212) كلهم من طرق عن العلاء بن عبد الرحمن، عن أبي كثير مولى محمد بن جحش فذكره.","grade":"حسن","chapter_ar":"باب الشهيد يُغفر له كل ذنب إلا الدين","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4684), Ahmad (22493), and al-Hakim (2212).","chapter_en":"The Martyr Is Forgiven Every Sin Except Debt","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Muhammad ibn ʿAbdullah ibn Jahsh said: We were sitting in the courtyard of the mosque where the funerals were placed, and the Messenger of Allah ﷺ was sitting among us. The Messenger of Allah ﷺ raised his gaze toward the sky and looked, then lowered his gaze, placed his hand on his forehead, and said: “Glory be to Allah, glory be to Allah! What severity has been revealed?” He said: We remained silent that day and night, and we did not see it as good until morning came. Muhammad said: I asked the Messenger of Allah ﷺ: “What severity was revealed?” He said: “Concerning debt. By the One in whose hand is the soul of Muhammad, if a man were killed in the path of Allah, then brought back to life, then killed in the path of Allah, then brought back to life, then killed in the path of Allah, then brought back to life, while he had a debt upon him, he would not enter Paradise until his debt was paid.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (4684)، وأحمد (22493)، والحاكم (2212)."},{"num":8105,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ جَحْشٍ، أَنَّ رَجُلًا جَاءَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، مَاذَا لِي إِنْ قُتِلْتُ فِي سَبِيلِ اللَّهِ؟ قَالَ: الْجَنَّةُ. فَلَمَّا وَلَّى قَالَ: إِلَّا الدَّيْنُ، سَارَّنِي بِهِ جِبْرِيلُ عَلَيْهِ السلام آنِفًا."],"takhrij":"حسن: رواه أحمد (19077، 17253)، وابن أبي شيبة (12019)، وعنه ابن أبي عاصم في الجهاد (2/238) عن محمد بن بشر، حدثنا محمد بن عمرو –وهو ابن علقمة الليثي-، حدثني أبو كثير مولى الليثيين، عن محمد بن عبد الله بن جحش فذكره.","grade":"حسن","chapter_ar":"باب الشهيد يُغفر له كل ذنب إلا الدين","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (17253, 19077), Ibn Abi Shaybah (3/273), and from him Ibn Abi ʿAsim in al-Jihad (2/238).","chapter_en":"The Martyr Is Forgiven Every Sin Except Debt","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Muhammad ibn ʿAbdullah ibn Jahsh narrated that a man came to the Prophet ﷺ and said: “What will I have, O Messenger of Allah, if I am killed in the path of Allah?” He said: “Paradise.” When he turned away, he said: “Except debt; Jibril, peace be upon him, privately informed me of that just now.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17253، 19077)، وابن أبي شيبة (12019)، وعنه ابن أبي عاصم في الجهاد (2/238)."},{"num":8106,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ طَلَبَ الشَّهَادَةَ صَادِقًا أُعْطِيَهَا، وَلَوْ لَمْ تُصِبْهُ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1908: 156) عن شيبان بن فروخ، حدثنا حماد بن سلمة، حدثنا ثابت، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب من طلب الشهادة في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1908:156).","chapter_en":"One Who Seeks Martyrdom in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":5,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said: “Whoever sincerely seeks martyrdom will be granted it, even if it does not physically reach him.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1908: 156)."},{"num":8107,"demo":false,"sanad":"","matn":["عَنْ سهل بْنِ حُنَيْفٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ سَأَلَ الشَّهَادَةَ بِصِدْقٍ، بَلَّغَهُ اللهُ مَنَازِلَ الشُّهَدَاءِ وَإِنْ مَاتَ عَلَى فِرَاشِهِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1909: 157) من طريق عبد الله بن وهب، حدثني أبو شُريح، أن سهل بن أبي أمامة بن سهل بن حنيف، حدثه عن أبيه، عن جده فذكره.","grade":"صحيح","chapter_ar":"باب من طلب الشهادة في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1909:157).","chapter_en":"One Who Seeks Martyrdom in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":5,"content":{"translation":{"en":["Sahl ibn Hunayf narrated that the Prophet ﷺ said: “Whoever sincerely asks for martyrdom, Allah will cause him to reach the ranks of the martyrs, even if he dies on his bed.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1909: 157)."},{"num":8108,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَجْمَعُ بَيْنَ الرَّجُلَيْنِ مِنْ قَتْلَى أُحُدٍ فِي ثَوْبٍ وَاحِدٍ ثُمَّ يَقُولُ: أَيُّهُمْ أَكْثَرُ أَخْذًا لِلْقُرْآنِ. فَإِذَا أُشِيرَ لَهُ إِلَى أَحَدِهِمَا قَدَّمَهُ فِي اللَّحْدِ وَقَالَ: أَنَا شَهِيدٌ عَلَى هَؤُلاَءِ يَوْمَ الْقِيَامَةِ. وَأَمَرَ بِدَفْنِهِمْ فِي دِمَائِهِمْ، وَلَمْ يُغَسَّلُوا، وَلَمْ يُصَلَّ عَلَيْهِمْ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1343) عن عبدالله بن يوسف، حدثنا الليث قال حدثني ابن شهاب عن عبد الرحمن بن كعب بن مالك عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب أن الشهيد في سبيل الله لا يُغسَل ولا يُنزع منه ثيابه التي استُشهد فيها ولا يُصلّى عليه","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1343).","chapter_en":"The Martyr in the Path of Allah Is Not Washed, His Clothes in Which He Was Martyred Are Not Removed, and the Funeral Prayer Is Not Performed over Him","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: The Prophet ﷺ used to place two men from those killed at Uhud together in one cloth, then say: “Which of them had taken more of the Qur’an?” When one of them was pointed out to him, he would place him first in the grave niche, and he said: “I am a witness over these people on the Day of Resurrection.” He ordered that they be buried in their blood; they were not washed, and the funeral prayer was not performed over them."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3755],"tks":"صحيح: رواه البخاري (1343)."},{"num":8109,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بَيْنَمَا رَجُلٌ يَمْشِي بِطَرِيقٍ إِذْ وَجَدَ غُصْنَ شَوْكٍ عَلَى الطَّرِيقِ، فَأَخَّرَهُ فَشَكَرَ اللهُ لَهُ، فَغَفَرَ لَهُ وَقَالَ: الشُّهَدَاءُ خَمْسَةٌ: الْمَطْعُونُ، وَالْمَبْطُونُ، وَالْغَرِقُ، وَصَاحِبُ الْهَدْمِ، وَالشَّهِيدُ فِي سَبِيلِ اللَّهِ. ثُمَّ ذَكَرَ حديث فضل الصف الأول فِي صلاة الْجَمَاعَةِ."],"takhrij":"متفق عليه: رواه مالك في صلاة الجماعة (6) عن سُمي مولى أبي بكر بن عبد الرحمن، عن أبي صالح، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الشهداء سوى القتيل في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (6), al-Bukhari (652–654, 2829), and Muslim (1914:164).","chapter_en":"What Has Been Reported Concerning Martyrs Other Than One Killed in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “While a man was walking on a road, he found a thorny branch on the road and removed it. Allah appreciated that from him and forgave him.” He also said: “The martyrs are five: one who dies of plague, one who dies of a stomach illness, one who drowns, one who dies under a collapsed structure, and the martyr in the path of Allah.” Then he mentioned the hadith about the virtue of the first row in congregational prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (6)، والبخاري (652-654، 2829)، ومسلم (1914: 164)."},{"num":8110,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ:  جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ إِنْ جَاءَ رَجُلٌ يُرِيدُ أَخْذَ مَالِي؟ قَالَ: فَلَا تُعْطِهِ مَالَكَ، قَالَ: أَرَأَيْتَ إِنْ قَاتَلَنِي؟ قَالَ: قَاتِلْهُ، قَالَ: أَرَأَيْتَ إِنْ قَتَلَنِي؟ قَالَ: فَأَنْتَ شَهِيدٌ، قَالَ: أَرَأَيْتَ إِنْ قَتَلْتُهُ؟ قَالَ: هُوَ فِي النَّارِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (140) عن أبي كريب محمد بن العلاء حدثنا خالد يعني بن مخلد حدثنا محمد بن جعفر عن العلاء بن عبد الرحمن عن أبيه عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الشهداء سوى القتيل في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (140).","chapter_en":"What Has Been Reported Concerning Martyrs Other Than One Killed in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah said: A man came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, what do you think if a man comes wanting to take my wealth?” He said: “Do not give him your wealth.” He said: “What if he fights me?” He said: “Fight him.” He said: “What if he kills me?” He said: “Then you are a martyr.” He said: “What if I kill him?” He said: “He is in the Fire.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (140)."},{"num":8111,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَا تَعُدُّونَ الشَّهِيدَ فِيكُمْ؟ قَالُوا: يَا رَسُولَ اللَّهِ، مَنْ قُتِلَ فِي سَبِيلِ اللَّهِ فَهُوَ شَهِيدٌ، قَالَ: إِنَّ شُهَدَاءَ أُمَّتِي إِذًا لَقَلِيلٌ، قَالُوا: فَمَنْ هُمْ يَا رَسُولَ اللَّهِ؟ قَالَ: مَنْ قُتِلَ فِي سَبِيلِ اللَّهِ فَهُوَ شَهِيدٌ، وَمَنْ مَاتَ فِي سَبِيلِ اللَّهِ فَهُوَ شَهِيدٌ، وَمَنْ مَاتَ فِي الطَّاعُونِ فَهُوَ شَهِيدٌ، وَمَنْ مَاتَ فِي الْبَطْنِ فَهُوَ شَهِيدٌ.","قَالَ ابْنُ مِقْسَمٍ: أَشْهَدُ عَلَى أَبِيكَ فِي هَذَا الْحَدِيثِ أَنَّهُ قَالَ: وَالْغَرِيقُ شَهِيدٌ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1915: 165) عن زهير بن حرب، حدثنا جرير، عن سُهيل، عن أبيه، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الشهداء سوى القتيل في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1915:165).","chapter_en":"What Has Been Reported Concerning Martyrs Other Than One Killed in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Whom do you count as a martyr among you?” They said: “O Messenger of Allah, whoever is killed in the path of Allah is a martyr.” He said: “Then the martyrs of my ummah would be few.” They said: “Then who are they, O Messenger of Allah?” He said: “Whoever is killed in the path of Allah is a martyr; whoever dies in the path of Allah is a martyr; whoever dies of plague is a martyr; and whoever dies of a stomach illness is a martyr.” Ibn Miqsam said: I testify concerning your father in this hadith that he said: “And the one who drowns is a martyr.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1915: 165)."},{"num":8112,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الطَّاعُونِ فَأَخْبَرَنِي: أَنَّهُ عَذَابٌ يَبْعَثُهُ اللَّهُ عَلَى مَنْ يَشَاءُ، وَأَنَّ اللَّهَ جَعَلَهُ رَحْمَةً لِلْمُؤْمِنِينَ، لَيْسَ مِنْ أَحَدٍ يَقَعُ الطَّاعُونُ، فَيَمْكُثُ فِي بَلَدِهِ صَابِرًا مُحْتَسِبًا يَعْلَمُ أَنَّهُ لاَ يُصِيبُهُ إِلاَّ مَا كَتَبَ اللَّهُ لَهُ إِلاَّ كَانَ لَهُ مِثْلُ أَجْرِ شَهِيدٍ."],"takhrij":"صحيح: رواه البخاري في أحاديث الأنبياء (3474) عن موسى بن إسماعيل، حدثنا داود بن أبي الفرات، حدثنا عبد الله بن بريدة، عن يحيى بن يعمر، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في الشهداء سوى القتيل في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3474).","chapter_en":"What Has Been Reported Concerning Martyrs Other Than One Killed in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["ʿA’ishah said: I asked the Messenger of Allah ﷺ about plague, and he informed me: “It is a punishment that Allah sends upon whom He wills, and Allah has made it a mercy for the believers. There is no one upon whom plague falls, and he remains in his land patiently seeking reward, knowing that nothing will befall him except what Allah has written for him, except that he will have the like of the reward of a martyr.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3474)."},{"num":8113,"demo":false,"sanad":"","matn":["عَنْ حَفْصَةَ بِنْتِ سِيرِينَ قَالَتْ:  قَالَ لِي أَنَسُ بْنُ مَالِكٍ: بِمَ مَاتَ يَحْيَى بْنُ أَبِي عَمْرَةَ؟ قَالَتْ: قُلْتُ بِالطَّاعُونِ، قَالَتْ: فَقَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الطَّاعُونُ شَهَادَةٌ لِكُلِّ مُسْلِمٍ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2830)، ومسلم في الإمارة (1916: 166) كلاهما من حديث عاصم، عن حفصة بنت سيرين فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الشهداء سوى القتيل في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2830) and Muslim (1916:166).","chapter_en":"What Has Been Reported Concerning Martyrs Other Than One Killed in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Hafsah bint Sirin said: Anas ibn Malik said to me: “What did Yahya ibn Abi ʿAmrah die of?” She said: I said: “Of plague.” She said: He said: The Messenger of Allah ﷺ said: “Plague is martyrdom for every Muslim.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11631],"tks":"متفق عليه: رواه البخاري (2830)، ومسلم (1916: 166)."},{"num":8114,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَنْ قُتل دُونَ مَالِهِ فَهُوَ شَهِيدٌ."],"takhrij":"متفق عليه: رواه البخاري في المظالم (2480) عن عبدالله بن يزيد، حدثنا سعيد ابن أبي أيوب قال: حدثني أبو الأسود، عن عكرمة، عن عبد الله بن عمرو فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الشهداء سوى القتيل في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2480) and Muslim (141).","chapter_en":"What Has Been Reported Concerning Martyrs Other Than One Killed in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr said: The Messenger of Allah ﷺ said: “Whoever is killed defending his wealth is a martyr.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2480)، ومسلم (141)."},{"num":8115,"demo":false,"sanad":"","matn":["وَعَنْ سَعْدٍ - يَعْنِي ابْنَ أَبِي وَقَّاصٍ - قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَسْتَشْهِدُونَ بِالْقَتْلِ، وَالطَّاعُونِ، وَالْغَرَقِ، وَالْبَطْنِ، وَمَوْتِ الْمَرْأَةِ جُمْعًا مَوْتُهَا فِي نِفَاسِهَا."],"takhrij":"صحيح: رواه أبو بكر بن أبي شيبة في مسنده (1920-المطالب)، وعنه عبد بن حميد (154)، -ومن طريقه الضياء في المختارة (1031)- والبزار (1191) كلهم من حديث أبي بكر بن حفص بن عمر بن سعد، عن عمر بن سعد، عن أبيه سعد بن أبي وقاص فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الشهداء سوى القتيل في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Bakr ibn Abi Shaybah in his Musnad (1920 — al-Matalib), ʿAbd ibn Humayd (154), through whom al-Diya’ narrated it in al-Mukhtarah (2/225), and al-Bazzar (1191).","chapter_en":"What Has Been Reported Concerning Martyrs Other Than One Killed in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Saʿd ibn Abi Waqqas said: The Messenger of Allah ﷺ said: “Martyrdom is attained through being killed, plague, drowning, stomach illness, and a woman dying while pregnant or in childbirth — that is, her death during postpartum bleeding.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو بكر بن أبي شيبة في مسنده (1920 — المطالب)، وعبد بن حميد (154)، ومن طريقه الضياء في المختارة (1031)، والبزار (1191)."},{"num":8116,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ زَيْدٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ قُتِلَ دُونَ مَالِهِ فَهُوَ شَهِيدٌ، وَمَنْ قُتِلَ دُونَ دِينِهِ فَهُوَ شَهِيدٌ، وَمَنْ قُتِلَ دُونَ دَمِهِ فَهُوَ شَهِيدٌ، وَمَنْ قُتِلَ دُونَ أَهْلِهِ فَهُوَ شَهِيدٌ."],"takhrij":"صحيح: رواه الترمذي (1421) –والسياق له-، وأبو داود (4772)، والنسائي (4094، 4095)، وأحمد (1652) من طرق عن إبراهيم بن سعد بن إبراهيم بن عبد الرحمن، عن أبيه، عن أبي عبيدة بن محمد بن عمار بن ياسر، عن طلحة بن عبد الله بن عوف، عن سعيد بن زيد فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الشهداء سوى القتيل في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1421), whose wording this is, Abu Dawud (4772), al-Nasa’i (4094, 4095), and Ahmad (1652).","chapter_en":"What Has Been Reported Concerning Martyrs Other Than One Killed in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Saʿid ibn Zayd said: I heard the Messenger of Allah ﷺ say: “Whoever is killed defending his wealth is a martyr; whoever is killed defending his religion is a martyr; whoever is killed defending his life is a martyr; and whoever is killed defending his family is a martyr.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (1421) — والسياق له —، وأبو داود (4772)، والنسائي (4094، 4095)، وأحمد (1652)."},{"num":8117,"demo":false,"sanad":"","matn":["8117 - عَنْ عُقْبَةَ بن عَامِرٍ قَالَ: قَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَنْ صُرِعَ عَنْ دَابَّتِهِ فِي سَبِيلِ اللَّهِ فَهُوَ شَهِيدٌ."],"takhrij":"صحيح: رواه ابن أبي عاصم في الجهاد (237)، والطبراني في الكبير (17/ح 892) كلاهما من حديث عبد الله بن وهب، عن عمرو بن الحارث، عن عبيد الله بن أبي جعفر، عن جعفر بن عبد الله ، عن عقبة بن عامر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الشهداء سوى القتيل في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Abi ʿAsim in al-Jihad (237) and al-Tabarani in al-Kabir (17/323).","chapter_en":"What Has Been Reported Concerning Martyrs Other Than One Killed in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["ʿUqbah ibn ʿAmir said: The Messenger of Allah ﷺ said: “Whoever is thrown from his mount in the path of Allah is a martyr.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن أبي عاصم في الجهاد (237)، والطبراني في الكبير (17/ح 892)."},{"num":8118,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عَتِيكٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَاءَ يَعُودُ عَبْدَ اللَّهِ بْنَ ثَابِتٍ فَوَجَدَهُ، قَدْ غُلِبَ عَلَيْهِ، فَصَاحَ بِهِ فَلَمْ يُجِبْهُ، فأسترجع رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: غُلِبْنَا عَلَيْكَ يَا أَبَا الرَّبِيعِ، فَصَاحَ النِّسْوَةُ، وَبَكَيْنَ فَجَعَلَ جَابِرٌ يُسَكِّتُهُنَّ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : دَعْهُنَّ فَإِذَا وَجَبَ فَلاَ تَبْكِيَنَّ بَاكِيَةٌ. قَالُوا: يَا رَسُولَ اللَّهِ وَمَا الْوُجُوبُ؟ قَالَ: إِذَا مَاتَ فَقَالَتِ ابْنَتُهُ وَاللَّهِ إِنْ كُنْتُ لأَرْجُو أَنْ تَكُونَ شَهِيدًا، فَإِنَّكَ كُنْتَ قَدْ قَضَيْتَ جِهَازَكَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّ اللَّهَ قَدْ أَوْقَعَ أَجْرَهُ علي قَدْرِ نِيَّتِهِ، وَمَا تَعُدُّونَ الشَّهَادَةَ؟ قَالُوا: الْقَتْلُ فِي سَبِيلِ اللَّهِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : الشُّهَدَاءُ سَبْعَةٌ سِوَى الْقَتْلِ فِي سَبِيلِ اللَّهِ، الْمَطْعُونُ شَهِيدٌ، وَالْغَرِقُ شَهِيدٌ، وَصَاحِبُ ذَاتِ الْجَنْبِ شَهِيدٌ، وَالْمَبْطُونُ شَهِيدٌ، وَالْحَرِقُ شَهِيدٌ، وَالَّذِي يَمُوتُ تَحْتَ الْهَدْمِ شَهِيدٌ، وَالْمَرْأَةُ تَمُوتُ بِجُمْعٍ شَهِيدٌ."],"takhrij":"حسن: رواه مالك في الجنائز (36) عن عبد الله بن عبد الله بن جابر بن عتيك، عن عتيك بن الحارث –وهو جد عبد الله بن عبد الله بن جابر أبو أمه- انه أخبره أن جابر بن عتيك أخبره فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الشهداء سوى القتيل في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Malik in al-Jana’iz (36).","chapter_en":"What Has Been Reported Concerning Martyrs Other Than One Killed in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Jabir ibn ʿAtik narrated that the Messenger of Allah ﷺ came to visit ʿAbdullah ibn Thabit and found him overcome by death. He called out to him, but he did not respond. The Messenger of Allah ﷺ said, “Indeed we belong to Allah and to Him we return,” and said: “We have been overcome concerning you, O Abu al-Rabiʿ.” The women cried out and wept, and Jabir began silencing them. The Messenger of Allah ﷺ said: “Leave them. But when it becomes certain, no woman should weep.” They said: “O Messenger of Allah, what is ‘when it becomes certain’?” He said: “When he dies.” His daughter said: “By Allah, I had hoped that you would be a martyr, for you had already prepared your equipment.” The Messenger of Allah ﷺ said: “Allah has assigned his reward according to his intention. What do you count as martyrdom?” They said: “Being killed in the path of Allah.” The Messenger of Allah ﷺ said: “The martyrs are seven besides being killed in the path of Allah: the one who dies of plague is a martyr; the one who drowns is a martyr; the one who dies of pleurisy is a martyr; the one who dies of a stomach illness is a martyr; the one who dies by burning is a martyr; the one who dies beneath a collapsed structure is a martyr; and the woman who dies while pregnant or in childbirth is a martyr.”"]},"buhuth":{"en":["“Dhat al-janb” is a hot swelling that occurs in the membrane lining the ribs.","His saying, “you had already prepared your equipment,” means: you had prepared what you needed for your journey to battle."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3588],"tks":"حسن: رواه مالك (36)."},{"num":8119,"demo":false,"sanad":"","matn":["عَنْ رُبَيِّعَ الأنصاري أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَادَ ابْنَ أَخِي جَبْرٌ الْأَنْصَارِيَّ فَجَعَلَ أَهْلُهُ يَبْكُونَ عَلَيْهِ فَقَالَ لَهُمْ جَبْرٌ: لَا تُؤْذُوا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فقا ل رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : دَعْهُنَّ فليبكين مادام حَيًّا فَإِذَا وَجَبَ فَلْيَسْكُتْنَ فَقَالَ بَعْضُهُمْ: مَا كُنَّا نَرَى أَنْ يَكُونَ مَوْتُكَ عَلَى فِرَاشِكَ حَتَّى تُقْتَلَ فِي سَبِيلِ اللَّهِ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. . فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أَوْ مَا الشَّهَادَةُ إِلَّا فِي الْقَتْلِ فِي سَبِيلِ اللَّهِ؟ إِنَّ شُهَدَاءَ أُمَّتِي إذن لَقَلِيلٌ إِنَّ الطَّعْنَ وَالطَّاعُونَ شَهَادَةٌ، وَالْبَطْنَ شَهَادَةٌ، وَالنُّفَسَاءَ بِجُمْعٍ شَهَادَةٌ، وَالْحَرْقَ شَهَادَةٌ، وَالْغَرَقَ شَهَادَةٌ وَالْهَدْمَ شَهَادَةٌ، وَذَاتَ الْجَنْبِ شَهَادَةٌ."],"takhrij":"حسن: رواه الطبراني في الكبير (4607) من طرق عن جرير (هو ابن عبد الحميد)، عن عبد الملك بن عمير، عن الربيع الأنصاري فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الشهداء سوى القتيل في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (5/65).","chapter_en":"What Has Been Reported Concerning Martyrs Other Than One Killed in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Rabiʿ al-Ansari narrated that the Messenger of Allah ﷺ visited the nephew of Jabr al-Ansari. His family began weeping over him, so Jabr said to them: “Do not bother the Messenger of Allah ﷺ.” The Messenger of Allah ﷺ said: “Leave them to weep as long as he is alive. But once it becomes certain, they should be silent.” Some of them said: “We did not think that your death would be on your bed; we expected you to be killed in the path of Allah with the Messenger of Allah ﷺ.” The Messenger of Allah ﷺ said: “Is martyrdom only in being killed in the path of Allah? Then the martyrs of my ummah would be few. Stabbing and plague are martyrdom; stomach illness is martyrdom; the postpartum woman dying while her child is still joined to her is martyrdom; burning is martyrdom; drowning is martyrdom; dying under a collapse is martyrdom; and pleurisy is martyrdom.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (4607)."},{"num":8120,"demo":false,"sanad":"","matn":["عَنْ عُتْبَةَ بْنِ عَبْدٍ السُّلَمِيِّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَأْتِي الشُّهَدَاءُ وَالْمُتَوَفَّوْنَ بِالطَّاعُونِ، فَيَقُولُ أَصْحَابُ الطَّاعُونِ: نَحْنُ شُهَدَاءُ، فَيُقَالُ: انْظُرُوا، فَإِنْ كَانَتْ جِرَاحُهُمْ كَجِرَاحِ الشُّهَدَاءِ تَسِيلُ دَمًا رِيحَ الْمِسْكِ، فَهُمْ شُهَدَاءُ فَيَجِدُونَهُمْ كَذَلِكَ."],"takhrij":"حسن: رواه أحمد (17651) عن الحكم بن نافع، حدثنا إسماعيل بن عياش، عن ضمضم بن زرعة، عن شريح بن عبيد، عن عتبة بن عبد السلمي فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الشهداء سوى القتيل في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (17651).","chapter_en":"What Has Been Reported Concerning Martyrs Other Than One Killed in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["ʿUtbah ibn ʿAbd al-Sulami narrated from the Prophet ﷺ that he said: “The martyrs and those who died of plague will come, and the people of plague will say: ‘We are martyrs.’ It will be said: ‘Look: if their wounds are like the wounds of the martyrs, flowing with blood and smelling of musk, then they are martyrs.’ They will find them to be so.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17651)."},{"num":8121,"demo":false,"sanad":"","matn":["عَنِ الْعِرْبَاضِ بْنِ سَارِيَةَ، قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يَخْتَصِمُ الشُّهَدَاءُ وَالْمُتَوَفَّوْنَ عَلَى فُرُشِهِمْ إِلَى اللَّهِ عَزَّ وَجَلَّ فِي الَّذِينَ مَاتُوا مِنَ الطَّاعُونِ، فَيَقُولُ الشُّهَدَاءُ: إِخْوَانُنَا قُتِلُوا، وَيَقُولُ الْمُتَوَفَّوْنَ عَلَى فُرُشِهِمْ: إِخْوَانُنَا مَاتُوا عَلَى فُرُشِهِمْ كَمَا مِتْنَا، فَيَقْضِي اللَّهُ عَزَّ وَجَلَّ بَيْنَهُمْ: أَنْ انْظُرُوا إِلَى جِرَاحَاتِ الْمَطْعُونِينَ، فَإِنْ أَشْبَهَتْ جِرَاحَاتِ الشُّهَدَاءِ، فَهُمْ مِنْهُمْ، فَيَنْظُرُونَ إِلَى جِرَاحِ الْمَطْعُونِينَ، فَإِذَا هِيَ قَدْ أَشْبَهَتْ، فَيُلْحَقُونَ مَعَهُمْ."],"takhrij":"حسن: رواه أحمد (17164) عن أبي اليمان، حدثنا إسماعيل بن عياش، عن بحير بن سعد، عن خالد بن معدان، عن ابن أبي بلال، عن العرباض بن سارية قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الشهداء سوى القتيل في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (17164).","chapter_en":"What Has Been Reported Concerning Martyrs Other Than One Killed in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Al-ʿIrbad ibn Sariyah said: I heard the Messenger of Allah ﷺ say: “The martyrs and those who died on their beds will dispute before Allah, Mighty and Majestic, concerning those who died of plague. The martyrs will say: ‘Our brothers were killed.’ Those who died on their beds will say: ‘Our brothers died on their beds just as we died.’ Allah will judge between them: ‘Look at the wounds of those who died of plague. If they resemble the wounds of the martyrs, then they are from them.’ They will look at the wounds of those who died of plague, and behold, they resemble the wounds of the martyrs, so they will be joined with them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17164)."},{"num":8122,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ، قَالَ: عَادَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَعْدَ بْنَ عُبَادَةَ فَقَالَ: مَا تَعُدُّونَ الشُّهَدَاءَ مِنْ أُمَّتِي؟ قَالَ: قَالَ ذَلِكَ ثَلَاثًا، قُلْنَا: اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ سَعْدُ بْنُ عُبَادَةَ: [إِنْ شَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَذِنَ لِي فَأَخْبَرْتُهُ] مَنِ الشُّهَدَاءُ مِنْ أُمَّتِهِ، قَالَ: فَأَخْبِرْنِي مَنِ الشُّهَدَاءُ مِنْ أُمَّتِي؟ قَالَ: أَسْنِدُونِي، فَأَسْنَدُوهُ، فَقَالَ: مَنْ آمَنَ بِاللَّهِ وَجَاهَدَ فِي سَبِيلِ اللَّهِ وَقَاتَلَ حَتَّى قُتِلَ فَهُوَ شَهِيدٌ، قَالَ: إِنَّ شُهَدَاءَ أُمَّتِي إِذَا لَقَلِيلٌ، الْقَتِيلُ فِي سَبِيلِ اللَّهِ شَهِيدٌ، [وَالْمَبْطُونُ شَهِيدٌ، وَالْمَطْعُونُ شَهِيدٌ]، وَالْغَرِيقُ شَهِيدٌ، وَالنُّفَسَاءُ شَهِيدٌ."],"takhrij":"حسن: رواه الطبراني في مسند الشاميين (1508) –ومن طريقه الضياء في المختارة (70)- عن هاشم بن مرثد الطبراني، ثنا أبو صالح الفراء، ثنا أبو إسحاق الفزاري، عن الأوزاعي، عن العلاء بن الحارث، عن عبد الله بن بسر قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الشهداء سوى القتيل في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in Musnad al-Shamiyyin (1508), and through him by al-Diya’ in al-Mukhtarah (9/87).","chapter_en":"What Has Been Reported Concerning Martyrs Other Than One Killed in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullah ibn Busr al-Mazini said: The Messenger of Allah ﷺ visited Saʿd ibn ʿUbadah and said: “Whom do you count as martyrs from my ummah?” He said this three times. We said: “Allah and His Messenger know best.” Saʿd ibn ʿUbadah said: “If the Messenger of Allah ﷺ permits me, I will inform him who the martyrs of his ummah are.” He said: “Then inform me: who are the martyrs of my ummah?” He said: “Support me.” So they supported him, and he said: “Whoever believes in Allah, strives in the path of Allah, and fights until he is killed is a martyr.” He said: “Then the martyrs of my ummah would be few. The one killed in the path of Allah is a martyr; the one who dies of a stomach illness is a martyr; the one who dies of plague is a martyr; the one who drowns is a martyr; and the postpartum woman is a martyr.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في مسند الشاميين (1508)، ومن طريقه الضياء في المختارة (70)."},{"num":8123,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَادَ عَبْدَ اللَّهِ بْنَ رَوَاحَةَ، فَمَا تَحَوَّزَ لَهُ عَنْ فِرَاشِهِ، فَقَالَ: أَتَدْرُونَ مَنْ شُهَدَاءُ أُمَّتِي؟ قَالُوا: قَتْلُ الْمُسْلِمِ شَهَادَةٌ، قَالَ: إِنَّ شُهَدَاءَ أُمَّتِي إِذًا لَقَلِيلٌ، قَتْلُ الْمُسْلِمِ شَهَادَةٌ، وَالطَّاعُونُ شَهَادَةٌ، وَالْمَرْأَةُ يَقْتُلُهَا وَلَدُهَا جَمْعَا."],"takhrij":"صحيح: رواه أحمد (17797، 22756، 22684)، والطيالسي (583) من طرق عن شعبة، عن أبي بكر بن حفص (وهو عبد الله بن حفص بن عمر الزهري) قال: سمعت أبا مصبّح- أو ابن مصبح شكَّ أبو بكر- عن شرحبيل بن السمط، عن عبادة بن الصامت فذكره. والسياق لأحمد. وزاد الطيالسي: والبطن شهادة.","grade":"صحيح","chapter_ar":"باب ما جاء في الشهداء سوى القتيل في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (17797, 22684, 22756) and al-Tayalisi (583). The wording is Ahmad’s; al-Tayalisi additionally has: “and stomach illness is martyrdom.”","chapter_en":"What Has Been Reported Concerning Martyrs Other Than One Killed in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["ʿUbadah ibn al-Samit said: The Messenger of Allah ﷺ visited ʿAbdullah ibn Rawahah, and he did not move aside for him from his bed. He said: “Who are the martyrs of my ummah?” They said: “A Muslim being killed is martyrdom.” He said: “Then the martyrs of my ummah would be few. A Muslim being killed is martyrdom; plague is martyrdom; stomach illness and drowning; and a woman whose child kills her while still joined to her.”"]},"buhuth":{"en":["His saying, “he did not move aside,” means: he did not shift away. His saying, “jamʿan,” with dammah on the jim and sukun on the mim, means while the child is still joined to her; that is, she dies while the child is in her womb."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (17797، 22684، 22756)، والطيالسي (583). والسياق لأحمد، وزاد الطيالسي: ((والبطن شهادة))."},{"num":8124,"demo":false,"sanad":"","matn":["أَنَّ أَبَا مَالِكٍ الأَشْعَرِيَّ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ فَصَلَ فِي سَبِيلِ اللَّهِ فَمَاتَ أَوْ قُتِلَ فَهُوَ شَهِيدٌ أَوْ وَقَصَهُ فَرَسُهُ أَوْ بَعِيرُهُ أَوْ لَدَغَتْهُ هَامَّةٌ أَوْ مَاتَ عَلَى فِرَاشِهِ، أَوْ بِأَىِّ حَتْفٍ شَاءَ اللَّهُ، فَإِنَّهُ شَهِيدٌ، وَإِنَّ لَهُ الْجَنَّةَ."],"takhrij":"حسن: رواه أبو داود ( 2499)، والحاكم (2416)، والبيهقي (18537)، وابن أبي عاصم في الجهاد (54، 235) كلهم من حديث عبد الوهاب بن نجدة حدثنا بقية بن الوليد قال: حدثنا عبد الرحمن بن ثوبان، عن أبيه يرده إلى مكحول إلى عبد الرحمن بن غنم الأشعرى، أن أبا مالك الأشعرى قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الشهداء سوى القتيل في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2499), al-Hakim (2416), al-Bayhaqi (9/166), and Ibn Abi ʿAsim in al-Jihad (54, 235).","chapter_en":"What Has Been Reported Concerning Martyrs Other Than One Killed in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Abu Malik al-Ashʿari said: I heard the Messenger of Allah ﷺ say: “Whoever sets out in the path of Allah and then dies or is killed is a martyr; or his horse or camel throws him and breaks his neck; or a venomous creature bites him; or he dies on his bed by whatever death Allah wills, he is a martyr, and Paradise is his.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2499)، والحاكم (2416)، والبيهقي (18537)، وابن أبي عاصم في الجهاد (54، 235)."},{"num":8125,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ زِيَادٍ الْأَلْهَانِيِّ، قَالَ: ذُكِرَ عِنْدَ أَبِي عِنَبَةَ الْخَوْلَانِيِّ الشُّهَدَاءُ، فَذَكَرُوا الْمَبْطُونَ، وَالْمَطْعُونَ، وَالنُّفَسَاءَ، فَغَضِبَ أَبُو عِنَبَةَ، وَقَالَ: حَدَّثَنَا أَصْحَابُ نَبِيِّنَا عَنْ نَبِيِّنَا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: إِنَّ شُهَدَاءَ اللَّهِ فِي الْأَرْضِ، أُمَنَاءُ اللهِ فِي الْأَرْضِ مِنْ خَلْقِهِ، قُتِلُوا أَوْ مَاتُوا."],"takhrij":"حسن: رواه أحمد (17786) عن أبي اليمان قال: حدثنا إسماعيل بن عياش، عن محمد بن زياد الألهاني فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الشهداء سوى القتيل في سبيل الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (17786).","chapter_en":"What Has Been Reported Concerning Martyrs Other Than One Killed in the Path of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الشهداء وأحكام الشهادة","group_en":"Collection of What Has Been Narrated Concerning Martyrs and the Rulings of Martyrdom","part_no":43,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Muhammad ibn Ziyad al-Alhani said: Martyrs were mentioned in the presence of Abu ʿAnabah al-Khawlani, and they mentioned the one who dies of stomach illness, the one who dies of plague, and the postpartum woman. Abu ʿAnabah became angry and said: The companions of our Prophet narrated to us from our Prophet ﷺ that he said: “The martyrs of Allah on earth are Allah’s trustees on earth among His creation, whether they are killed or die.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17786)."},{"num":8126,"demo":false,"sanad":"","matn":["عَنْ أَبِي فاطمة قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ: حَدِّثْنِي بِعَمَلٍ أَسْتَقِيمُ عَلَيْهِ، وَأَعْمَلُهُ. قَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : عَلَيْكَ بِالْهِجْرَةِ فَإِنَّهُ لاَ مِثْلَ لَهَا."],"takhrij":"حسن: رواه النسائي (4167) عن هارون بن محمد بن بكار بن بلال، عن محمد (وهو ابن عيسى بن سميع) قال: حدثنا زيد بن واقد، عن كثير بن مرة أن أبا فاطمة حدثه، أنه قال: يار سول الله ... فذكر الحديث.","grade":"حسن","chapter_ar":"باب الحث على الهجرة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4167).","chapter_en":"Encouragement to Migrate","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Abu Fatimah said: I said: “O Messenger of Allah, tell me of a deed that I may remain steadfast upon and do.” The Messenger of Allah ﷺ said to him: “Hold fast to migration, for there is nothing like it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (4167)."},{"num":8127,"demo":false,"sanad":"","matn":["عن خبّاب قَالَ: هَاجَرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبْتَغِي وَجْهَ اللَّهِ، وَوَجَبَ أَجْرُنَا عَلَى اللَّهِ، فَمِنَّا مَنْ مَضَى لَمْ يَأْكُلْ مِنْ أَجْرِهِ شَيْئًا، مِنْهُمْ مُصْعَبُ بْنُ عُمَيْرٍ، قُتِلَ يَوْمَ أُحُدٍ، فَلَمْ نَجِدْ شَيْئًا نُكَفِّنُهُ فِيهِ، إِلاَّ نَمِرَةً، كُنَّا إِذَا غَطَّيْنَا بِهَا رَأْسَهُ خَرَجَتْ رِجْلاَهُ، فَإِذَا غَطَّيْنَا رِجْلَيْهِ خَرَجَ رَأْسُهُ، فَأَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نُغْطِيَ رَأْسَهُ بِهَا، وَنَجْعَلَ عَلَى رِجْلَيْهِ مِنْ إِذْخِرٍ، وَمِنَّا مَنْ أَيْنَعَتْ لَهُ ثَمَرَتُهُ فَهْوَ يَهْدِبُهَا."],"takhrij":"صحيح: رواه البخاري في المناقب (3914) عن مسدد، حدثنا يحيى، عن الأعمش، قال: سمعت شقيق بن سلمة، قال: حدثنا خبّاب قال: فذكره.","grade":"صحيح","chapter_ar":"باب الهجرة لوجه الله","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3914).","chapter_en":"Migration for the Sake of Allah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":2,"content":{"translation":{"en":["Khabbab said: We migrated with the Messenger of Allah ﷺ seeking the Face of Allah, and our reward became due upon Allah. Some of us passed away without consuming anything from his reward; among them was Musʿab ibn ʿUmayr. He was killed on the day of Uhud, and we found nothing to shroud him in except a striped cloak. When we covered his head with it, his feet were exposed, and when we covered his feet, his head was exposed. So the Messenger of Allah ﷺ ordered us to cover his head with it and place idhkhir grass over his feet. And among us are those whose fruits ripened for them, and they are harvesting them."]},"buhuth":{"en":["His saying, “yahdibuha,” comes from “hadb,” meaning to harvest or gather fruit."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (3914)."},{"num":8128,"demo":false,"sanad":"","matn":["عن أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَهُ عَنِ الْهِجْرَةِ فَقَالَ: وَيْحَكَ إِنَّ الْهِجْرَةَ شَأْنُهَا شَدِيدٌ، فَهَلْ لَكَ مِنْ إِبِلٍ. قَالَ: نَعَمْ. قَالَ: فَتُعْطِي صَدَقَتَهَا. قَالَ: نَعَمْ. قَالَ: فَهَلْ تَمْنَحُ مِنْهَا. قَالَ: نَعَمْ. قَالَ: فَتَحْلُبُهَا يَوْمَ وُرُودِهَا. قَالَ: نَعَمْ. قَالَ: فَاعْمَلْ مِنْ وَرَاءِ الْبِحَارِ، فَإِنَّ اللَّهَ لَنْ يَتِرَكَ مِنْ عَمَلِكَ شَيْئًا."],"takhrij":"متفق عليه: رواه البخاري في مناقب الأنصار (3923)، ومسلم في الإمارة (1865) كلاهما من طريق الوليد بن مسلم حدثنا الأوزاعي عن الزهري، عن عطاء بن يزيد الليثي، عن أبي سعيد فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب أن شأن الهجرة شديد","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3923) and Muslim (1865). The wording is al-Bukhari’s.","chapter_en":"Migration Is a Serious Matter","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":3,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: A Bedouin came to the Prophet ﷺ and asked him about migration. He said: “Woe to you! Migration is a serious matter. Do you own camels?” He said: “Yes.” He said: “Do you give their charity?” He said: “Yes.” He said: “Do you lend some of them for milk?” He said: “Yes.” He said: “Do you milk them on the day they come to water?” He said: “Yes.” He said: “Then do good deeds even from beyond the seas, for Allah will never leave anything of your deeds unrewarded.”"]},"buhuth":{"en":["His saying, “do deeds from beyond the seas,” is an emphatic way of informing him that his deeds will not be wasted wherever he may be. Fath al-Bari (7/259)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3923)، ومسلم (1865). واللفظ للبخاري."},{"num":8129,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، قَالَ: قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ! أَىُّ الْهِجْرَةِ أَفْضَلُ؟ قَالَ: أَنْ تَهْجُرَ مَا كَرِهَ رَبُّكَ عَزَّ وَجَلَّ. وَقَالَ: رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْهِجْرَةُ هِجْرَتَانِ، هِجْرَةُ الْحَاضِرِ وَهِجْرَةُ الْبَادِي. فَأَمَّا الْبَادِي فَيُجِيبُ إِذَا دُعِيَ، وَيُطِيعُ إِذَا أُمِرَ، وَأَمَّا الْحَاضِرُ فَهُوَ أَعْظَمُهُمَا بَلِيَّةً، وَأَعْظَمُهُمَا أَجْرًا."],"takhrij":"صحيح: رواه النسائي (4165) وصحّحه ابن حبان (4863) كلاهما من حديث عمرو بن مرة، عن عبد الله بن الحارث، عن أبي كثير الزبيدي، عن عبد الله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب هجرة الحاضر أفضل من هجرة البادي","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4165), and authenticated by Ibn Hibban (4863).","chapter_en":"The Migration of the Settled Person Is Better Than the Migration of the Desert-Dweller","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr said: A man said: “O Messenger of Allah, which migration is best?” He said: “That you abandon what your Lord, Mighty and Majestic, dislikes.” The Messenger of Allah ﷺ said: “Migration is of two kinds: the migration of the settled person and the migration of the desert-dweller. As for the desert-dweller, he responds when called and obeys when commanded. As for the settled person, it is greater in trial and greater in reward.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (4165)، وصححه ابن حبان (4863)."},{"num":8130,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ، رَضِيَ اللَّهُ عَنْهُ قَالَ كَانَ فَرَضَ لِلْمُهَاجِرِينَ الأَوَّلِينَ أَرْبَعَةَ آلاَفٍ فِي أَرْبَعَةٍ، وَفَرَضَ لاِبْنِ عُمَرَ ثَلاَثَةَ آلاَفٍ وَخَمْسَمِائَةٍ فَقِيلَ لَهُ: هُوَ مِنَ الْمُهَاجِرِينَ، فَلِمَ نَقَصْتَهُ مِنْ أَرْبَعَةِ آلاَفٍ؟ فَقَالَ: إِنَّمَا هَاجَرَ بِهِ أَبَوَاهُ. يَقُولُ: لَيْسَ هُوَ كَمَنْ هَاجَرَ بِنَفْسِهِ."],"takhrij":"صحيح: رواه البخاري في المناقب (3912) عن إبراهيم بن موسى، أخبرنا هشام (ابن يوسف الصنعاني) عن ابن جريج قال: أخبرني عبيد الله بن عمر، عن نافع، يعني عن ابن عمر، عن عمر بن الخطاب فذكره.","grade":"صحيح","chapter_ar":"باب من هاجر مع أبويه ليس كمن هاجر بنفسه","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3912).","chapter_en":"One Who Migrated with His Parents Is Not Like One Who Migrated by Himself","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["ʿUmar ibn al-Khattab had assigned four thousand to the earliest Muhajirun in four installments, and he assigned three thousand five hundred to Ibn ʿUmar. It was said to him: “He is among the Muhajirun, so why did you reduce him from four thousand?” He said: “His parents only brought him in migration.” Meaning: he is not like one who migrated by himself."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3912)."},{"num":8131,"demo":false,"sanad":"","matn":["عَنْ مجاشع بن مَسْعُودٍ السلمي قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَخِي بَعْدَ الْفَتْحِ، قُلْتُ: يَا رَسُولَ اللَّهِ، جِئْتُكَ بِأَخِي لِتُبَايِعَهُ عَلَى الْهِجْرَةِ، قَالَ: ذَهَبَ أَهْلُ الْهِجْرَةِ بِمَا فِيهَا فَقُلْتُ: عَلَى أي شيء تُبَايِعُهُ؟ قَالَ: أُبَايِعُهُ عَلَى الإِسْلاَمِ، وَالإِيمَانِ، وَالْجِهَادِ فَلَقِيتُ أَبَا مَعْبَدٍ بَعْدُ، وَكَانَ أَكْبَرَهُمَا، فَسَأَلْتُهُ فَقَالَ: صَدَقَ مُجَاشِعٌ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4306،4305) ومسلم في الإمارة (84:1863) كلاهما من طرق عن عاصم بن سليمان الأحول، عن أبي عثمان النهدي، قال: أخبرني مجاشع بن مسعود السلمي قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب لا هجرة بعد فتح مكة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4305, 4306) and Muslim (1863:84).","chapter_en":"There Is No Migration After the Conquest of Makkah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":6,"content":{"translation":{"en":["Mujashiʿ ibn Masʿud al-Sulami said: I came to the Prophet ﷺ with my brother after the Conquest. I said: “O Messenger of Allah, I have brought my brother to you so that you may accept his pledge for migration.” He said: “The people of migration have gone with what it contains.” I said: “Then upon what will you accept his pledge?” He said: “I will accept his pledge upon Islam, faith, and jihad.” Later I met Abu Maʿbad, who was the older of the two, and asked him, and he said: “Mujashiʿ spoke the truth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4305، 4306)، ومسلم (84:1863)."},{"num":8132,"demo":false,"sanad":"","matn":["عَنْ مُجَاشِعِ بْنِ مَسْعُودٍ، أَنَّهُ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِابْنِ أَخٍ لَهُ، يُبَايِعُهُ عَلَى الْهِجْرَةِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا، بَلْ يُبَايِعُ عَلَى الْإِسْلَامِ، فَإِنَّهُ، لَا هِجْرَةَ بَعْدَ الْفَتْحِ، وَيَكُونُ مِنَ التَّابِعِينَ بِإِحْسَانٍ."],"takhrij":"صحيح: رواه أحمد (15847) وابن أبي عاصم في الآحاد والمثاني (1404) والطبراني في الكبير (20/768) كلهم من طريق أبي معاوية – يعني شيبان، عن يحيى بن أبي كثير، عن يحيى بن إسحاق، عن مجاشع بن مسعود فذكره.","grade":"صحيح","chapter_ar":"باب لا هجرة بعد فتح مكة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (15847), Ibn Abi ʿAsim in al-Ahad wa al-Mathani (1404), and al-Tabarani in al-Kabir (20/768).","chapter_en":"There Is No Migration After the Conquest of Makkah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":6,"content":{"translation":{"en":["Mujashiʿ ibn Masʿud brought a nephew of his to the Prophet ﷺ so that he might pledge allegiance for migration. The Messenger of Allah ﷺ said: “No; rather, he pledges allegiance upon Islam, for there is no migration after the Conquest, and he will be among those who follow in goodness.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (15847)، وابن أبي عاصم في الآحاد والمثاني (1404)، والطبراني في الكبير (20/768)."},{"num":8133,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ فَتْحِ مَكَّةَ: لاَ هِجْرَةَ، وَلَكِنْ جِهَادٌ وَنِيَّةٌ، وَإِذَا اسْتُنْفِرْتُمْ فَانْفِرُوا."],"takhrij":"متفق عليه: رواه البخاري في الجهاد (3077) ومسلم في الإمارة (85:1353) كلاهما من حديث منصور، عن مجاهد، عن طاوس، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب لا هجرة بعد فتح مكة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3077) and Muslim (1353:85).","chapter_en":"There Is No Migration After the Conquest of Makkah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":6,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ said on the day of the Conquest, the Conquest of Makkah: “There is no migration, but there is jihad and intention. And when you are called to mobilize, then go forth.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3077)، ومسلم (85:1353)."},{"num":8134,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْهِجْرَةِ؟ فَقَالَ: لَا هِجْرَةَ بَعْدَ الْفَتْحِ، وَلَكِنْ جِهَادٌ وَنِيَّةٌ، وَإِذَا اسْتُنْفِرْتُمْ فَانْفِرُوا."],"takhrij":"صحيح: رواه مسلم في الإمارة (86:1864) عن محمد بن عبد الله بن نمير، حدثنا أبي، حدثنا عبد الله بن حبيب بن أبي ثابت، عن عبد الله بن عبدالرحمن بن أبي حسين، عن عطاء، عن عائشة قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب لا هجرة بعد فتح مكة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1864:86).","chapter_en":"There Is No Migration After the Conquest of Makkah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":6,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ was asked about migration, and he said: “There is no migration after the Conquest, but there is jihad and intention. And when you are called to mobilize, then go forth.”"]}},"tuhfa":{},"full":1,"rep":[7805],"tks":"صحيح: رواه مسلم (86:1864)."},{"num":8135,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده قال: قال رسول الله صلى الله عليه وسلم لما فتحت مكة: لا هجرة بعد الفتح، ولا شغار في الإسلام."],"takhrij":"حسن: رواه أبو داود (2751،1591) والترمذي (1413) والنسائي (4806) وابن ماجة (2959) وأحمد (7012) وصحّحه ابن خزيمة (2280) كلهم من حديث عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب لا هجرة بعد فتح مكة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2751, 1591), al-Tirmidhi (1413), al-Nasa’i (4806), Ibn Majah (2959), Ahmad (7012), and authenticated by Ibn Khuzaymah (2280).","chapter_en":"There Is No Migration After the Conquest of Makkah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":6,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather, who said: When Makkah was conquered, the Messenger of Allah ﷺ said: “There is no migration after the Conquest, and there is no shighar marriage in Islam.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2751، 1591)، والترمذي (1413)، والنسائي (4806)، وابن ماجه (2959)، وأحمد (7012)، وصححه ابن خزيمة (2280)."},{"num":8136,"demo":false,"sanad":"","matn":["عَنْ صَفْوَانَ بْنِ أُمَيَّةَ، أَنَّهُ قِيلَ لَهُ: لَا يَدْخُلُ الْجَنَّةَ إِلَّا مَنْ هَاجَرَ، قَالَ: فَقُلْتُ: لَا أَدْخُلُ مَنْزِلِي، حَتَّى آتِيَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَسْأَلَهُ، فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ هَذَا سَرَقَ خَمِيصَةً لِي لِرَجُلٍ مَعَهُ، فَأَمَرَ بِقَطْعِهِ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، فَإِنِّي قَدْ وَهَبْتُهَا لَهُ، قَالَ: فَهَلَّا قَبْلَ أَنْ تَأْتِيَنِي بِهِ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّهُمْ يَقُولُونَ: لَا يَدْخُلُ الْجَنَّةَ إِلَّا مَنْ هَاجَرَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا هِجْرَةَ بَعْدَ فَتْحِ مَكَّةَ، وَلَكِنْ جِهَادٌ وَنِيَّةٌ، فَإِذَا اسْتُنْفِرْتُمْ فَانْفِرُوا."],"takhrij":"صحيح: رواه النسائي (4169) وأحمد (15306) كلاهما من حديث وهيب، حدثنا ابن طاوس، عن أبيه، عن صفوان بن أمية فذكره واللفظ لأحمد، ولفظ النسائي مختصر.","grade":"صحيح","chapter_ar":"باب لا هجرة بعد فتح مكة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4169) and Ahmad (15306).","chapter_en":"There Is No Migration After the Conquest of Makkah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":6,"content":{"translation":{"en":["Safwan ibn Umayyah was told: “No one will enter Paradise except one who migrated.” He said: So I said: “I will not enter my house until I come to the Messenger of Allah ﷺ and ask him.” I came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, this man stole a cloak of mine from a man with him,” so he ordered that his hand be cut. I said: “O Messenger of Allah, I have given it to him as a gift.” He said: “Why did you not do so before bringing him to me?” I said: “O Messenger of Allah, they say that no one will enter Paradise except one who migrated.” The Messenger of Allah ﷺ said: “There is no migration after the Conquest of Makkah, but there is jihad and intention. And when you are called to mobilize, then go forth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (4169)، وأحمد (15306)."},{"num":8137,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: أتى نفرٌ من أهل البادية إلى رسول الله صلى الله عليه وسلم، فقالوا : يا رسول الله، إنَّ أهل قرانا زعموا أنه لا ينفع عمل دون الهجرة، والجهاد في سبيل الله، فقال رسول الله صلى الله عليه وسلم: حيث ما كنتم فأحسنتم عبادة الله، فأبشروا بالجنة."],"takhrij":"حسن: رواه الدولابي في الكنى (2/557) عن إسحاق بن سويد الرملي قال: حدثنا ابن أبي أويس قال: حدثني يحيى بن عمير أبو زكريا البزاز مولى نوفل بن عدي بن نوفل بن أسد، أنه سمع سعيد بن أبي سعيد المقبري، يحدث عن أبيه ، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب لا هجرة بعد فتح مكة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by al-Dulabi in al-Kuna (2/557).","chapter_en":"There Is No Migration After the Conquest of Makkah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: A group of desert people came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, the people of our villages claim that no deed benefits without migration and jihad in the path of Allah.” The Messenger of Allah ﷺ said: “Wherever you are, if you worship Allah well, then receive glad tidings of Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الدولابي في الكنى (2/557)."},{"num":8138,"demo":false,"sanad":"","matn":["عَنْ غَزِيَّةَ بْنِ الْحَارِثِ، أَنَّهُ أَخْبَرَهُ أَنَّ شَبَابًا مِنْ قُرَيْشٍ أَرَادُوا أَنْ يُهَاجِرُوا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَمَنَعَهُمْ آبَاؤُهُمْ، فَذَكَرُوا ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا هِجْرَةَ بَعْدَ الْفَتْحِ، إِنَّمَا هُوَ الْحَشْرُ، وَالنِّيَّةُ، وَالْجِهَادُ."],"takhrij":"صحيح: رواه سعيد بن منصور في سننه (2353) عن عبد الله بن وهب، قال: أخبرني عمرو بن الحارث أن ابن أبي هلال حدثه عن يزيد بن خصيفة عن عبد الله بن رافع، عن غزية فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب لا هجرة بعد فتح مكة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Saʿid ibn Mansur in his Sunan (2353).","chapter_en":"There Is No Migration After the Conquest of Makkah","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":6,"content":{"translation":{"en":["Ghaziyyah ibn al-Harith reported that some youths from Quraysh wanted to migrate to the Messenger of Allah ﷺ, but their fathers prevented them. They mentioned that to the Messenger of Allah ﷺ, and the Messenger of Allah ﷺ said: “There is no migration after the Conquest; rather, there is gathering, intention, and jihad.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه سعيد بن منصور في سننه (2353)."},{"num":8139,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ حُمَيْدٍ،  أَنَّهُ سَمِعَ عُمَرَ بْنَ عَبْدِ الْعَزِيزِ يَسْأَلُ السَّائِبَ بْنَ يَزِيدَ يَقُولُ: هَلْ سَمِعْتَ فِي الْإِقَامَةِ بِمَكَّةَ شَيْئًا؟ فَقَالَ السَّائِبُ: سَمِعْتُ الْعَلَاءَ بْنَ الْحَضْرَمِيِّ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لِلْمُهَاجِرِ إِقَامَةُ ثَلَاثٍ بَعْدَ الصَّدَرِ. بِمَكَّةَ، كَأَنَّهُ يَقُولُ: لَا يَزِيدُ عَلَيْهَا."],"takhrij":"متفق عليه: رواه البخاري في مناقب الأنصار (3933)، ومسلم في الحج (1352) كلاهما من طرق عن حميد بن عبد الرحمن فذكره.","grade":"متفق عليه","chapter_ar":"باب جواز إقامة المهاجرين من مكة بعد قضاء نسكه لمدة ثلاثة أيام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3933) and Muslim (1352).","chapter_en":"The Permissibility of the Migrants from Makkah Staying There for Three Days After Completing Their Rituals","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":7,"content":{"translation":{"en":["ʿAbd al-Rahman ibn Humayd heard ʿUmar ibn ʿAbd al-ʿAziz asking al-Sa’ib ibn Yazid: “Have you heard anything about staying in Makkah?” Al-Sa’ib said: I heard al-ʿAla’ ibn al-Hadrami say: I heard the Messenger of Allah ﷺ say: “The migrant may stay three days after departure.” It is as though he meant: he may not exceed that."]},"buhuth":{"en":["His saying, “after departure,” means after returning from Mina. This is specific to the migrants from Makkah to Medina, because the time of the Prophet ﷺ was the time of jihad and the establishment of the Islamic state."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3933)، ومسلم (1352)."},{"num":8140,"demo":false,"sanad":"","matn":["عن جُنَادَةَ بْنِ أَبِي أُمَيَّةَ حدث حَدَّثَهُ، أَنَّ رِجَالًا مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ بَعْضُهُمْ: إِنَّ الْهِجْرَةَ قَدِ انْقَطَعَتْ، فَاخْتَلَفُوا فِي ذَلِكَ، قَالَ: فَانْطَلَقْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ أُنَاسًا يَقُولُونَ: إِنَّ الْهِجْرَةَ قَدِ انْقَطَعَتْ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الْهِجْرَةَ لَا تَنْقَطِعُ مَا كَانَ الْجِهَادُ."],"takhrij":"صحيح: رواه أحمد (16597) عن حجاج، حدثنا ليث (ابن سعد) حدثني يزيد بن أبي حبيب، عن أبي الخير، عن جنادة بن أبي أمية فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب لا تنقطع الهجرة من دار الكفر إلى دار الإسلام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (16597).","chapter_en":"Migration from the Abode of Disbelief to the Abode of Islam Does Not Cease","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":8,"content":{"translation":{"en":["Junadah ibn Abi Umayyah narrated that some men from the companions of the Messenger of Allah ﷺ said: “Migration has ceased.” They differed about that. He said: So I went to the Messenger of Allah ﷺ and said: “O Messenger of Allah, some people say that migration has ceased.” The Messenger of Allah ﷺ said: “Migration does not cease as long as jihad remains.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أحمد (16597)."},{"num":8141,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن السعدي – رجل من بَنِي مالك بن حسْل – أَنَّهُ قَدِمَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَاسٍ مِنْ أَصْحَابِهِ فَقَالُوا لَهُ: احْفَظْ رِحَالَنَا، ثُمَّ تَدْخُلُ، وَكَانَ أَصْغَرَ الْقَوْمِ، فَقَضَى لَهُمْ حَاجَتَهُمْ ثُمَّ قَالُوا لَهُ: ادْخُلْ فَدَخَلَ، فَقَالَ: حَاجَتُكَ؟ قَالَ: حَاجَتِي تُحَدِّثُنِي: انقضت الْهِجْرَةُ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : حَاجَتُكَ خَيْرٌ مِنْ حَوَائِجِهِمْ، لَا تَنْقَطِعُ الْهِجْرَةُ مَا قُوتِلَ الْعَدُوُّ."],"takhrij":"صحيح: رواه أحمد (22324) والبيهقي (17779) وصحّحه ابن حبان (4866) كلهم من حديث عبد الله بن محيريز، عن عبد الله بن السعدي فذكره.","grade":"صحيح","chapter_ar":"باب لا تنقطع الهجرة من دار الكفر إلى دار الإسلام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (22324), al-Bayhaqi (9/17–18), and authenticated by Ibn Hibban (4866).","chapter_en":"Migration from the Abode of Disbelief to the Abode of Islam Does Not Cease","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":8,"content":{"translation":{"en":["ʿAbdullah ibn al-Saʿdi — a man from Banu Malik ibn Hisl — came to the Prophet ﷺ with a group of his companions. They said to him: “Watch our belongings, then enter,” and he was the youngest of the group. The Prophet fulfilled their needs, then they said to him: “Enter.” So he entered, and the Prophet ﷺ said: “What is your need?” He said: “My need is that you tell me: has migration ended?” The Prophet ﷺ said: “Your need is better than their needs. Migration does not cease as long as the enemy is fought.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (22324)، والبيهقي (17779)، وصححه ابن حبان (4866)."},{"num":8142,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن السعدي أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا تَنْقَطِعُ الْهِجْرَةُ مَا دَامَ الْعَدُوُّ يُقَاتَلُ فَقَالَ مُعَاوِيَةُ وَعَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ، وَعَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  إِنَّ الْهِجْرَةَ خَصْلَتَانِ: إِحْدَاهُمَا أَنْ تَهْجُرَ السَّيِّئَاتِ، وَالْأُخْرَى أَنْ تُهَاجِرَ إِلَى اللَّهِ وَرَسُولِهِ، وَلا تَنْقَطِعُ الْهِجْرَةُ مَا تُقُبِّلَتِ التَّوْبَةُ، وَلا تَزَالُ التَّوْبَةُ مَقْبُولَةً حَتَّى تَطْلُعَ الشَّمْسُ مِنَ المَغْرِبِ، فَإِذَا طَلَعَتْ طُبِعَ عَلَى كُلِّ قَلْبٍ بِمَا فِيهِ. وَكُفِيَ النَّاسُ عن الْعَمَلَ."],"takhrij":"حسن: رواه أحمد (1671) عن الحكم بن نافع، حدثنا إسماعيل بن عياش، عن ضمضم بن زرعة، عن شريح بن عبيد، يرده إلى مالك بن يخامر عن ابن السعدي فذكره.","grade":"حسن","chapter_ar":"باب لا تنقطع الهجرة من دار الكفر إلى دار الإسلام","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (1671).","chapter_en":"Migration from the Abode of Disbelief to the Abode of Islam Does Not Cease","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":8,"content":{"translation":{"en":["ʿAbdullah ibn al-Saʿdi narrated that the Prophet ﷺ said: “Migration does not cease as long as the enemy continues to fight.” Muʿawiyah, ʿAbd al-Rahman ibn ʿAwf, and ʿAbdullah ibn ʿAmr ibn al-ʿAs said that the Prophet ﷺ said: “Migration has two qualities: one is to abandon evil deeds, and the other is to migrate to Allah and His Messenger. Migration does not cease as long as repentance is accepted, and repentance will continue to be accepted until the sun rises from the west. When it rises, every heart will be sealed upon what is in it, and people will be sufficed from deeds.”"]},"buhuth":{"en":["Benefit:","Muslims who live in the lands of the disbelievers and are unable to perform the obligations and duties must migrate from them, as happened in the previous century when the communists took control of the Soviet Union and prohibited religious rites and recitation of the Qur’an. Migration became obligatory upon them due to the statement of Allah Most High:","“Indeed, those whom the angels take in death while wronging themselves — they will say: ‘In what condition were you?’ They will say: ‘We were oppressed in the land.’ They will say: ‘Was not the earth of Allah spacious enough for you to migrate therein?’ For those, their refuge is Hell, and evil it is as a destination.” [Surat al-Nisa’: 97]","Whoever is unable to migrate is excused, due to the statement of Allah Most High:","“Except for the oppressed among men, women, and children who are unable to devise a plan and are not guided to a way. For those, perhaps Allah will pardon them; and Allah is ever Pardoning, Forgiving.” [al-Nisa’: 98–99]","As for those who are in the lands of the disbelievers and have freedom to worship Allah alone and perform the other rites of Islam, migration is not obligatory upon them. Rather, remaining there is better for calling non-Muslims to Islam. This occurred in the distant past when Muslims left the Arabian Peninsula for religious reasons, such as jihad in the path of Allah and calling to Allah, or for worldly reasons, such as trade, education, medical treatment, marriage, and other matters, going to lands of disbelievers from Afghanistan through India to the farthest reaches of Bukhara and Samarkand, as well as to the countries of central and northern Africa. In a short time, Islam spread in those vast lands until they transformed from lands of disbelief into lands of Islam. This shows the universality of Islam and that it is a religion suitable for every time and place.","Today we are facing the West, and Westerners do not desire Muslim migration to their lands. Thus, every day we hear of new conditions being placed to prevent Muslims from migrating to them, so that the Christian majority does not become a minority. Recent history bears witness to this. How many European cities had neither a mosque nor an Islamic center in the last century, yet through the efforts of callers to Islam and migrants to those lands who possessed knowledge and insight regarding their religion, Islam spread, mosques and centers increased, and the call of Islam is heard from pulpits there just as in Muslim lands. Thus, such people remaining in these lands is better than migrating away from them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (1671)."},{"num":8143,"demo":false,"sanad":"","matn":["عَنْ سَلَمَةَ بْنِ الأَكْوَعِ، أَنَّهُ دَخَلَ عَلَى الْحَجَّاجِ فَقَالَ: يَا ابْنَ الأَكْوَعِ: ارْتَدَدْتَ عَلَى عَقِبَيْكَ؟ تَعَرَّبْتَ؟ قَالَ: لاَ، وَلَكِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَذِنَ لِي فِي الْبَدْوِ."],"takhrij":"متفق عليه: رواه البخاري في الفتن (7087) ومسلم في الإمارة (1862) كلاهما عن قتيبة بن سعيد، حدثنا حاتم بن إسماعيل، عن يزيد بن أبي عبيد، عن سلمة بن الأكوع قال:فذكره.","grade":"متفق عليه","chapter_ar":"باب جواز الرجوع إلى البداوة بعد الهجرة إذا أمن من الفتنة","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7087) and Muslim (1862).","chapter_en":"The Permissibility of Returning to Desert Life After Migration if One Is Safe from Trial","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":9,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ entered upon al-Hajjaj, who said: “O Ibn al-Akwaʿ, have you turned back on your heels? Have you become a desert-dweller?” He said: “No, but the Messenger of Allah ﷺ gave me permission to live in the desert.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7087)، ومسلم (1862)."},{"num":8144,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا دَخَلَ مَكَّةَ قَالَ: اللهُمَّ لَا تَجْعَلْ مَنَايَانَا بِهَا حَتَّى تُخْرِجَنَا مِنْهَا."],"takhrij":"صحيح: رواه أحمد (4778، 6076)، والبزار (كشف الأستار 1751)، والبيهقي (17789) كلهم من طرق عن عبد الله بن سعيد بن أبي هند، عن أبيه، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب كراهة موت المهاجر بأرض خرج منها","chapter_ur":"","part_ar":"كتاب الجهاد","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (4778, 6076), al-Bazzar (Kashf al-Astar: 1751), and al-Bayhaqi (9/19).","chapter_en":"The Dislike of a Migrant Dying in the Land from Which He Left","part_en":"Book of Striving in the Path of Allah","group_ar":"جموع ما جاء في الهجرة","group_en":"Collection of What Has Been Narrated Concerning Migration","part_no":43,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: When the Messenger of Allah ﷺ entered Makkah, he would say: “O Allah, do not make our deaths there until You bring us out of it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (4778، 6076)، والبزار (كشف الأستار: 1751)، والبيهقي (17789)."},{"num":8145,"demo":false,"sanad":"","matn":["عن عبدالله بن عمرو، عن النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ قَتَلَ مُعَاهَدًا لَمْ يَرَحْ رَائِحَةَ الْجَنَّةِ، وَإِنَّ رِيحَهَا تُوجَدُ مِنْ مَسِيرَةِ أَرْبَعِينَ عَامًا."],"takhrij":"صحيح: رواه البخاري في الجزية والموادعة (3166) عن قيس بن حفص، حدثنا عبد الواحد، حدثنا الحسن بن عمرو، حدثنا مجاهد، عن عبد الله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب من حقوق المعاهد الحفظ على نفسه وماله في دولة الإسلام","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3166).","chapter_en":"Among the Rights of the Muʿāhad Is Protection of His Life and Wealth in the Islamic State","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs narrated from the Prophet ﷺ that he said: “Whoever kills a person under covenant will not smell the fragrance of Paradise, though its fragrance can be found from a distance of forty years.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3166)."},{"num":8146,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكَرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ قَتَلَ نَفْسًا مُعَاهَدَةً بِغَيْرِ حِلِّهَا، حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ أَنْ يَجِدَ رِيحَهَا."],"takhrij":"حسن: رواه النسائي (4748)، وأحمد (20383)، 20397)، وابن أبي عاصم في الديات (209)، والبيهقي (18734)، وصحّحه ابن حبان (4882)، والحاكم (135) كلهم من حديث يونس بن عبيد، عن الحكم بن الأعرج، عن الأشعث بن ثُرملة، عن أبي بكرة فذكره.","grade":"حسن","chapter_ar":"باب من حقوق المعاهد الحفظ على نفسه وماله في دولة الإسلام","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4748), Ahmad (20383, 20397), Ibn Abi ʿAsim in al-Diyat (209), al-Bayhaqi (9/205), authenticated by Ibn Hibban (4882), and al-Hakim (135).","chapter_en":"Among the Rights of the Muʿāhad Is Protection of His Life and Wealth in the Islamic State","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Bakrah said: The Messenger of Allah ﷺ said: “Whoever kills a covenanted soul without lawful right, Allah will forbid him from finding the fragrance of Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16287],"tks":"حسن: رواه النسائي (4748)، وأحمد (20383، 20397)، وابن أبي عاصم في الديات (209)، والبيهقي (18734)، وصححه ابن حبان (4882)، والحاكم (135)."},{"num":8147,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: كُنَّا لَا نَقْتُلُ تُجَّارَ الْمُشْرِكِينَ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه ابن أبي شيبة في مسنده (1956- المطالب العالية)، وأبو يعلى (1917) كلاهما من طريق عباد بن العوام، عن حجاج –هو ابن الأرطاة-، عن أبي الزبير، عن جابر بن عبد الله قال: فذكره.","grade":"حسن","chapter_ar":"باب تُجّار المشركين مأمونون على أنفسهم وعلى تجارتهم في دولة الإسلام","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abi Shaybah in his Musnad (1956 — al-Matalib al-ʿAliyah) and Abu Yaʿla (1917).","chapter_en":"The Merchants of the Polytheists Are Safe in Their Lives and Trade in the Islamic State","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Jabir said: We did not kill the merchants of the polytheists during the time of the Messenger of Allah ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي شيبة في مسنده (1956 — المطالب العالية)، وأبو يعلى (1917)."},{"num":8148,"demo":false,"sanad":"","matn":["عن عمر بن الخطاب أنه اسْتَعْمَلَ مَوْلًى لَهُ يُدْعَى هُنَيًّا عَلَى الحِمَى، فَقَالَ: يَا هُنَيُّ، اضْمُمْ جَنَاحَكَ عَن الناس، وَاتَّقِ دَعْوَةَ المظلومِ، فَإِنَّ دَعْوَةَ المظلومِ مُسْتَجَابَةٌ، وَأَدْخِلْ رَبَّ الصُّرَيْمَةِ وَرَبَّ الْغُنَيْمَةِ، وَإِيَّايَ وَنَعَمَ ابْنِ عَوْفٍ وَنَعَمَ ابْنِ عَفَّانَ، فَإِنَّهُمَا إِنْ تَهْلِكْ مَاشِيَتُهُمَا يَرْجِعَا إِلَى نَخْلٍ وَزَرْعٍ، وَإِنَّ رَبَّ الصُّرَيْمَةِ وَرَبَّ الْغُنَيْمَةِ إِنْ تَهْلِكْ مَاشِيَتُهُمَا يَأْتِنِي بِبَنِيهِ، فَيَقُولُ: يَا أَمِيرَ المُؤْمِنِينَ! يَا أَمِيرَ المُؤْمِنِينَ! أَفَتَارِكُهُمْ أَنَا؟ لَا أَبَا لَكَ، فَالمَاءُ وَالْكَلَأُ أَيْسَرُ عَلَيَّ مِنْ الذَّهَبِ وَالْوَرِقِ، وَايْمُ الله إِنَّهُمْ لَيَرَوْنَ أَنِّي قَدْ ظَلَمْتُهُمْ، إِنَّهَا لَبِلَادُهُمْ ومياهُهم، قَاتَلُوا عَلَيْهَا فِي الجَاهِلِيَّةِ، وَأَسْلَمُوا عَلَيْهَا فِي الْإِسْلَامِ، وَالَّذِي نَفْسِي بِيَدِهِ لَوْلَا المَالُ الَّذِي أَحْمِلُ عَلَيْهِ فِي سَبِيلِ الله مَا حَمَيْتُ عَلَيْهِمْ مِنْ بِلَادِهِمْ شِبْرًا."],"takhrij":"صحيح: رواه مالك في دعوة المظلوم (1) عن زيد بن أسلم، عن أبيه، عن عمر بن الخطاب فذكره.ورواه البخاري في الجهاد (3059) من طريق مالك به مثله.","grade":"صحيح","chapter_ar":"باب إذا أسلم قوم في دار الحرب ولهم مال وأرضون فهي لهم","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (1) and al-Bukhari (3059).","chapter_en":"If a People Accept Islam in the Abode of War and They Have Wealth and Lands, They Remain Theirs","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿUmar ibn al-Khattab appointed a freedman of his called Hunayy over the protected grazing land. He said: “O Hunayy, lower your wing toward the people, and beware of the supplication of the oppressed, for the supplication of the oppressed is answered. Admit the owner of a small flock and the owner of a few sheep, but beware of the livestock of Ibn ʿAwf and the livestock of Ibn ʿAffan, for if their animals perish, they can return to date-palms and crops. But if the animals of the owner of a small flock or the owner of a few sheep perish, he will come to me with his children and say: ‘O Commander of the Believers! O Commander of the Believers!’ Am I to abandon them? May your father be bereft of you! Water and pasture are easier for me than gold and silver. By Allah, they think that I have wronged them. It is their land and their water; they fought over it in the pre-Islamic period, and they accepted Islam while possessing it. By the One in whose hand is my soul, were it not for the wealth that I carry upon in the path of Allah, I would not have protected against them even a handspan of their land.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (1)، والبخاري (3059)."},{"num":8149,"demo":false,"sanad":"","matn":["عن جُوَيْرِيَةَ بن قدامة التميمي قَالَ: سَمِعْتُ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قُلْنَا: أَوْصِنَا يَا أَمِيرَ الْمُؤْمِنِينَ. قَالَ: أُوصِيكُمْ بِذِمَّةِ اللَّهِ، فَإِنَّهُ ذِمَّةُ نَبِيِّكُمْ، وَرِزْقُ عِيَالِكُمْ."],"takhrij":"صحيح: رواه البخاري في الجزية والموادعة (3162) عن آدم بن أبي إياس، حدثنا شعبة، حدثنا أبو جمرة قال: سمعت جويرية بن قدامة التميمي فذكره.","grade":"صحيح","chapter_ar":"باب الوصية بأهل الذمة","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3162).","chapter_en":"The Instruction to Care for the People of Dhimmah","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Juwayriyah ibn Qudamah al-Tamimi said: I heard ʿUmar ibn al-Khattab. We said: “Advise us, O Commander of the Believers.” He said: “I advise you concerning the covenant of Allah, for it is the covenant of your Prophet and the provision of your dependents.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (3162)."},{"num":8150,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَيْفَ أَنْتُمْ إِذَا لَمْ تَجْتَبُوا دِينَارًا وَلاَ دِرْهَمًا؟ فَقِيلَ لَهُ: وَكَيْفَ تَرَى ذَلِكَ كَائِنًا يَا أَبَا هُرَيْرَةَ؟ قَالَ: إِيْ وَالَّذِي نَفْسُ أَبِي هُرَيْرَةَ بِيَدِهِ عَنْ قَوْلِ الصَّادِقِ الْمَصْدُوقِ. قَالُوا: عَمَّ ذَاكَ؟ قَالَ: تُنْتَهَكُ ذِمَّةُ اللَّهِ وَذِمَّةُ رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَيَشُدُّ اللَّهُ عَزَّ وَجَلَّ قُلُوبَ أَهْلِ الذِّمَّةِ، فَيَمْنَعُونَ مَا فِي أَيْدِيهِمْ."],"takhrij":"صحيح: رواه البخاري في الجزية والموادعة (3180) قال: قال أبو موسى (هو محمد بن المثنى) حدثنا هاشم بن القاسم، حدثنا إسحاق بن سعيد، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب التحذير من ظلم رعايا غير المسلمين","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3180).","chapter_en":"Warning Against Wronging Non-Muslim Subjects","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah said: “How will you be when you no longer collect a dinar or a dirham?” It was said to him: “How do you think that will happen, O Abu Hurayrah?” He said: “Yes, by the One in whose hand is the soul of Abu Hurayrah, this is from the statement of the truthful and confirmed one.” They said: “Because of what?” He said: “The covenant of Allah and the covenant of His Messenger ﷺ will be violated, so Allah, Mighty and Majestic, will strengthen the hearts of the people of dhimmah, and they will withhold what is in their hands.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (3180)."},{"num":8151,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنَعَتِ الْعِرَاقُ دِرْهَمَهَا وَقَفِيزَهَا، وَمَنَعَتِ الشَّأْمُ مُدْيَهَا وَدِينَارَهَا، وَمَنَعَتْ مِصْرُ إِرْدَبَّهَا وَدِينَارَهَا، وَعُدْتُمْ مِنْ حَيْثُ بَدَأْتُمْ، وَعُدْتُمْ مِنْ حَيْثُ بَدَأْتُمْ، وَعُدْتُمْ مِنْ حَيْثُ بَدَأْتُمْ. شَهِدَ عَلَى ذَلِكَ لَحْمُ أَبِي هُرَيْرَةَ وَدَمُهُ."],"takhrij":"صحيح: رواه مسلم في الفتن وأشراط الساعة (2896: 33) من طريق يحيى بن آدم بن سليمان مولى خالد بن خالد، حدثنا زهير، عن سهيل بن أبي صالح، عن أبيه عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب التحذير من ظلم رعايا غير المسلمين","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2896:33).","chapter_en":"Warning Against Wronging Non-Muslim Subjects","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Iraq will withhold its dirham and its qafiz; Syria will withhold its mudd and its dinar; Egypt will withhold its irdabb and its dinar; and you will return to where you began, you will return to where you began, you will return to where you began.” Abu Hurayrah’s flesh and blood bore witness to that."]}},"tuhfa":{},"full":1,"rep":[15843],"tks":"صحيح: رواه مسلم (2896: 33)."},{"num":8152,"demo":false,"sanad":"","matn":["عَنْ هِشَامِ بْنِ حَكِيمِ بْنِ حِزَامٍ، قَالَ مَرَّ بِالشَّامِ عَلَى أُنَاسٍ، وَقَدْ أُقِيمُوا فِي الشَّمْسِ، وَصُبَّ عَلَى رُءُوسِهِمُ الزَّيْتُ فَقَالَ: مَا هَذَا؟ قِيلَ: يُعَذَّبُونَ فِي الْخَرَاجِ. فَقَالَ: أَمَا إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  يَقُولُ: إِنَّ اللَّهَ يُعَذِّبُ الَّذِينَ يُعَذِّبُونَ فِي الدُّنْيَا."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2613: 117، 118) عن أبي بكر بن أبي شيبة، حدثنا حفص بن غياث، عن هشام بن عروة، عن أبيه، عن هشام بن حكيم بن حزام فذكره.","grade":"صحيح","chapter_ar":"باب التحذير من ظلم رعايا غير المسلمين","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in al-Birr wa al-Silah (2613:117, 118).","chapter_en":"Warning Against Wronging Non-Muslim Subjects","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Hisham ibn Hakim ibn Hizam passed by some people in Syria who had been made to stand in the sun, and oil had been poured over their heads. He said: “What is this?” It was said: “They are being punished regarding the land-tax.” He said: “Indeed, I heard the Messenger of Allah ﷺ say: ‘Allah punishes those who punish people in this world.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2613: 117، 118)."},{"num":8153,"demo":false,"sanad":"","matn":["عَنْ عِدَّةٍ، مِنْ أَبْنَاءِ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ   عَنْ آبَائِهِمْ دِنْيَةً عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَالَ: أَلاَ مَنْ ظَلَمَ مُعَاهِدًا أَوِ انْتَقَصَهُ أَوْ كَلَّفَهُ فَوْقَ طَاقَتِهِ أَوْ أَخَذَ مِنْهُ شَيْئًا بِغَيْرِ طِيبِ نَفْسٍ فَأَنَا حَجِيجُهُ يَوْمَ الْقِيَامَةِ.","وزاد في رواية: وَأَشَارَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأُصْبُعِهِ إِلَى صَدْرِهِ: أَلَا وَمَنْ قَتَلَ مُعَاهَدًا لَهُ ذِمَّةُ اللهِ وَذِمَّةُ رَسُولِهِ حَرَّمَ اللهُ عَلَيْهِ رِيحَ الْجَنَّةِ، وَإِنَّ رِيحَهَا لَتُوجَدُ مِنْ مَسِيرَةِ سَبْعِينَ خَرِيفًا."],"takhrij":"حسن: رواه أبو داود (3052) عن سليمان بن داود المهرى، أخبرنا ابن وهب، حدثنى أبو صخر المدينى أن صفوان بن سليم أخبره عن عدة من أبناء أصحاب رسول الله صلى الله عليه وسلم عن آباءهم فذكره. ورواه البيهقي (١٨٧٣١) من طريق محمد بن عبد الله بن عبد الحكم، عن ابن وهب به وفيه: عن ثلاثين من أبناء أصحاب رسول الله صلى الله عليه وسلم. والزيادة المذكورة له.","grade":"حسن","chapter_ar":"باب التحذير من ظلم رعايا غير المسلمين","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3052).","chapter_en":"Warning Against Wronging Non-Muslim Subjects","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Several sons of the companions of the Messenger of Allah ﷺ narrated directly from their fathers, from the Messenger of Allah ﷺ, that he said: “Indeed, whoever wrongs a covenanted person, diminishes him, burdens him beyond his capacity, or takes something from him without his willing consent, I will be his opponent on the Day of Resurrection.” Another narration adds: The Messenger of Allah ﷺ pointed with his finger to his chest and said: “Indeed, whoever kills a covenanted person who has the protection of Allah and His Messenger, Allah will forbid him the fragrance of Paradise, though its fragrance can be found from a distance of seventy autumns.”"]},"buhuth":{"en":["His saying “dinyatan,” with kasrah on the dal, sukun on the nun, and fathah on the ya’, is a verbal noun used as a circumstantial qualifier, meaning: directly connected in lineage."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3052)."},{"num":8154,"demo":false,"sanad":"","matn":["عَنِ الْعِرْبَاضِ بْنِ سَارِيَةَ السُّلَمِيِّ، قَالَ: نَزَلْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ، وَمَعَهُ مَنْ مَعَهُ مِنْ أَصْحَابِهِ، وَكَانَ صَاحِبُ خَيْبَرَ رَجُلاً مَارِدًا مُنْكَرًا، فَأَقْبَلَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا مُحَمَّدُ! أَلَكُمْ أَنْ تَذْبَحُوا حُمُرَنَا، وَتَأْكُلُوا ثَمَرَنَا، وَتَضْرِبُوا نِسَاءَنَا، فَغَضِبَ يَعْنِي: النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: يَا ابْنَ عَوْفٍ، ارْكَبْ فَرَسَكَ، ثُمَّ نَادِ: أَلاَ إِنَّ الْجَنَّةَ لاَ تَحِلُّ إِلاَّ لِمُؤْمِنٍ وَأَنِ اجْتَمِعُوا لِلصَّلاَةِ. قَالَ: فَاجْتَمَعُوا ثُمَّ صَلَّى بِهِمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَامَ فَقَالَ: أَيَحْسَبُ أَحَدُكُمْ مُتَّكِئًا عَلَى أَرِيكَتِهِ قَدْ يَظُنُّ أَنَّ اللَّهَ لَمْ يُحَرِّمْ شَيْئًا إِلاَّ مَا فِي هَذَا الْقُرْآنِ، أَلاَ وَإِنِّي وَاللَّهِ قَدْ وَعَظْتُ، وَأَمَرْتُ، وَنَهَيْتُ عَنْ أَشْيَاءَ إِنَّهَا لَمِثْلُ الْقُرْآنِ، أَوْ أَكْثَرُ، وَأَنَّ اللَّهَ عَزَّ وَجَلَّ لَمْ يُحِلَّ لَكُمْ أَنْ تَدْخُلُوا بُيُوتَ أَهْلِ الْكِتَابِ إِلاَّ بِإِذْنٍ، وَلاَ ضَرْبَ نِسَائِهِمْ وَلاَ أَكْلَ ثِمَارِهِمْ إِذَا أَعْطَوْكُمُ الَّذِي عَلَيْهِمْ."],"takhrij":"حسن: رواه أبو داود ( 3050) عن محمد بن عيسى، حدثنا أشعث بن شعبة، حدثنا أرطاة بن المنذر قال: سمعت حكيم بن عمير أبا الأحوص يحدث عن العرباض فذكره.","grade":"حسن","chapter_ar":"باب في حقوق أهل الذمة في نسائهم وأموالهم","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3050).","chapter_en":"Concerning the Rights of the People of Dhimmah Regarding Their Women and Wealth","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Al-ʿIrbad ibn Sariyah al-Sulami said: We stopped with the Prophet ﷺ at Khaybar, and with him were those of his companions who were with him. The leader of Khaybar was a defiant, harsh man. He came to the Prophet ﷺ and said: “O Muhammad, is it lawful for you to slaughter our donkeys, eat our fruit, and strike our women?” The Prophet ﷺ became angry and said: “O Ibn ʿAwf, mount your horse, then announce: Indeed, Paradise is not lawful except for a believer, and gather for prayer.” He said: They gathered, then the Prophet ﷺ led them in prayer. Then he said: “Does one of you, reclining on his couch, think that Allah has not forbidden anything except what is in this Qur’an? Indeed, by Allah, I have admonished, commanded, and forbidden things, and they are like the Qur’an or more. Allah, Mighty and Majestic, has not made it lawful for you to enter the houses of the People of the Book except with permission, nor to strike their women, nor to eat their fruits, when they have given you what is due from them.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[15641],"tks":"حسن: رواه أبو داود (3050)."},{"num":8155,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ غُلاَمٌ يَهُودِيٌّ يَخْدُمُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَمَرِضَ، فَأَتَاهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعُودُهُ، فَقَعَدَ عِنْدَ رَأْسِهِ، فَقَالَ لَهُ: أَسْلِمْ. فَنَظَرَ إِلَى أَبِيهِ وَهْوَ عِنْدَهُ فَقَالَ لَهُ: أَطِعْ أَبَا الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَأَسْلَمَ، فَخَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهْوَ يَقُولُ: الْحَمْدُ لِلَّهِ الَّذِي أَنْقَذَهُ مِنَ النَّارِ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1356) عن سليمان بن حرب، حدثنا حماد بن زيد، عن ثابت، عن أنس قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في عيادة الرعايا من الكفار","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1356).","chapter_en":"What Has Been Reported Concerning Visiting Sick Non-Muslim Subjects","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Anas said: A Jewish boy used to serve the Prophet ﷺ. He became ill, so the Prophet ﷺ came to visit him and sat by his head. He said to him: “Accept Islam.” The boy looked at his father, who was with him, and his father said to him: “Obey Abu al-Qasim ﷺ.” So he accepted Islam. The Prophet ﷺ left while saying: “Praise be to Allah who saved him from the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3770],"tks":"صحيح: رواه البخاري (1356)."},{"num":8156,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب قال: من زعم أن عندنا شيئا نقرؤه إلا كتاب الله وهذه الصحيفة قال: -وصحيفة معلقة في قراب سيفه- فقد كذب. وفيها: وذمة المسلمين واحدة يسعى بها أدناهم. ومن أخفر مسلما فعليه لعنة الله والملائكة والناس أجمعين لا يقبل منه يوم القيامة صرف ولا عدل."],"takhrij":"متفق عليه:  رواه البخاري في الجزية (3172)، ومسلم في الحج(1370: 467، 468) كلاهما من حديث الأعمش، عن إبراهيم التيمي، عن أبيه قال: خطبنا علي فقال: فذكره في حديث طويل. والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أمان الرجال والنساء للأقلية غير المسلمة","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3172) and Muslim (1370:467, 468). The wording is Muslim’s.","chapter_en":"What Has Been Reported Concerning Men and Women Granting Safety to the Non-Muslim Minority","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿAli ibn Abi Talib said: Whoever claims that we possess something to recite other than the Book of Allah and this document — he said: a document hanging in the sheath of his sword — has lied. In it is: “The protection granted by the Muslims is one, and the lowest of them may grant it. Whoever violates the protection granted by a Muslim, upon him is the curse of Allah, the angels, and all people; no obligatory or voluntary deed will be accepted from him on the Day of Resurrection.”"]},"buhuth":{"en":["His saying, “the protection of the Muslims,” means their guarantee of safety. His saying, “violates the protection granted by a Muslim,” means he breaks the safety granted by a Muslim and attacks a disbeliever who has safety, killing him."]},"intro":{"ar":["قال تعالى:","(وَإِنْ أَحَدٌ مِّنَ الْمُشْرِكِينَ اسْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَامَ اللهِ) [سورة التوبة: ٦]."],"en":["Allah Most High said:","“And if any one of the polytheists seeks your protection, then grant him protection so that he may hear the words of Allah.” [Surat al-Tawbah: 6]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3172)، ومسلم (1370: 467، 468). والسياق لمسلم."},{"num":8157,"demo":false,"sanad":"","matn":["عن أبي هريرة عن النبي صلى الله عليه وسلم قال: ذمة المسلمين واحدة، يسعى بها أدناهم فمن أخفر مسلما فعليه لعنة الله والملائكة والناس أجمعين، لا يقبل منه يوم القيامة عدل ولا صرف."],"takhrij":"صحيح: رواه مسلم في الحج (1371) عن أبي بكر بن النضر بن أبي النضر، حدثني أبو النضر، حدثني عبيد الله الأشجعي، عن سفيان، عن الأعمش، عن أبي صالح، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أمان الرجال والنساء للأقلية غير المسلمة","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1371).","chapter_en":"What Has Been Reported Concerning Men and Women Granting Safety to the Non-Muslim Minority","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “The protection granted by the Muslims is one, and the lowest of them may grant it. Whoever violates the protection granted by a Muslim, upon him is the curse of Allah, the angels, and all people; no obligatory or voluntary deed will be accepted from him on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1371)."},{"num":8158,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْمَرْأَةَ لَتَأْخُذُ لِلْقَوْمِ يَعْنِي تُجيرُ على الْمُسلمين."],"takhrij":"حسن: رواه الترمذي: (1579) عن يحيى بن أكثم، حدثنا عبد العزيز بن أبي حازم، عن كثير بن زيد، عن الوليد بن رباح، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في أمان الرجال والنساء للأقلية غير المسلمة","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1579), who said: “This is a good, strange hadith.”","chapter_en":"What Has Been Reported Concerning Men and Women Granting Safety to the Non-Muslim Minority","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “A woman may take protection for a people,” meaning she may grant protection binding upon the Muslims."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1579)، وقال: “هذا حديث حسن غريب”."},{"num":8159,"demo":false,"sanad":"","matn":["عَنْ أُمِّ هَانِئٍ بنت أَبِي طَالِبٍ قَالَتْ: ذَهَبْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ الْفَتْحِ، فَوَجَدْتُهُ يَغْتَسِلُ، وَفَاطِمَةُ ابْنَتُهُ تَسْتُرُهُ بِثَوْبٍ، فَسَلَّمْتُ عَلَيْهِ فَقَالَ: مَنْ هَذِهِ؟ فَقُلْتُ: أَنَا أُمُّ هَانِئٍ بِنْتُ أَبِي طَالِبٍ فَقَالَ: مَرْحَبًا بِأُمِّ هَانِئٍ فَلَمَّا فَرَغَ مِنْ غُسْلِهِ قَامَ، فَصَلَّى ثَمَانِيَ رَكَعَاتٍ مُلْتَحِفًا فِي ثَوْبٍ وَاحِدٍ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، زَعَمَ ابْنُ أُمِّي عَلِيٌّ أَنَّهُ قَاتِلٌ رَجُلاً قَدْ أَجَرْتُهُ فُلاَنُ بْنُ هُبَيْرَةَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : قَدْ أَجَرْنَا مَنْ أَجَرْتِ يَا أُمَّ هَانِئٍ، قَالَتْ أُمُّ هَانِئٍ: وَذَلِكَ ضُحًى."],"takhrij":"متفق عليه: رواه مالك في قصر الصلاة في السفر (28) عن أبي النضر مولى عمر بن عبيد الله، أن أبا مرة مولى عقيل بن أبي طالب أخبره أنه سمع أم هانئ بنت أبي طالب تقول فذكرته. ورواه البخاري في الجزية (3171)، ومسلم في الحيض (336) كلاهما من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أمان الرجال والنساء للأقلية غير المسلمة","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (28), al-Bukhari (3171), and Muslim (336).","chapter_en":"What Has Been Reported Concerning Men and Women Granting Safety to the Non-Muslim Minority","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Umm Hani’ bint Abi Talib said: I went to the Messenger of Allah ﷺ in the year of the Conquest and found him bathing, while Fatimah, his daughter, was screening him with a cloth. I greeted him, and he said: “Who is this?” I said: “I am Umm Hani’ bint Abi Talib.” He said: “Welcome, Umm Hani’.” When he finished bathing, he stood and prayed eight rakʿahs wrapped in a single garment. I said: “O Messenger of Allah, my brother ʿAli claims that he will kill a man to whom I have granted protection: so-and-so ibn Hubayrah.” The Messenger of Allah ﷺ said: “We have granted protection to the one you protected, O Umm Hani’.” Umm Hani’ said: That was in the forenoon."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (28)، والبخاري (3171)، ومسلم (336)."},{"num":8160,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ عَوْفٍ -وهو حليف بنى عَامِرٍ بن لُؤَيٍّ، وَكَانَ شَهِدَ بَدْرًا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَخْبَرَهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ أَبَا عُبَيْدَةَ بْنَ الْجَرَّاحِ إِلَى الْبَحْرَيْنِ يَأْتِي بِجِزْيَتِهَا، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هُوَ صَالَحَ أَهْلَ الْبَحْرَيْنِ، وَأَمَّرَ عَلَيْهِمُ الْعَلاَءَ بْنَ الْحَضْرَمِيِّ، فَقَدِمَ أَبُو عُبَيْدَةَ بِمَالٍ مِنَ الْبَحْرَيْنِ، فَسَمِعَتِ الأَنْصَارُ بِقُدُومِ أَبِي عُبَيْدَةَ، فوافوا صَلاَةَ الْفَجْرَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَلَمَّا صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ انْصَرَفَ، فَتَعَرَّضُوا لَهُ، فَتَبَسَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ رَآهُمْ ثُمَّ قَالَ: أَظُنُّكُمْ سَمِعْتُمْ أَنَّ أَبَا عُبَيْدَةَ قدم بشيء مِنْ الْبَحْرَيْنِ فَقَالُوا: أَجَلْ، يَا رَسُولَ اللَّهِ قَالَ: فَأَبْشِرُوا وَأَمِّلُوا مَا يَسُرُّكُمْ، فَوَاللَّهِ مَا الْفَقْرَ أَخْشَى عَلَيْكُمْ، وَلَكِنِّي أَخْشَى عَلَيْكُمْ أَنْ تُبْسَطَ الدُّنْيَا عليكم كَمَا بُسِطَتْ عَلَى مَنْ كَانَ قَبْلَكُمْ، فَتَنَافَسُوهَا كَمَا تَنَافَسُوهَا وَتُهْلِكَكُمْ كَمَا أَهْلَكَتْهُمْ."],"takhrij":"متفق عليه: رواه البخاري في الجزية (3158)، ومسلم في الزهد (2961: 6) كلاهما من طريق الزهري، حدثني عروة بن الزبير، أن المسور بن مخرمة أخبره عن عمرو بن عوف قال:فذكره.","grade":"متفق عليه","chapter_ar":"باب أخذ الجزية من أهل الذمة","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3158) and Muslim (2961:6).","chapter_en":"Taking Jizyah from the People of Dhimmah","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿAmr ibn ʿAwf — an ally of Banu ʿAmir ibn Lu’ayy, who had attended Badr with the Messenger of Allah ﷺ — reported that the Messenger of Allah ﷺ sent Abu ʿUbaydah ibn al-Jarrah to Bahrain to bring its jizyah. The Messenger of Allah ﷺ had made a treaty with the people of Bahrain and appointed al-ʿAla’ ibn al-Hadrami over them. Abu ʿUbaydah arrived with wealth from Bahrain, and the Ansar heard of his arrival, so they attended the Fajr prayer with the Messenger of Allah ﷺ. When the Messenger of Allah ﷺ finished praying and turned away, they came before him. The Messenger of Allah ﷺ smiled when he saw them, then said: “I think you have heard that Abu ʿUbaydah has brought something from Bahrain?” They said: “Yes, O Messenger of Allah.” He said: “Then rejoice and hope for what will please you. By Allah, it is not poverty that I fear for you; rather, I fear that the world will be spread out for you as it was spread out for those before you, and you will compete over it as they competed over it, and it will destroy you as it destroyed them.”"]},"intro":{"ar":["قال تعالى:","(قَاتِلُوا الَّذِينَ لَا يُؤْمِنُونَ بِاللهِ وَلَا بِالْيَوْمِ الْآخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ اللهُ وَرَسُولُهُ وَلَا يَدِينُونَ دِينَ الْحَقِّ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ حَتَّىٰ يُعْطُوا الْجِزْيَةَ عَن يَدٍ وَهُمْ صَاغِرُونَ) [التوبة: ٢٩].","قال ابن جرير في تفسيره (١١/٤٠٧): معناه: “وهم أذلاء مقهورون”."],"en":["Allah Most High said:","“Fight those who do not believe in Allah or in the Last Day, and who do not forbid what Allah and His Messenger have forbidden, and who do not follow the religion of truth among those who were given the Book, until they give the jizyah willingly while they are humbled.” [al-Tawbah: 29]","Ibn Jarir said in his Tafsir (11/407): Its meaning is: “while they are humbled and subdued.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3158)، ومسلم (2961: 6)."},{"num":8161,"demo":false,"sanad":"","matn":["عَنْ سُلَيْمَانَ بْنِ بُرَيْدَةَ، عَنْ أَبِيهِ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَمَّرَ أَمِيرًا عَلَى جَيْشٍ أَوْ سَرِيَّةٍ أَوْصَاهُ فِي خَاصَّتِهِ بِتَقْوَى اللَّهِ وَمَنْ مَعَهُ مِنَ الْمُسْلِمِينَ خَيْرًا ثُمَّ قَالَ: اغْزُوا بِاسْمِ اللَّهِ فِي سَبِيلِ اللَّهِ، قَاتِلُوا مَنْ كَفَرَ بِاللهِ، اغْزُوا، وَلَا تَغُلُّوا، وَلَا تَغْدِرُوا، وَلَا تَمْثُلُوا، وَلَا تَقْتُلُوا وَلِيدًا، وَإِذَا لَقِيتَ عَدُوَّكَ مِنَ الْمُشْرِكِينَ فَادْعُهُمْ إِلَى ثَلَاثِ خِصَالٍ -أَوْ خِلَالٍ- فَأَيَّتُهُنَّ مَا أَجَابُوكَ فَاقْبَلْ مِنْهُمْ فَذَكَرَ وَمِنْهَا: فَسَلْهُمُ الْجِزْيَةَ فَإِنْ هُمْ أَجَابُوكَ فَاقْبَلْ مِنْهُمْ وَكُفَّ عَنْهُمْ."],"takhrij":"صحيح: رواه مسلم في الجهاد والسير (1731: 2) عن عبد الله بن هاشم، حدثني عبد الرحمن يعني بن مهدي، حدثنا سفيان، عن علقمة بن مرثد، عن سليمان بن بريدة، عن أبيه قال: فذكره.","grade":"صحيح","chapter_ar":"باب أخذ الجزية من أهل الذمة","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1731:2).","chapter_en":"Taking Jizyah from the People of Dhimmah","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Sulayman ibn Buraydah narrated from his father, who said: When the Messenger of Allah ﷺ appointed a commander over an army or detachment, he would advise him personally to fear Allah and to treat the Muslims who were with him well. Then he would say: “Fight in the name of Allah in the path of Allah. Fight those who disbelieve in Allah. Fight, and do not steal from the spoils, do not betray, do not mutilate, and do not kill a child. When you meet your enemy from among the polytheists, call them to three qualities — or options — and whichever of them they accept from you, accept it from them.” He mentioned among them: “Then ask them for jizyah; if they respond to you, accept it from them and refrain from fighting them.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1731: 2)."},{"num":8162,"demo":false,"sanad":"","matn":["عَنْ جُبَيْرِ بْنِ حَيَّةَ، قَالَ: بَعَثَ عُمَرُ النَّاسَ فِي أَفْنَاءِ الأَمْصَارِ يُقَاتِلُونَ الْمُشْرِكِينَ، فَأَسْلَمَ الْهُرْمُزَانُ فَقَالَ: إِنِّي مُسْتَشِيرُكَ فِي مَغَازِيَّ هَذِهِ. قَالَ: نَعَمْ، مَثَلُهَا وَمَثَلُ مَنْ فِيهَا مِنَ النَّاسِ مِنْ عَدُوِّ الْمُسْلِمِينَ مَثَلُ طَائِرٍ لَهُ رَأْسٌ وَلَهُ جَنَاحَانِ، وَلَهُ رِجْلاَنِ، فَإِنْ كُسِرَ أَحَدُ الْجَنَاحَيْنِ نَهَضَتِ الرِّجْلاَنِ بِجَنَاحٍ وَالرَّأْسُ، فَإِنْ كُسِرَ الْجَنَاحُ الآخَرُ نَهَضَتِ الرِّجْلاَنِ وَالرَّأْسُ، وَإِنْ شُدِخَ الرَّأْسُ ذَهَبَتِ الرِّجْلاَنِ وَالْجَنَاحَانِ وَالرَّأْسُ، فَالرَّأْسُ كِسْرَى، وَالْجَنَاحُ قَيْصَرُ، وَالْجَنَاحُ الآخَرُ فَارِسُ، فَمُرِ الْمُسْلِمِينَ فَلْيَنْفِرُوا إِلَى كِسْرَى. وَقَالَ بَكْرٌ وَزِيَادٌ جَمِيعًا عَنْ جُبَيْرِ بْنِ حَيَّةَ قَالَ فَنَدَبَنَا عُمَرُ وَاسْتَعْمَلَ عَلَيْنَا النُّعْمَانَ بْنَ مُقَرِّنٍ، حَتَّى إِذَا كُنَّا بِأَرْضِ الْعَدُوِّ، وَخَرَجَ عَلَيْنَا عَامِلُ كِسْرَى فِي أَرْبَعِينَ أَلْفًا، فَقَامَ تُرْجُمَانٌ فَقَالَ لِيُكَلِّمْنِي رَجُلٌ مِنْكُمْ. فَقَالَ الْمُغِيرَةُ سَلْ عَمَّا شِئْتَ. قَالَ مَا أَنْتُمْ قَالَ نَحْنُ أُنَاسٌ مِنَ الْعَرَبِ كُنَّا فِي شَقَاءٍ شَدِيدٍ وَبَلاَءٍ شَدِيدٍ، نَمَصُّ الْجِلْدَ وَالنَّوَى مِنَ الْجُوعِ، وَنَلْبَسُ الْوَبَرَ وَالشَّعَرَ، وَنَعْبُدُ الشَّجَرَ وَالْحَجَرَ، فَبَيْنَا نَحْنُ كَذَلِكَ، إِذْ بَعَثَ رَبُّ السَّمَوَاتِ وَرَبُّ الأَرَضِينَ تَعَالَى ذِكْرُهُ وَجَلَّتْ عَظَمَتُهُ إِلَيْنَا نَبِيًّا مِنْ أَنْفُسِنَا، نَعْرِفُ أَبَاهُ وَأُمَّهُ، فَأَمَرَنَا نَبِيُّنَا رَسُولُ رَبِّنَا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نَقَاتِلَكُمْ حَتَّى تَعْبُدُوا اللَّهَ وَحْدَهُ أَوْ تُؤَدُّوا الْجِزْيَةَ، وَأَخْبَرَنَا نَبِيُّنَا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ رِسَالَةِ رَبِّنَا أَنَّهُ مَنْ قُتِلَ مِنَّا صَارَ إِلَى الْجَنَّةِ فِي نَعِيمٍ لَمْ يَرَ مِثْلَهَا قَطُّ، وَمَنْ بَقِيَ مِنَّا مَلَكَ رِقَابَكُمْ."],"takhrij":"صحيح: رواه البخاري في الجزية والموادعة (3159) عن الفضل بن يعقوب حدثنا عبد الله بن جعفر الرقي، حدثنا المعتمر بن سليمان، حدثنا سعيد بن عبيد الله الثقفي، حدثنا بكر بن عبد الله المزني، وزياد بن جبير، عن جبير بن حية قال: فذكره.","grade":"صحيح","chapter_ar":"باب أخذ الجزية من أهل الذمة","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3159).","chapter_en":"Taking Jizyah from the People of Dhimmah","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Jubayr ibn Hayyah said: ʿUmar sent the people throughout the regions to fight the polytheists. Al-Hurmuzan accepted Islam, and ʿUmar said: “I am seeking your counsel concerning these campaigns.” He said: “Yes. Their example and the example of the people among the enemies of the Muslims is like a bird with a head, two wings, and two legs. If one wing is broken, the two legs, the other wing, and the head rise up. If the other wing is broken, the two legs and the head rise up. But if the head is crushed, the two legs, the two wings, and the head are gone. The head is Chosroes, one wing is Caesar, and the other wing is Persia. So command the Muslims to march against Chosroes.” Bakr and Ziyad both narrated from Jubayr ibn Hayyah, who said: ʿUmar summoned us and appointed al-Nuʿman ibn Muqarrin over us. When we were in the land of the enemy, the governor of Chosroes came out against us with forty thousand. An interpreter stood and said: “Let one man from you speak to me.” Al-Mughirah said: “Ask whatever you wish.” He said: “Who are you?” He said: “We are people from the Arabs. We were in severe misery and severe hardship. Out of hunger, we would suck on hides and date-stones. We wore wool and hair, and we worshiped trees and stones. While we were in that state, the Lord of the heavens and the Lord of the earth — exalted is His mention and majestic is His greatness — sent to us a Prophet from among ourselves, whose father and mother we know. Our Prophet, the Messenger of our Lord ﷺ, commanded us to fight you until you worship Allah alone or pay the jizyah. Our Prophet informed us from the message of our Lord that whoever among us is killed will go to Paradise in bliss unlike anything ever seen, and whoever remains among us will own your necks.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3159)."},{"num":8163,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ دِينَارٍ قَالَ: كُنْتُ جَالِسًا مَعَ جَابِرِ بْنِ زَيْدٍ وَعَمْرِو بْنِ أَوْسٍ فَحَدَّثَهُمَا بَجَالَةُ سَنَةَ سَبْعِينَ عَامَ حَجَّ مُصْعَبُ بْنُ الزُّبَيْرِ بِأَهْلِ الْبَصْرَةِ عِنْدَ دَرَجِ زَمْزَمَ قَالَ: كُنْتُ كَاتِبًا لِجَزْءِ بْنِ مُعَاوِيَةَ عَمِّ الأَحْنَفِ، فَأَتَانَا كِتَابُ عُمَرَ بْنِ الْخَطَّابِ قَبْلَ مَوْتِهِ بِسَنَةٍ: فَرِّقُوا بَيْنَ كُلِّ ذِي مَحْرَمٍ مِنَ الْمَجُوسِ وَلَمْ يَكُنْ عُمَرُ أَخَذَ الْجِزْيَةَ مِنَ الْمَجُوسِ حَتَّى شَهِدَ عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَذَهَا مِنْ مَجُوسِ هَجَرٍ."],"takhrij":"صحيح: رواه البخاري في الجزية (3156-3157) عن علي بن عبد الله، حدثنا سفيان، قال سمعت عمروا قال: فذكره.","grade":"صحيح","chapter_ar":"باب أخذ الجزية من أهل الذمة","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3156–3157).","chapter_en":"Taking Jizyah from the People of Dhimmah","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿAmr ibn Dinar said: I was sitting with Jabir ibn Zayd and ʿAmr ibn Aws when Bajalah narrated to them — in the year seventy, the year Musʿab ibn al-Zubayr led the people of Basra in Hajj, near the steps of Zamzam — saying: I was the scribe of Jaz’ ibn Muʿawiyah, the uncle of al-Ahnaf. A letter from ʿUmar ibn al-Khattab came to us one year before his death: “Separate every mahram relative among the Magians.” ʿUmar had not taken jizyah from the Magians until ʿAbd al-Rahman ibn ʿAwf testified that the Messenger of Allah ﷺ had taken it from the Magians of Hajar."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (3156-3157)."},{"num":8164,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، وَعَنْ عُثْمَانَ بْنِ أَبِي سُلَيْمَانَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ خَالِدَ بْنَ الْوَلِيدِ إِلَى أُكَيْدِرِ دُومَةَ فَأُخِذَ فَأَتَوْهُ بِهِ، فَحَقَنَ لَهُ دَمَهُ، وَصَالَحَهُ عَلَى الْجِزْيَةِ."],"takhrij":"حسن: رواه أبو داود (3037)، والبيهقي (18641) من طريق محمد بن إسحاق قال: عن عاصم بن عمر، عن أنس بن مالك وعن عثمان بن أبي سليمان فذكراه. وفي إسناده محمد بن إسحاق وهو مدلس، وقد عنعن.","grade":"حسن","chapter_ar":"باب الصلح على الجزية","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3037) and al-Bayhaqi (9/186) through Muhammad ibn Ishaq, from ʿAsim ibn ʿUmar, from Anas ibn Malik and ʿUthman ibn Abi Sulayman. Muhammad ibn Ishaq is a mudallis, and he narrates this route with ʿanʿanah.","chapter_en":"Making Peace on the Basis of Jizyah","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Anas ibn Malik and ʿUthman ibn Abi Sulayman narrated that the Prophet ﷺ sent Khalid ibn al-Walid to Ukaydir of Dumah. They captured him and brought him to the Prophet ﷺ. He spared his life and made peace with him on the basis of jizyah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3037)، والبيهقي (18641)."},{"num":8165,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ قَالَ: قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  لَوْ قَدْ جَاءَنَا مَالُ الْبَحْرَيْنِ لَقَدْ أَعْطَيْتُكَ هَكَذَا وَهَكَذَا وَهَكَذَا - وَقَالَ بِيَدَيْهِ جَمِيعًا، فَقُبِضَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَبْلَ أَنْ يَجِيءَ مَالُ الْبَحْرَيْنِ. فَقَدِمَ عَلَى أَبِي بَكْرٍ بَعْدَهُ، فَأَمَرَ مُنَادِيًا، فَنَادَى: مَنْ كَانَتْ لَهُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِدَةٌ أَوْ دَيْنٌ فَلْيَأْتِ! فَقُمْتُ فَقُلْتُ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَوْ قَدْ جَاءَنَا مَالُ الْبَحْرَيْنِ أَعْطَيْتُكَ هَكَذَا وَهَكَذَا وَهَكَذَا! فَحَثَى أَبُو بَكْرٍ مَرَّةً، ثُمَّ قَالَ لِي: عُدَّهَا. فَعَدَدْتُهَا فَإِذَا هِيَ خَمْسُمِائَةٍ، فَقَالَ: خُذْ مِثْلَيْهَا."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3137)، ومسلم في الفضائل (2314: 60) كلاهما من طريق سفيان بن عيينة، حدثنا محمد بن المنكدر، سمع جابر بن عبد الله يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب قسمة مال الجزية على مصالح المسلمين","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3137) and Muslim (2314:60). The wording is Muslim’s.","chapter_en":"Dividing the Wealth of Jizyah for the Interests of the Muslims","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: The Messenger of Allah ﷺ said: “If the wealth of Bahrain comes to us, I will give you like this, like this, and like this,” and he gestured with both hands. The Prophet ﷺ passed away before the wealth of Bahrain came. It arrived afterward during the time of Abu Bakr, so he ordered a caller to announce: “Whoever has a promise or debt owed to him by the Prophet ﷺ, let him come.” I stood and said: “The Prophet ﷺ said: ‘If the wealth of Bahrain comes to us, I will give you like this, like this, and like this.’” Abu Bakr scooped once, then said to me: “Count it.” I counted it, and it was five hundred. He said: “Take twice as much.”"]},"buhuth":{"en":["His saying, “The Prophet ﷺ passed away before the wealth of Bahrain came,” does not contradict the coming hadith of Anas, because this was jizyah wealth, and it would arrive from year to year. See al-Fath (1/517)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3137)، ومسلم (2314: 60). والسياق لمسلم."},{"num":8166,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ بْنِ مَالِكٍ قَالَ: أُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَالٍ مِنَ الْبَحْرَيْنِ، فَقَالَ: انْثُرُوهُ فِي الْمَسْجِدِ، وَكَانَ أَكْثَرَ مَالٍ أُتِيَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَىَّ الصلاة، وَلَمْ يَلْتَفِتْ إِلَيْهِ، فَلَمَّا قَضَى الصَّلَاةَ جَاءَ، فَجَلَسَ إِلَيْهِ، فَمَا كَانَ يَرَى أَحَدًا إِلاَّ أَعْطَاهُ، إِذْ جَاءَهُ الْعَبَّاسُ فَقَالَ: يَا رَسُولَ اللَّهِ، أَعْطِنِي، فَإِنِّي فَادَيْتُ نَفْسِي، وَفَادَيْتُ عَقِيلاً فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : خُذْ. فَحَثَا فِي ثَوْبِهِ ثُمَّ ذَهَبَ يُقِلُّهُ فَلَمْ يَسْتَطِعْ، فَقَالَ: يَا رَسُولَ اللَّهِ اؤمر بَعْضَهُمْ يَرْفَعْهُ إِلَى قَالَ: لاَ قَالَ: فَارْفَعْهُ أَنْتَ علي قَالَ: لاَ فَنَثَرَ مِنْهُ ثُمَّ ذَهَبَ يُقِلُّهُ فَقَالَ: يَا رَسُولَ اللَّهِ اؤمر بَعْضَهُمْ يَرْفَعْهُ علي قَالَ: لاَ قَالَ: فَارْفَعْهُ أَنْتَ علي قَالَ: لاَ فَنَثَرَ مِنْهُ ثُمَّ احْتَمَلَهُ فألقاه عَلَى كَاهِلِهِ ثُمَّ انْطَلَقَ فَمَا زَالَ رسول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُتْبِعُهُ بَصَرَهُ حَتَّى خَفِيَ عَلَيْنَا عَجَبًا مِنْ حِرْصِهِ، فَمَا قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، وثَمَّ مِنْهَا دِرْهَمٌ."],"takhrij":"حسن: أورده البخاري في الجزية (3165) فقال: قال إبراهيم يعني ابن طهمان- عن عبد العزيز بن صهيب، عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب قسمة مال الجزية على مصالح المسلمين","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Hasan: Al-Bukhari (3165) cited it in suspended form, and al-Hafiz connected it in Taghliq al-Taʿliq (2/227).","chapter_en":"Dividing the Wealth of Jizyah for the Interests of the Muslims","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ was brought wealth from Bahrain. He said: “Scatter it in the mosque.” It was the greatest amount of wealth ever brought to the Messenger of Allah ﷺ. The Messenger of Allah ﷺ went out to prayer and did not look at it. When he finished the prayer, he came and sat beside it, and he did not see anyone except that he gave him from it. Then al-ʿAbbas came and said: “O Messenger of Allah, give me, for I ransomed myself and ransomed ʿAqil.” The Messenger of Allah ﷺ said to him: “Take.” He scooped some into his garment, then tried to lift it but could not. He said: “O Messenger of Allah, order some of them to lift it for me.” He said: “No.” He said: “Then lift it upon me yourself.” He said: “No.” So he scattered some of it, then tried to lift it and said: “O Messenger of Allah, order some of them to lift it upon me.” He said: “No.” He said: “Then lift it upon me yourself.” He said: “No.” So he scattered some of it, then carried it and placed it on his shoulder, and left. The Messenger of Allah ﷺ continued following him with his gaze until he disappeared from us, amazed at his eagerness. The Messenger of Allah ﷺ did not stand while even a single dirham remained from it there."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: أورده البخاري (3165) معلقا، ووصله الحافظ في تغليق التعليق (2/227)."},{"num":8167,"demo":false,"sanad":"","matn":["عَنْ مُعَاذٍ بن جَبَلٍ قَالَ: بَعَثَنِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْيَمَنِ، فَأَمَرَنِي أَنْ آخُذَ مِنْ كُلِّ ثَلاَثِينَ بقرة تَبِيعًا أَوْ تَبِيعَةً، وَمِنْ كُلِّ أَرْبَعِينَ مُسِنَّةً، وَمِنْ كُلِّ حَالِمٍ دِينَارًا أَوْ عِدْلَهُ معافر."],"takhrij":"صحيح: رواه أبو داود (1576)، والترمذي (623) -واللفظ له-، والنسائي (2455)، وابن ماجه (1803)، وأحمد (22013)، وابن خزيمة (2267)، وابن حبان (4886)، والحاكم (1449) كلهم من طريق الأعمش، عن أبي وائل، عن مسروق، عن معاذ بن جبل فذكره.","grade":"صحيح","chapter_ar":"باب ما يؤخذ في الجزية","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1576), al-Tirmidhi (623), whose wording this is, al-Nasa’i (2455), Ibn Majah (1803), Ahmad (22013), Ibn Khuzaymah (2267), Ibn Hibban (4886), and al-Hakim (1/398).","chapter_en":"What Is Taken as Jizyah","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Muʿadh ibn Jabal said: The Prophet ﷺ sent me to Yemen and ordered me to take from every thirty cattle a one-year-old male or female calf, from every forty a two-year-old cow, and from every adult one dinar or its equivalent in Maʿafir cloth."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1576)، والترمذي (623) — واللفظ له —، والنسائي (2455)، وابن ماجه (1803)، وأحمد (22013)، وابن خزيمة (2267)، وابن حبان (4886)، والحاكم (1449)."},{"num":8168,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: صَالَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَهْلَ نَجْرَانَ عَلَى أَلْفَيْ حُلَّةٍ، النِّصْفُ فِي صَفَرٍ، وَالْبَقِيَّةُ فِي رَجَبٍ، يُؤَدُّونَهَا إِلَى الْمُسْلِمِينَ، وَعَارِيَةِ ثَلَاثِينَ دِرْعًا، وَثَلَاثِينَ فَرَسًا، وَثَلَاثِينَ بَعِيرًا، وَثَلَاثِينَ مِنْ كُلِّ صِنْفٍ مِنْ أَصْنَافِ السِّلَاحِ، يَغْزُونَ بِهَا، وَالْمُسْلِمُونَ ضَامِنُونَ لَهَا حَتَّى يَرُدُّوهَا عَلَيْهِمْ إِنْ كَانَ بِالْيَمَنِ كَيْدٌ أَوْ غَدْرَةٌ، عَلَى أَنْ لَا يُهْدَمَ لَهُمْ بَيْعَةٌ، وَلَا يُخْرَجَ لَهُمْ قَسٌّ، وَلَا يُفْتَنُوا عَنْ دِينِهِمْ مَا لَمْ يُحْدِثُوا حَدَثًا، أَوْ يَأْكُلُوا الرِّبَا."],"takhrij":"حسن: رواه أبو داود (3043)، والبيهقي (18680)، والضياء في المختارة (492) كلهم من حديث يونس بن بكير، حدثنا أسباط بن نصر الهمدانى، عن إسماعيل بن عبد الرحمن القرشي، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب ما يؤخذ في الجزية","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3043), al-Bayhaqi (9/187), and al-Diya’ in al-Mukhtarah (9/508).","chapter_en":"What Is Taken as Jizyah","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ made peace with the people of Najran for two thousand garments: half in Safar and half in Rajab, to be paid to the Muslims; and the loan of thirty coats of armor, thirty horses, thirty camels, and thirty of each type of weapon, with which campaigns could be undertaken. The Muslims would guarantee them until they returned them to the people of Najran if there was treachery or danger in Yemen. This was on the condition that no church of theirs be demolished, no priest of theirs be expelled, and that they not be put to trial regarding their religion, so long as they did not introduce a new offense or consume usury."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3043)، والبيهقي (18680)، والضياء في المختارة (492)."},{"num":8169,"demo":false,"sanad":"","matn":["عن ابن عباس أنه قال عن هذه الآية ﴿فَإِنْ جَاءُوكَ فَاحْكُمْ بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ﴾ [المائدة: 42] نُسخت بقوله تعالى: ﴿فَاحْكُمْ بَيْنَهُمْ بِمَا أَنْزَلَ اللَّهُ﴾ [المائدة: 48]."],"takhrij":"حسن: رواه أبو داود (3590) عن أحمد بن محمد المروزى، حدثنى على بن حسين، عن أبيه، عن يزيد النحوى، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب الحكم بين الرعية من غير المسلمين","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3590).","chapter_en":"Judging Between Non-Muslim Subjects","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿAbbas said about this verse: “So if they come to you, judge between them or turn away from them” [al-Ma’idah: 42]: It was abrogated by His statement, Most High: “So judge between them by what Allah has revealed” [al-Ma’idah: 48]."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3590)."},{"num":8170,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَا تَبْدَءُوا الْيَهُودَ وَلَا النَّصَارَى بِالسَّلَامِ، فَإِذَا لَقِيتُمْ أَحَدَهُمْ فِي طَرِيقٍ فَاضْطَرُّوهُ إِلَى أَضْيَقِهِ."],"takhrij":"صحيح: رواه مسلم في السلام (2167) عن قتيبة بن سعيد، حدثنا عبد العزيز -يعني الدراوردي-، عن سهيل، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب كراهة بدء السلام بغير المسلمين وكيف يرد عليهم","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2167).","chapter_en":"The Dislike of Initiating Salām to Non-Muslims and How to Reply to Them","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Do not initiate salām to the Jews or Christians. If you meet one of them on a road, then make him go to its narrowest part.”"]}},"tuhfa":{},"full":1,"rep":[14247],"tks":"صحيح: رواه مسلم (2167)."},{"num":8171,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ:  سَلَّمَ نَاسٌ مِنْ يَهُودَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: السَّامُ عَلَيْكَ يَا أَبَا الْقَاسِمِ! فَقَالَ: وَعَلَيْكُمْ. فَقَالَتْ عَائِشَةُ وَغَضِبَتْ: أَلَمْ تَسْمَعْ مَا قَالُوا؟ قَالَ: بَلَى، قَدْ سَمِعْتُ فَرَدَدْتُ عَلَيْهِمْ، وَإِنَّا نُجَابُ عَلَيْهِمْ وَلَا يُجَابُونَ عَلَيْنَا."],"takhrij":"صحيح: رواه مسلم في السلام (2166) من طرق عن حجاج بن محمد قال: قال ابن جريج: أخبرني أبو الزبير أنه سمع جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب كراهة بدء السلام بغير المسلمين وكيف يرد عليهم","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2166).","chapter_en":"The Dislike of Initiating Salām to Non-Muslims and How to Reply to Them","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: Some Jews greeted the Messenger of Allah ﷺ and said: “Al-sām be upon you, O Abu al-Qasim.” He said: “And upon you.” ʿA’ishah became angry and said: “Did you not hear what they said?” He said: “Yes, I heard, and I replied to them. Our supplication against them is answered, while theirs against us is not answered.”"]}},"tuhfa":{},"full":1,"rep":[13506,14250],"tks":"صحيح: رواه مسلم (2166)."},{"num":8172,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: دَخَلَ رَهْطٌ مِنَ الْيَهُودِ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: السَّامُ عَلَيْكَ فَفَهِمْتُهَا فَقُلْتُ: عَلَيْكُمُ السَّامُ وَاللَّعْنَةُ فَقَالَ رَسُولُ اللَّهِ : صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَهْلاً يَا عَائِشَةُ فَإِنَّ اللَّهَ يُحِبُّ الرِّفْقَ فِي الأَمْرِ كُلِّهِ فَقُلْتُ: يَا رَسُولَ اللَّهِ أَوَلَمْ تَسْمَعْ مَا قَالُوا؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : فَقَدْ قُلْتُ: وَعَلَيْكُمْ."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6256) ومسلم في السلام (2165) كلاهما من طرق عن الزهري، عن عروة، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب كراهة بدء السلام بغير المسلمين وكيف يرد عليهم","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6256) and Muslim (2165). In a narration with al-Bukhari (6030): “Did you not hear what I said? I returned it upon them, so my supplication against them will be answered, while theirs against me will not be answered.” With Muslim: “I said: Rather, upon you be al-sām and al-dhām.”","chapter_en":"The Dislike of Initiating Salām to Non-Muslims and How to Reply to Them","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["ʿA’ishah said: A group of Jews entered upon the Messenger of Allah ﷺ and said: “Al-sām be upon you.” I understood it and said: “Upon you be al-sām and the curse.” The Messenger of Allah ﷺ said: “Slow down, O ʿA’ishah, for Allah loves gentleness in every matter.” I said: “O Messenger of Allah, did you not hear what they said?” The Messenger of Allah ﷺ said: “I already said: ‘And upon you.’”"]},"buhuth":{"en":["“Al-sām and al-dhām”: al-sām means death, and al-dhām means blame or defect."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6256)، ومسلم (2165). وفي رواية عند البخاري (6030): ((أولم تسمعي ما قلت؟ رددت عليهم، فيستجاب لي فيهم، ولا يستجاب لهم في)). وعند مسلم: ((قلت: بل عليكم السام والذام))."},{"num":8173,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إن الْيَهُودُ إِذَا سلّم عَلَيْكُمُ أَحَدُهُمُ فَإِنَّمَا يَقُولُ: السَّامُ عَلَيْكُمُ، فَقُلْ: عَلَيْكَ."],"takhrij":"متفق عليه: رواه مالك في السلام (3) عن عبد الله بن دينار، عن عبد الله بن عمر فذكره. ورواه البخاري في الاستئذان (6257) من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب كراهة بدء السلام بغير المسلمين وكيف يرد عليهم","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (3), al-Bukhari (6257), and Muslim (2164).","chapter_en":"The Dislike of Initiating Salām to Non-Muslims and How to Reply to Them","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “When one of the Jews greets you, he is only saying: ‘Al-sām be upon you,’ so say: ‘Upon you.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14249],"tks":"متفق عليه: رواه مالك (3)، والبخاري (6257)، ومسلم (2164)."},{"num":8174,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا سَلَّمَ عَلَيْكُمْ أَهْلُ الْكِتَابِ فَقُولُوا: وَعَلَيْكُمْ.","وَفِي لفظ: إِنَّ أَهْلَ الْكِتَابِ يُسَلِّمُونَ عَلَيْنَا فَكَيْفَ نَرُدُّ عَلَيْهِمْ؟ قَالَ: قُولُوا: وَعَلَيْكُمْ."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6258)، ومسلم في السلام (2163: 6) من طرق عن هشيم، أخبرنا عبيد الله بن أبي بكر بن أنس، عن جده أنس بن مالك فذكره. ورواه مسلم (2163: 7) من طرق عن شعبة، عن قتادة عن أنس فذكر باللفظ الثاني.","grade":"متفق عليه","chapter_ar":"باب كراهة بدء السلام بغير المسلمين وكيف يرد عليهم","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6258) and Muslim (2163:6). Muslim (2163:7) also narrated it with the second wording.","chapter_en":"The Dislike of Initiating Salām to Non-Muslims and How to Reply to Them","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Anas said: The Prophet ﷺ said: “When the People of the Book greet you, say: ‘And upon you.’” In another wording: “The People of the Book greet us, so how should we reply to them?” He said: “Say: ‘And upon you.’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6258)، ومسلم (2163: 6). ورواه مسلم (2163: 7) باللفظ الثاني."},{"num":8175,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَصْرَةَ الْغِفَارِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَهُمْ يَوْمًا: إِنِّي رَاكِبٌ إِلَى يَهُودَ، فَمَنْ انْطَلَقَ مَعِي، فَإِنْ سَلَّمُوا عَلَيْكُمْ فَقُولُوا: وَعَلَيْكُمْ، فَانْطَلَقْنَا، فَلَمَّا جِئْنَاهُمْ وَسَلَّمُوا عَلَيْنَا فَقُلْنَا: وَعَلَيْكُمْ."],"takhrij":"حسن: رواه أحمد (27235) –واللفظ له-، والنسائي في الكبرى (10148) مختصرا من طرق عن عبد الحميد بن جعفر، أخبرني يزيد بن أبي حبيب، عن مرثد بن عبد الله، عن أبي بصرة الغفاري فذكره.","grade":"حسن","chapter_ar":"باب كراهة بدء السلام بغير المسلمين وكيف يرد عليهم","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (27235) — this is his wording — and al-Nasa’i in al-Kubra (10148).","chapter_en":"The Dislike of Initiating Salām to Non-Muslims and How to Reply to Them","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Abu Basrah al-Ghifari said: The Messenger of Allah ﷺ said to them one day: “I am riding to the Jews, so whoever goes with me, if they greet you, say: ‘And upon you.’” So we set out. When we came to them and they greeted us, we said: “And upon you.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14251],"tks":"حسن: رواه أحمد (27235) — واللفظ له — والنسائي في الكبرى (10148)."},{"num":8176,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو، أنّ النبيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بلِّغوا عنّي وَلَوْ آيَةً، وَحَدِّثُوا عَنْ بَنِي إِسْرَائِيلَ وَلاَ حَرَجَ، وَمَنْ كَذَبَ عليَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ."],"takhrij":"صحيح: رواه البخاريّ في أحاديث الأنبياء (3461)عن أبي عاصم الضحاك بن مخلد، أخبرنا الأوزاعيّ، حدّثنا حسان بن عطية، عن أبي كبشة، عن عبدالله بن عمرو بن العاص فذكره.","grade":"صحيح","chapter_ar":"باب الرخصة في الحديث عن بني إسرائيل","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3461).","chapter_en":"The Concession to Narrate from the Children of Israel","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr narrated that the Prophet ﷺ said: “Convey from me, even if it is one verse; narrate from the Children of Israel, and there is no harm. Whoever deliberately lies about me, let him take his seat in the Fire.”"]}},"tuhfa":{},"full":1,"rep":[1181,1261,8275],"tks":"صحيح: رواه البخاري (3461)."},{"num":8177,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: كَانَ أَهْلُ الْكِتَابِ يقرؤون التَّوْرَاةَ بالعبريّة وَيُفَسِّرُونَهَا بِالْعَرَبِيَّةِ لأَهْلِ الإِسْلاَمِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : لاَ تُصَدِّقُوا أَهْلَ الْكِتَابِ وَلاَ تُكَذِّبُوهُمْ، قُولُوا آمَنَّا بِاللَّهِ وَمَا أُنْزِلَ إِلَيْنَا - الآيَةَ [سورة الْبَقَرَةِ: 136]."],"takhrij":"صحيح: رواه البخاريّ في التفسير (4485)، ثنا محمد بن بشار، حدّثنا عثمان بن عمر، أخبرنا علي بن المبارك، عن يحيى بن أبي كثير، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الرخصة في الحديث عن بني إسرائيل","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4485).","chapter_en":"The Concession to Narrate from the Children of Israel","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["Abu Hurayrah said: The People of the Book used to recite the Torah in Hebrew and explain it in Arabic to the people of Islam. The Messenger of Allah ﷺ said: “Do not believe the People of the Book and do not deny them. Say: ‘We believe in Allah and what has been sent down to us…’” the verse [Surat al-Baqarah: 136]."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (4485)."},{"num":8178,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ قَالَ: يَوْمُ الْخَمِيسِ، وَمَا يَوْمُ الْخَمِيسِ؟ ثُمَّ بَكَى حَتَّى خَضَبَ دَمْعُهُ الْحَصْبَاءَ فَقَالَ: اشْتَدَّ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَجَعُهُ يَوْمَ الْخَمِيسِ فَقَالَ: ائْتُونِي بِكِتَابٍ أَكْتُبْ لَكُمْ كِتَابًا لَنْ تَضِلُّوا بَعْدَهُ أَبَدًا. فَتَنَازَعُوا وَلاَ يَنْبَغِي عِنْدَ نَبِيٍّ تَنَازُعٌ فَقَالُوا: هَجَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: دَعُونِي فَالَّذِي أَنَا فِيهِ خَيْرٌ مِمَّا تَدْعُونِي إِلَيْهِ. وَأَوْصَى عِنْدَ مَوْتِهِ بِثَلاَثٍ: أَخْرِجُوا الْمُشْرِكِينَ مِنْ جَزِيرَةِ الْعَرَبِ، وَأَجِيزُوا الْوَفْدَ بِنَحْوِ مَا كُنْتُ أُجِيزُهُمْ. وَنَسِيتُ الثَّالِثَةَ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (3053)، ومسلم في الوصية (1637: 20) كلاهما من طريق سفيان بن عيينة، عن سليمان الأحول، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب إخراج المشركين واليهود والنصارى من جزيرة العرب","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3053) and Muslim (1637:20).","chapter_en":"Expelling the Polytheists, Jews, and Christians from the Arabian Peninsula","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Ibn ʿAbbas said: “Thursday — and what a Thursday!” Then he wept until his tears wet the pebbles. He said: The pain of the Messenger of Allah ﷺ became severe on Thursday, and he said: “Bring me writing materials so that I may write for you a document after which you will never go astray.” They disputed, and dispute is not proper in the presence of a Prophet. They said: “Has the Messenger of Allah ﷺ become delirious?” He said: “Leave me, for what I am in is better than what you are calling me to.” At his death, he gave three instructions: “Expel the polytheists from the Arabian Peninsula, and grant delegations gifts similar to what I used to grant them.” And I forgot the third."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3053)، ومسلم (1637: 20)."},{"num":8179,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَيْنَمَا نَحْنُ فِي الْمَسْجِدِ خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: انْطَلِقُوا إِلَى يَهُودَ. فَخَرَجْنَا حَتَّى جِئْنَا بَيْتَ الْمِدْرَاسِ، فَقَالَ: أَسْلِمُوا تَسْلَمُوا، وَاعْلَمُوا أَنَّ الأَرْضَ لِلَّهِ وَرَسُولِهِ، وَإِنِّي أُرِيدُ أَنْ أُجْلِيَكُمْ مِنْ هَذِهِ الأَرْضِ، فَمَنْ يَجِدْ مِنْكُمْ بِمَالِهِ شَيْئًا فَلْيَبِعْهُ، وَإِلاَّ فَاعْلَمُوا أَنَّ الأَرْضَ لِلَّهِ وَرَسُولِهِ."],"takhrij":"متفق عليه: رواه البخاري في الجزية (3167)، ومسلم في الجهاد والسير (1765: 61) كلاهما من طريق الليث، حدثني سعيد المقبري، عن أبيه، عن أبي هريرة فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب إخراج المشركين واليهود والنصارى من جزيرة العرب","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3167) and Muslim (1765:61). The wording is al-Bukhari’s.","chapter_en":"Expelling the Polytheists, Jews, and Christians from the Arabian Peninsula","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Abu Hurayrah said: While we were in the mosque, the Prophet ﷺ came out and said: “Go to the Jews.” So we went out until we came to the house of study. He said: “Accept Islam and you will be safe. Know that the land belongs to Allah and His Messenger, and I intend to expel you from this land. Whoever among you finds something for his property, let him sell it; otherwise, know that the land belongs to Allah and His Messenger.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3167)، ومسلم (1765: 61). واللفظ للبخاري."},{"num":8180,"demo":false,"sanad":"","matn":["عن عُمَرَ بن الْخَطَّابِ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  لَأُخْرِجَنَّ الْيَهُودَ وَالنَّصَارَى مِنْ جَزِيرَةِ الْعَرَبِ، حَتَّى لَا أَدَعَ إِلَّا مُسْلِمًا."],"takhrij":"صحيح: رواه مسلم في الجهاد والسير (1767: 63) من طريق ابن جريج، أخبرني أبو الزبير انه سمع جابر بن عبد الله يقول: أخبرني عمر بن الخطاب فذكره.","grade":"صحيح","chapter_ar":"باب إخراج المشركين واليهود والنصارى من جزيرة العرب","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1767:63).","chapter_en":"Expelling the Polytheists, Jews, and Christians from the Arabian Peninsula","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["ʿUmar ibn al-Khattab heard the Messenger of Allah ﷺ say: “I will surely expel the Jews and Christians from the Arabian Peninsula until I leave none but Muslims.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1767: 63)."},{"num":8181,"demo":false,"sanad":"","matn":["عَنْ أَبِي عُبَيْدَةَ، قَالَ: آخِرُ مَا تَكَلَّمَ بِهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَخْرِجُوا يَهُودَ أَهْلِ الْحِجَازِ، وَأَهْلِ نَجْرَانَ مِنْ جَزِيرَةِ الْعَرَبِ، وَاعْلَمُوا أَنَّ شِرَارَ النَّاسِ الَّذِينَ اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ."],"takhrij":"حسن: رواه أحمد (1691) عن يحيى بن سعيد، حدثنا إبراهيم بن ميمون، حدثنا سعد بن سمرة بن جندب، عن أبيه، عن أبي عبيدة فذكره.","grade":"حسن","chapter_ar":"باب إخراج المشركين واليهود والنصارى من جزيرة العرب","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (1691).","chapter_en":"Expelling the Polytheists, Jews, and Christians from the Arabian Peninsula","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Abu ʿUbaydah said: The last words spoken by the Prophet ﷺ were: “Expel the Jews of the people of the Hijaz and the people of Najran from the Arabian Peninsula. Know that the worst of people are those who took the graves of their prophets as places of worship.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9336],"tks":"حسن: رواه أحمد (1691)."},{"num":8182,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: كَانَ آخِرُ مَا عَهِدَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ قَالَ: لَا يُتْرَكُ بِجَزِيرَةِ الْعَرَبِ دِينَانِ."],"takhrij":"حسن: رواه أحمد (26352)، والطبراني في الأوسط (2691- مجمع البحرين) كلاهما من طريق ابن إسحاق قال: حدثني صالح بن كيسان، عن الزهري، عن عبيدالله بن عبد الله بن عتبة، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب إخراج المشركين واليهود والنصارى من جزيرة العرب","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (26352) and al-Tabarani in al-Awsat (2691 — Majmaʿ al-Bahrayn), both through Ibn Ishaq, who said: Salih ibn Kaysan narrated to me, from al-Zuhri, from ʿUbayd Allah ibn ʿAbdullah ibn ʿUtbah, from ʿA’ishah, who mentioned it.","chapter_en":"Expelling the Polytheists, Jews, and Christians from the Arabian Peninsula","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["The Mother of the Believers ʿA’ishah said: Among the final instructions of the Messenger of Allah ﷺ was that he said: “Two religions are not to be left in the Arabian Peninsula.”"]},"buhuth":{"en":["Its chain is good because of Muhammad ibn Ishaq.","Al-Haythami said in al-Majmaʿ (5/325): “The men of Ahmad are the men of the authentic collections except Ibn Ishaq, and he clearly stated that he heard it.”","Malik narrated in al-Jamiʿ (17), from Ibn Shihab, that the Messenger of Allah ﷺ said: “Two religions shall not gather in the Arabian Peninsula.”","However, Ibn ʿAbd al-Barr decisively stated that this hadith is connected through good routes from the Prophet ﷺ, and he mentioned among them the hadith of ʿA’ishah. See al-Tamhid (12/13)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (26352)، والطبراني في الأوسط (2691 — مجمع البحرين)."},{"num":8183,"demo":false,"sanad":"","matn":["عن أُمِّ سَلَمَةَ، قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَخْرِجُوا الْيَهُودَ مِنْ جَزِيرَةِ الْعَرَبِ."],"takhrij":"حسن: رواه الطبراني في الكبير (23/ح 560) من حديث وهب بن جرير، ثنا أبي، عن يحيى بن أيوب، عن يزيد بن أبي حبيب، عن أبي سلمة، عن أم سلمة فذكرته. وإسناده حسن من أجل يحيى بن أيوب وهو الغافقي المصري فإنه حسن الحديث. وأبو سلمة هو ابن عبد الرحمن بن عوف الزهري.","grade":"حسن","chapter_ar":"باب إخراج المشركين واليهود والنصارى من جزيرة العرب","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (23/265) through Wahb ibn Jarir, from his father, from Yahya ibn Ayyub, from Yazid ibn Abi Habib, from Abu Salamah, from Umm Salamah. Its chain is good due to Yahya ibn Ayyub al-Ghafiqi al-Misri, whose hadith is hasan; Abu Salamah is Ibn ʿAbd al-Rahman ibn ʿAwf al-Zuhri. As for the boundaries of the Arabian Peninsula, Saʿid ibn ʿAbd al-ʿAziz said: “The Arabian Peninsula is what lies between the valley to the farthest Yemen, to the borders of Iraq, to the sea.”","chapter_en":"Expelling the Polytheists, Jews, and Christians from the Arabian Peninsula","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Umm Salamah said: The Messenger of Allah ﷺ said: “Expel the Jews from the Arabian Peninsula.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (23/ح 560)."},{"num":8184,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَمَّا فَدَعَ أَهْلُ خَيْبَرَ عَبْدَ اللَّهِ بْنَ عُمَرَ، قَامَ عُمَرُ خَطِيبًا فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ عَامَلَ يَهُودَ خَيْبَرَ عَلَى أَمْوَالِهِمْ، وَقَالَ: نُقِرُّكُمْ مَا أَقَرَّكُمُ اللَّهُ. وَإِنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ خَرَجَ إِلَى مَالِهِ هُنَاكَ فَعُدِيَ عَلَيْهِ مِنَ اللَّيْلِ، فَفُدِعَتْ يَدَاهُ وَرِجْلاَهُ، وَلَيْسَ لَنَا هُنَاكَ عَدُوٌّ غَيْرُهُمْ، هُمْ عَدُوُّنَا وَتُهَمَتُنَا، وَقَدْ رَأَيْتُ إِجْلاَءَهُمْ، فَلَمَّا أَجْمَعَ عُمَرُ عَلَى ذَلِكَ أَتَاهُ أَحَدُ بَنِي أَبِي الْحُقَيْقِ، فَقَالَ: يَا أَمِيرَ الْمُؤْمِنِينَ، أَتُخْرِجُنَا وَقَدْ أَقَرَّنَا مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَامَلَنَا عَلَى الأَمْوَالِ، وَشَرَطَ ذَلِكَ لَنَا؟ فَقَالَ عُمَرُ: أَظَنَنْتَ أَنِّي نَسِيتُ قَوْلَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَيْفَ بِكَ إِذَا أُخْرِجْتَ مِنْ خَيْبَرَ تَعْدُو بِكَ قَلُوصُكَ، لَيْلَةً بَعْدَ لَيْلَةٍ. فَقَالَ: كَانَتْ هَذِهِ هُزَيْلَةً مِنْ أَبِي الْقَاسِمِ. قَالَ: كَذَبْتَ يَا عَدُوَّ اللَّهِ. فَأَجْلاَهُمْ عُمَرُ وَأَعْطَاهُمْ قِيمَةَ مَا كَانَ لَهُمْ مِنَ الثَّمَرِ مَالاً وَإِبِلاً وَعُرُوضًا، مِنْ أَقْتَابٍ وَحِبَالٍ وَغَيْرِ ذَلِكَ."],"takhrij":"صحيح: رواه البخاري في الشروط (2730) عن أبي أحمد مرار بن حمويه حدثنا محمد بن يحيى أبو غسان الكناني، أخبرنا مالك، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب إخراج المشركين واليهود والنصارى من جزيرة العرب","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2730).","chapter_en":"Expelling the Polytheists, Jews, and Christians from the Arabian Peninsula","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Ibn ʿUmar said: When the people of Khaybar dislocated the hands and feet of ʿAbdullah ibn ʿUmar, ʿUmar stood as a preacher and said: The Messenger of Allah ﷺ had made an agreement with the Jews of Khaybar over their properties and said: “We will let you remain as long as Allah lets you remain.” ʿAbdullah ibn ʿUmar went out to his property there and was attacked at night; his hands and feet were dislocated. We have no enemy there except them; they are our enemy and the ones under suspicion. I have decided to expel them. When ʿUmar resolved to do that, one of Banu Abi al-Huqayq came to him and said: “O Commander of the Believers, will you expel us when Muhammad ﷺ allowed us to remain, made an agreement with us over the properties, and stipulated that for us?” ʿUmar said: “Do you think I have forgotten the statement of the Messenger of Allah ﷺ: ‘How will you be when you are expelled from Khaybar, with your young she-camel carrying you night after night?’” He said: “That was only a joke from Abu al-Qasim.” He said: “You have lied, O enemy of Allah.” So ʿUmar expelled them and gave them the value of what they had of fruits in money, camels, and goods, such as saddles, ropes, and other things."]}},"tuhfa":{},"full":1,"rep":[9048],"tks":"صحيح: رواه البخاري (2730)."},{"num":8185,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، قَالَ: خَرَجْتُ أَنَا وَالزُّبَيْرُ والْمِقْدَادُ بْنُ الْأَسْوَدِ إِلَى أَمْوَالِنَا بِخَيْبَرَ نَتَعَاهَدُهَا، فَلَمَّا قَدِمْنَاهَا تَفَرَّقْنَا فِي أَمْوَالِنَا، قَالَ: فَعُدِيَ عَلَيَّ تَحْتَ اللَّيْلِ، وَأَنَا نَائِمٌ عَلَى فِرَاشِي، فَفُدِعَتْ يَدَايَ مِنْ مِرْفَقَيَّ، فَلَمَّا أَصْبَحْتُ اسْتُصْرِخَ عَلَيَّ صَاحِبَايَ، فَأَتَيَانِي، فَسَأَلانِي عَمَّنْ صَنَعَ هَذَا بِكَ؟ قُلْتُ: لَا أَدْرِي، قَالَ: فَأَصْلَحَا مِنْ يَدَيَّ، ثُمَّ قَدِمُوا بِي عَلَى عُمَرَ فَقَالَ: هَذَا عَمَلُ يَهُودَ. ثُمَّ قَامَ فِي النَّاسِ خَطِيبًا، فَقَالَ: أَيُّهَا النَّاسُ، إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ عَامَلَ يَهُودَ خَيْبَرَ عَلَى أَنَّا نُخْرِجُهُمْ إِذَا شِئْنَا، وَقَدْ عَدَوْا عَلَى عَبْدِ اللَّهِ بْنِ عُمَرَ فَفَدَعُوا يَدَيْهِ كَمَا بَلَغَكُمْ، مَعَ عَدْوَتِهِمْ عَلَى الْأَنْصَارِيِّ قَبْلَهُ، لَا نَشُكُّ أَنَّهُمْ أَصْحَابُهُمْ، لَيْسَ لَنَا هُنَاكَ عَدُوٌّ غَيْرَهُمْ، فَمَنْ كَانَ لَهُ مَالٌ بِخَيْبَرَ فَلْيَلْحَقْ بِهِ فَإِنِّي مُخْرِجٌ يَهُودَ. فَأَخْرَجَهُمْ."],"takhrij":"حسن: رواه أحمد (90) عن يعقوب –هو ابن إبراهيم- حدثنا أبي عن ابن إسحاق قال حدثني نافع مولى عبد الله بن عمر، عن عبد الله بن عمر فذكره.","grade":"حسن","chapter_ar":"باب إخراج المشركين واليهود والنصارى من جزيرة العرب","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (90).","chapter_en":"Expelling the Polytheists, Jews, and Christians from the Arabian Peninsula","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: I, al-Zubayr, and al-Miqdad ibn al-Aswad went out to our properties in Khaybar to inspect them. When we arrived, we separated among our properties. He said: I was attacked during the night while I was asleep on my bed, and my hands were dislocated from my elbows. In the morning, my two companions were called to help me, and they came and asked me: “Who did this to you?” I said: “I do not know.” He said: They set my hands right, then brought me to ʿUmar. He said: “This is the work of the Jews.” Then he stood among the people as a preacher and said: “O people, the Messenger of Allah ﷺ had made an agreement with the Jews of Khaybar on the basis that we could expel them whenever we wished. They have attacked ʿAbdullah ibn ʿUmar and dislocated his hands, as has reached you, along with their previous attack on the Ansari. We do not doubt that they were involved; we have no enemy there except them. Whoever has property in Khaybar should go to it, for I am expelling the Jews.” So he expelled them."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9050],"tks":"حسن: رواه أحمد (90)."},{"num":8186,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : وَالَّذِي نَفْسِي بِيَدِهِ لَيُوشِكَنَّ أَنْ يَنْزِلَ فِيكُمُ ابْنُ مَرْيَمَ حَكَمًا مُقْسِطًا فَيَكْسِرَ الصَّلِيبَ، وَيَقْتُلَ الْخِنْزِيرَ، وَيَضَعَ الْجِزْيَةَ، وَيَفِيضَ الْمَالُ حَتَّى لاَ يَقْبَلَهُ أَحَدٌ."],"takhrij":"متفق عليه: رواه البخاري في البيوع (2222)، ومسلم في الإيمان (155: 242) كلاهم عن قتيبة بن سعيد، حدثنا الليث، عن ابن شهاب، عن ابن المسيب أنه سمع ابا هريرة يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب وضع الجزية في آخر الزمان","chapter_ur":"","part_ar":"كتاب أحكام أهل الذمة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2222) and Muslim (155:242).","chapter_en":"The Lifting of Jizyah at the End of Time","part_en":"Book of the Rulings Concerning the People of Dhimmah","group_ar":"","group_en":"","part_no":44,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “By the One in whose hand is my soul, the son of Mary will soon descend among you as a just ruler. He will break the cross, kill the pig, abolish the jizyah, and wealth will overflow until no one accepts it.”"]},"buhuth":{"en":["In another narration: “Until a single prostration will be better than the world and all that is in it.” Then Abu Hurayrah would say: Recite, if you wish: “And there is none from the People of the Book except that he will surely believe in him before his death” [al-Nisa’: 159].","His saying, “he will abolish the jizyah,” means that ʿIsa, peace be upon him, will not accept from the People of the Book except Islam or being killed, unlike today; for if the disbelievers accept the jizyah, they are not compelled to enter Islam. This ruling continues until near the Hour. When ʿIsa, peace be upon him, descends, it will be abrogated by the ruling of the Prophet ﷺ, namely that ʿIsa, peace be upon him, will not accept except Islam or being killed.","His saying, “wealth will overflow,” is due to his justice, peace be upon him, and blessings will descend from the sky, so the produce of the earth will increase.","His saying, “before his death,” means before the death of ʿIsa, peace be upon him; for his descent to earth and his declaration that he is the servant of Allah and His Messenger refute the Christian belief in his deity. However, many exegetes held that the pronoun refers to the person from the People of the Book, meaning that before his death he will believe in the humanity of the Messiah and that he is the servant of Allah and His Messenger, but his faith will not benefit him at the moment of death, as is known."]}},"tuhfa":{},"full":1,"dr":1,"rep":[5820],"tks":"متفق عليه: رواه البخاري (2222)، ومسلم (155: 242)."},{"num":8187,"demo":false,"sanad":"","matn":["عن عمر بن الخطاب قال: قام فينا النبي صلى الله عليه وسلم مقاما، فأخبرنا عن بَدْء الخلق حتى دخل أهل الجنة منازلهم وأهل النار منازلهم، حفظ ذلك من حفظه ونسيه من نسي."],"takhrij":"صحيح: رواه الطبراني في مسند رقبة بن مصقلة من تأليفه، وابن مندة في أماليه، ومن طريقهما أخرجه الحافظ في التغليق (3/487) من رواية عيسى بن موسى، عن أبي حمزة، عن رقبة بن مصقلة، عن قيس بن مسلم، عن طارق بن شهاب سمعتُ عمر بن الخطاب يقول: فذكره.","grade":"صحيح","chapter_ar":"باب إخبار النبي ﷺ عن بدء الخلق","chapter_ur":"","part_ar":"كتاب بدء الخلق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tabarani and Ibn Mandah, and through their route al-Hafiz narrated it in Taghliq al-Taʿliq (3/487). Al-Bukhari narrated it in suspended form (3192).","chapter_en":"The Prophet ﷺ Informing About the Beginning of Creation","part_en":"Book of the Beginning of Creation","group_ar":"","group_en":"","part_no":45,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿUmar ibn al-Khattab said: The Prophet ﷺ stood among us in a gathering and informed us about the beginning of creation until the people of Paradise entered their dwellings and the people of the Fire entered their dwellings. Whoever memorized it memorized it, and whoever forgot it forgot it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني، وابن منده، ومن طريقهما رواه الحافظ في تغليق التعليق (3/487)، ورواه البخاري معلقا (3192)."},{"num":8188,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قَالَ اللَّهُ: كَذَّبَنِي ابْنُ آدَمَ وَلَمْ يَكُنْ لَهُ ذَلِكَ، وَشَتَمَنِي وَلَمْ يَكُنْ لَهُ ذَلِكَ، فَأَمَّا تَكْذِيبُهُ إِيَّاىَ فَقَوْلُهُ لَنْ يُعِيدَنِي كَمَا بَدَأَنِي، وَلَيْسَ أَوَّلُ الْخَلْقِ بِأَهْوَنَ عَلَىَّ مِنْ إِعَادَتِهِ، وَأَمَّا شَتْمُهُ إِيَّاىَ فَقَوْلُهُ اتَّخَذَ اللَّهُ وَلَدًا، وَأَنَا الأَحَدُ ﴿الصَّمَدُ لَمْ أَلِدْ وَلَمْ أُولَدْ وَلَمْ يَكُنْ﴾ [سورة الإخلاص: 2، 4] لِي كُفْأً أَحَدٌ."],"takhrij":"صحيح: رواه البخاري في التفسير (4974) عن أبي اليمان، عن شعيب حدثنا أبو الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب إخبار النبي ﷺ عن بدء الخلق","chapter_ur":"","part_ar":"كتاب بدء الخلق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4974).","chapter_en":"The Prophet ﷺ Informing About the Beginning of Creation","part_en":"Book of the Beginning of Creation","group_ar":"","group_en":"","part_no":45,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “Allah said: The son of Adam has denied Me, though he had no right to do so, and he has insulted Me, though he had no right to do so. As for his denial of Me, it is his saying: He will not bring me back as He created me first — while the first creation is not easier for Me than bringing it back. As for his insult of Me, it is his saying: Allah has taken a child — while I am the One, the Self-Sufficient Master; I neither beget nor was I begotten, and there is none comparable to Me.”"]},"buhuth":{"en":["Insult means describing someone with what implies deficiency. Ibn Hajar said this in al-Fath (6/291)."]}},"tuhfa":{},"full":1,"dr":1,"rep":[12716,12996,13378,13812,16133],"tks":"صحيح: رواه البخاري (4974)."},{"num":8189,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ قَالَ: قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  يَأْتِي الشَّيْطَانُ أَحَدَكُمْ فَيَقُولُ: مَنْ خَلَقَ كَذَا؟ وَكَذَا؟ حَتَّى يَقُولَ: لَهُ: مَنْ خَلَقَ رَبَّكَ؟ فَإِذَا بَلَغَ ذَلِكَ، فَلْيَسْتَعِذْ بِاللهِ، وَلْيَنْتَهِ."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3276)، ومسلم في الإيمان (214: 134) كلاهما من طريق الليث بن سعد، حدثني عقيل بن خالد قال: قال ابن شهاب أخبرني عروة بن الزبير أن أبا هريرة قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب في كراهية القول: “من خلق الله؟”","chapter_ur":"","part_ar":"كتاب بدء الخلق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3276) and Muslim (214:134). The wording is al-Bukhari’s.","chapter_en":"The Dislike of Saying, “Who Created Allah?”","part_en":"Book of the Beginning of Creation","group_ar":"","group_en":"","part_no":45,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Satan comes to one of you and says: Who created such-and-such? Who created such-and-such? Until he says: Who created your Lord? When it reaches that point, let him seek refuge in Allah and stop.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3276)، ومسلم (214: 134). واللفظ للبخاري."},{"num":8190,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ يَقُولُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَنْ يَبْرَحَ النَّاسُ يَتَسَاءَلُونَ حَتَّى يَقُولُوا: هَذَا اللَّهُ خَالِقُ كُلِّ شَىْءٍ، فَمَنْ خَلَقَ اللَّهَ."],"takhrij":"متفق عليه: رواه البخاري في الاعتصام (7296) عن الحسن بن صباح، حدثنا شبابة، حدثنا ورقاء عن عبدالله بن عبدالرحمن، سمعت أنس بن مالك يقول: فذكره. ورواه مسلم في الإيمان من وجه آخر عن المختار بن فلفل عن أنس به نحوه.","grade":"متفق عليه","chapter_ar":"باب في كراهية القول: “من خلق الله؟”","chapter_ur":"","part_ar":"كتاب بدء الخلق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7296) and Muslim (136:217).","chapter_en":"The Dislike of Saying, “Who Created Allah?”","part_en":"Book of the Beginning of Creation","group_ar":"","group_en":"","part_no":45,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ said: “People will continue asking questions until they say: This is Allah, the Creator of everything, so who created Allah?”"]}},"tuhfa":{},"full":1,"rep":[213],"tks":"متفق عليه: رواه البخاري (7296)، ومسلم (136: 217)."},{"num":8191,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، قَالَ: إِنِّي عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ جَاءَهُ قَوْمٌ مِنْ بَنِي تَمِيمٍ فَقَالَ: اقْبَلُوا الْبُشْرَى يَا بَنِي تَمِيمٍ. قَالُوا: بَشَّرْتَنَا فَأَعْطِنَا. فَدَخَلَ نَاسٌ مِنْ أَهْلِ الْيَمَنِ فَقَالَ: اقْبَلُوا الْبُشْرَى يَا أَهْلَ الْيَمَنِ إِذْ لَمْ يَقْبَلْهَا بَنُو تَمِيمٍ. قَالُوا: قَبِلْنَا. جِئْنَاكَ لِنَتَفَقَّهَ فِي الدِّينِ، وَلِنَسْأَلَكَ عَنْ أَوَّلِ هَذَا الأَمْرِ مَا كَانَ. قَالَ: كَانَ اللَّهُ وَلَمْ يَكُنْ شَىْءٌ قَبْلَهُ، وَكَانَ عَرْشُهُ عَلَى الْمَاءِ، ثُمَّ خَلَقَ السَّمَوَاتِ وَالأَرْضَ، وَكَتَبَ فِي الذِّكْرِ كُلَّ شَىْءٍ. ثُمَّ أَتَانِي رَجُلٌ فَقَالَ: يَا عِمْرَانُ أَدْرِكْ نَاقَتَكَ فَقَدْ ذَهَبَتْ فَانْطَلَقْتُ أَطْلُبُهَا، فَإِذَا السَّرَابُ يَنْقَطِعُ دُونَهَا، وَايْمُ اللَّهِ لَوَدِدْتُ أَنَّهَا قَدْ ذَهَبَتْ وَلَمْ أَقُمْ."],"takhrij":"صحيح: رواه البخاري في التوحيد (7418) عن عبدان، قال: أخبرنا أبو حمزة، عن الأعمش، عن جامع بن شداد، عن صفوان بن محرز، عن عمران بن حصين فذكره.","grade":"صحيح","chapter_ar":"باب كان الله ولم يكن شيء قبله","chapter_ur":"","part_ar":"كتاب بدء الخلق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7418).","chapter_en":"Allah Existed, and There Was Nothing Before Him","part_en":"Book of the Beginning of Creation","group_ar":"","group_en":"","part_no":45,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿImran ibn Husayn said: I was with the Prophet ﷺ when some people from Banu Tamim came to him. He said: “Accept the glad tidings, O Banu Tamim.” They said: “You have given us glad tidings, so give us.” Then some people from Yemen entered, and he said: “Accept the glad tidings, O people of Yemen, since Banu Tamim did not accept them.” They said: “We accept. We have come to you to gain understanding of the religion and to ask you about the beginning of this matter: what was it?” He said: “Allah existed, and there was nothing before Him. His Throne was upon the water. Then He created the heavens and the earth, and He wrote everything in the Reminder.” Then a man came to me and said: “O ʿImran, catch your she-camel, for it has gone away.” So I set off looking for it, and behold, the mirage was cutting off my view of it. By Allah, I wished it had gone away and that I had not stood up."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (7418)."},{"num":8192,"demo":false,"sanad":"","matn":["عن أَبِي رَزِينٍ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ أَيْنَ كَانَ رَبُّنَا قَبْلَ أَنْ يَخْلُقَ خَلْقَهُ؟ قَالَ: كَانَ فِي عَمَاءٍ، مَا تَحْتَهُ هَوَاءٌ، وَمَا فَوْقَهُ هَوَاءٌ، وَخَلَقَ عَرْشَهُ عَلَى الْمَاءِ."],"takhrij":"حسن: رواه الترمذي (3109)، وابن ماجه (182) كلاهما من طريق يزيد بن هارون، أخبرنا حماد بن سلمة، عن يعلى بن عطاء، عن وكيع بن حدس، عن عمه أبي رزين قال: فذكره.","grade":"حسن","chapter_ar":"باب كان الله ولم يكن شيء قبله","chapter_ur":"","part_ar":"كتاب بدء الخلق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (3109) and Ibn Majah (182).","chapter_en":"Allah Existed, and There Was Nothing Before Him","part_en":"Book of the Beginning of Creation","group_ar":"","group_en":"","part_no":45,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abu Razin said: I said: “O Messenger of Allah, where was our Lord before He created His creation?” He said: “He was in ‘amā’, with no air beneath it and no air above it, and He created His Throne upon the water.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3109)، وابن ماجه (182)."},{"num":8193,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قُلْتُ: يَارَسُولُ اللَّهَ! أَخْبِرْنِي مِمَّ خَلَقَ الْخَلْقَ؟ فَقَالَ: مِنَ الْمَاءِ."],"takhrij":"حسن: رواه إسحاق بن راهويه (301) عن أبي معاوية، نا حمزة الزيات، عن أبي مجاهد سعد الطائي، عن أبي مدلّة، عن أبي هريرة، فذكره في حديث طويل.","grade":"حسن","chapter_ar":"باب إن الماء أساس جميع المخلوقات الحية","chapter_ur":"","part_ar":"كتاب بدء الخلق","part_ur":"","takhrij_en":"Hasan: Narrated by Ishaq ibn Rahwayh (301), Ahmad (8043), ʿAbd ibn Humayd (1420), and Ibn Hibban (7387).","chapter_en":"Water Is the Foundation of All Living Created Things","part_en":"Book of the Beginning of Creation","group_ar":"","group_en":"","part_no":45,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: I said: “O Messenger of Allah, tell me: from what was creation created?” He said: “From water.”"]},"intro":{"ar":["قال الله تعالى:","(وَجَعَلْنَا مِنَ الْمَاءِ كُلَّ شَيْءٍ حَيٍّ ۖ أَفَلَا يُؤْمِنُونَ) [الأنبياء: ٣٠]."],"en":["Allah Most High said:","“And We made from water every living thing. Will they not then believe?” [al-Anbiya’: 30]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12751],"tks":"حسن: رواه إسحاق بن راهويه (301)، وأحمد (8043)، وعبد بن حميد (1420)، وابن حبان (7387)."},{"num":8194,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي إِذَا رَأَيْتُكَ طَابَتْ نَفْسِي، وَقَرَّتْ عَيْنِي، فَأَنْبِئْنِي عَنْ كُلِّ شَيْءٍ. فَقَالَ: كُلُّ شَيْءٍ خُلِقَ مِنْ مَاءٍ. قَالَ: قُلْتُ: أَنْبِئْنِي عَنْ أَمْرٍ إِذَا أَخَذْتُ بِهِ دَخَلْتُ الْجَنَّةَ. قَالَ: أَفْشِ السَّلَامَ، وَأَطْعِمِ الطَّعَامَ، وَصِلِ الْأَرْحَامَ، وَقُمْ بِاللَّيْلِ، وَالنَّاسُ نِيَامٌ، ثُمَّ ادْخُلِ الْجَنَّةَ بِسَلَامٍ."],"takhrij":"صحيح: رواه أحمد (7932)، وصحّحه ابن حبان (508)، والحاكم (7278) كلهم من طريق همام بن يحيى، عن قتادة، عن أبي ميمونة، عن أبي هريرة، قال: فذكره.","grade":"صحيح","chapter_ar":"باب إن الماء أساس جميع المخلوقات الحية","chapter_ur":"","part_ar":"كتاب بدء الخلق","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (7932), and authenticated by Ibn Hibban (508) and al-Hakim (7278).","chapter_en":"Water Is the Foundation of All Living Created Things","part_en":"Book of the Beginning of Creation","group_ar":"","group_en":"","part_no":45,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: I said: “O Messenger of Allah, when I see you, my soul becomes pleased and my eye is comforted, so inform me about everything.” He said: “Everything was created from water.” He said: I said: “Inform me of a deed that, if I hold to it, I will enter Paradise.” He said: “Spread peace, feed food, maintain family ties, and stand in prayer at night while people are asleep; then enter Paradise in peace.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[63,2680,12750,13660,13725,14216],"tks":"صحيح: رواه أحمد (7932)، وصححه ابن حبان (508)، والحاكم (7278)."},{"num":8195,"demo":false,"sanad":"","matn":["عن عُبَادَةَ بْنِ الصَّامِتِ لاِبْنِهِ: يَا بُنَىَّ إِنَّكَ لَنْ تَجِدَ طَعْمَ حَقِيقَةِ الإِيمَانِ حَتَّى تَعْلَمَ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ، وَمَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ. سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ أَوَّلَ مَا خَلَقَ اللَّهُ الْقَلَمَ، فَقَالَ لَهُ: اكْتُبْ. قَالَ: رَبِّ، وَمَاذَا أَكْتُبُ؟ قَالَ: اكْتُبْ مَقَادِيرَ كُلِّ شَىْءٍ حَتَّى تَقُومَ السَّاعَةُ. يَا بُنَىَّ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ مَاتَ عَلَى غَيْرِ هَذَا فَلَيْسَ مِنِّي."],"takhrij":"حسن: رواه أبو داود (4700) عن جعفر بن مسافر الهذليّ، حدّثنا يحيى بن حسّان، حدّثنا الوليد بن رباح، عن إبراهيم بن أبي عبلة، عن أبي حفصة، قال: قال عبادة بن الصّامت لابنه، فذكر الحديث.","grade":"حسن","chapter_ar":"باب خلق الله القلم بعد العرش والماء","chapter_ur":"","part_ar":"كتاب بدء الخلق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4700).","chapter_en":"Allah Created the Pen After the Throne and the Water","part_en":"Book of the Beginning of Creation","group_ar":"","group_en":"","part_no":45,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿUbadah ibn al-Samit said to his son: “My son, you will not taste the reality of faith until you know that what struck you could never have missed you, and what missed you could never have struck you. I heard the Messenger of Allah ﷺ say: ‘Indeed, the first thing Allah created was the Pen. He said to it: Write. It said: My Lord, what shall I write? He said: Write the decrees of everything until the Hour is established.’ My son, I heard the Messenger of Allah ﷺ say: ‘Whoever dies upon other than this is not from me.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4700)."},{"num":8196,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّهُ كَانَ يُحَدِّثُ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ: إِنَّ أَوَّلَ مَا خَلَقَ اللَّهُ الْقَلَمُ، وَأَمَرَهُ أَنْ يَكْتُبَ كُلَّ شَيْءٍ يَكُونُ."],"takhrij":"صحيح: رواه أبو يعلى (2329) عن أحمد بن جميل المروزيّ، حدّثنا عبدالله بن المبارك، عن رباح بن زيد، عن عمر بن حبيب المكيّ، عن القاسم بن أبي بزة، عن سعيد بن جبير، عن ابن عباس، فذكر مثله.","grade":"صحيح","chapter_ar":"باب خلق الله القلم بعد العرش والماء","chapter_ur":"","part_ar":"كتاب بدء الخلق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Yaʿla (2329) and ʿAbdullah ibn Ahmad in al-Sunnah (854).","chapter_en":"Allah Created the Pen After the Throne and the Water","part_en":"Book of the Beginning of Creation","group_ar":"","group_en":"","part_no":45,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbas used to narrate that the Messenger of Allah ﷺ said: “Indeed, the first thing Allah created was the Pen, and He commanded it to write everything that would occur.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[993],"tks":"صحيح: رواه أبو يعلى (2329)، وعبد الله بن أحمد في السنة (854)."},{"num":8197,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: سَمِعْتُ رَسُولَ اللَّهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أوّل مَا خَلَقَ اللَّهُ تَعَالَى الْقَلَمُ، فَأَخَذَهُ بِيَمِينِهِ -وَكِلْتَا يَدَيْهِ يَمِينٌ- قَالَ: فَكَتَبَ الدُّنْيَا وَمَا يَكُونُ فِيهَا مِنْ عَمَلٍ مَعْمُولٍ بِرٍّ أَوْ فُجُورٍ، رَطْبٍ أَوْ يَابِسٍ، فَأَحْصَاهُ عِنْدَهُ فِي الذِّكْرِ، فَقَالَ: اقرأوا إِنْ شِئْتُمْ: ﴿هَذَا كِتَابُنَا يَنْطِقُ عَلَيْكُمْ بِالْحَقِّ إِنَّا كُنَّا نَسْتَنْسِخُ مَا كُنْتُمْ تَعْمَلُونَ﴾ [سورة الجاثية: 29]، فَهَلْ تكون النَّسْخَةُ إلاّ مِنْ شَيْءٍ قَدْ فُرغ مِنْهُ."],"takhrij":"حسن: رواه ابنُ أبي عاصم في \"السنة\" (106) عن ابن المصفى، ثنا بقية، حدّثني أرطاة بن المنذر، عن مجاهد بن جبير، عن ابن عمر، فذكره.","grade":"حسن","chapter_ar":"باب خلق الله القلم بعد العرش والماء","chapter_ur":"","part_ar":"كتاب بدء الخلق","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abi ʿAsim in al-Sunnah (106), al-Firyabi in al-Qadar (416), and al-Ajurri in al-Shariʿah (340).","chapter_en":"Allah Created the Pen After the Throne and the Water","part_en":"Book of the Beginning of Creation","group_ar":"","group_en":"","part_no":45,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿUmar said: I heard the Messenger of Allah ﷺ say: “The first thing Allah Most High created was the Pen. He took it in His right hand — and both His hands are right — and it wrote the world and whatever deeds would occur in it: righteousness or wickedness, wet or dry. He recorded it with Him in the Reminder. So recite, if you wish: ‘This is Our Book, speaking against you in truth. Indeed, We used to record what you were doing.’ [al-Jathiyah: 29] Is a copy made except from something already completed?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم في السنة (106)، والفريابي في القدر (416)، والآجري في الشريعة (340)."},{"num":8198,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو بْنِ الْعَاصِ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: كتبَ اللهُ مَقَادِيرَ الْخَلَائِقِ قَبْلَ أَنْ يَخْلُقَ السَّمَاوَاتِ وَالْأَرْضَ بِخَمْسِينَ أَلْفَ سَنَةٍ، قَالَ: وَعَرْشُهُ عَلَى الْمَاءِ."],"takhrij":"صحيح: رواه مسلم في القدر (2653) عن أبي الطاهر أحمد بن عمرو بن عبدالله بن عمرو بن سرْح، حدّثنا ابن وهب، أخبرني أبو هانئ الخولانيّ، عن أبي عبدالرحمن الحبُليّ، عن عبدالله بن عمرو بن العاص، فذكره.","grade":"صحيح","chapter_ar":"باب خلق الله القلم بعد العرش والماء","chapter_ur":"","part_ar":"كتاب بدء الخلق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2653).","chapter_en":"Allah Created the Pen After the Throne and the Water","part_en":"Book of the Beginning of Creation","group_ar":"","group_en":"","part_no":45,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs said: I heard the Messenger of Allah ﷺ say: “Allah wrote the decrees of created beings fifty thousand years before He created the heavens and the earth.” He said: “And His Throne was upon the water.”"]},"buhuth":{"en":["His saying, “The first thing Allah created was the Pen”: what is meant by firstness here is the first command issued by Allah, Mighty and Majestic, to the Pen: “Write the decrees of everything until the Hour is established.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8207],"tks":"صحيح: رواه مسلم (2653)."},{"num":8199,"demo":false,"sanad":"","matn":["عَنْ مَالِكِ بن صَعْصَعَةَ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : بَيْنَا أَنَا عِنْدَ الْبَيْتِ بَيْنَ النَّائِمِ وَالْيَقْظَانِ... فَذَكَرَ حَدِيثَ الإِسْرَاءِ وَالمِعْرَاجِ وَفِيهِ: فَأَتَيْنَا السَّمَاءَ السَّابِعَةَ قِيلَ: مَنْ هَذَا؟ قِيلَ: جِبْرِيلُ. قِيلَ: مَنْ مَعَكَ؟ قِيلَ: مُحَمَّدٌ قِيلَ: وَقَدْ أُرْسِلَ إِلَيْهِ؟ مَرْحَبًا بِهِ وَلَنِعْمَ الْمَجِيءُ جَاءَ فَأَتَيْتُ عَلَى إِبْرَاهِيمَ فَسَلَّمْتُ عَلَيْهِ فَقَالَ: مَرْحَبًا بِكَ مِنِ ابْنٍ وَنَبِيٍّ فَرُفِعَ لِيَ الْبَيْتُ الْمَعْمُورُ فَسَأَلْتُ جِبْرِيلَ فَقَالَ: هَذَا الْبَيْتُ الْمَعْمُورُ يُصَلِّي فِيهِ كُلَّ يَوْمٍ سَبْعُونَ أَلْفَ مَلَكٍ إِذَا خَرَجُوا لَمْ يَعُودُوا إِلَيْهِ آخِرَ مَا عَلَيْهِمْ وَرُفِعَتْ لِي سِدْرَةُ الْمُنْتَهَى."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3207)، ومسلم في الإيمان (164: 264) كلاهما من طريق قتادة، حدثنا أنس بن مالك، عن مالك بن صعصعة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في البيت المعمور","chapter_ur":"","part_ar":"كتاب بدء الخلق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3207) and Muslim (164:264).","chapter_en":"What Has Been Reported Concerning al-Bayt al-Maʿmur","part_en":"Book of the Beginning of Creation","group_ar":"","group_en":"","part_no":45,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Mālik ibn Ṣaʿṣaʿah reported that the Prophet ﷺ said: “While I was at the House, between sleep and wakefulness…” He then mentioned the hadith of the Night Journey and Ascension, in which he said: “We came to the seventh heaven. It was asked, ‘Who is this?’ It was said, ‘Jibrīl.’ It was asked, ‘Who is with you?’ He replied, ‘Muḥammad.’ It was asked, ‘Has he been sent for?’ ‘Welcome to him; what an excellent arrival he has made.’ Then I came upon Ibrāhīm and greeted him. He said, ‘Welcome to you, a son and a prophet.’ Then al-Bayt al-Maʿmūr was raised before me. I asked Jibrīl about it, and he said, ‘This is al-Bayt al-Maʿmūr. Every day seventy thousand angels pray in it. Once they leave it, they never return to it again; that is their final turn.’ Then Sidrat al-Muntahā was raised before me.”"]},"intro":{"ar":["قال الله تعالى:","(وَالطُّورِ ۝ وَكِتَابٍ مَّسْطُورٍ ۝ فِي رَقٍّ مَّنشُورٍ ۝ وَالْبَيْتِ الْمَعْمُورِ) [سورة الطور: ١-٤]."],"en":["Allah Most High said:","“By the Mount, and by a Book inscribed, in parchment unrolled, and by the Frequented House.” [al-Tur: 1–4]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3207)، ومسلم (164: 264)."}]);